    "content": "[b]Salomlashib olaylik:[/b] Salom! 👋 Grammatika olamiga xush kelibsiz! 'Olamiga' deganimga qo'rqib ketmang😄. Biz bu ilovamizda iloji boricha soddalashtirilgan, qiziqarli, kulgili va interaktiv holatda o'rganishga harakat qilamiz. \n\n"
