        "  • He jumped [b]over[/b] the swimming pool. – U basseyn [b]ustidan[/b] sakrab o'tdi. 🤸\n\n"
        "• [b]Up[/b] (yuqoriga, tepaga)\n"
        "  • Prices are going [b]up[/b]. – Narxlar ko'tarilmoqda. 📈\n"
        "  • She walked [b]up[/b] the stairs. – U zina bo'ylab yuqoriga chiqdi. 🪜\n\n"
        "• [b]Down[/b] (pastga, quyiga)\n"
        "  • He sat [b]down[/b] on the ground. – U yerga o'tirdi. ⬇️\n"
        "  • The rain is pouring [b]down[/b]. – Yomg'ir tinmay yog'moqda. 🌧️\n\n"
        "• [b]To[/b] (ga, gacha, tomon)\n"
        "  • I go [b]to[/b] work every day. – Men har kuni ish[b]ga[/b] boraman. 🚶\n"
        "  • She gave a flower [b]to[/b] me. – U men[b]ga[/b] gul berdi. 🎁\n\n"
        "• [b]With[/b] (bilan)\n"
        "  • I went to the cinema [b]with[/b] my friends. – Men do'stlarim [b]bilan[/b] kinoga bordim. 🍿\n"
        "  • He writes [b]with[/b] a pen. – U qalam [b]bilan[/b] yozadi. ✍️\n\n"
        "• [b]From[/b] (dan, dan kelib chiqqan)\n"
        "  • I am [b]from[/b] Uzbekistan. – Men O'zbekiston[b]dan[/b]man. 🇺🇿\n"
        "  • He sent a letter [b]from[/b] his office. – U menga ofisi[b]dan[/b] xat yubordi. 📧\n\n"
        "[center][b]Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=EmWHDcJKLbE&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=7]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link] 🎥"
  },
  {
    "lesson": 7,
    "title": "Present Simple – Savollar (Oddiy hozirgi zamon)",
    "content": "[b]Assalomu alaykum![/b] 👋 Bugun biz [b]Present Simple[/b] (Oddiy hozirgi zamon) yordamida [b]savol shaklini[/b] qanday yasashni o‘rganamiz. Keling, boshladik! ❓👀\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "[b]Savol shakli qanday yasaladi?[/b]\n\n"
        "Agar biror harakat haqida savol bermoqchi bo‘lsangiz, quyidagi tuzilmani ishlating: 📝\n"
        "[b]Do / Does + ega + fe’l (asosiy shaklda)[/b]\n\n"
        "[b]I / You / We / They[/b] bilan [b]do[/b] ishlatiladi:\n"
        "• Do you like tea? – Siz choyni yoqtirasizmi? ☕\n"
        "• Do they live in this house? – Ular shu uyda yashaydimi? 🏠\n\n"
        "[b]He / She / It[/b] bilan [b]does[/b] ishlatiladi:\n"
        "• Does she work hard? – U qattiq ishlaydimi? 👩‍💼\n"
        "• Does it cost a lot? – Bu qimmat turadimi? 💰\n\n"
        "[i]Eslatma:[/i] Savolda fe’lga hech qachon [b]-s[/b] qo‘shilmaydi. Chunki [b]does[/b] bu qo‘shimchani o‘zida mujassam etgan. 👍\n\n"
        "[center][b]Savol so‘zlari bilan savollar[/b][/center]\n"
        "Agar savolga faqat “ha” yoki “yo‘q” emas, balki [b]qo‘shimcha ma’lumot[/b] kerak bo‘lsa, [b]wh-words[/b] bilan boshlang: 👇\n\n"
        "• [b]What[/b] do you do? – Nima qilasiz? 🤷‍♀️\n"
        "• [b]Where[/b] do they live? – Ular qayerda yashaydi? 🗺️\n"
        "• [b]When[/b] does he come? – U qachon keladi? ⏰\n"
        "• [b]Why[/b] does she cry? – U nega yig‘laydi? 😢\n"
        "• [b]Who[/b] teaches English? – Ingliz tilini kim o‘rgatadi? 👩‍🏫\n"
        "• [b]Which[/b] book do you want? – Qaysi kitobni xohlaysiz? 📖\n"
        "• [b]How[/b] do you feel? – O‘zingizni qanday his qilyapsiz? 😌\n\n"
        "[center][b]Misollar orqali mustahkamlaymiz[/b][/center]\n"
        "• Do you go to school every day? – Siz har kuni maktabga borasizmi? 🏫\n"
        "• Does your sister like animals? – Singlingiz hayvonlarni yoqtiradimi? 🐶\n"
        "• What do your parents say? – Ota-onangiz nima deyishadi? 🗣️\n"
        "• Where does he work? – U qayerda ishlaydi? 🏢\n\n"
        "[center][b]Uyga vazifa[/b][/center]\n"
        "Ingliz tilida hafta kunlarini qanday aytishni o'rganing. Bu jarayonda youtube videolaridan foydalanishingizni tavsiya qilamiz. 📆\n\n"
        "[center][b]Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=6icIxa75PcY]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link] 🎥"
  },
  {
    "lesson": 8,
    "title": "I have / I have got (Menda bor)",
    "content": "[b]Assalomu alaykum![/b] 👋 Bugun siz bilan [b]“menda bor”[/b] degan fikrni qanday ifodalashni o‘rganamiz: [b]I have[/b] va [b]I have got[/b] yordamida. 🐱🚲🌳\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "[b]I have[/b] va [b]I have got[/b] bir xil ma’noni bildiradi — [i]menda bor[/i]. ✨\n\n"
        "• [b]I have[/b] – biroz rasmiyroq va asosan Amerikada ishlatiladi 🇺🇸\n"
        "• [b]I have got[/b] – Angliyada norasmiy so'zlashuvda ko‘proq ishlatiladi 🇬🇧\n\n"
        "[center][b]Shakllar[/b][/center]\n"
        "[b]I have + narsa[/b]\n"
        "• [b]I have a bicycle.[/b] – Menda velosiped bor. 🚲\n"
        "• [b]I have a black cat.[/b] – Menda qora mushuk bor. 🐈‍⬛\n\n"
        "[b]I have got + narsa[/b]\n"
        "• [b]I have got a bicycle.[/b] – Menda velosiped bor. 🚴‍♀️\n"
        "• [b]I have got a black cat.[/b] – Menda qora mushuk bor. 🐾\n\n"
        "[i]Eslatma:[/i] “I have” va “I have got” bir xil ma’no beradi. Farqi yo‘q. 👌\n\n"
        "[center][b]He / She / It bilan[/b][/center]\n"
        "• [b]She has a cat.[/b] – Unda mushuk bor.\n"
        "• [b]She has got a cat.[/b] – Unda mushuk bor.\n"
        "• [b]It has a long tail.[/b] – Uning uzun dum(i) bor. 🦊\n\n"
        "[center][b]Inkor shakli[/b][/center]\n"
        "• [b]I don't have a bicycle.[/b] – Menda velosiped yo'q. ❌\n"
        "• [b]I haven't got a bicycle.[/b] – Menda velosiped yo'q. ❌\n"
        "• [b]She doesn't have a cat.[/b] – Unda mushuk yo'q. ❌\n"
        "• [b]She hasn't got a cat.[/b] – Unda mushuk yo'q. ❌\n\n"
        "[center][b]Savol shakli[/b][/center]\n"
        "• [b]Do you have a bicycle?[/b] – Sizda velosiped bormi? ❓\n"
        "• [b]Have you got a bicycle?[/b] – Sizda velosiped bormi? ❓\n"
        "• [b]Does she have a cat?[/b] – Unda mushuk bormi? ❓\n"
        "• [b]Has she got a cat?[/b] – Unda mushuk bormi? ❓\n\n"
        "[center][b]Misollar orqali mustahkamlaymiz[/b][/center]\n"
        "• [b]I have a short knife.[/b] – Menda kalta pichoq bor. 🔪\n"
        "• [b]I have got something in my bag.[/b] – Sumkamda biror narsa bor. 👜\n"
        "• [b]My children have bicycles.[/b] – Bolalarimda velosipedlar bor. 🧒🚲\n"
        "• [b]She has got beautiful eyes.[/b] – Unda chiroyli ko‘zlar bor. 👀\n"
        "• [b]We have a big garden.[/b] – Bizda katta bog‘ bor. 🌳\n"
        "• [b]They have got a house.[/b] – Ularda uy bor. 🏡\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=4-afuqA10t4&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=10]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 9,
    "title": "Was / Were (O‘tgan Zamon “edi”)",
    "content": "[b]Salom, do‘stlar![/b] 👋 Bugun biz o‘tgan zamondagi holatlarni ifodalash uchun ishlatiladigan [b]was[/b] va [b]were[/b] ni o‘rganamiz. Bu dars orqali siz: “Men uyda edim”, “Ular charchagan edi” kabi gaplarni tuzishni bilib olasiz. ⏳🏠😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "[b]Was[/b] va [b]were[/b] fe’li “edi” degan ma’noni bildiradi. Bu fe’llar hozirgi zamondagi [i]am / is / are[/i] ning o‘tgan zamondagi shaklidir. 🕰️\n\n"
        "• [b]I / he / she / it[/b] bilan → [b]was[/b] ✅\n"
        "• [b]You / we / they[/b] bilan → [b]were[/b] ✅\n\n"
        "[center][b]Misollar:[/b][/center]\n"
        "• I was at home. – Men uyda edim. 🏡\n"
        "• She was happy. – U baxtli edi. 😄\n"
        "• It was cold yesterday. – Kecha sovuq edi. ❄️\n"
        "• You were at the park. – Siz parkda edingiz. 🌳\n"
        "• We were tired. – Biz charchagan edik. 😴\n"
        "• They were on holiday. – Ular ta’tilda edi. 🏝️\n\n"
        "[center][b]Davom etamiz...[/b][/center]\n"
        "• I was late this morning. – Men bugun ertalab kech qoldim. ⏰\n"
        "• She was my best friend. – U mening eng yaxshi do‘stim edi. 👭\n"
        "• It was a beautiful day. – Juda chiroyli kun edi. ☀️\n"
        "• We were happy with the result. – Biz natijadan mamnun edik. 🎉\n"
        "• They were not at school. – Ular maktabda emas edi. 🏫❌\n\n"
        "[center][b]Eslab qoling:[/b][/center]\n"
        "[b]Was = edi[/b] (I, he, she, it)\n"
        "[b]Were = edingiz / edik / edilar[/b] (you, we, they)\n\n"
        "[center][b]Kichik eslatma[/b][/center]\n"
        "Hikoyalarimizda ayrim fe’llarning ohiriga [b]-ed[/b] qo‘shilganini sezgan bo‘lsangiz kerak. Bu — harakatning o‘tgan zamonda sodir bo‘lganini bildiradi. Kelgusi darslarda o‘tgan zamon fe’llarini batafsil o‘rganamiz. Hozircha bu shakllarga ortiqcha bosh qotirmang — faqat shuni bilingki, [b]-ed[/b] qo‘shimchasi o‘tgan zamon belgisi hisoblanadi. ✍️\n\n"
        "[center][b]Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=6A7n5RKFa2c&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=11]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link] 🎥"
  },
  {
    "lesson": 10,
    "title": "Past Simple (O‘tgan Zamon)",
    "content": "[b]Salomlashib olaylik:[/b] Qalaysilar😀! Ancha-muncha narsani o'rganib ham oldinglar. Tasanno! 👏 Lekin bugungi mavzu ancha kattaroq va shuning uchun ham ikki yoki uchga bo'lib o'rganishga to'g'ri keladi! 📚\n\n"
        "[center][b]Grammatika tushuntirish (Past Simple)[/b][/center]\n"
        "Past Simple — o‘tgan zamonda sodir bo‘lgan va tugagan ish-harakatlarni ifodalaydi. ⏳\n\n"
        "[b]1. Oddiy fe’llar (regular verbs)[/b]\n"
        "Ko‘pchilik fe’llarga [b]-ed[/b] qo‘shimchasi qo‘shilib o‘tgan zamon yasaladi:\n\n"
        "[i]work → worked[/i] (ishlamoq → ishladi) 👩‍💼\n"
        "[i]clean → cleaned[/i] (tozalamoq → tozaladi) 🧼\n"
        "[i]start → started[/i] (boshlamoq → boshladi) ▶️\n\n"
        "Misollar:\n"
        "• I cleaned my room yesterday. – Kecha xonamni tozaladim. ✨\n"
        "• We worked together last year. – Biz o‘tgan yili birga ishladik. 🤝\n\n"
        "[b]2. Maxsus yozilish qoidalari[/b]\n"
        "Ba'zi fe’llarga [b]-ed[/b] qo‘shishda yozilish biroz o‘zgaradi:\n"
        "[i]try → tried[/i] (urinmoq → urindi) 🧐\n"
        "[i]stop → stopped[/i] (to‘xtamoq → to‘xtadi) 🛑\n"
        "[i]plan → planned[/i] (rejalashtirmoq → rejalashtirdi) 🗺️\n\n"
        "[b]3. Noto‘g‘ri fe’llar (irregular verbs)[/b]\n"
        "Ba'zi fe’llar [b]-ed[/b] qo‘shimchasi bilan emas, balki butunlay o‘zgaradi. Ularni yodlab olish kerak: 🧠\n\n"
        "[i]go → went[/i] (bormoq → bordi) 🚶\n"
        "[i]have → had[/i] (ega bo‘lmoq → ega edi) 🎁\n"
        "[i]come → came[/i] (kelmoq → keldi) 🚶‍♀️\n"
        "[i]see → saw[/i] (ko‘rmoq → ko‘rdi) 👀\n\n"
        "[b]4. Misollar:[/b]\n"
        "• I went to school yesterday. – Kecha maktabga bordim. 🏫\n"
        "• She had lunch at 1 o’clock. – U soat birda tushlik qildi. 🍽️\n"
        "• They came home late. – Ular uyga kech keldi. 🏠\n\n"
        "[center][b]Kichik eslatma[/b][/center]\n"
        "Hozircha faqat o‘tgan zamonning [b]ijobiy shakli[/b]ni o‘rganamiz. Savol va inkor shakllari keyingi darslarda tushuntiriladi. 🤔\n\n"
        "Qo'shimcha video darslik uchun [link=https://www.youtube.com/watch?v=sY2b-mj76h8&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=12]bu yerni bosing![/link]\n"
  },
  {
    "lesson": 11,
    "title": "Past Simple – Inkor va Savol shakli (O‘tgani zamon)",
    "content": "[b]Salom![/b] 👋 Oldingi darsda o‘tmishdagi oddiy harakatlarni qanday ifodalashni o‘rgandik. Endi esa o‘sha harakatlarni qanday [b]inkor qilish[/b] ❌ va ular haqida [b]savol berish[/b] ❓ mumkinligini ko‘rib chiqamiz. Tayyormisiz? [i]Kettik![/i] 🚀\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "[b]1. Inkor shakli:[/b]\n"
        "O‘tgan zamonda inkor qilish uchun [b]did not[/b] (yoki qisqa shakli: [b]didn’t[/b]) yordamchi fe’lidan foydalaniladi. 🚫\n"
        "[b]Tuzilishi:[/b] Subject (I/you/he...) + didn’t + fe’l\n\n"
        "[b]Misollar:[/b]\n"
        "• I didn’t go. – Men bormadim. 🚶‍♀️❌\n"
        "• She didn’t eat dinner. – U kechki ovqatni yemadi. 🍽️\n"
        "• They didn’t play football. – Ular futbol o‘ynamadi. ⚽\n"
        "• We didn’t hear the sound. – Biz ovozni eshitmadik. 🙉\n\n"
        "[i]Eslatma:[/i] \"Didn’t\" ishlatilganda fe’l o‘zgarmaydi – [b]doim 1-shaklda[/b] bo‘ladi: go, eat, play, see, hear va h.k. ✅\n\n"
        "[b]2. Savol shakli:[/b]\n"
        "O‘tgan zamonda savol berishda [b]did[/b] yordamchi fe’li gap boshida bo‘ladi. 🧐\n"
        "[b]Tuzilishi:[/b] Did + subject(I/you/he...) + fe’l (asosiy shakl)\n\n"
        "[b]Misollar:[/b]\n"
        "• Did you go to school? – Siz maktabga bordingizmi? 🏫\n"
        "• Did she cut the paper? – U qog‘ozni kesdimi? ✂️\n"
        "• Did your parents hurry? – Ota-onangiz shoshildimi? 🏃‍♂️\n"
        "• Did they climb the mountain? – Ular tog‘ga chiqishdimi? 🏔️\n"
        "• Where did you go two days ago? – Ikki kun avval qayerga bording? 📍\n"
        "• What did I eat yesterday? – Kecha nima yedim? 🍕\n"
        "[center][b]Qo‘shimcha misollar:[/b][/center]\n"
        "• I didn’t see the plane. – Men samolyotni ko‘rmadim. ✈️\n"
        "• Did he bring his bag? – U sumkasini olib keldimi? 💼\n"
        "• She didn’t win the game. – U o‘yinda g‘alaba qozonmadi. 🏆❌\n"
        "• Did they open the door? – Ular eshikni ochishdimi? 🚪\n\n"
        "[center][b]Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=XfLqJNHSdZU&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=13]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link] 🎥"
  },
  {
    "lesson": 12,
    "title": "Past Continuous (O‘tgani davomli zamon)",
    "content": "[b]Salom![/b] 👋 Bu darsda biz [b]Past Continuous[/b] zamonini o‘rganamiz. Bu zamon o‘tmishda ma’lum bir paytda davom etayotgan harakatlarni ifodalash uchun ishlatiladi. ⏳\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "Past Continuous quyidagicha tuziladi:\n"
        "[b]Subject + was/were + fe’l + -ing[/b] ✍️\n\n"
        "[b]Qachon ishlatiladi?[/b]\n"
        "• O‘tmishda biror ish muayyan vaqt davomida sodir bo‘lganini aytishda: ⏰\n"
        "  I was studying at 9 o’clock. – Soat 9 da men o‘qiyotgan edim. 📖\n\n"
        "• O‘tmishda bir harakat sodir bo‘layotgan paytda boshqa bir ish sodir bo‘lsa: 💥\n"
        "  She was sleeping when the phone rang. – Telefon jiringlaganda u uxlayotgan edi. 😴\n\n"
        "[center][b]Fe’lga –ing qo‘shiladi:[/b][/center]\n"
        "• read → reading 📚\n"
        "• play → playing 🎮\n"
        "• write → writing 📝\n"
        "• eat → eating 🍎\n\n"
        "[b]To‘g‘ri ishlatiladigan to‘ldiruvchilar:[/b] yesterday, last night, at 9 o’clock, when, while\n\n"
        "[center][b]Tuzilish:[/b][/center]\n"
        "[b]1. Affirmative (ijobiy):[/b] ✅\n"
        "• I/he/she/it [b]was[/b] + fe’l + -ing\n"
        "• We/you/they [b]were[/b] + fe’l + -ing\n\n"
        "Misollar:\n"
        "• I was reading a book. – Men kitob o‘qiyotgan edim. 🤓\n"
        "• They were watching a movie. – Ular film ko‘rayotgan edi. 🍿\n\n"
        "[b]2. Negative (inkor):[/b] ❌\n"
        "[b]was not (wasn’t)[/b] yoki [b]were not (weren’t)[/b] ishlatiladi.\n"
        "• She wasn’t eating. – U yemayotgan edi. 🚫🍽️\n"
        "• We weren’t listening. – Biz tinglamayotgan edik. 👂\n\n"
        "[b]3. Question (savol):[/b] ❓\n"
        "[b]Was/Were[/b] boshida keladi:\n"
        "• Was he working? – U ishlayotgan edimi? 👷‍♂️\n"
        "• Were they playing? – Ular o‘ynayotgan edimi? ⛹️\n\n"
        "[center][b]Qo‘shimcha misollar:[/b][/center]\n"
        "• I was wearing a skirt yesterday. – Kecha yubka kiygan edim. 👗\n"
        "• Was she driving the car? – U mashinani haydayotgan edimi? 🚗\n"
        "• They weren’t listening to the teacher. – Ular o‘qituvchini tinglamayotgan edi. 👩‍🏫\n"
        "• What were you doing at 8? – Soat 8 da nima qilayotgan eding? 🤔\n\n"
        "[center][b]Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=t_7oBHw-k-o]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link] 🎥"
  },
  {
    "lesson": 13,
    "title":
        "Present Perfect (I have done) – Hozirgi Tugallangan Zamon (1-qism)",
    "content": "Salom! 👋 Bugungi [b]Lesson 13[/b] darsimizda ingliz tilidagi juda muhim zamonlardan biri – [b]Present Perfect (Hozirgi Tugallangan Zamon)[/b]ning birinchi qismini o'rganamiz. Bu zamon o'tmishdagi harakatlar hozirgi holatga qanday ta'sir qilishini ifodalash uchun ishlatiladi. 🎯\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "[b]Present Perfect[/b] zamoni quyidagicha tuziladi:\n"
        "[b]Ega (Subject)[/b] + [b]have / has[/b] + [b]V3 ya'ni fe'lning uchinchi shakli[/b] ✍️\n\n"
        "• [b]I / You / We / They[/b] uchun [b]have[/b] ishlatiladi. (Qisqartmasi: [b]’ve[/b])\n"
        "• [b]He / She / It[/b] uchun [b]has[/b] ishlatiladi. (Qisqartmasi: [b]’s[/b])\n\n"
        "[b]Fe'lning o'tgan zamon sifatdoshi (Past Participle ya'ni V3)[/b]:\n"
        "• Ko'pchilik to'g'ri fe'llar uchun bu [b]-ed[/b] qo'shimchasi bilan tugaydi. Masalan: [i]clean -> cleaned, finish -> finished.[/i] ✨\n"
        "• Noto'g'ri fe'llarning shakllari esa yod olinishi kerak. Masalan: [i]do -> done, eat -> eaten, see -> seen.[/i] 📚\n\n"
        "✅ [b]Qachon ishlatamiz?[/b]\n"
        "Biz [b]Present Perfect[/b]ni o'tmishda sodir bo'lgan, ammo [b]natijasi hozirda mavjud bo'lgan[/b] yoki hozirgi vaziyatga aloqador bo'lgan harakatlar uchun ishlatamiz. 💡\n\n"
        "• [b]Misollar:[/b]\n"
        "  • He has cleaned his shoes. – U poyabzallarini tozalab bo'ldi. Natija: Uning poyabzallari hozir toza. 👟✨\n"
        "  • I have lost my passport. – Men pasportimni yo'qotdim. Natija: Hozirda pasportim yo'q va uni topa olmayapman. 🔑❌\n"
        "  • They have gone home. – Ular uyga qaytib ketishdi. Natija: Ular hozir bu yerda emas. 🚶‍♀️🏡\n"
        "  • We have bought a new car. – Biz yangi mashina sotib oldik. Natija: Hozirda yangi mashinamiz bor. 🚗🎉\n"
        "  • Have you finished this newspaper? – Siz bu gazetani o'qib bo'ldingizmi? Natija: Men uni hozir o'qiy olamanmi? 📰❓\n\n"
        "Bu zamon ko'pincha hozirgi natijaga e'tibor qaratadi, harakatning qachon sodir bo'lganligi unchalik muhim emas. 🕰️\n\n"
        "[center][b]Present Perfect zamonining shakllari[/b][/center]\n"
        "1. [b]Darak shakli (Affirmative Form)[/b] ✅\n"
        "   [b]Ega + have/has + Past Participle[/b]\n"
        "   • I have bought a new book. – Men yangi kitob sotib oldim. 📚\n"
        "   • They have completed the project. – Ular loyihani tugatdilar. 🎉\n"
        "   • The birds have flown away. – Qushlar uchib ketishdi. 🐦⬆️\n\n"
        "2. [b]Bo'lishsizlik shakli (Negative Form)[/b] ❌\n"
        "   [b]Ega + have/has + not + Past Participle[/b] (Qisqartmasi: [b]haven't / hasn't[/b])\n"
        "   • I have not eaten breakfast yet. (yoki I haven't eaten breakfast yet.) – Men hali nonushta qilmadim. 🍳⏳\n"
        "   • She has not finished her homework yet. (yoki She hasn't finished her homework yet.) – U hali uy vazifasini tugatgani yo'q. 📝🤷‍♀️\n"
        "   • We have not seen this movie. (yoki We haven't seen this movie.) – Biz bu filmni ko'rmaganmiz. 🎬🚫\n\n"
        "3. [b]So'roq shakli (Interrogative Form)[/b] ❓\n"
        "   [b]Have/Has + Ega + Past Participle + ?[/b]\n"
        "   • Have you cooked dinner? – Sen kechki ovqatni tayyorladingmi? 🍝❓\n"
        "   • Has he heard the news? – U xabarni eshitdimi? 👂❓\n"
        "   • Have they been to Paris? – Ular Parijga borganmi? 🇫🇷❓\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=Ew9OR6q6GW8]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 14,
    "title": "Present Perfect (2-qism): Just, Already, Yet",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 14[/b] darsimizda Present Perfect zamonining ikkinchi qismini o'rganamiz. Bu darsda biz 'just', 'already' va 'yet' kabi so'zlarning Present Perfect bilan qanday ishlatilishini ko'rib chiqamiz. Bu so'zlar harakatning vaqti haqida qo'shimcha ma'lumot beradi. ⏱️\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Just (Hozirgina / Yaqinda)[/b]\n"
        "[b]Just[/b] so'zi biror harakatning [b]juda qisqa vaqt oldin[/b] sodir bo'lganligini bildiradi. U odatda [b]have/has[/b] va fe'lning [b]past participle[/b] shakli o'rtasida keladi. ➡️\n\n"
        "• They have just arrived. – Ular hozirgina yetib kelishdi. 🚶‍♂️🚶‍♀️\n"
        "• I have just cooked dinner. – Men hozirgina kechki ovqatni tayyorladim. 🍝\n\n"
        "✅ [b]Already (Allaqaqon / Allaqachon)[/b]\n"
        "[b]Already[/b] so'zi biror harakatning [b]kutilganidan oldinroq[/b] yoki [b]hozirgacha[/b] sodir bo'lganligini bildiradi. U ham odatda [b]have/has[/b] va fe'lning [b]past participle[/b] shakli o'rtasida keladi. ✔️\n\n"
        "• We have already met. – Biz allaqachon uchrashganmiz. 🤝\n"
        "• She has already read the book. – U allaqachon kitobni o'qib bo'ldi. 📖✅\n\n"
        "✅ [b]Yet (Hali / Hali ham)[/b]\n"
        "[b]Yet[/b] so'zi odatda [b]bo'lishsiz (negative) gaplarda[/b] va [b]so'roq (interrogative) gaplarda[/b] ishlatiladi. U [b]gapning oxirida[/b] keladi. 📍\n\n"
        "• [b]Bo'lishsiz gaplarda:[/b] Biror narsaning hozirgacha sodir bo'lmaganligini bildiradi.\n"
        "  • They have not arrived yet. (yoki They haven't arrived yet.) – Ular hali yetib kelishmadi. ⏳❌\n"
        "  • I have not seen this movie yet. – Men hali bu filmni ko'rganim yo'q. 🎬🤷‍♀️\n\n"
        "• [b]So'roq gaplarda:[/b] Biror narsaning hozirgacha sodir bo'lganligini so'rash uchun ishlatiladi.\n"
        "  • Have you finished your homework yet? – Sen uy vazifangni tugatdingmi? 📝❓\n"
        "  • Has the computer been repaired yet? – Kompyuter ta'mirlandimi? 💻✅\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=54Xj_PcwlIY]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 15,
    "title": "Present Perfect (3-qism): Have you ever...? (Hayotiy Tajribalar)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 15[/b] darsimizda Present Perfect zamonining uchinchi qismini o'rganamiz. Bu safar biz uni hayotiy tajribalarimiz, ya'ni o'tmishdan hozirgacha bo'lgan davrda sodir bo'lgan voqealar haqida gapirish uchun qanday ishlatishni ko'rib chiqamiz. Asosiy e'tibor [b]\"Have you ever...?\"[/b] va [b]\"been to\" / \"gone to\"[/b] farqlariga qaratiladi. 🧐\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Have you ever...? (Qachonlardir qilganmisiz?)[/b]\n"
        "Bu savol shakli biror shaxsning [b]hayoti davomida[/b] (o'tmishdan hozirgi kungacha bo'lgan istalgan vaqtda) biror harakatni bajargan-bajarmaganligini so'rash uchun ishlatiladi. [b]Ever[/b] so'zi 'qachonlardir' degan ma'noni beradi va faqat so'roq gaplarda keladi. ❓\n\n"
        "• Have you ever lived abroad? – Siz hech(qachonlardir) chet elda yashaganmisiz? 🌍❓\n"
        "• Has she ever ridden a horse? – U hech ot minganmi? 🐎❓\n"
        "• Have you ever been to the top of a skyscraper? – Siz hech osmon o'par binoning tepasida bo'lganmisiz? 🏙️❓\n\n"
        "✅ [b]Never (Hech qachon)[/b]\n"
        "[b]Never[/b] so'zi [b]hech qachon[/b] biror harakatni bajarmaganlikni ifodalash uchun ishlatiladi. Bu so'zning o'zi inkor ma'nosini berganligi sababli, [b]not[/b] qo'shimchasi ishlatilmaydi. 🚫\n\n"
        "• I have never tasted sushi. – Men hech qachon sushini tatib ko'rmaganman. 🍣❌\n"
        "• He has never been to Japan. – U hech qachon Yaponiyada bo'lmagan. 🇯🇵🚫\n\n"
        "✅ [b]Been to[/b] vs. [b]Gone to[/b]\n"
        "Bu ikki ibora o'rtasida muhim farq bor: 🔄\n\n"
        "• [b]Been to[/b] (Borib kelgan / Bo'lib kelgan) ➡️ Siz biror joyga borganingizni va hozirda [b]qaytib kelganingizni[/b] bildiradi.\n"
        "  • I have been to Paris. – Men Parijda bo'lganman. (Hozirda men shu yerda) 🇫🇷✅\n"
        "  • They have been to the shop. – Ular do'konga borib kelishdi. (Hozirda ular shu yerda) 🛒↩️\n\n"
        "• [b]Gone to[/b] (Ketgan / Borgan) ➡️ Siz biror joyga ketganingizni va hozirda [b]hali ham o'sha yerda ekanligingizni[/b] bildiradi.\n"
        "  • Bill has gone to Spain. – Bill Ispaniyaga ketgan. (U hozirda Ispaniyada) 🇪🇸✈️\n"
        "  • Mary has gone for lunch. – Meri tushlik qilish uchun ketgan. (U hozirda bu yerda emas) 🚶‍♀️🍽️\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=xk6Nf-L1OYM&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=18]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 16,
    "title": "Present Perfect (4-qism): How long...? (Qancha vaqtdan beri?)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 16[/b] darsimizda Present Perfect zamonining to'rtinchi qismini o'rganamiz. Bu darsda biz '[b]How long...?[/b]', '[b]for[/b]' va '[b]since[/b]' so'zlari yordamida biror harakat yoki holatning [b]qancha vaqtdan beri[/b] davom etayotganini qanday ifodalashni bilib olamiz. ⏱️\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]How long...? (Qancha vaqtdan beri?)[/b]\n"
        "Bu so'roq shakli biror holat yoki harakatning [b]qancha muddat davom etganligini[/b] (o'tmishdan hozirgacha) so'rash uchun ishlatiladi. ⏳\n\n"
        "• How long have you lived here? – Siz qancha vaqtdan beri bu yerda yashayapsiz? 🏡⏳\n"
        "• How long has he worked for this company? – U qancha vaqtdan beri bu kompaniyada ishlaydi? 🏢🗓️\n\n"
        "✅ [b]For (Davomiylik uchun)[/b]\n"
        "[b]For[/b] so'zi biror harakat yoki holatning [b]umumiy davomiyligini[/b] (masalan, uch kun, besh yil) ifodalash uchun ishlatiladi. 📅\n\n"
        "• I have been in Ireland for three days. – Men uch kundan beri Irlandiyadaman. 🇮🇪🗓️\n"
        "• They have been married for ten years. – Ular o'n yildan beri turmush qurishgan. 💍🔟\n\n"
        "✅ [b]Since (Boshlanish nuqtasi uchun)[/b]\n"
        "[b]Since[/b] so'zi biror harakat yoki holatning [b]qachon boshlanganini[/b] (aniq bir vaqt, sana, yoki boshqa harakat) ifodalash uchun ishlatiladi. 🏁\n\n"
        "• I have been in Ireland since Monday. – Men dushanbadan beri Irlandiyadaman. 🇮🇪📅\n"
        "• She has lived in London since 2020. – U 2020-yildan beri Londonda yashaydi. 🇬🇧🗓️\n\n"
        "✅ [b]Present Simple va Present Perfect o'rtasidagi farq (davomiylikda)[/b]\n"
        "• Hozirgi holatni ifodalash uchun [b]Present Simple[/b] ishlatamiz. Masalan: I know Sarah. (Men Sarani bilaman) 🤔\n"
        "• Holatning [b]qancha vaqtdan beri[/b] davom etayotganini ifodalash uchun [b]Present Perfect[/b] ishlatamiz: I have known Sarah for a long time. (Men Sarani ancha vaqtdan beri bilaman) ⏳👯‍♀️\n\n"
        "• I have a car. – Mening mashinam bor. 🚗\n"
        "• I have had a car since April. – Mening aprel oyidan beri mashinam bor. 🗓️🚗\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=FJ8XZiOFn98&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=19]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 17,
    "title": "Present Perfect (5-qism): For, Since, Ago",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 17[/b] darsimizda Present Perfect zamonini yanada chuqurroq o'rganamiz. Bu darsda biz '[b]for[/b]', '[b]since[/b]' va '[b]ago[/b]' so'zlari yordamida vaqtni qanday ifodalashni ko'rib chiqamiz. Bu uchala so'z ham [b]vaqtni[/b] ifodalaydi, lekin ularning ishlatilishi va kontekstlari farq qiladi. ⏳\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]For (Davomiylik uchun)[/b]\n"
        "[b]For[/b] so'zi biror harakat yoki holatning [b]umumiy davomiyligini[/b] (masalan, besh daqiqa, uch yil) ifodalash uchun ishlatiladi. U ko'pincha Present Perfect bilan ishlatiladi. 🗓️\n\n"
        "• I have studied for three hours. – Men uch soatdan beri o'qiyapman. 📚🕒\n"
        "• She has waited for twenty minutes. – U yigirma daqiqadan beri kutmoqda. ⏱️🧍‍♀️\n\n"
        "✅ [b]Since (Boshlanish nuqtasi uchun)[/b]\n"
        "[b]Since[/b] so'zi biror harakat yoki holatning [b]qachon boshlanganini[/b] (aniq bir vaqt, sana, yoki boshqa harakat) ifodalash uchun ishlatiladi. U ham ko'pincha Present Perfect bilan ishlatiladi. 📍\n\n"
        "• We have lived here since 2010. – Biz bu yerda 2010-yildan beri yashaymiz. 🏡🗓️\n"
        "• He has played piano since he was a child. – U yoshligidan beri pianino chaladi. 🎹👶\n\n"
        "✅ [b]Ago (Oldin)[/b]\n"
        "[b]Ago[/b] so'zi biror harakat yoki hodisaning [b]hozirdan qancha vaqt oldin[/b] sodir bo'lganligini ifodalaydi. [b]Ago[/b] odatda [b]Past Simple (Oddiy o'tgan zamon)[/b] bilan ishlatiladi, chunki u o'tmishdagi tugallangan harakatni ko'rsatadi. 🔙\n\n"
        "• I saw him two days ago. – Men uni ikki kun oldin ko'rdim. 👀🗓️\n"
        "• The meeting ended an hour ago. – Yig'ilish bir soat oldin tugadi. ⏰✅\n\n"
        "💡 [b]For/Since va Ago o'rtasidagi asosiy farq:[/b]\n"
        "• [b]For[/b] va [b]Since[/b] hozirgi kungacha davom etayotgan harakatlar yoki holatlar uchun Present Perfect bilan ishlatiladi. 🔄\n"
        "• [b]Ago[/b] esa o'tmishdagi tugallangan nuqtaviy harakatlar uchun Past Simple bilan ishlatiladi. ✅\n\n"
        "• She arrived yesterday. – U kecha keldi. 🗓️🚶‍♀️\n"
        "• She arrived a day ago. – U bir kun oldin keldi. 🗓️⬅️\n"
        "• She has been here for a day. – U bir kundan beri shu yerda. ⏳\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=j1bsFkoflsY&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=20]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 18,
    "title": "Past Simple vs Present Perfect",
    "content": "👋 Assalomu alaykum, aziz o‘quvchilar!\n\n"
        "📚 Bugun biz ikki muhim zamonni – [b]Past Simple[/b] (oddiy o‘tgan zamon) va [b]Present Perfect[/b] (hozirgi tugallangan zamon)ni solishtiramiz. 🤔\n\n"
        "[b]📌 Qisqacha qoida:[/b]\n"
        "Past Simple o‘tmishda sodir bo‘lgan, aniq vaqt ko‘rsatilgan harakatlar uchun ishlatiladi. 📅\n"
        "Present Perfect esa o‘tmishda boshlangan va hozirga aloqador bo‘lgan harakatlar uchun ishlatiladi. ➡️\n\n"
        "[b]🧩 Past Simple shakli:[/b]\n"
        "• I went to the park yesterday. – Men kecha bog‘ga bordim. 🚶‍♂️\n"
        "• She watched a movie last night. – U kecha film tomosha qildi. 🎬\n\n"
        "[b]🧩 Present Perfect shakli:[/b]\n"
        "• I have been to the park. – Men bog‘da bo‘lganman. 🌳\n"
        "• She has watched that movie. – U o‘sha filmni tomosha qilgan. 🍿\n\n"
        "⚠️ [i]Present Perfect bilan “just”, “already”, “yet”, “ever”, “never” kabi so‘zlar ko‘p ishlatiladi.[/i] ✨\n\n"
        "🔍 [b]Taqqoslash misollar:[/b]\n"
        "• I ate lunch at 1 PM. (Past Simple – aniq vaqt bor) – Men soat 1 da tushlik qildim. 🕐\n"
        "• I have eaten lunch. (Present Perfect – qachonligi muhim emas, natija muhim) – Men tushlik qildim. ✅\n\n"
