  {
    "lesson": 19,
    "title": "Passive Voice 1 (Majhul nisbat – is/are done, was/were done)",
    "content": "👋 Assalomu alaykum, aziz o‘quvchilar!\n\n"
        "📚 Bugungi darsimizda biz [b]Passive Voice[/b] – ya’ni [b]majhul nisbat[/b]ni o‘rganamiz. Bu grammatik qurilish, harakat kim tomonidan bajarilgani noma’lum yoki ahamiyatsiz bo‘lgan holatlarda ishlatiladi. 🧠\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "Majhul nisbat shakli quyidagicha yasaladi:\n"
        "[b]be (is/are/was/were) + fe’lning 3-shakli (Past Participle)[/b] ✍️\n\n"
        "📌 [b]Hozirgi zamon (Present Simple Passive):[/b]\n"
        "➡️ [b]is/are + 3-shakl[/b]\n"
        "• The car is washed every week. – Mashina har hafta yuviladi. 🚗\n"
        "• Books are sold here. – Bu yerda kitoblar sotiladi. 📚\n\n"
        "📌 [b]O‘tgan zamon (Past Simple Passive):[/b]\n"
        "➡️ [b]was/were + 3-shakl[/b]\n"
        "• The cake was baked by my mom. – Tort onam tomonidan pishirildi. 🎂\n"
        "• The windows were cleaned yesterday. – Derazalar kecha tozalandi. 🧼\n\n"
        "💬 [b]Savol shakli:[/b]\n"
        "• Was the letter sent? – Xat yuborildimi? ✉️\n"
        "• Are the rooms cleaned every day? – Xonalar har kuni tozalanadimi? 🏨\n\n"
        "🚫 [b]Inkor shakli:[/b]\n"
        "• The food was not (wasn’t) prepared well. – Taom yaxshi tayyorlanmagan edi. 🍲\n"
        "• The doors aren’t locked at night. – Eshiklar kechasi qulflanmaydi. 🚪\n\n"
        "🎯 [b]Qo‘shimcha misollar:[/b]\n"
        "• English is spoken in many countries. – Ingliz tili ko‘plab mamlakatlarda so‘zlanadi. 🌍\n"
        "• The lights were turned off at 10 p.m. – Chiroqlar kechki 10 da o‘chirildi. 💡\n\n"
