  },
  {
    "lesson": 20,
    "title":
        "Passive Voice 2 (Majhul nisbat – have/has been done, am/is/are being done)",
    "content": "👋 Assalomu alaykum, aziz bilim izlovchilar!\n\n"
        "📘 Bugungi darsimizda [b]majhul nisbat[/b]ning (Passive Voice) [b]Hozirgi tugallangan zamon[/b] (Present Perfect Passive) va [b]Hozirgi davomli zamon[/b] (Present Continuous Passive) shakllarini o‘rganamiz. 🧠\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "➡️ [b]Present Perfect Passive:[/b] [b]have/has been + 3-shakl[/b] ✅\n"
        "➡️ [b]Present Continuous Passive:[/b] [b]am/is/are being + 3-shakl[/b] 🔄\n\n"
        "✅ [b]Present Perfect Passive misollar:[/b]\n"
        "• The work has been finished. – Ish tugatildi. ✔️\n"
        "• Many emails have been sent today. – Ko‘plab email'lar bugun yuborildi. 📧\n\n"
        "❓ [b]Savol shakli:[/b]\n"
        "• Has the room been cleaned? – Xona tozalangani bormi? 🧽\n\n"
        "🚫 [b]Inkor shakli:[/b]\n"
        "• The papers haven’t been signed. – Qog‘ozlar imzolanmagan. 📝\n\n"
        "🔄 [b]Present Continuous Passive misollar:[/b]\n"
        "• The house is being painted. – Uy bo‘yalmoqda. 🎨\n"
        "• The floors are being cleaned now. – Pol hozir tozalanmoqda. 🧼\n\n"
        "❓ [b]Savol shakli:[/b]\n"
        "• Is the car being repaired? – Mashina ta’mirlanayaptimi? 🚘\n\n"
        "🚫 [b]Inkor shakli:[/b]\n"
        "• Lunch isn’t being cooked yet. – Tushlik hali tayyorlanmayapti. 🍽️\n\n"
        "🎯 [b]Qo‘shimcha misollar:[/b]\n"
        "• A new road has been built in the city. – Shahar ichida yangi yo‘l qurildi. 🛣️\n"
        "• The windows are being washed now. – Derazalar hozir yuvilmoqda. 🪟\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=idPtxgnyYdo&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=23]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 21,
    "title": "I used to... (O'tmishdagi odatlar va holatlar)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 21[/b] darsimizda [b]\"I used to...\"[/b] iborasini o'rganamiz. Bu ibora ingliz tilida o'tmishdagi odatlarimiz, holatlarimiz yoki faktlarimiz haqida gapirish uchun ishlatiladi. Dars yakunida esa '[b]that[/b]' bog'lovchisining gaplarni bog'lashdagi rolini ham ko'rib chiqamiz. 📝\n\n"
        "[center][b]Grammatik tushuntirish: I used to...[/b][/center]\n"
        "✅ [b]\"Used to\" + fe'l (verb)[/b]\n"
        "[b]Used to + fe'l[/b] (fe'lning asl shakli) iborasi o'tmishda muntazam sodir bo'lgan, ammo [b]hozirda sodir bo'lmaydigan odatlar[/b] yoki o'tmishda haqiqat bo'lgan, ammo [b]hozirda bunday bo'lmagan holatlar[/b] haqida gapirish uchun ishlatiladi. 🔄\n\n"
        "• I used to play basketball every weekend. – Men har dam olish kunlari basketbol o'ynar edim. (Hozir o'ynamayman) 🏀➡️\n"
        "• She used to live in a small village. – U kichik qishloqda yashar edi. (Hozir yashamaydi) 🏡🏞️\n"
        "• There used to be a cinema on this street. – Bu ko'chada kino teatri bo'lar edi. (Hozir yo'q) 🎬🚧\n\n"
        "✅ [b]Bo'lishsiz (Negative) shakli:[/b]\n"
        "Bo'lishsiz shaklini yasash uchun [b]didn't use to[/b] dan foydalanamiz:\n   [b]Ega + didn't use to + fe'l (asl shakli)[/b] ❌\n\n"
        "• He didn't use to like spicy food. – U ilgari achchiq ovqatni yoqtirmas edi. 🌶️❌\n"
        "• We didn't use to have a car. – Bizning ilgari mashinamiz yo'q edi. 🚗🤷‍♀️\n\n"
        "✅ [b]So'roq (Interrogative) shakli:[/b]\n"
        "So'roq shaklini yasash uchun [b]Did + Ega + use to + fe'l (asl shakli)?[/b] dan foydalanamiz: ❓\n\n"
        "• Did you use to walk to school? – Siz maktabga piyoda borar edingizmi? 🚶‍♀️🏫❓\n"
        "• Did they use to visit this park often? – Ular bu bog'ga tez-tez kelishar edimi? 🌳❓\n\n"
        "✅ [b]Muhim eslatma: Faqat o'tmish uchun![/b]\n"
        "[b]Used to[/b] iborasi faqat [b]o'tmishdagi odatlar yoki holatlar[/b] uchun ishlatiladi va [b]hozirgi zamon uchun qo'llanilmaydi[/b]. Hozirgi odatlarni ifodalash uchun Present Simple ishlatiladi. 🕰️\n\n"
        "• I used to play tennis. (O'tmishdagi odat) – Men tennis o'ynar edim. 🎾\n"
        "• Nowadays, I play golf. (Hozirgi odat) – Hozirgi kunda men golf o'ynayman. 🏌️‍♂️\n\n"
        "[center][b]\"That\" bog'lovchisi (Sentence Connector)[/b][/center]\n"
        "🗣️ [b]\"That\"[/b] so'zi ko'pincha murakkab gaplarda ikkita sodda gapni bog'lash uchun ishlatiladi va biror ma'lumotni kiritadi. Ko'p hollarda, ayniqsa norasmiy nutqda, uni tushirib qoldirish mumkin. 🔗\n\n"
        "• I think that she is a very talented artist. – Menimcha, u juda iste'dodli rassom. 🎨\n"
        "• She said that she would be late. – U kechikishini aytdi. ⏰\n"
        "• It is important that you listen carefully. – Siz diqqat bilan tinglashingiz muhimdir. 👂\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=z_gZh4bqGwU&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=27]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 22,
    "title": "Going to (Niyat va Rejalar)",
    "content": "👋 Assalomu alaykum, aziz o‘rganayotganlar! 📘\n\n"
        "Bugun biz [b]kelajakdagi niyat[/b] va [b]reja[/b]lar haqida gaplashamiz. Bunda [b]am/is/are + going to + fe’l[/b] formulasi ishlatiladi. 📝\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• “Going to” — [b]rejalashtirilgan[/b] yoki [b]niyat qilingan[/b] harakatlarni ifodalashda ishlatiladi. 📅\n"
        "Ha, bu o‘sha “go” — ya’ni bormoq fe’li, lekin bu yerda u [i]“moqchi”[/i] ma’nosida tarjima qilinadi. Uning haqiqiy ma’nosi undan keyin keladigan fe’lga bog‘liq bo‘ladi. ✅\n\n"
        "✅ [b]Darak shakli (Affirmative):[/b]\n"
        "• I am going to visit the park. – Men bog‘ga bormoqchiman. 🌳\n"
        "• She is going to learn Spanish. – U ispan tilini o‘rganmoqchi. 🇪🇸\n"
        "• We are going to buy a new car next month. – Biz keyingi oy yangi mashina sotib olmoqchimiz. 🚗\n"
        "• They are going to cook dinner tonight. – Ular bugun kechki ovqat tayyorlamoqchi. 🍝\n\n"
        "❓ [b]So‘roq shakli (Question):[/b]\n"
        "• Is she going to call you? – U sizga qo‘ng‘iroq qilmoqchimi? 📞\n"
        "• Are you going to travel this summer? – Siz bu yozda sayohat qilmoqchimisiz? ✈️\n"
        "• Is he going to apply for a new job? – U yangi ishga topshirmoqchimi? 💼\n\n"
        "🚫 [b]Inkor shakli (Negative):[/b]\n"
        "• They aren’t going to eat out. – Ular tashqarida ovqatlanmoqchi emas. 🍽️\n"
        "• I am not going to watch that movie. – Men u filmni ko‘rmoqchi emasman. 🍿❌\n"
        "• She is not going to quit her job. – U ishdan ketmoqchi emas. 🙅‍♀️\n\n"
        "📝 [b]Qo‘shimcha misollar:[/b]\n"
        "• I am going to help the needy people. – Men muhtojlarga yordam bermoqchiman. 🤝\n"
        "• Is she going to donate? – U xayriya qilmoqchimi? 💰\n"
        "• We are going to have a party. – Biz ziyofat qilmoqchimiz. 🎉\n"
        "• He is going to fix the broken window. – U singan derazani tuzatmoqchi. 🪟\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=H1gZ_EWC2zA&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=28]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 23,
    "title": "Will/Shall (Kelajak Zamon)",
    "content": "👋 Salom, aziz til o‘rganuvchilar! 📚\n\n"
        "Bugun biz [b]kelajakdagi harakatlar[/b] haqida so‘zlashni o‘rganamiz. Bunda [b]will[/b] va [b]shall[/b] ishlatiladi. \n"
        "[b]Shall[/b] ko‘proq rasmiy nutqda, odatda \"I\" va \"we\" bilan taklif bildirganda ishlatiladi. 📌 Ammo bugungi zamonaviy ingliz tilida bu shakl kam qo‘llaniladi, shuning uchun asosan [b]will[/b] ga e'tibor qaratishingiz mumkin.\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• I/You/He/She/We/They + [b]will[/b] + fe’l (asosiy harakat)\n"
        "• (I/We + [b]shall[/b] + fe’l — rasmiy yoki taklif shakllarida)\n\n"
        "✅ [b]Affirmative (Darak) jumlalar:[/b]\n"
        "• I [b]will cook[/b] meat for dinner. 🍖 – Men kechki ovqat uchun go‘sht pishiraman.\n"
        "• They [b]will visit[/b] the museum tomorrow. 🏛️ – Ular ertaga muzeyga borishadi.\n"
        "• We [b]shall meet[/b] again soon. 🤝 – Tez orada yana uchrashamiz. (rasmiy)\n"
        "• My sister [b]will travel[/b] to Italy next month. ✈️ – Singlim kelasi oy Italiyaga sayohat qiladi.\n"
        "• The sun [b]will rise[/b] at 6 AM. 🌅 – Quyosh soat 6 da chiqadi.\n"
        "• You [b]will enjoy[/b] this movie. 🎬 – Sizga bu film yoqadi.\n"
        "• He [b]will help[/b] the old man. 👴 – U cholga yordam beradi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=49MkAq6fdSA&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=29]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 24,
    "title": "Will Not / Will You (Rad etish va Taklif)",
    "content": "👋 Salom, bilim izlovchi do‘stlar! 🧠\n\n"
        "Avvalgi darsda biz [b]Will/Shall[/b] bilan kelasi zamon shakllarni o‘rgandik. Endi esa [i]inkor (negative)[/i] va [i]savol (question)[/i] shakllarini o‘rganamiz! 🚫❓\n\n"
        "📌 [b]Qisqacha qoida:[/b]\n"
        "• [b]Will not[/b] (yoki qisqargan shakli: [b]won’t[/b]) — rad etish uchun ishlatiladi.\n"
        "• [b]Will you...?[/b] — kimdandir nimanidir so‘rash yoki taklif qilishda ishlatiladi.\n\n"
        "✅ [b]Misollar – Inkor shakllar:[/b]\n"
        "• I [b]will not[/b] accept the offer. ❌ – Men taklifni qabul qilmayman.\n"
        "• They [b]won’t go[/b] to the party. 🥳🚫 – Ular ziyofatga bormaydi.\n"
        "• She [b]won’t eat[/b] meat. 🍖🚫 – U go‘sht yemaydi.\n"
        "• We [b]will not play[/b] football today. ⚽ – Biz bugun futbol o‘ynamaymiz.\n"
        "• My brother [b]won’t help[/b] with homework. 📚 – Akam uy vazifasiga yordam bermaydi.\n\n"
        "❓ [b]Misollar – Savol shakllar:[/b]\n"
        "• [b]Will you[/b] help me? 🙋 – Menga yordam berasizmi?\n"
        "• [b]Will she[/b] call you? 📞 – U sizga qo‘ng‘iroq qiladimi?\n"
        "• [b]Will they[/b] join the trip? 🧳 – Ular safarga qo‘shiladimi?\n"
        "• [b]Will we[/b] have a meeting tomorrow? 📅 – Ertaga yig‘ilishimiz bo‘ladimi?\n"
        "• [b]Will your father[/b] cook dinner? 👨‍🍳 – Otangiz kechki ovqat pishiradimi?\n\n"
  },
  {
    "lesson": 25,
    "title": "May and Might (Ehtimollik)",
    "content": "👋 Salom, bilimli do‘stlar! 😊\n\n"
        "Bugungi darsimizdan boshlab biz [b]modal fe'llar[/b] (Modal Verbs) mavzusini o'rganishni boshlaymiz. Modal fe'llar asosiy fe'lga yordamchi bo'lib keladi va [b]qobiliyat, majburiyat, ruxsat yoki ehtimollik[/b] kabi ma'nolarni ifodalaydi. Ular alohida fe'llar bo'lib, o'ziga xos qoidalariga ega. 📝\n\n"
        "Bugun biz birinchi modal fe'llarimiz – [b]May[/b] va [b]Might[/b] so‘zlarini o‘rganamiz. Ular biror narsa sodir bo‘lishi [i]mumkinligini[/i] yoki ruxsat so‘rashni bildiradi. 🔮\n\n"
        "📌 [b]Qisqacha qoida:[/b]\n"
        "• [b]May[/b] – nisbatan [b]yuqori ehtimollikni[/b] bildiradi yoki ruxsat so‘rash/berishda ishlatiladi. ✅\n"
        "• [b]Might[/b] – [b]kamroq ehtimollikni[/b] bildiradi. 🤏\n\n"
        "✅ [b]Ehtimollik – Misollar:[/b]\n"
        "• It may rain tomorrow. – Ertaga yomg'ir yog'ishi mumkin. 🌧️\n"
        "• She might come to the party. – U ziyofatga kelishi mumkin. 🥳\n"
        "• They may be busy now. – Ular hozir band bo'lishi mumkin. 🕒\n"
        "• He might forget the meeting. – U yig'ilishni unutishi mumkin. 🤔\n"
        "• We may go to the mountains this weekend. – Bu hafta oxiri tog‘larga borishimiz mumkin. 🏔️\n\n"
        "🤝 [b]May ruxsat so'rash uchun ham ishlatiladi – Misollar:[/b]\n"
        "• May I ask a question? – Savol bersam maylimi? ❓\n"
        "• You may leave early today. – Bugun erta ketishingiz mumkin. ⏰\n"
        "• May I come in? – Kirsam maylimi? ❓\n"
        "• May I sit here? – Bu yerga o‘tirsam bo‘ladimi? 🪑\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=Lta1sfBIXCY&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=31]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 26,
    "title": "Can and Could (Qobiliyat va Imkoniyat)",
    "content": "👋 Salom, bilimli do‘stlar! 📘\n\n"
        "Bugun biz [b]can[/b] va [b]could[/b] yordamchi fe’llari orqali [b]qobiliyat[/b], [b]imkoniyat[/b] yoki [b]ruxsat[/b] haqida qanday gapirishni o‘rganamiz. \n\n"
        "🔎 [b]Can[/b] – hozirgi zamonda nimagadir qodir bo‘lish (biror ishni qila olish) ma’nosida ishlatiladi.\n"
        "🔎 [b]Could[/b] – o'tgan zamonda biror ishni qila olganlik yoki rasmiy/muloyim shaklda ehtiyotkorona taklif, iltimos yoki ruxsat so‘rashda ishlatiladi.\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• I/You/He/She/We/They + [b]can/could[/b] + fe’l (asosiy harakat)\n\n"
        "✅ [b]Affirmative (Ijobiy) jumlalar:[/b]\n"
        "• [b]I can speak English.[/b] 🗣️ – Men ingliz tilida gapira olaman.\n"
        "• [b]She can swim very well.[/b] 🏊‍♀️ – U juda yaxshi suza oladi.\n"
        "• [b]They can solve this problem.[/b] 🧠 – Ular bu muammoni hal qila olishadi.\n"
        "• [b]We can improve our pronunciation.[/b] 🔊 – Biz talaffuzimizni yaxshilashimiz mumkin.\n"
        "• [b]He could read at the age of four.[/b] 📖 – U to‘rt yoshida o‘qiy olardi.\n"
        "• [b]My grandfather could play the violin beautifully.[/b] 🎻 – Bobom skripkada chiroyli chalardi.\n"
        "• [b]They could travel anywhere they wanted.[/b] 🌍 – Ular xohlagan joyga sayohat qila olishardi.\n\n"
        "[center][b]💡 \"Be able to\" iborasi[/b][/center]\n"
        "🗣️ [b]\"Be able to\"[/b] iborasi [b]can[/b] va [b]could[/b] fe'llariga ma'no jihatidan tengdir va ko'pincha ular o'rnida ishlatilishi mumkin. Bu ibora [b]can[/b] yoki [b]could[/b] ishlatib bo'lmaydigan zamonlarda (masalan, Future Simple, Present Perfect, Gerund) ayniqsa foydalidir.\n\n"
        "• [b]I am able to speak English.[/b] 🗣️\n"
        "  Men ingliz tilida gapira olaman. (Can speak ga teng)\n"
        "• [b]She was able to swim very well when she was young.[/b] 🏊‍♀️\n"
        "  U yoshligida juda yaxshi suza olardi. (Could swim ga teng)\n"
        "• [b]They will be able to solve this problem tomorrow.[/b] 🧠\n"
        "  Ular bu muammoni ertaga hal qila olishadi. (Bu yerda 'can' ishlatilmaydi)\n"
        "• [b]Having been able to travel has changed her perspective.[/b] ✈️\n"
        "  Sayohat qila olganligi uning dunyoqarashini o'zgartirdi. (Bu yerda 'can' ishlatilmaydi)\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=lSakX0FIkgg&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=32]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 27,
    "title": "Can and Could in Questions and Negatives (Savollar va Inkorlar)",
    "content": "👋 Salom, bilim izlovchilar! 🔍\n\n"
        "Bugun [b]can[/b] va [b]could[/b] yordamida [b]savol[/b] va [b]inkor[/b] gaplar tuzishni o‘rganamiz. Bu shakllar orqali siz biror ishni qila olmaslik yoki biror narsani so‘rash (ruxsat, iltimos) haqida gapira olasiz.\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• [b]Savollar:[/b] Can/Could + ega + fe’l\n"
        "• [b]Inkor:[/b] Ega + can’t/can not / couldn’t + fe’l\n\n"
        "❓ [b]Questions (Savollar):[/b]\n"
        "• [b]Can you[/b] help me with this? 🙋 – Menga bu borada yordam bera olasizmi?\n"
        "• [b]Can she[/b] cook dinner today? 🍳 – U bugun kechki ovqat tayyorlay oladimi?\n"
        "• [b]Could they[/b] solve the puzzle? 🧩 – Ular jumboqni yecha olishadimi?\n"
        "• [b]Could I[/b] borrow your book? 📘 – Kitobingizni olsam bo‘ladimi?\n\n"
        "🚫 [b]Negatives (Inkorlar):[/b]\n"
        "• I [b]can’t understand[/b] this text. 📄 – Men bu matnni tushunmayapman.\n"
        "• She [b]can’t drive[/b] a car. 🚗 – U mashina hayday olmaydi.\n"
        "• They [b]couldn’t come[/b] to the meeting. ⏰ – Ular uchrashuvga kela olishmadi.\n"
        "• We [b]couldn’t find[/b] the address. 🗺️ – Biz manzilni topa olmadik.\n\n"
  },
  {
    "lesson": 28,
    "title": "Must (Zarurat va Majburiyat)",
    "content": "👋 Salom, bilimga chanqoq do‘stlar! 📘\n\n"
        "Bugun biz [b]majburiyat[/b] va [b]zaruratni[/b] bildiruvchi [b]must[/b] yordamchi fe’lini o‘rganamiz. Bu so‘z orqali biror ishni qilish [i]shart[/i] yoki [i]zarur[/i] ekanligini ifodalaymiz.\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• Must + fe’l (asosiy harakat)\n"
        "• [b]Must[/b] hozirgi va kelajakdagi majburiyatlar uchun ishlatiladi.\n"
        "• Biz bu fe’lni asosan [b]affirmative[/b] (tasdiq) holatda ishlatamiz.\n"
        "• [b]Negative[/b] (inkor) shakllari ham mavjud: [b]must not[/b] yoki qisqacha [b]mustn't[/b].\n"
        "• [u]Savol shakllari esa juda kam ishlatiladi.[/u]\n\n"
        "✅ [b]Affirmative(Darak):[/b]\n"
        "• You [b]must finish[/b] your homework. 📝 – Siz uy vazifangizni tugatishingiz kerak.\n"
        "• I [b]must sleep[/b] early tonight. 😴 – Men bugun kechqurun erta uxlashim kerak.\n"
        "• They [b]must follow[/b] the instructions. 📋 – Ular ko‘rsatmalarga amal qilishlari kerak.\n"
        "• We [b]must be careful[/b] with money. 💰 – Pulga ehtiyotkorlik bilan munosabatda bo‘lishimiz kerak.\n\n"
        "🚫 [b]Negative (Inkor):[/b]\n"
        "• She [b]must not be[/b] late. ⏰ – U kechikmasligi kerak.\n"
        "• You [b]mustn’t forget[/b] your ID. 🪪 – Siz shaxsiy guvohnomangizni unutmasligingiz kerak.\n\n"
