        "[link=https://www.youtube.com/watch?v=ppwXw2Dh-l0&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=33]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 29,
    "title": "Should (Maslahat)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 📖\n\n"
        "Bugun biz [b]should[/b] yordamida qanday qilib [b]maslahat berish[/b] yoki [b]zarur tavsiyalar[/b] aytishni o‘rganamiz. Bu so‘z kimdandir biror ishni qilishni tavsiya qilganimizda ishlatiladi. 📝\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• Should + fe’l (asosiy harakat)\n"
        "• Bu yordamchi fe’l maslahat, keraklilik yoki muloyim tavsiya bildiradi. ✅\n\n"
        "✅ [b]Affirmative(Darak):[/b]\n"
        "• You [b]should call[/b] your friend. ☎️ – Siz do‘stingizga qo‘ng‘iroq qilishingiz kerak.\n"
        "• I [b]should drink[/b] more water. 💧 – Men ko‘proq suv ichishim kerak.\n"
        "• We [b]should study[/b] for the test. 📚 – Biz testga tayyorlanishimiz kerak.\n"
        "• He [b]should help[/b] his parents. 👨‍👩‍👦 – U ota-onasiga yordam berishi kerak.\n\n"
        "🚫 [b]Negative (Inkor):[/b]\n"
        "• She [b]should not ignore[/b] the problem. ⚠️ – U muammoni e’tiborsiz qoldirmasligi kerak.\n"
        "• You [b]shouldn't eat[/b] too much sugar. 🍬 – Siz juda ko‘p shakar iste’mol qilmasligingiz kerak.\n\n"
        "❓ [b]Questions (Savollar):[/b]\n"
        "• [b]Should I take[/b] an umbrella? ☔ – Soyabon olishim kerakmi?\n"
        "• [b]Should we wait[/b] here? 🕒 – Biz shu yerda kutishimiz kerakmi?\n\n"
        "📝 [b]Qo‘shimcha misollar:[/b]\n"
        "• You [b]should take[/b] an umbrella; it’s cloudy. – Soyabon olganingiz yaxshi; havo bulutli.\n"
        "• She [b]should stay[/b] indoors if it’s rainy. – Agar yomg‘ir yog‘sa, u uyda qolishi kerak.\n"
        "• [b]Should they help[/b] us with the work? – Ular bizga ishda yordam berishlari kerakmi?\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=0PjvlBq5S5o&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=34]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 30,
    "title": "Have to (Zarurat va Majburiyat)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 📚\n\n"
        "Bugun biz [b]have to[/b] yordamida [b]zarurat[/b] va [b]majburiyat[/b]ni ifodalashni o‘rganamiz. Bu so‘z biror ishni qilish shart yoki kerakligini bildiradi. [b]Have to[/b] — \"majburman\" yoki \"qilishim kerak\" degani. [b]He/She/It[/b] bilan [b]has to[/b] shakli ishlatiladi. 📝\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• I/You/We/They [b]have to[/b] + fe’l\n"
        "• He/She/It [b]has to[/b] + fe’l\n\n"
        "✅ [b]Affirmative(Darak):[/b]\n"
        "• I [b]have to finish[/b] my homework. ✍️ – Men uy vazifamni tugatishim kerak.\n"
        "• She [b]has to attend[/b] the meeting. 🏢 – U yig‘ilishda qatnashishi kerak.\n"
        "• We [b]have to be[/b] ready at 7 o’clock. 🕖 – Biz soat 7 da tayyor bo‘lishimiz kerak.\n"
        "• He [b]has to wear[/b] a uniform at work. 👔 – U ishda forma kiyishi kerak.\n"
        "• They [b]have to follow[/b] the rules. 📜 – Ular qoidalarga amal qilishlari kerak.\n"
        "• You [b]have to pay[/b] before entering. 💳 – Siz kirishdan oldin to‘lashingiz kerak.\n"
        "• My brother [b]has to take[/b] his medicine every day. 💊 – Akam har kuni dorisini ichishi kerak.\n"
        "• I [b]have to go[/b] to the bank tomorrow. 🏦 – Men ertaga bankka borishim kerak.\n"
        "• We [b]have to clean[/b] the house today. 🧹 – Bugun uyni tozalashimiz kerak.\n"
        "• The teacher [b]has to check[/b] all the homework. 📝 – O‘qituvchi barcha vazifalarni tekshirishi kerak.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=qgdclNoDQIs&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=35]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 31,
    "title": "Would You Like and I’d Like (Taklif va Istak)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 😊\n\n"
        "Bugun biz [b]taklif qilish[/b] va [b]istak bildirish[/b] haqida gaplashamiz. Bunda [b]Would you like...?[/b] va [b]I'd like...[/b] (I would like qisqartmasi) shakllari ishlatiladi. Eslatib o'tamiz would like bu want(xohlamoq) ning muloyim shakli. 📝\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• [b]Would you like[/b] + ot / to + fe’l – Sizga ... kerakmi? / ... qilishni xohlaysizmi?\n"
        "• [b]I’d like[/b] + ot / to + fe’l – Men ... xohlayman\n\n"
        "✅ [b]Affirmative(Darak):[/b]\n"
        "• I’d like a cup of tea. 🍵 – Men bir piyola choy xohlayman.\n"
        "• I’d like to go for a walk. 🚶 – Men yurishga chiqishni xohlayman.\n"
        "• I’d like some rest. 😌 – Men biroz dam olishni xohlayman.\n"
        "• I’d like to read that book. 📖 – Men o‘sha kitobni o‘qishni xohlayman.\n"
        "• I’d like to meet your friend. 🧑‍🤝‍🧑 – Men do‘stingiz bilan tanishishni xohlayman.\n\n"
        "❓ [b]Question (Taklif):[/b]\n"
        "• Would you like some coffee? ☕ – Sizga qahva kerakmi?\n"
        "• Would you like to join us? 🤝 – Bizga qo‘shilishni xohlaysizmi?\n"
        "• Would you like to watch a movie? 🎬 – Kino ko‘rishni xohlaysizmi?\n"
        "• Would you like an apple? 🍎 – Olma xohlaysizmi?\n"
        "• Would you like to visit the museum? 🏛️ – Muzeyga borishni xohlaysizmi?\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
