  {
    "lesson": 32,
    "title": "Adjectives (Sifatlar)",
    "content": "👋 Salom, do‘stlar! 😊\n\n"
        "Boy, uzun, ko'p, sariq, olifta, hayolparast, baxtli. Bu so'zlarni umumiy nima birlashtiradi bilasizmi? Bular hammasi sifatlar. Bugungi darsimizda [b]Adjectives[/b] – ya’ni [b]sifatlar[/b] bilan tanishamiz. Sifatlar [b]otlarni qanday ekanini[/b] yoki [b]ahvolini[/b] bildiradi. 📝\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• Sifatlar [b]otlardan oldin[/b] keladi: a [b]big house[/b], a [b]red ball[/b].\n"
        "• Yoki [b]to be[/b] fe'li bilan birga ishlatiladi: She [b]is tired[/b].\n\n"
        "✅ [b]Misollar:[/b]\n"
        "• I have a brown bag. 🎒 – Mening [b]jigarrang[/b] sumkam bor.\n"
        "• The cake was delicious. 🍰 – Tort [b]mazali[/b] edi.\n"
        "• She is happy today. 😊 – U bugun [b]baxtli[/b].\n"
        "• This book is interesting. 📚 – Bu kitob [b]qiziqarli[/b].\n"
        "• They are tired after the game. 😴 – Ular o‘yindan keyin [b]charchagan[/b].\n"
        "• He has a new phone. 📱 – Uning [b]yangi[/b] telefoni bor.\n"
        "• It’s a hot day. ☀️ – Bugun [b]issiq[/b] kun.\n"
        "• She wore a beautiful dress. 👗 – U [b]chiroyli[/b] ko‘ylak kiydi.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=OaPMtoGixBs&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=85]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 33,
    "title": "Adverbs (Ravishlar): Harakatni Qanday Tasvirlaymiz?",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 33[/b] darsimizda ingliz tilidagi muhim so'z turkumlaridan biri – [b]Ravishlar (Adverbs)[/b] haqida gaplashamiz. Ravishlar gapda harakatni, sifatni yoki boshqa ravishni qanday tasvirlashimizga yordam beradi. 🏃‍♀️💨\n\n"
        "[center][b]Ravishlar nima?[/b][/center]\n"
        "Ravishlar – bu fe'llarni (harakatlarni), sifatlarni (narsalarni tasvirlovchi so'zlarni) yoki boshqa ravishlarni tasvirlovchi so'zlardir. Ular bizga biror ish [b]qanday (how?)[/b], [b]qachon (when?)[/b], [b]qayerda (where?)[/b], [b]qanchalik tez-tez (how often?)[/b] yoki [b]qaysi darajada (to what extent?)[/b] sodir bo'lganligini aytib beradi. 📝\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Sifat + -ly = Ravish[/b]\n"
        "Ko'pchilik ravishlar sifatlarga [b]\"-ly\"[/b] qo'shimchasini qo'shish orqali yasaladi.\n\n"
        "• Quick (tez) → [b]Quickly[/b] (tezlik bilan) 🚀\n"
        "• Careful (ehtiyotkor) → [b]Carefully[/b] (ehtiyotkorlik bilan) 🧐\n"
        "• Sudden (to'satdan) → [b]Suddenly[/b] (to'satdan) 😮\n    • Quiet (sokin) → [b]Quietly[/b] (sokinlik bilan) 🤫\n\n"
        "• He spoke quietly to the child. 🤫👶\n"
        "  U bolaga sokin gapirdi.\n"
        "• The car stopped suddenly. 🚗🛑\n"
        "  Mashina to'satdan to'xtadi.\n\n"
        "✅ [b]Harakatni tasvirlash (Adverbs of Manner)[/b]\n"
        "Ravishlar ko'pincha harakatning [b]qanday[/b] bajarilganini ko'rsatadi.\n\n"
        "• She drives safely. 🚘✅\n"
        "  U xavfsiz haydaydi.\n"
        "• He sings beautifully. 🎤🎶\n"
        "  U chiroyli kuylaydi.\n\n"
        "Sifat va ravishni solishtirish:\n"
        "• She is a careful driver. (Sifat) 👩‍🔬\n"
        "  U ehtiyotkor haydovchi.\n"
        "• She drives carefully. (Ravish) 🚗\n"
        "  U ehtiyotkorlik bilan haydaydi.\n\n"
        "✅ [b]Sifat va ravish bir xil bo'lgan so'zlar[/b]\n"
        "Ba'zi so'zlar sifat sifatida ham, ravish sifatida ham bir xil shaklga ega. Bularga [b]hard[/b], [b]fast[/b], [b]late[/b], [b]early[/b] kabi so'zlar kiradi.\n\n"
        "• It was a hard exam. (Sifat) ✍️\n"
        "  Bu qiyin imtihon edi.\n"
        "• She worked hard. (Ravish) 💼💪\n"
        "  U qattiq ishladi.\n\n"
        "• He is a fast runner. (Sifat) 🏃‍♂️\n"
        "  U tez yuguruvchi.\n"
        "• He runs fast. (Ravish) 💨\n"
        "  U tez yuguradi.\n\n"
        "✅ [b]Good (Sifat) va Well (Ravish)[/b]\n"
        "[b]Good[/b] har doim [b]sifat[/b] bo'ladi va narsalarni tasvirlaydi. [b]Well[/b] esa odatda [b]ravish[/b] bo'lib, harakatni tasvirlaydi.\n\n"
        "• Her English is very good. (Sifat) ✅\n"
        "  Uning ingliz tili juda yaxshi.\n"
        "• She speaks English very well. (Ravish) 🗣️\n"
        "  U ingliz tilida juda yaxshi gapiradi.\n\n"
        "'''Eslatma: [b]Well[/b] ba'zan sifat sifatida ham ishlatilishi mumkin, \"sog'lom\" ma'nosida.\n\" '''\n"
        "• I'm not feeling well today. 🤒\n"
        "  Bugun o'zimni yaxshi his qilmayapman.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=rDdj4I2FSZg&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=86]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 34,
    "title": "There is/are (Bor)",
    "content": "👋 Salom, do‘stlar! 😊\n\n"
        "Bugungi darsimizda [b]There is / There are[/b] — ya'ni [b]mavjudlikni bildirish[/b] haqida o‘rganamiz. Bu tuzilma biror narsa yoki kishining [i]qayerdadir mavjudligini[/i] ko‘rsatadi. 📝\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• [b]There is[/b] – [i]bir dona (yakka) narsalar[/i] uchun ishlatiladi.\n"
        "• [b]There are[/b] – [i]ko‘plikdagi narsalar[/i] uchun ishlatiladi.\n\n"
        "✅ [b]Affirmative(Darak):[/b]\n"
        "• There is a book on the table. 📚 – Stolda [i]kitob[/i] bor.\n"
        "• There are many people in the park. 🌳 – Bog‘da [i]ko‘p odamlar[/i] bor.\n"
        "• There is a white car in the garage. 🚗 – Garajda [i]oq mashina[/i] bor.\n"
        "• There are white flowers in the garden. 🌼 – Bog‘da [i]oq gullar[/i] bor.\n"
        "• There is a letter for you. ✉️ – Siz uchun [i]xat[/i] bor.\n"
        "• There are some apples in the basket. 🍎 – Savatda [i]olmalar[/i] bor.\n\n"
        "❌ [b]Negative (Inkor):[/b]\n"
        "• There isn’t a book on the table. ❌📚 – Stolda [i]kitob yo‘q[/i].\n"
        "• There aren’t many people in the park. ❌🌳 – Bog‘da [i]ko‘p odamlar yo‘q[/i].\n"
        "• There isn’t any water in the glass. ❌💧 – Stakanda [i]umuman suv yo‘q[/i].\n"
        "• There aren’t any flowers in the garden. ❌🌼 – Bog‘da [i]gullar yo‘q[/i].\n"
        "• There isn’t a cat under the table. ❌🐱 – Stol ostida [i]mushuk yo‘q[/i].\n\n"
        "❓ [b]Questions (Savollar):[/b]\n"
        "• Is there a book on the table? ❓📖 – Stolda [i]kitob bormi?[/i]\n"
        "• Are there any people in the park? ❓🌳 – Bog‘da [i]odamlar bormi?[/i]\n"
        "• Is there a letter for me? ❓✉️ – Mening ismimga [i]xat bormi?[/i]\n"
        "• Are there white flowers in the garden? ❓🌸 – Bog‘da [i]oq gullar[/i] bormi?\n"
        "• Is there a problem? ❓ – [i]Muammo[/i] bormi?\n\n"
        "[center][b]💡 Eslatma:[/b] \"There’s\" qisqartmasi – \"There is\" o‘rnida ishlatiladi: [i]There’s a dog outside.[/i][/center]\n\n"
        "📝 Mashq uchun savol:\n"
        "📌 What is there in your room?\n"
        "📌 Are there any books in your bag?\n"
        "📌 Is there a window in your classroom?\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=8W-7SdxjfaM&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=37]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 35,
    "title": "There was/were (Bor edi)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 😊\n\n"
        "Bugun biz [b]o‘tmishda mavjud bo‘lgan narsalar[/b] haqida gaplashamiz. Buning uchun [b]There was[/b] va [b]There were[/b] tuzilmalaridan foydalanamiz. 📝\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "• [b]There was[/b] – [i]bir dona (yakka) narsalar[/i] uchun.\n"
        "• [b]There were[/b] – [i]ko‘plikdagi narsalar[/i] uchun.\n\n"
        "✅ [b]Affirmative(Darak):[/b]\n"
        "• There was a book on the table. 📕 – Stolda [i]kitob bor edi[/i].\n"
        "• There were many people in the park. 🌳 – Bog‘da [i]ko‘p odamlar bor edi[/i].\n"
        "• There was a wallet on the table. 👛 – Stolda [i]hamyon bor edi[/i].\n"
        "• There were chairs in the corner of the garden. 🪑 – Bog‘ning burchagida [i]stullar bor edi[/i].\n"
        "• There was a problem yesterday. ❗ – Kecha [i]muammo[/i] bor edi.\n"
        "• There were children in the room. 👧🧒 – Xonada [i]bolalar[/i] bor edi.\n\n"
        "❌ [b]Negative (Inkor):[/b]\n"
        "• There wasn’t a book on the table. ❌📖 – Stolda [i]kitob yo‘q edi[/i].\n"
        "• There weren’t many people in the park. ❌🌳 – Bog‘da [i]ko‘p odamlar yo‘q edi[/i].\n"
        "• There wasn’t any water in the glass. ❌💧 – Stakanda [i]suv yo‘q edi[/i].\n"
        "• There weren’t any flowers in the garden. ❌🌼 – Bog‘da [i]gullar yo‘q edi[/i].\n"
        "• There wasn’t a bus at 8 o’clock. 🚌 – Soat 8 da [i]avtobus yo‘q edi[/i].\n\n"
        "❓ [b]Questions (Savollar):[/b]\n"
        "• Was there a book on the table? ❓📖 – Stolda [i]kitob bor edi mi?[/i]\n"
        "• Were there many people in the park? ❓🌳 – Bog‘da [i]ko‘p odamlar bor edi mi?[/i]\n"
        "• Was there a cat under the chair? ❓🐱 – Stul ostida [i]mushuk bor edi mi?[/i]\n"
        "• Were there chairs in the room? ❓🪑 – Xonada [i]stullar bor edi mi?[/i]\n"
        "• Was there a mistake in the text? ❓📄 – Matnda [i]xatolik bor edi mi?[/i]\n\n"
        "[center][b]💡 Eslatma:[/b] \"There was\" va \"There were\" o‘tgan zamon (past simple) shakllaridir. Ular hozirgi zamondagi \"There is/are\" ga o‘xshaydi, faqat o‘tmishdagi holatni bildiradi.[/center]\n\n"
        "📝 Mashq uchun savollar:\n"
        "📌 Was there anything in your bag yesterday?\n"
        "📌 Were there any guests at your home last night?\n"
        "📌 Was there a test in school yesterday?\n\n"
