  },
  {
    "lesson": 36,
    "title": "It... (Shaxsiz Ega 'It')",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 36[/b] darsimizda ingliz tilida juda ko'p ishlatiladigan [b]\"It\"[/b] olmoshi haqida gaplashamiz. Ayniqsa, u qanday qilib shaxsiz ega sifatida ishlatilishi va vaqt, kun, masofa yoki ob-havo haqida gapirganda qanday ahamiyatga ega ekanligini ko'rib chiqamiz. 📝\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "🗣️ Ingliz tilida gaplar odatda ega bilan boshlanishi kerak. Agar gapda aniq bir ega bo'lmasa, [b]\"It\"[/b] shaxsiz ega sifatida ishlatiladi.\n\n"
        "✅ [b]Vaqt (Time) uchun \"It\"[/b]\n"
        "Vaqt haqida gapirganda [b]\"It\"[/b] ishlatiladi.\n"
        "• What time is it? ⏰❓ - Soat nechchi?\n"
        "• It's ten past three. 🕒 - Soat uchdan o'n daqiqa o'tdi.\n"
        "• It's getting late. 🌙 - Kech bo'lib bormoqda.\n\n"
        "✅ [b]Kun (Day) uchun \"It\"[/b]\n"
        "Kunlar, sanalar va bayramlar haqida gapirganda [b]\"It\"[/b] ishlatiladi.\n"
        "• What day is it today? 🗓️❓ - Bugun qaysi kun?\n"
        "• It's Friday. 🎉 - Bugun juma.\n"
        "• It was my birthday last week. 🎂 - O'tgan hafta mening tug'ilgan kunim edi.\n\n"
        "✅ [b]Masofa (Distance) uchun \"It\"[/b]\n"
        "Masofa haqida gapirganda [b]\"It\"[/b] ishlatiladi.\n"
        "• How far is it to the nearest shop? 🚶‍♀️🛍️❓ - Eng yaqin do'konga qancha masofa bor?\n"
        "• It's about two kilometers from here. 🗺️ - Bu yerdan taxminan ikki kilometr.\n"
        "• It's a long way to the top of the mountain. 🏔️ - Tog' cho'qqisiga uzoq yo'l.\n\n"
        "✅ [b]Ob-havo (Weather) uchun \"It\"[/b]\n"
        "Ob-havo sharoitlari haqida gapirganda [b]\"It\"[/b] ishlatiladi.\n"
        "• It's raining heavily outside. 🌧️ - Tashqarida qattiq yomg'ir yog'moqda.\n"
        "• Is it snowing now? 🌨️❓ - Hozir qor yog'yaptimi?\n"
        "• It was very windy yesterday. 🌬️ - Kecha juda shamolli edi.\n"
        "• It's a beautiful sunny day. ☀️😊 - Bugun go'zal quyoshli kun.\n\n"
        "✅ [b]\"It's + sifat + to do something\" tuzilmasi[/b]\n"
        "Biror ishni qilish haqida fikr bildirish yoki tasvirlash uchun [b]\"It's + sifat + to + fe'l\"[/b] tuzilmasidan foydalanamiz.\n"
        "• It's easy to learn new things. 💡 - Yangi narsalarni o'rganish oson.\n"
        "• It's important to study regularly. 📚 - Muntazam o'qish muhim.\n"
        "• It's difficult to understand complex theories. 🧠❓ - Murakkab nazariyalarni tushunish qiyin.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=stCZZfcZhv4&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=40]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 37,
    "title": "Who va What savol olmoshlari (Kim? Nima?)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 37[/b] darsimizda biz savol berishda juda muhim bo'lgan [b]\"who\"[/b] (kim) va [b]\"what\"[/b] (nima) savol olmoshlaridan qanday to'g'ri foydalanishni o'rganamiz. Bu olmoshlarning gapdagi o'rni savolning tuzilishiga ta'sir qiladi. 📝\n\n"
        "[center]Grammatik tushuntirish[/center]\n"
        "Biz [b]who[/b] ni odamlar (kim) haqida, [b]what[/b] ni esa narsalar yoki g'oyalar (nima) haqida savol berish uchun ishlatamiz.\n\n"
        "✅ [b]Who/What gapning egasi (subject) bo'lsa[/b]\n"
        "Agar [b]who[/b] yoki [b]what[/b] gapda [b]ega[/b] vazifasini bajarsa, biz [b]do/does/did[/b] yordamchi fe'llaridan foydalanmaymiz. Savol tuzilishi oddiy darak gapga o'xshash bo'ladi, faqat ega o'rnida [b]who[/b] yoki [b]what[/b] turadi.\n\n"
        "• Who ate this chocolate? - Kim bu shokoladni yedi? 🍫\n"
        "• What happened? - Nima sodir bo'ldi? ❓\n"
        "• Who is your favorite singer? - Kim sening sevimli qo'shiqching? 🎤\n"
        "• What is in this box? - Bu qutida nima bor? 📦\n\n"
        "✅ [b]Who/What gapning to'ldiruvchisi (object) bo'lsa[/b]\n"
        "Agar [b]who[/b] yoki [b]what[/b] gapda [b]to'ldiruvchi[/b] (ob'ekt) vazifasini bajarsa, biz odatdagi savol tuzilishidan foydalanamiz, ya'ni [b]do/does/did[/b] yordamchi fe'llari (yoki boshqa yordamchi fe'llar) ishlatiladi.\n\n"
        "• Who did you meet yesterday? - Siz kecha kimni uchratdingiz? 👤\n"
        "• What did Anna say? - Anna nima dedi? 💬\n"
        "• Who are you phoning? - Kimga telefon qilyapsiz? 📱\n"
        "• What does she have in her briefcase? - Uning portfelida nima bor? 💼\n\n"
        "✅ [b]Who odamlar uchun, What narsalar/g'oyalar uchun[/b]\n"
        "• [b]Who[/b] savoli doimo shaxslar haqida so'rash uchun ishlatiladi.\n"
        "• [b]What[/b] savoli esa narsalar, holatlar, g'oyalar haqida so'rash uchun ishlatiladi.\n\n"
        "• Who is your friend? - Kim sening do'sting? (Odam haqida) 🧍\n"
        "• What is your favorite color? - Nima sening sevimli ranging? (Narsa haqida) 🌈\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=4mrLSvN_Qs4&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=45]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 38,
    "title": "Savol Olmoshlari va Predloglar (Who...to?, What...like?)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 38[/b] darsimizda biz savollarni yanada to'g'ri va tabiiy shaklda tuzishga yordam beradigan muhim qoida – predloglarning savollar oxirida kelishi hamda [b]\"What... like?\"[/b] iborasining qo'llanilishini o'rganamiz. 📝\n\n"
        "[center]Grammatik tushuntirish[/center]\n"
        "✅ [b]Savollar oxirida keladigan predloglar[/b]\n"
        "Ingliz tilida [b]who, what, where, which[/b] kabi savol olmoshlari bilan boshlanadigan gaplarda, agar savol predlogni talab qilsa, bu predlog odatda savolning oxirida keladi. Bu ayniqsa norasmiy so'zlashuv tilida keng tarqalgan.\n\n"
        "• Who are you talking to? 📞 - Kim bilan gaplashyapsan?\n"
        "• Where are you from? 🌍 - Qayerdan siz?\n"
        "• What are you looking at? 👀 - Nimaga qarayapsan?\n"
        "• What was he afraid of? 😨 - U nimadan qo'rqardi?\n"
        "• Who do these books belong to? 📚 - Bu kitoblar kimga tegishli?\n"
        "• What are you waiting for? ⏳ - Nimani kutyapsan?\n"
        "• Which hospital is he in? 🏥 - U qaysi kasalxonada?\n"
        "• Who is she going with? 👫 - U kim bilan ketyapti?\n\n"
        "✅ [b]\"What ... like?\" (Qanday? Nimaga o'xshaydi?)[/b]\n"
        "[b]\"What ... like?\"[/b] iborasi biror narsa yoki shaxsning [b]tavsifini[/b], [b]xususiyatlarini[/b] yoki [b]qandayligini[/b] so'rash uchun ishlatiladi. Bu yerda 'like' fe'l emas, balki 'kabi' ma'nosidagi predlogdir.\n\n"
        "• What's her new house like? 🏡 - Uning yangi uyi qanday?\n"
        "• What was the weather like yesterday? ☀️ - Kechagi ob-havo qanday edi?\n"
        "• What's her new teacher like? 👩‍🏫 - Uning yangi o'qituvchisi qanday?\n"
        "• What are your parents like? 👨‍👩‍👧 - Ota-onangiz qanday insonlar? (Tabiatlari qanday?)\n"
        "• What's the food like in that restaurant? 🍽️ - O'sha restoranda ovqatlar qanday?\n"
        "• What was your holiday like? 🏖️ - Dam olishingiz qanday o'tdi?\n"
        "• What's the new movie like? 🎬 - Yangi film qanday?\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=yBZTL6Kssck&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=46]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 39,
    "title": "What, Which, How (Nima, Qaysi, Qanday)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 😊\n\n"
        "Bugun biz [b]savol so‘zlari[/b] – [b]What[/b] (nima), [b]Which[/b] (qaysi) va [b]How[/b] (qanday) haqida o‘rganamiz. Bu so‘zlar savol berishda ishlatiladi va ularni to‘g‘ri qo‘llash juda muhim! 💡\n\n"
        "🧠 [b]What + ot[/b] (Nima + ot)\n"
        "Ushbu tuzilma cheksiz variantlar ichidan umumiy ma'lumotni so'rash uchun ishlatiladi.\n"
        "• What colour is your car? 🚗 – Mashinangiz qanday rangda?\n"
        "• What size is this shirt? 👕 – Bu ko‘ylak qanday o‘lchamda?\n"
        "• What kind of job do you want? 💼 – Qanday ish qilishni xohlaysiz?\n"
        "• What music do you listen to? 🎶 – Siz qanday musiqani tinglaysiz?\n"
        "• What country are you from? 🌍 – Siz qaysi davlatdansiz?\n\n"
        "🧠 [b]What (otlarsiz)[/b] – Nima?\n"
        "Bu holatda ham umumiy ma'lumot so'raladi, lekin savol olmoshidan keyin to'g'ridan-to'g'ri fe'l keladi.\n"
        "• What’s your favourite colour? 🎨 – Sizning sevimli rangingiz nima?\n"
        "• What happened? 😱 – Nima bo'ldi?\n"
        "• What do you want to do tonight? 🌃 – Bugun kechqurun nima qilishni xohlaysiz?\n"
        "• What's in the box? 📦 – Qutida nima bor?\n\n"
        "🧠 [b]Which + ot[/b] (Qaysi + ot)\n"
        "[b]Which[/b] odatda cheklangan variantlar (masalan, ikkita yoki bir nechta aniq narsa) orasidan tanlovni so'rash uchun ishlatiladi.\n"
        "• Which train did you catch? 🚆 – Qaysi poyezdga chiqdingiz?\n"
        "• Which doctor did you see? 👨‍⚕️ – Qaysi shifokorga ko‘rindingiz?\n"
        "• Which book do you prefer, this one or that one? 📖 – Qaysi kitobni afzal ko'rasiz, bu yoki u?\n"
        "• Which car is yours, the red one or the blue one? 🚗🔵🔴 – Qaysi mashina sizniki, qizilimi yoki ko'kimi?\n\n"
        "🧠 [b]Which (otlarsiz)[/b] – faqat narsalar uchun\n"
        "Cheklangan tanlov bo'lganda, otni tushirib qoldirish mumkin.\n"
        "• Which is bigger — Canada or Australia? 🌎 – Qaysi kattaroq — Kanada yoki Avstraliya?\n"
        "• I have two shirts. Which do you like more? 👕 – Menda ikkita ko'ylak bor. Qaysi biri ko'proq yoqadi?\n"
        "• There are three options. Which would you choose? 🤔 – Uchta variant bor. Qaysi birini tanlaysiz?\n\n"
        "🧠 [b]Who[/b] – faqat odamlar uchun\n"
        "[b]Who[/b] odamlar haqida savol berish uchun ishlatiladi.\n"
        "• Who is taller — Bill or Gerry? 📏 – Kim balandroq — Bill yoki Gerry?\n"
        "• Who broke the window? 👤🔨 – Derazani kim sindirdi?\n"
        "• Who lives in this house? 🏠 – Bu uyda kim yashaydi?\n\n"
        "📌 [b]What vs. Which:[/b]\n"
        "[b]What[/b] umumiy, keng doiradagi ma'lumotni so'raydi. [b]Which[/b] esa aniq bir tanlovni so'raydi, odatda ma'lum bir guruh ichidan.\n"
        "• What is the capital of Argentina? 🇦🇷 – Argentinaning poytaxti qaysi shahar?\n"
        "• Which colour do you prefer, pink or yellow? 🎨 – Qaysi rangni afzal ko‘rasiz, pushti yoki sariq?\n"
        "• What is your favorite sport? ⚽ – Sizning sevimli sport turingiz nima? (Cheksiz sport turlari ichidan)\n"
        "• Which sport do you play: tennis or volleyball? 🎾🏐 – Qaysi sport turini o'ynaysiz: tennismi yoki voleybolmi? (Ikki variant ichidan tanlov)\n\n"
        "🧠 [b]How[/b] – qanday?\n"
        "[b]How[/b] biror narsaning holatini, usulini yoki darajasini so'rash uchun ishlatiladi.\n"
        "• How was the party last night? 🎉 – Kecha kechki ziyofat qanday edi?\n"
        "• How do you usually go to work? 🚌 – Ishga odatda qanday borasiz?\n"
        "• How did you open the box? 🔓 – Qutini qanday ochdingiz?\n"
        "• How do you feel today? 😊 – Bugun o'zingizni qanday his qilyapsiz?\n\n"
        "🧠 [b]How + sifat/ravish:[/b]\n"
        "• How tall are you? 📏 – Bo‘yingiz qancha?\n"
        "• How big is the house? 🏠 – Uy qancha katta?\n"
        "• How old is your mother? 👵 – Onangiz necha yoshda?\n"
        "• How far is it from here to the airport? ✈️ – Bu yerdan aeroportgacha qancha masofa?\n"
        "• How long have you used your car? 🚗 – Mashinangizni qanchadan beri ishlatasiz?\n"
        "• How much was the meal? 🍽️ – Ovqat qancha turdi?\n"
        "• How many books do you have? 📚 – Sizda nechta kitob bor?\n"
        "• How often do you visit your grandparents? 👴👵 – Bobo va buvingizni qanchalik tez-tez borib turasiz?\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=PE7fkwAxH-Y&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=47]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 40,
    "title":
        "Do you know where...? / I don’t know what... (Bilasanmi...? Bilmayman nima...)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 😊\n\n"
        "Bugun biz savollarni bilish/bilmaslik ifodalarida qanday ishlatishni o‘rganamiz: [b]Do you know...?[/b], [b]I don’t know...[/b], [b]Can you tell me...?[/b] va hokazo. Bunda so‘z tartibi oddiy savollardagi kabi emas! ❗\n\n"
        "🧠 [b]Oddiy savol:[/b]\n"
        "• Where is Paula? – Paula qayerda?\n\n"
        "✅ [b]Bilish/bilmaslik shakli:[/b]\n"
        "• Do you know [i]where Paula is[/i]? ❌ (not: where is Paula)\n"
        "• I don’t know [i]where Paula is[/i].\n"
        "• Can you tell me [i]where Paula is[/i].\n\n"
        "💡 [b]Yana misollar:[/b]\n"
        "• Who are those people? 👥 - Do you know [i]who those people are[/i]?\n"
        "• How old is Linda? 🎂 - I don’t know [i]how old Linda is[/i].\n"
        "• What time is it? ⏰ - Can you tell me [i]what time it is[/i]?\n"
        "• Where can I go? 🚶 - Do you know [i]where I can go[/i]?\n"
        "• How much is this camera? 📷 - I don’t remember [i]how much this camera is[/i].\n"
        "• When are you going away? ✈️ - Do you know [i]when you’re going away[/i]?\n"
        "• Where have they gone? 🚗 - I don’t know [i]where they have gone[/i].\n"
        "• What was Ann wearing? 👗 - Can you tell me [i]what Ann was wearing[/i]?\n\n"
        "🧠 [b]Present/Past Simple savollari (do/does/did):[/b]\n"
        "• Where does he live? 🏠 - Do you know [i]where he lives[/i]? ❌ (not: where does he live)\n"
        "• What does Jane want? 🎁 - I don’t know [i]what Jane wants[/i].\n"
        "• Why did she go home? 🏡 - I don’t remember [i]why she went home[/i].\n"
        "• Where did I put the key? 🔑 - I know [i]where I put the key[/i].\n\n"
        "🧠 [b]Yes/No savollar bilan: if / whether[/b]\n"
        "• Is Jack at home? 🏡 - Do you know [i]if Jack is at home[/i]?\n"
        "• Have they got a car? 🚘 - Do you know [i]if they’ve got a car[/i]? yoki [i]whether they’ve got a car[/i]?\n"
        "• Can Brian swim? 🏊 - Do you know [i]if Brian can swim[/i]?\n"
        "• Do they live near here? 📍 - I don’t know [i]whether they live near here[/i].\n"
        "• Did anybody see you? 👀 - I don’t know [i]if anybody saw me[/i].\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=-ZRsTNWQYI4&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=49]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 41,
    "title":
        "She said that... / He told me that... (U aytdiki... / U menga aytdiki...)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 😊\n\n"
        "Bugun biz boshqalarning so‘zlarini [b]reported speech[/b] (o'zlashtirma gap) orqali qanday ifodalashni o‘rganamiz. Ya'ni, kimdir aytgan gapni boshqalarga yetkazish: [b]She said that...[/b] / [b]He told me that...[/b] kabi. ✅\n\n"
        "🧠 [b]Asosiy o‘zgarishlar:[/b]\n"
        "[i]Hozirgi zamondan o‘tgan zamonga o‘zgaradi:[/i]\n"
        "• am / is / are → was / were\n"
        "• do / does → did\n"
        "• have / has → had\n"
        "• can → could\n"
        "• will → would\n"
        "• go → went\n"
        "• look → looked\n"
        "• feel → felt\n\n"
        "📌 [b]Misollar:[/b]\n"
        "• Diane: “I’m enjoying my new job.”\n"
        "→ She said [i]that she was enjoying her new job[/i].\n\n"
        "• Diane: “My father isn’t very well.”\n"
        "→ She said [i]that her father wasn’t very well[/i].\n\n"
        "• Sarah and Tim: “We’re going to buy a house.”\n"
        "→ They said [i]that they were going to buy a house[/i].\n\n"
        "• Peter: “I have to go early.”\n"
        "→ He said [i]that he had to go early[/i].\n\n"
        "• Peter: “My sister has gone to Australia.”\n"
        "→ He said [i]his sister had gone to Australia[/i].\n\n"
        "• Ann: “I can’t find a job.”\n"
        "→ She said [i]she couldn’t find a job[/i].\n\n"
        "• Steve: “I’ll phone you.”\n"
        "→ He said [i]he would phone me[/i].\n\n"
        "• Angela: “I don’t like my job.”\n"
        "→ She said [i]she didn’t like her job[/i].\n\n"
        "• Angela: “My son doesn’t like school.”\n"
        "→ She said [i]her son didn’t like school[/i].\n\n"
        "• Mike: “You look tired.”\n"
        "→ He said [i]I looked tired[/i].\n\n"
        "• Mike: “You feel fine.”\n"
        "→ I said [i]I felt fine[/i].\n\n"
        "🧠 [b]Say / Tell farqi:[/b]\n"
        "• Say – He said that he was tired. ❌ (not: He said me)\n"
        "• Tell – He told me that he was tired. ❌ (not: He told that...)\n"
        "• What did she say to you?\n"
        "• What did she tell you?\n\n"
        "✅ [b]‘That’ bilan yoki ‘that’ siz ham mumkin:[/b]\n"
        "• He said that he was tired. = He said he was tired.\n"
        "• She told me that she didn’t like her job. = She told me she didn’t like her job.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=Bf5vZP4ckyU&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=50]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 42,
    "title":
        "To... (I want to do) va -ing (I enjoy doing) - Fe'llar bilan to-infinitive va -ing ishlatilishi",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 42[/b] darsimizda ingliz tilida fe'llardan keyin keladigan fe'l shakllarini o'rganamiz: [b]to + infinitive[/b] (masalan, [b]to do[/b]) va [b]-ing[/b] qo'shimchali fe'l (masalan, [b]doing[/b]). Ba'zi fe'llardan keyin birinchisi, ba'zilaridan keyin ikkinchisi, ba'zilaridan keyin esa ikkalasi ham kelishi mumkin. Keling, tushunib olaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Fe'llar + to ... (I want to do)[/b]\n"
        "Quyidagi fe'llardan keyin odatda [b]to + fe'lning boshlang'ich shakli[/b] ishlatiladi:\n"
        "• [b]want[/b] (xohlamoq), [b]hope[/b] (umid qilmoq), [b]expect[/b] (kutmoq), [b]plan[/b] (rejalashtirmoq),\n"
        "  [b]decide[/b] (qaror qilmoq), [b]promise[/b] (va'da bermoq), [b]offer[/b] (taklif qilmoq),\n"
        "  [b]refuse[/b] (rad etmoq), [b]try[/b] (urinmoq), [b]forget[/b] (unutmoq), [b]learn[/b] (o'rganmoq).\n\n"
        "• I want to learn English. 📚 – Men ingliz tilini o'rganishni xohlayman.\n"
        "• They decided to move to a new city. 🏘️ – Ular yangi shaharga ko'chishga qaror qilishdi.\n"
        "• He promised to help me. 🙏 – U menga yordam berishga va'da berdi.\n"
        "• She tried to call him but couldn't. 📞 – U unga qo'ng'iroq qilishga urindi, lekin qila olmadi.\n\n"
        "✅ [b]Fe'llar + -ing (I enjoy doing)[/b]\n"
        "Bu fe'llardan keyin fe'lga [b]\"-ing\"[/b] qo'shimchasi qo'shiladi:\n"
        "• [b]enjoy[/b] (zavqlanmoq), [b]mind[/b] (qarshi bo'lmoq), [b]stop[/b] (to'xtatmoq), [b]finish[/b] (tugatmoq), [b]suggest[/b] (taklif qilmoq).\n\n"
        "• I enjoy reading books. 📖 – Men kitob o'qishdan zavqlanaman.\n"
        "• Would you mind opening the window? 🌬️ – Derazani ochib yuborishga qarshi emasmisiz?\n"
        "• She stopped talking suddenly. 🗣️🛑 – U to'satdan gapirishni to'xtatdi.\n"
        "• They suggested going to the cinema. 🎬 – Ular kinoga borishni taklif qilishdi.\n\n"
        "✅ [b]Fe'llar + -ing yoki to ...[/b]\n"
        "Ba'zi fe'llar [b]\"-ing\"[/b] bilan ham, [b]\"to ...\"[/b] bilan ham ishlatilishi mumkin, va ma'nosida deyarli farq bo'lmaydi:\n"
        "• [b]like[/b] (yoqtirmoq), [b]prefer[/b] (afzal ko'rmoq), [b]love[/b] (sevmoq), [b]hate[/b] (yomon ko'rmoq),\n"
        "  [b]start[/b] (boshlamoq), [b]begin[/b] (boshlamoq), [b]continue[/b] (davom etmoq).\n\n"
        "• I like to swim / I like swimming. 🏊‍♀️ – Men suzishni yoqtiraman.\n"
        "• She loves to read / She loves reading. 📖❤️ – U kitob o'qishni juda yaxshi ko'radi.\n"
        "• It started to rain / It started raining. 🌧️ – Yomg'ir yog'a boshladi.\n\n"
        "✅ [b]Would like to ... (va boshqalar)[/b]\n"
        "[b]Would like[/b], [b]would love[/b], [b]would prefer[/b], [b]would hate[/b] kabi iboralar har doim [b]to + fe'l[/b] bilan ishlatiladi.\n\n"
        "• I would like to drink some tea. ☕ – Men choy ichishni xohlardim.\n"
        "• She would love to visit Paris. 🗼 – U Parijga borishni juda xohlardi.\n"
        "• We would prefer to stay at home tonight. 🏡 – Biz bugun kechqurun uyda qolishni afzal ko'ramiz.\n"
        "• He wouldn't like to lose his job. 😟 – U ishini yo'qotishni xohlamasdi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=KaZDD-rG-h8&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=52]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 43,
    "title": "I want you to ... / I told you to ...",
    "content": "👋 Salom, aziz o‘rganuvchilar! 😊\n\n"
        "Bugun biz I want you to... va I told you to... kabi gap tuzilmalarini o‘rganamiz. Bu struktura fe’l + [b]somebody + to + verb[/b] ko‘rinishida ishlatiladi. ✅\n\n"
        "🎯 [b]I want you to ...[/b]\n"
        "Bu tuzilma orqali boshqa odamga nisbatan nimanidir xohlayotganimizni aytamiz:\n\n"
        "• I want you to be happy. 😊 - Men sening baxtli bo‘lishingni xohlayman.\n\n"
        "• He wants her to stay. 👫 - U qizning qolishini xohlayapti.\n\n"
        "• They didn’t want anybody to know their secret. 🤫 - Ular hech kim sirlarini bilishini xohlamadilar.\n\n"
        "• Do you want me to help you? 🤔 - Men senga yordam berishimni xohlaysanmi?\n\n"
        "🎯 [b]Would like you to ...[/b]\n"
        "Bu ham xuddi shunday ishlatiladi, faqat biroz muloyimroq:\n\n"
        "• Would you like me to lend you some money? 💸 - Sizga bir oz pul qarz berishimni xohlaysizmi?\n\n"
        "🎯 [b]Boshqa fe’llar bilan: ask, tell, advise, expect, persuade, teach[/b]\n\n"
        "• Sue asked a friend to lend her some money. 💬 - Syuz do‘stidan unga pul qarz berishini so‘radi.\n\n"
        "• I told you to be careful. ⚠️ - Men senga ehtiyot bo‘l, degan edim.\n\n"
        "• What do you advise me to do? 🤷‍♂️ - Menga nima qilishni maslahat berasan?\n\n"
        "• We persuaded George to come with us. 🚶‍♂️ - Biz Jorjni biz bilan kelishga ko‘ndirdik.\n\n"
        "• I taught my brother to swim. 🏊 - Men ukamga suzishni o‘rgatdim.\n\n"
        "🎯 [b]I told you to ... / I told you not to ...[/b]\n\n"
        "• Ann told me to wait for her. ⏳ - Ann uni kut dedi menga.\n\n"
        "• Paul told Sue not to wait for him. 🚫⏳ - Pol Syuga uni kutmaslikni aytdi.\n\n"
        "🎯 [b]Make va Let fe’llari bilan to ishlatilmaydi[/b]\n\n"
        "• He makes me laugh. 😂 (not ‘to laugh’) - U meni kuldiradi.\n\n"
        "• Our teacher made us work hard. 📚 - O‘qituvchimiz bizni qattiq ishlashga majbur qilardi.\n\n"
        "• Sue let me use her computer. 💻 - Syuz menga kompyuteridan foydalanishga ruxsat berdi.\n\n"
        "🎯 [b]Let’s ...[/b] = [i]Let us ...[/i] (Biror narsani birgalikda qilishni taklif qilish):\n\n"
        "• Let’s dance! 💃🕺 - Keling, raqsga tushaylik!\n\n"
        "• Let’s stay at home tonight. 🏡 - Keling, bugun kechasi uyda qolamiz.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=eetqsi6CkZQ&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=53]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 44,
    "title": "To va For (Maqsad va Sababni ifodalash)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 44[/b] darsimizda ingliz tilida [b]\"to\"[/b] va [b]\"for\"[/b] predloglarining turli xil qo'llanilishini o'rganamiz. Ular ko'pincha harakatning [b]maqsadini[/b] yoki [b]sababini[/b] ifodalash uchun ishlatiladi, ammo ularning o'ziga xos qoidalari bor. Keling, farqlarini bilib olaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]To ... (maqsadni bildirish uchun)[/b]\n"
        "[b]To + fe'lning boshlang'ich shakli[/b] ([b]to do[/b], [b]to buy[/b] va hokazo) biror ishning [b]maqsadini[/b] bildirish uchun ishlatiladi. Ya'ni, [b]nimaga?[/b] degan savolga javob beradi.\n\n"
        "• Why are you going out? 🤷‍♀️❓ - Nega tashqariga chiqyapsiz?\n"
        "  → To get some fresh air. 🌬️ - Bir oz toza havo olish uchun.\n"
        "• I went to the library to study. 📚 - Men kutubxonaga o'qish uchun bordim.\n"
        "• She turned on the radio to listen to the news. 📻 - U yangiliklarni tinglash uchun radioni yoqdi.\n"
        "• We need money to buy food. 💰 - Bizga oziq-ovqat sotib olish uchun pul kerak.\n"
        "• I don't have time to watch TV. 📺 - Televizor ko'rishga vaqtim yo'q.\n\n"
        "✅ [b]To ... (fe'l) va For ... (ot)[/b]\n"
        "[b]To[/b] dan keyin fe'lning boshlang'ich shakli ([b]to buy[/b], [b]to see[/b] kabi) keladi. [b]For[/b] dan keyin esa ot ([b]for a newspaper[/b], [b]for food[/b] kabi) keladi.\n\n"
        "• She went to the shop to buy a newspaper. 📰 - U gazeta sotib olish uchun do'konga bordi.\n"
        "• She went to the shop for a newspaper. 🛍️ - U do'konga gazeta uchun bordi.\n"
        "• They're going to Scotland to see their friends. 🏴󠁧󠁢󠁳󠁣󠁴󠁿 - Ular do'stlarini ko'rish uchun Shotlandiyaga ketishmoqda.\n"
        "• They're going to Scotland for a holiday. ✈️ - Ular ta'til uchun Shotlandiyaga ketishmoqda.\n"
        "• We need some money to buy food. 🍎 - Bizga oziq-ovqat sotib olish uchun pul kerak.\n"
        "• We need some money for food. 🛒 - Bizga oziq-ovqat uchun pul kerak.\n\n"
        "✅ [b]Wait for ... / Wait to do something[/b]\n"
        "• [b]Wait for + ot/kishi[/b]: Biror narsa yoki kishini kutish.\n"
        "  • Please wait for me. 🚶‍♂️ - Iltimos, meni kuting.\n"
        "  • Are you waiting for the bus? 🚌❓ - Avtobusni kutyapsizmi?\n"
        "• [b]Wait to do something[/b]: Biror ishni qilishni kutish.\n"
        "  • I'm waiting to see the doctor. 🩺 - Men shifokorga ko'rinishni kutyapman.\n"
        "  • Hurry up! I'm waiting to go home. 🏠💨 - Tezroq bo'ling! Uyga ketishni kutyapman.\n"
        "  • I can’t go out yet. I’m waiting for John to phone. 📞 - Hali tashqariga chiqa olmayman. Jonning qo'ng'iroq qilishini kutyapman.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=rCPRlThNmOI&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=54]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 45,
    "title":
        "Go to... / Go on... / Go for...? / Go -ing (Harakat fe'llari bilan predloglar va -ing shakli)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 45[/b] darsimizda [b]“go”[/b] fe’lining turli predloglar va fe’l shakllari bilan ishlatilishini o‘rganamiz. Bu sizga turli harakatlar va faoliyatlarni aniqroq ifodalashga yordam beradi. Keling, boshlaymiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Go to... (Biror joyga borish)[/b]\n"
        "[b]Go to + joy nomi[/b] biror manzilga borishni anglatadi.\n"
        "• I'm going to the supermarket. 🛒 - Men supermarketga boryapman.\n"
        "• Did you go to the party last night? 🎉 - Kecha kechki ziyofatga bordingizmi?\n"
        "• She usually goes to the gym on Mondays. 💪 - U odatda dushanba kunlari sport zaliga boradi.\n"
        "• We're going to London next month. 🇬🇧 - Kelasi oy Londonga ketyapmiz.\n"
        "Eslatma: Go home deyishda 'to' predlogi ishlatilmaydi. Masalan: [i]I'm going home now.[/i] (Not: [i]I'm going to home now.[/i])\n\n"
        "✅ [b]Go on... (Sayohatlar, tadbirlar uchun)[/b]\n"
        "[b]Go on + ot[/b] sayohatlar, ta'tillar, ekskursiyalar yoki ish tashlash kabi maxsus tadbirlar uchun ishlatiladi.\n"
        "• They plan to go on a world tour next year. ✈️ - Ular kelasi yili jahon sayohatiga borishni rejalashtirishmoqda.\n"
        "• Have you ever gone on a cruise? 🛳️ - Siz hech kruizga borganmisiz?\n"
        "• The employees decided to go on strike for better wages. ✊ - Xodimlar yaxshiroq ish haqi uchun ish tashlashga qaror qilishdi.\n\n"
        "✅ [b]Go for...? (Qisqa faoliyatlar uchun)[/b]\n"
        "[b]Go for a + ot[/b] ko'pincha qisqa yurishlar, yugurishlar, suzishlar yoki ovqatlanish kabi faoliyatlar uchun ishlatiladi.\n"
        "• Let's go for a walk in the park. 🌳 - Keling, parkda sayr qilamiz.\n"
        "• He goes for a run every morning to stay fit. 🏃 - U sog'lom bo'lish uchun har kuni ertalab yugurishga boradi.\n"
        "• We often go for a coffee after lunch. ☕ - Biz tushlikdan keyin tez-tez qahva ichishga boramiz.\n"
        "• She went for a ride on her new bicycle. 🚴‍♀️ - U yangi velosipedida sayr qilishga bordi.\n\n"
        "✅ [b]Go -ing (Sport va shunga o'xshash faoliyatlar uchun)[/b]\n"
        "[b]Go + -ing[/b] ko'pincha sport turlari (masalan, [b]swimming[/b], [b]skiing[/b]) va ba'zi boshqa faoliyatlar (masalan, [b]shopping[/b]) uchun ishlatiladi.\n"
        "• I love to go hiking in the mountains. ⛰️ - Men tog'larda piyoda yurishni yaxshi ko'raman.\n"
        "• They usually go fishing on weekends. 🎣 - Ular odatda dam olish kunlari baliq ovlashga boradilar.\n"
        "• Do you want to go cycling with me tomorrow? 🚴 - Ertaga men bilan velosipedda yurishga borishni xohlaysizmi?\n"
        "• We should go dancing sometime soon! 💃🕺 - Tez orada raqsga tushishga borishimiz kerak!\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=S0db9gFaGdQ&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=55]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 46,
    "title": "Get (Fe'lining Turli Ma'nolari va Ishlatilishi)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 46[/b] darsimizda ingliz tilidagi eng ko'p qo'llaniladigan va ko'p ma'noli fe'llardan biri – [b]“get”[/b] fe'lini o'rganamiz. Uning ma'nosi qanday so'z bilan birga ishlatilishiga qarab o'zgaradi. Keling, uning asosiy qo'llanilishlarini ko'rib chiqaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Get + Ot (Olish / Erishish)[/b]\n"
        "[b]Get + ot[/b] biror narsani olish, sotib olish yoki topish ma'nosini bildiradi.\n"
        "• Did you [b]get my email[/b] yesterday? 📧 – Kecha mening elektron pochtamni oldingizmi?\n"
        "• I need to [b]get some groceries[/b] on my way home. 🛒 – Uyga ketayotganimda ba'zi oziq-ovqat mahsulotlarini olishim kerak.\n"
        "• Where did you [b]get that book[/b]? It's very interesting. 📚 – Bu kitobni qayerdan oldingiz? Juda qiziq ekan.\n"
        "• You can [b]get a bus[/b] from here to the city center. 🚌 – Shahar markaziga shu yerdan avtobusga chiqishingiz mumkin.\n\n"
        "✅ [b]Get + Sifat (Holatni O'zgartirish / Bo'lib Qolish)[/b]\n"
        "[b]Get + sifat[/b] biror holatga kelish yoki o'zgarishni anglatadi ([b]become[/b] yoki [b]to be[/b] fe'liga o'xshash).\n"
        "• I always [b]get tired[/b] after a long day at work. 😴 – Uzoq ish kunidan keyin men doim charchayman.\n"
        "• It's [b]getting dark[/b] outside. Let's go inside. 🌃 – Tashqarida qorong'u bo'lyapti. Ichkariga kiraylik.\n"
        "• Don't [b]get angry[/b] about it; it's not worth it. 😡 – Bu haqida jahl qilmang; bunga arzimaydi.\n"
        "• She hopes to [b]get better[/b] soon. 🙏 – U tez orada tuzalib ketishiga umid qiladi.\n\n"
        "✅ [b]Get to + joy (Yetib borish / Kelish)[/b]\n"
        "[b]Get to + joy[/b] biror manzilga yetib borishni yoki kelishni bildiradi.\n"
        "• What time do you usually [b]get to work[/b]? 🏢 – Siz odatda ishga qaysi vaqtda yetib borasiz?\n"
        "• How long does it take to [b]get to the airport[/b] from here? ✈️ – Bu yerdan aeroportga yetib borish qancha vaqt oladi?\n"
        "• We [b]got to the concert[/b] just before it started. 🎸 – Konsert boshlanishidan sal oldin yetib bordik.\n"
        "Eslatma: [b]Get home[/b] deyishda [b]'to'[/b] predlogi ishlatilmaydi. Masalan: [i]How did you get home last night?[/i]\n\n"
        "✅ [b]Get in/out/on/off (Transportga chiqish/tushish)[/b]\n"
        "Bu iboralar transport vositalariga chiqish yoki tushishni anglatadi.\n"
        "• [b]Get in[/b] / [b]Get out of[/b] (avtomobil uchun)\n"
        "  • She [b]got in the car[/b] and drove away. 🚗 – U mashinaga o'tirdi va ketdi.\n"
        "  • Be careful when you [b]get out of the car[/b] on the street. ⚠️ – Ko'chada mashinadan tushayotganda ehtiyot bo'ling.\n"
        "• [b]Get on[/b] / [b]Get off[/b] (avtobus, poyezd, samolyot, velosiped kabi katta transportlar uchun)\n"
        "  • I [b]got on the bus[/b] at the next stop. 🚌 – Keyingi bekatda avtobusga chiqdim.\n"
        "  • Remember to [b]get off the train[/b] at the right station. 🚂 – To'g'ri stansiyada poyezddan tushishni unutmang.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=y4TBbP2K9d4&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=56]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 47,
    "title": "Do va Make (Farqlari va Qo'llanilishi)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 47[/b] darsimizda ingliz tilida tez-tez chalkashtirib yuboriladigan ikkita fe'l – [b]“do”[/b] va [b]“make”[/b] fe'llarining to'g'ri ishlatilishini o'rganamiz. Garchi ikkalasi ham \"qilmoq\" ma'nosini bersa-da, ularning o'ziga xos qo'llanish doiralari bor. Keling, farqlarini aniqlashtirib olaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Do (Umumiy Harakatlar, Vazifalar va Faoliyatlar uchun)[/b]\n"
        "[b]“Do”[/b] fe'li ko'pincha umumiy harakatlar, vazifalar, tadbirlar yoki ish-harakatlar haqida gapirganda ishlatiladi. Ko'pincha yakuniy mahsulot emas, balki jarayon muhim bo'ladi.\n"
        "• What [b]do you do[/b] for a living? 💼 – Tirikchilik uchun nima qilasiz?\n"
        "• I need to [b]do some chores[/b] around the house. 🧹 – Uyda ba'zi yumushlarni qilishim kerak.\n"
        "• Can you [b]do me a favor[/b]? 🤔 – Menga bir iltifot qila olasizmi?\n"
        "• She decided to [b]do a course[/b] in web design. 💻 – U veb-dizayn bo'yicha kurs o'tashga qaror qildi.\n\n"
        "✅ [b]Make (Yaratish, Ishlab Chiqarish, Sabab Bo'lish uchun)[/b]\n"
        "[b]“Make”[/b] fe'li biror narsani yaratish, ishlab chiqarish, qurish yoki biror narsaga sabab bo'lish ma'nolarida qo'llaniladi. Ko'pincha yakuniy mahsulot yoki natija muhim bo'ladi.\n"
        "• My grandmother loves to [b]make delicious cakes[/b]. 🍰 – Mening buvim mazali tortlar pishirishni yaxshi ko'radilar.\n"
        "• He wants to [b]make a new table[/b] for the living room. 🔨 – U mehmonxona uchun yangi stol yasamoqchi.\n"
        "• The company [b]makes high-quality electronics[/b]. 📱 – Kompaniya yuqori sifatli elektronika mahsulotlarini ishlab chiqaradi.\n"
        "• Reading this book [b]makes me happy[/b]. 😊 – Bu kitobni o'qish meni xursand qiladi.\n\n"
        "✅ [b]“Do” bilan ishlatiladigan umumiy iboralar:[/b]\n"
        "• [b]do homework[/b] ✍️ – uy vazifasini bajarmoq\n"
        "• [b]do the shopping[/b] 🛍️ – xarid qilmoq\n"
        "• [b]do housework[/b] 🏠 – uy ishlarini bajarmoq\n"
        "• [b]do an exam[/b] / [b]do a test[/b] 📝 – imtihon topshirmoq\n"
        "• [b]do exercises[/b] 🤸 – mashq qilmoq\n"
        "• [b]do your best[/b] ⭐ – borini berib harakat qilmoq\n\n"
        "✅ [b]“Make” bilan ishlatiladigan umumiy iboralar:[/b]\n"
        "• [b]make a mistake[/b] 🤦 – xato qilmoq\n"
        "• [b]make a decision[/b] ✅ – qaror qabul qilmoq\n"
        "• [b]make a noise[/b] 🔊 – shovqin qilmoq\n"
        "• [b]make a phone call[/b] 📞 – telefon qilmoq\n"
        "• [b]make a bed[/b] 🛌 – o'rinni yig'ishtirmoq\n"
        "• [b]make friends[/b] 👫 – do'stlashmoq\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=bDf7xZyicxM&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=57]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 48,
    "title":
        "I/me, He/him, They/them va Boshqa Olmoshlar (Ega va To'ldiruvchi)",
    "content": "Assalomu alaykum! Bugungi [b]Lesson 48[/b] darsimizda ingliz tilida shaxs olmoshlarining asosiy shakllari – [b]ega (subject)[/b] va [b]to'ldiruvchi (object)[/b] olmoshlarini yanada aniqroq o'rganamiz. Bu [b]I[/b] va [b]me[/b], [b]he[/b] va [b]him[/b], [b]they[/b] va [b]them[/b] kabi juftliklar orasidagi farqni to'liq tushunishga yordam beradi. Keling, boshlaymiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Ega (Subject) va To'ldiruvchi (Object) Olmoshlar[/b]\n"
        "Ingliz tilida shaxs olmoshlari ikki asosiy shaklda keladi:\n"
        "• [b]Ega olmoshlari[/b] (I, he, she, we, they, you, it): Fe'ldan [b]oldin[/b] keladi va harakatni bajaruvchini bildiradi (o'zbek tilida: [b]kim/nima?[/b] savollariga javob beradi).\n"
        "• [b]To'ldiruvchi olmoshlari[/b] (me, him, her, us, them, you, it): Fe'ldan [b]keyin[/b] yoki predlogdan [b]keyin[/b] keladi va harakatni qabul qiluvchisini bildiradi (o'zbek tilida: [b]kimga/nimaga?[/b] yoki [b]kimni/nimani?[/b] savollariga javob beradi).\n\n"
        "• I ([b]Ega[/b]) → me ([b]To'ldiruvchi[/b])\n"
        "• you ([b]Ega[/b]) → you ([b]To'ldiruvchi[/b])\n"
        "• he ([b]Ega[/b]) → him ([b]To'ldiruvchi[/b])\n"
        "• she ([b]Ega[/b]) → her ([b]To'ldiruvchi[/b])\n"
        "• it ([b]Ega[/b]) → it ([b]To'ldiruvchi[/b])\n"
        "• we ([b]Ega[/b]) → us ([b]To'ldiruvchi[/b])\n"
        "• they ([b]Ega[/b]) → them ([b]To'ldiruvchi[/b])\n\n"
        "• [b]She[/b] called [b]him[/b] yesterday. 📞 – U kecha unga qo'ng'iroq qildi.\n"
        "• [b]We[/b] saw [b]them[/b] at the park. 🌳 – Biz ularni parkda ko'rdik.\n"
        "• [b]He[/b] is helping [b]me[/b] with my project. 🤝 – U menga loyihamda yordam beryapti.\n"
        "• [b]They[/b] invited [b]us[/b] to their party. 🎉 – Ular bizni ziyofatlariga taklif qilishdi.\n\n"
        "✅ [b]Predloglardan keyin To'ldiruvchi (Object) Olmoshlari[/b]\n"
        "Predloglardan ([b]for[/b], [b]to[/b], [b]with[/b], [b]about[/b] va boshqalar) keyin doimo [b]to'ldiruvchi (object) olmoshi[/b] ishlatiladi.\n"
        "• This gift is [b]for you[/b]. 🎁 – Bu sovg'a siz uchun.\n"
        "• I want to talk [b]to him[/b] about the meeting. 🗣️ – U bilan uchrashuv haqida gaplashmoqchiman.\n"
        "• Are you going [b]with us[/b]? 🚶‍♀️🚶‍♂️ – Biz bilan ketyapsizmi?\n"
        "• What do you know [b]about her[/b]? 🕵️‍♀️ – U haqida nimalarni bilasiz?\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=FLUwRWhGZcc&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=59]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 49,
    "title": "Egalik Sifat-Olmoshlari: My, Your, His, Her, Its, Our, Their",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 49[/b] darsimizda ingliz tilida egalikni ifodalovchi asosiy so'zlar – [b]egalik sifat-olmoshlari[/b]ni ([b]my, your, his, her, its, our, their[/b]) o'rganamiz. Ular biror narsaning kimga yoki nimaga tegishli ekanligini ko'rsatish uchun otlardan oldin keladi. Keling, ularni to'g'ri ishlatishni bilib olaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Egalik Sifat-Olmoshlari (Possessive Adjectives)[/b]\n"
        "Bu olmoshlar har doim [b]otdan oldin[/b] keladi va unga tegishlilikni bildiradi. Ular sifat kabi otni ta'riflaydi.\n"
        "• [b]my[/b] (mening)\n"
        "• [b]your[/b] (sening/sizning)\n"
        "• [b]his[/b] (uning - erkak)\n"
        "• [b]her[/b] (uning - ayol)\n"
        "• [b]its[/b] (uning - jonsiz/hayvon)\n"
        "• [b]our[/b] (bizning)\n"
        "• [b]their[/b] (ularning)\n\n"
        "• This is [b]my new jacket[/b]. 🧥 – Bu mening yangi kurtkam.\n"
        "• Is that [b]your idea[/b]? 🤔 – Bu sizning g'oyangizmi?\n"
        "• He lost [b]his keys[/b] yesterday. 🔑 – U kecha kalitlarini yo'qotdi.\n"
        "• She finished [b]her homework[/b]. ✍️ – U uy vazifasini tugatdi.\n"
        "• The bird built [b]its nest[/b] in the tree. 🐦🌳 – Qush daraxtga inini qurdi.\n"
        "• We are proud of [b]our team[/b]. 🏆 – Biz jamoamizdan faxrlanamiz.\n"
        "• They sold [b]their old car[/b]. 🚗 – Ular eski mashinasini sotishdi.\n\n"
        "✅ [b]Its va It's (Farqi)[/b]\n"
        "Bu ikkita so'z ko'pincha chalkashtiriladi, ammo ularning ma'nolari butunlay boshqacha.\n"
        "• [b]Its[/b] – egalik sifat-olmoshi, \"uning\" (jonsiz narsaga yoki hayvonga tegishli) degan ma'noni bildiradi.\n"
        "  • The cat is licking [b]its paws[/b]. 🐾 – Mushuk panjalarini yalayapti.\n"
        "  • The company celebrated [b]its 10th anniversary[/b]. 🏢 – Kompaniya o'zining 10 yilligini nishonladi.\n"
        "• [b]It's[/b] – [b]it is[/b] yoki [b]it has[/b] so'zlarining qisqartmasi.\n"
        "  • [b]It's[/b] a beautiful day today. ☀️ ([b]It is[/b] a beautiful day today.) – Bugun ajoyib kun.\n"
        "  • [b]It's[/b] been raining all morning. 🌧️ ([b]It has[/b] been raining all morning.) – Butun ertalab yomg'ir yog'di.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=3OwiFP-eTmE&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=60]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
