  {
    "lesson": 50,
    "title": "Kimniki? Egalik Olmoshlari: Mine, Yours, His, Hers, Ours, Theirs",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 50[/b] darsimizda ingliz tilida \"kimniki?\" degan savolga javob berishda ishlatiladigan [b]egalik olmoshlari[/b] ([b]mine, yours, his, hers, ours, theirs[/b]) va [b]“Whose?”[/b] so'zini o'rganamiz. Bu olmoshlar avvalgi darsdagi egalik sifat-olmoshlaridan farqli o'laroq otsiz keladi. Keling, tushunib olaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Egalik Olmoshlari (Possessive Pronouns)[/b]\n"
        "Bu olmoshlar gapda otsiz keladi va gapda mustaqil ishlatiladi. Ular biror narsaning kimga tegishli ekanligini ko'rsatadi.\n"
        "• [b]mine[/b] (meniki)\n"
        "• [b]yours[/b] (seniki/sizniki)\n"
        "• [b]his[/b] (uniniki - erkak)\n"
        "• [b]hers[/b] (uniniki - ayol)\n"
        "• [b]ours[/b] (bizniki)\n"
        "• [b]theirs[/b] (ularniki)\n\n"
        "• This phone isn't [b]mine[/b]. I think it's yours. 📱 – Bu telefon meniki emas. O'ylaymanki, sizniki.\n"
        "• I thought this was Sarah's coat, but it's actually [b]hers[/b]. 🧥 – Bu Saraning paltosi deb o'yladim, lekin aslida uniki (ayol).\n"
        "• That beautiful house at the end of the street is [b]theirs[/b]. 🏡 – Ko'cha oxiridagi chiroyli uy ularniki.\n"
        "• Our project is almost finished. What about [b]yours[/b]? 📝 – Loyihamiz deyarli tugadi. Siznikichi?\n"
        "• This car is [b]ours[/b], not John's. 🚗 – Bu mashina bizniki, Jonniki emas.\n\n"
        "✅ [b]Whose...? (Kimniki?)[/b]\n"
        "[b]“Whose”[/b] so'zi egalik haqida savol berish uchun ishlatiladi. U ot bilan birga yoki o'zi mustaqil kelishi mumkin.\n"
        "• [b]Whose bag[/b] is this? 🎒 – Bu kimning sumkasi?\n"
        "  • It's [b]mine[/b]. – Meniki.\n"
        "• [b]Whose are[/b] these shoes? 👟 – Bu poyabzallar kimniki?\n"
        "  • They're [b]hers[/b]. – Uniki (ayol).\n"
        "• [b]Whose turn[/b] is it? 🎲 – Navbat kimniki?\n"
        "  • It's [b]his[/b]. – Uniki (erkak).\n\n"
        "✅ [b]Egalik Sifat Olmoshlari va Egalik Olmoshlari Farqi (Qisqacha)[/b]\n"
        "Yodingizda tuting: [b]egalik sifat-olmoshlari[/b] ([b]my, your, his[/b]...) har doim ot oldidan keladi, [b]egalik olmoshlari[/b] ([b]mine, yours, his[/b]...) esa otsiz, gapda mustaqil keladi.\n"
        "• That's [b]our dog[/b]. (Egalik-sifat olmoshi) 🐕 – Bu bizning itimiz.\n"
        "• That dog is [b]ours[/b]. (Egalik olmoshi) 🐕 – Bu it bizniki.\n\n"
        "✅ [b]\"A friend of mine\" / \"A car of theirs\" kabi tuzilmalar[/b]\n"
        "Bu tuzilma ([b]a / an + ot + of + egalik olmoshi[/b]) egalikni ifodalashning yana bir usulidir. U oddiy \"my friend\" yoki \"their car\" kabi aytishning muqobilidir.\n"
        "• I met [b]a friend of mine[/b] at the concert. 🎤 – Konsertda bir do'stimni uchratdim. (Ya'ni: I met my friend.)\n"
        "• She lives in [b]a house of hers[/b] near the lake. 🏞️ – U ko'l yaqinidagi o'z uyida yashaydi. (Ya'ni: She lives in her house.)\n"
        "• That's [b]a great idea of yours[/b]! ✨ – Bu sizning ajoyib g'oyangiz! (Ya'ni: That's your great idea!)\n"
        "• They introduced me to [b]some colleagues of theirs[/b]. 🤝 – Ular meni o'z hamkasblaridan ba'zilariga tanishtirishdi. (Ya'ni: They introduced me to their colleagues.)\n\n"
