  {
    "lesson": 51,
    "title": "I / me / my / mine",
    "content": "👋 Assalomu alaykum, aziz o‘rganuvchilar! 📘\n\n"
        "Bugun biz [b]I / me / my / mine[/b] so‘zlarining farqini o‘rganamiz. Bu so‘zlar bir-biriga o‘xshash ko‘rinsa-da, ularning ishlatilish o‘rni har xil. 💡\n\n"
        "🧠 [b]Qisqacha qoida:[/b]\n"
        "[b]I[/b] – gap boshida keladi, ya'ni [b]subject[/b] (Men)\n"
        "[b]me[/b] – harakat [b]menga ham qilinayotgan[/b] bo‘lsa ishlatiladi (meni / menga)\n"
        "[b]my[/b] – biror narsa [b]menga ham tegishli[/b] bo‘lsa, keyin [b]ot[/b] keladi (mening ...)\n"
        "[b]mine[/b] – biror narsa menga tegishli, lekin keyin [b]ot yo‘q[/b] (meniki)\n\n"
        "✅ [b]Misollar:[/b]\n"
        "• “Do you know my teacher?” – “Yes, I know [b]him[/b], but I can’t remember [b]his name[/b].”\n"
        "  – O'qituvchimni taniysizmi? Ha, men uni taniyman, lekin ismini eslay olmayapman.\n\n"
        "• She is our new cleaner. We hired [b]her[/b] to clean [b]our[/b] house. 🏡\n"
