        "  – Bu sizning stakaningizmi? Yo‘q, bu meniki.\n\n"
        "• It was not my song. It was [b]hers[/b]. 🎤\n"
        "  – U mening qo'shig'im emas edi. Bu uniki edi.\n\n"
