  {
    "lesson": 52,
    "title": "Refleksiv Olmoshlar: Myself, Yourself, Themselves va Boshqalar",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 52[/b] darsimizda ingliz tilidagi [b]refleksiv olmoshlar[/b] (myself, yourself, himself, herself, itself, ourselves, yourselves, themselves)ni o'rganamiz. Bu olmoshlar harakatning bajaruvchisi va qabul qiluvchisi bir xil bo'lgan holatlarda ishlatiladi. Keling, tushunib olaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Refleksiv Olmoshlar Jadvali (Reflexive Pronoun Table)[/b]\n"
        "Refleksiv olmoshlar shaxs olmoshlaridan yasaladi va harakatni subyektga qaytaradi.\n\n"
        "• I → [b]myself[/b] (o'zim)\n"
        "• you → [b]yourself[/b] (o'zing - birlik) / [b]yourselves[/b] (o'zingiz - ko'plik)\n"
        "• he → [b]himself[/b] (o'zi - erkak)\n"
        "• she → [b]herself[/b] (o'zi - ayol)\n"
        "• it → [b]itself[/b] (o'zi - jonsiz/hayvon)\n"
        "• we → [b]ourselves[/b] (o'zimiz)\n"
        "• they → [b]themselves[/b] (o'zlari)\n\n"
        "✅ [b]Asosiy Qo'llanilishi (Main Usage)[/b]\n"
        "Refleksiv olmoshlar harakatni bajaruvchi va harakatni qabul qiluvchi bir shaxs yoki narsa bo'lganda ishlatiladi.\n"
        "• I accidentally cut [b]myself[/b] while cooking. 🔪 – Tasodifan pishirayotganda o'zimni kesib oldim.\n"
        "• He taught [b]himself[/b] how to play the guitar. 🎸 – U gitara chalishni o'ziga o'zi o'rgatdi.\n"
        "• Be careful not to hurt [b]yourselves[/b] during the game. ⚽ – O'yin paytida o'zingizni shikastlab olmaslik uchun ehtiyot bo'ling.\n"
        "• The cat cleaned [b]itself[/b] after eating. 🐈 – Mushuk ovqatlangandan keyin o'zini tozaladi.\n"
        "• We enjoyed [b]ourselves[/b] a lot at the party. 🎉 – Biz ziyofatda juda yaxshi dam oldik.\n\n"
        "✅ [b]by myself / by yourself etc. (Mustaqil ravishda)[/b]\n"
        "[b]by + refleksiv olmosh[/b] tuzilmasi biror narsani yolg'iz yoki yordamisiz bajarishni anglatadi.\n"
        "• She prefers to travel [b]by herself[/b]. ✈️ – U yolg'iz sayohat qilishni afzal ko'radi.\n"
        "• I fixed the broken chair [b]by myself[/b]. 🔧 – Singan stulni o'zim tuzatdim.\n"
        "• Can you solve this problem [b]by yourself[/b]? 🤔 – Bu muammoni o'zingiz hal qila olasizmi?\n\n"
        "✅ [b]\"Each other\" nima?[/b]\n\n"
        "• [b]Each other[/b] ikki yoki undan ortiq odamlar bir-biriga nisbatan harakat qilganda ishlatiladi (o'zaro harakat).\n"
        "  • John and Mary helped [b]each other[/b] with their homework. 🤝 – Jon va Meri uy vazifalarida bir-birlariga yordam berishdi.\n"
        "  • The children enjoy playing with [b]each other[/b] in the park. 🧒👧 – Bolalar bog'da bir-birlari bilan o'ynashdan zavqlanishadi.\n"
        "  • Sarah and Tom text [b]each other[/b] every day. 📱 – Sara va Tom har kuni bir-birlariga xabar yozishadi.\n"
        "  • The team members always support [b]each other[/b]. 💪 – Jamoa a'zolari har doim bir-birlarini qo'llab-quvvatlaydilar.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=w4e2YVU5vbk&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=63]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 53,
    "title": "Egalik Qo'shimchasi '-s' (Possessive 's)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 53[/b] darsimizda ingliz tilida egalikni ifodalashning keng tarqalgan usullaridan biri – [b]egalik qo'shimchasi '-s'[/b]ni o'rganamiz. Bu qo'shimcha asosan odamlarga va hayvonlarga tegishlilikni ko'rsatish uchun ishlatiladi. Keling, buni qanday to'g'ri ishlatishni bilib olaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Odamlar va Hayvonlar Uchun Egalik ('s for people and animals)[/b]\n"
        "Yagona shaxs yoki hayvonga tegishlilikni bildirish uchun otga apostrof va 's' (['s]) qo'shiladi.\n"
        "• This is [b]David's car[/b]. 🚗 – Bu Devidning mashinasi.\n"
        "• [b]My sister's room[/b] is very tidy. 🛏️ – Singlimning xonasi juda ozoda.\n"
        "• The [b]dog's leash[/b] is on the table. 🐾 – Itning tasmasi stol ustida.\n"
        "• Have you seen [b]Sarah's new phone[/b]? 📱 – Sarohning yangi telefonini ko'rdingizmi?\n"
        "• It was a brilliant [b]colleague's idea[/b]. 💡 – Bu ajoyib hamkasbimning g'oyasi edi.\n"
        "• We heard the [b]baby's cry[/b] from the next room. 👶 – Qo'shni xonadan chaqaloqning yig'isini eshitdik.\n\n"
        "✅ [b]Birlik va Ko'plik Otlar ('s with singular and plural nouns)[/b]\n"
        "• [b]Birlik otlar[/b] uchun: [b]ot + 's[/b].\n"
        "  • The [b]student's bag[/b] is on the chair. 🎒 – Talabaning sumkasi stulda.\n"
        "  • [b]My friend's opinion[/b] matters a lot to me. 💬 – Do'stimning fikri men uchun juda muhim.\n"
        "• [b]S bilan tugaydigan ko'plik otlar[/b] uchun: [b]apostrof (')[/b] s dan keyin qo'yiladi.\n"
        "  • The [b]students' projects[/b] were all excellent. 👩‍🎓👨‍🎓 – Talabalarning loyihalari hammasi a'lo edi.\n"
        "  • The [b]teachers' meeting[/b] will be held tomorrow. 🧑‍🏫 – O'qituvchilarning yig'ilishi ertaga bo'lib o'tadi.\n"
        "• [b]S bilan tugamaydigan tartibsiz ko'plik otlar[/b] uchun: [b]ot + 's[/b].\n"
        "  • The [b]children's toys[/b] are scattered everywhere. 🧸 – Bolalarning o'yinchoqlari hamma joyda sochilib yotibdi.\n"
        "  • The [b]men's restroom[/b] is on the left. 🚻 – Erkaklar hojatxonasi chap tomonda.\n"
        "  • [b]Women's rights[/b] are human rights. ✊ – Ayollar huquqlari inson huquqlaridir.\n\n"
        "✅ [b]Ot bo'lmaganda (When 's stands alone)[/b]\n"
        "Egalikni bildiruvchi ot aniq bo'lsa, uni takrorlamaslik uchun '-s' ot holda ishlatilishi mumkin.\n"
        "• Is this [b]your car[/b]? No, it's [b]my brother's[/b]. 🚗 – Bu sizning mashinangizmi? Yo'q, bu akamniki.\n"
        "• I bought coffee at [b]the cafe's[/b]. ☕ – Men kafeda qahva sotib oldim. (Ya'ni: the cafe's [b]store/place[/b])\n"
        "• That beautiful jacket must be [b]Maria's[/b]. 🧥 – O'sha chiroyli kurtka Mariyaniki bo'lishi kerak.\n"
        "• This isn't [b]my book[/b]; I think it's [b]Tom's[/b]. 📚 – Bu mening kitobim emas; o'ylaymanki, bu Tomniki.\n\n"
        "✅ [b]Buyumlar va Joylar Uchun 'of' (Use 'of' for things and places)[/b]\n"
        "Odatda, jonsiz narsalar va joylarga tegishlilikni bildirish uchun '-s' o'rniga [b]'of'[/b] predlogi ishlatiladi.\n"
        "• The [b]door of the room[/b] is open. 🚪 – Xonaning eshigi ochiq.\n"
        "• What's the [b]capital of Uzbekistan[/b]? 🇺🇿 – O'zbekistonning poytaxti nima?\n"
        "• The [b]roof of the building[/b] needs repair. 🏗️ – Binoning tomi ta'mirga muhtoj.\n"
        "• I don't remember the [b]name of the book[/b]. 📖 – Kitobning nomini eslay olmayapman.\n"
        "• The [b]history of the city[/b] is very rich. 🏛️ – Shahar tarixi juda boy.\n"
        "• What's the [b]price of the product[/b]? 💰 – Mahsulotning narxi qancha?\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=FmFilejfH00&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=64]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 54,
    "title": "Artikllar: A / An (Noma'lum Artikllar)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 54[/b] darsimizda ingliz tilidagi noma'lum artikllar – [b]'a' va 'an'[/b]ni o'rganamiz. Bu artikllar birlikdagi sanaladigan otlar oldidan kelib, \"bitta\" yoki \"biror bir\" degan ma'nolarni anglatadi. Keling, ularni qanday to'g'ri ishlatishni bilib olaylik! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]A va An Artikllarining Asosiy Qo'llanilishi (Basic Use of A and An)[/b]\n"
        "• [b]'A'[/b] artikli undosh tovush bilan boshlanadigan birlikdagi sanaladigan otlar oldidan ishlatiladi.\n"
        "  • I have [b]a cat[/b]. 🐱 – Mening mushugim bor.(ya'ni bitta mushuk)\n"
        "  • She bought [b]a new dress[/b]. 👗 – U yangi ko'ylak sotib oldi.(bitta ko'ylak)\n"
        "  • We need [b]a table[/b] for the meeting. 🛋️ – Yig'ilish uchun bizga stol kerak.(bitta stol)\n"
        "• [b]'An'[/b] artikli unli tovush bilan boshlanadigan birlikdagi sanaladigan otlar oldidan ishlatiladi (a, e, i, o, u).\n"
        "  • He wants [b]an apple[/b]. 🍎 – U olma xohlaydi.(bitta olma)\n"
        "  • There is [b]an old book[/b] on the shelf. 📖 – Javonda eski kitob bor.(bitta kitob)\n"
        "  • I saw [b]an interesting movie[/b] last night. 🎬 – Kecha qiziqarli film ko'rdim.\n\n"
        "✅ [b]Tovushga E'tibor bering (Focus on Sound, not Letter)[/b]\n"
        "Artikl tanlashda so'zning bosh harfiga emas, balki uning [b]boshlang'ich tovushiga[/b] e'tibor berish muhim.\n"
        "• It takes [b]an hour[/b] to get there. ⏰ (H harfi undosh bo'lsa-da, tovush unli: /aʊər/)\n"
        "  – U erga borish uchun bir soat ketadi.\n"
        "• She studies at [b]a university[/b]. 🎓 (U harfi unli bo'lsa-da, tovush undosh: /juːnɪˈvɜːrsɪti/)\n"
        "  – U universitetda o'qiydi.\n"
        "• This is [b]an honest person[/b]. 😇 (H harfi undosh bo'lsa-da, tovush unli: /ˈɒnɪst/)\n"
        "  – Bu halol inson.\n\n"
        "✅ [b]Artikllarning Boshqa Ishlatilish Holatlari (Other Uses of Articles)[/b]\n"
        "• Biror narsaning yoki shaxsning [b]nimaga tegishli ekanligini[/b] yoki [b]kim ekanligini[/b] aytishda.\n"
        "  • My father is [b]a doctor[/b]. 👨‍⚕️ – Otam shifokor.\n"
        "  • It's [b]a beautiful day[/b] today. ☀️ – Bugun chiroyli kun.\n"
        "  • She is [b]an excellent singer[/b]. 🎤 – U ajoyib qo'shiqchi.\n"
        "• Biror narsa yoki shaxsning [b]soni bitta[/b] ekanligini anglatish uchun.\n"
        "  • Can I have [b]a cup of tea[/b]? ☕ – Bir chashka choy ichsam bo'ladimi?\n"
        "  • There is [b]a woman[/b] waiting for you. 👩 – Sizni bir ayol kutmoqda.\n\n"
