  {
    "lesson": 55,
    "title":
        "Sanaladigan va Sanalmaydigan Otlar (Countable and Uncountable Nouns)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 55[/b] darsimizda ingliz tilidagi otlarni ikki katta guruhga ajratishni o'rganamiz: [b]sanaladigan (countable) va sanalmaydigan (uncountable) otlar[/b]. Bu farq ingliz tilida artikllar, sonlar va miqdor so'zlarini to'g'ri ishlatish uchun juda muhimdir. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Sanaladigan Otlar (Countable Nouns)[/b]\n"
        "Sanaladigan otlar bu [b]hisoblash mumkin bo'lgan[/b] narsalar, odamlar yoki g'oyalarni anglatadi. Ular birlik va ko'plik shakliga ega bo'lishi mumkin.\n"
        "• Birlik shaklida ulardan oldin [b]'a' yoki 'an'[/b] artikllari keladi.\n"
        "  • I saw [b]a bird[/b] in the garden. 🐦 – Bog'da bir qushni ko'rdim.\n"
        "  • She has [b]an idea[/b] for the project. 💡 – Uning loyiha uchun g'oyasi bor.\n"
        "• Ko'plik shaklida raqamlar ([b]one, two, three[/b]...) yoki [b]many, few, some[/b] kabi so'zlar bilan ishlatiladi.\n"
        "  • There are [b]three books[/b] on the table. 📚 – Stol ustida uchta kitob bor.\n"
        "  • I have [b]many friends[/b] around the world. 🌍 – Dunyo bo'ylab ko'plab do'stlarim bor.\n\n"
        "✅ [b]Sanalmaydigan Otlar (Uncountable Nouns)[/b]\n"
        "Sanalmaydigan otlar bu [b]hisoblash mumkin bo'lmagan[/b] narsalar, moddalar, suyuqliklar, mavhum tushunchalar yoki umumiy kategoriyalarni anglatadi. Ular odatda [b]ko'plik shakliga ega bo'lmaydi[/b] va ulardan oldin [b]'a' yoki 'an'[/b] ishlatilmaydi.\n"
        "• Misollar: [b]water, rice, information, advice, furniture, money, music[/b].\n"
        "  • I need [b]some information[/b]. ℹ️ – Menga bir oz ma'lumot kerak.\n"
        "  • Can I have [b]some water[/b], please? 💧 – Iltimos, menga bir oz suv bera olasizmi?\n"
        "  • We need [b]new furniture[/b] for the living room. 🛋️ – Mehmonxona uchun bizga yangi mebel kerak.\n"
        "• Sanalmaydigan otlarni [b]miqdorini aniqlash[/b] uchun maxsus iboralar ishlatiladi.\n"
        "  • [b]a glass of water[/b] 🥛 – bir stakan suv\n"
        "  • [b]a piece of advice[/b] 💬 – bir maslahat\n"
        "  • [b]a slice of bread[/b] 🍞 – bir bo'lak non\n"
        "  • [b]a bowl of rice[/b] 🍚 – bir kosa guruch\n\n"
        "✅ [b]Muhim Farqlar va Umumiy Qoidalar (Key Differences and General Rules)[/b]\n"
        "• [b]A/An[/b] faqat birlik sanaladigan otlar bilan ishlatiladi. Sanalmaydigan otlar bilan [b]ishlatilmaydi[/b].\n"
        "  • _Correct_: [b]a chair[/b] ✅ / _Incorrect_: [b]an information[/b] ❌\n"
        "• Sanaladigan otlar bilan [b]'many' va 'few'[/b] ishlatiladi. Sanalmaydigan otlar bilan [b]'much' va 'little'[/b] ishlatiladi.\n"
        "  • He has [b]many books[/b]. 📚 – Uning ko'p kitoblari bor.\n"
        "  • She doesn't have [b]much money[/b]. 💸 – Uning ko'p puli yo'q.\n"
        "  • I have [b]much information[/b]. 📚 – Mening ko'p informatsiyam bor.\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=q5rWCTq47iU&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=67]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 56,
    "title": "Artikllar: A / An va The (Mavhum va Aniq Artikllar)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 56[/b] darsimizda ingliz tilidagi ikkita asosiy artiklni – [b]'a' / 'an' va 'the'[/b]ni birgalikda ko'rib chiqamiz. Oldingi darsimizda 'a' va 'an'ni o'rgangan edik. Endi 'the' artiklini qo'llash qoidalarini va ular o'rtasidagi farqlarni tushunamiz. Keling, boshlaymiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]A / An (Noma'lum Artikllar) Qisqacha Takrorlash (Brief Review of A / An)[/b]\n"
        "• [b]'A'[/b] va [b]'an'[/b] artikllari birlikdagi sanaladigan otlar oldidan, ular [b]noma'lum[/b] yoki birinchi marta tilga olinayotganda ishlatiladi. Ular \"birorta\" degan ma'noni beradi.\n"
        "  • I need [b]a pen[/b]. 🖊️ – Menga bir ruchka kerak. (Har qanday ruchka)\n"
        "  • She has [b]an old bicycle[/b]. 🚲 – Uning eski velosipedi bor. (Har qanday eski velosiped)\n\n"
        "✅ [b]The (Aniq Artiklar) - Umumiy Qoidalar (The (Definite Article) - General Rules)[/b]\n"
        "• [b]'The'[/b] artikli [b]aniq[/b] biror aniq narsa yoki shaxs haqida gapirilganda, yoki oldinroq tilga olingan narsa qayta eslanganda yoki dunyodagi yagona jismlarga(the sun, the moon) nisbatan ishlatiladi.\n"
        "  • I have a car. [b]The car[/b] is red. 🚗 – Mening mashinam bor. O'sha mashina qizil. (gap qaysi mashina haqida ketayotgani aniq)\n"
        "  • Can you close [b]the door[/b]? 🚪 – Eshikni yopa olasizmi? (Qaysi eshikligi ma'lum. Xonamizning eshigi)\n"
        "  • [b]The sun[/b] is very bright today. ☀️ – Bugun quyosh juda yorqin. (Dunyoda yagona bo'lgan narsalar bilan)\n"
        "  • Who is [b]the manager[/b] of this store? 🧑‍💼 – Bu do'konning menejeri kim? (Ma'lum bir shaxs)\n\n"
        "• Please turn off [b]the light[/b]. 💡 – Iltimos, chiroqni o'chiring. (Xonadagi ma'lum chiroq)\n"
        "• Where is [b]the bathroom[/b]? 🚽 – Hammom qayerda? (Uyning yagona hammomi)\n"
        "• Can you pass me [b]the salt[/b]? 🧂 – Menga tuzni uzata olasizmi? (Stoldagi ma'lum tuz)\n\n"
        "✅ [b]Sanaladigan/Sanalmaydigan Otlar bilan The (The with Countable/Uncountable Nouns)[/b]\n"
        "[b]'The'[/b] artikli ham sanaladigan, ham sanalmaydigan otlar bilan ishlatilishi mumkin, agar ular [b]aniq[/b] bo'lsa.\n"
        "• [b]The apples[/b] in this basket are fresh. 🍎 (sanaladigan) – Bu savatdagi olmalar yangi.\n"
        "• [b]The water[/b] in the bottle is cold. 💧 (sanalmaydigan) – Idishdagi suv sovuq.\n"
        "• I enjoyed [b]the music[/b] at the concert last night. 🎶 (sanalmaydigan) – Kecha konsertdagi musiqadan rohatlandim.\n\n"
        "Oxirgi misol(a/an vs the)\n"
        "Give me an apple - Menga olma ber.(Aniq qaysi olmani berish kerakligi ochiqlanmayapti. Masalan 1kg olmadan xohlagan bittasini berish aytilyapti)\n"
        "Give me the apple on the table - Stol ustidagi olmani ber.(Stol ustida bitta olma bor va o'shani ber deyilyapti)\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=49RNu3zbR5U&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=69]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 57,
    "title": "Aniq Artikllar: The (Chuqurlashtirilgan Qo'llash)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 57[/b] darsimizda aniq artikl – [b]'the'[/b]ning turli qo'llanish holatlarini chuqurroq o'rganamiz. 'The' artikli ingliz tilida juda ko'p ishlatiladi va uning ma'nosi aniqlikni, ma'lum bir narsani bildiradi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Biz Gapirayotgan Predmet Aniq Bo'lganda (When it's clear which thing or person we mean)[/b]\n"
        "Biz gapirayotgan narsa yoki shaxs [b]kim yoki qaysi[/b] ekanligi aniq bo'lganda [b]'the'[/b] ishlatamiz.\n"
        "• Excuse me, where is [b]the nearest post office[/b]? ✉️ – Uzr, eng yaqin pochta bo'limi qayerda?\n"
        "• Can you please tell me [b]the time[/b]? ⌚ – Iltimos, menga vaqtni ayta olasizmi? (Hozirgi vaqt)\n"
        "• I live on [b]the third floor[/b]. 🏢 – Men uchinchi qavatda yashayman. (Ma'lum bir qavat)\n"
        "• What is [b]the name of this player[/b]? 🛣️ – Bu o'yinchining ismi nima? (Ma'lum bir o'yinchi)\n\n"
        "✅ [b]\"The same...\" (Bir xil bo'lganda)[/b]\n"
        "[b]'The same'[/b] iborasi doim [b]'the'[/b] artikli bilan ishlatiladi.\n"
        "• My brother and I have [b]the same[/b] hobby. 🎨 – Akam ikkalamizning hobbiimiz bir xil.\n"
        "• We live in [b]the same[/b] neighborhood. 🏘️ – Biz bir mahallada yashaymiz.\n\n"
        "✅ [b]Umumiy Yagona Narsalar va Guruhlar (Unique General Things and Groups)[/b]\n"
        "• Dunyoda [b]yagona[/b] bo'lgan narsalar bilan:\n"
        "  • [b]The sun[/b] is shining brightly. ☀️ – Quyosh yorqin nur sochmoqda.\n"
        "  • We can see [b]the moon[/b] clearly tonight. 🌙 – Bugun kechqurun oyni tiniq ko'rishimiz mumkin.\n"
        "  • They traveled all around [b]the world[/b]. 🗺️ – Ular butun dunyo bo'ylab sayohat qilishdi.\n"
        "• Ma'lum bir [b]guruh yoki tashkilotlar[/b] bilan:\n"
        "  • [b]The police[/b] arrived quickly at the scene. 🚓 – Politsiya voqea joyiga tez yetib keldi.\n"
        "  • My brother wants to join [b]the army[/b]. 💂‍♂️ – Akam armiyaga qo'shilishni xohlaydi.\n"
        "• Joylashuvni bildiruvchi ba'zi so'zlar bilan:\n"
        "  • Your books are at [b]the top[/b] of the shelf. ✍️ – Kitoblaringiz javonning yuqorisida.\n"
        "  • The university is at [b]the end[/b] of this street. 🏡 – Universitet shu ko'chaning oxirida.\n"
        "• [b]Musiqiy asboblar[/b] bilan:\n"
        "  • She plays [b]the piano[/b] very well. 🎹 – U pianino chalishni juda yaxshi biladi.\n"
        "  • He wants to learn to play [b]the guitar[/b]. 🎸 – U gitara chalishni o'rganishni xohlaydi.\n"
        "• [b]Radio[/b] bilan:\n"
        "  • I often listen to [b]the radio[/b] in the car. 📻 – Men mashinada tez-tez radio eshitib turaman.\n\n"
        "✅ [b]'The' Ishlatilmaydigan Holatlar (When 'The' is NOT Used)[/b]\n"
        "Ba'zi holatlarda [b]'the'[/b] artikli ishlatilmaydi. Ularni eslab qolish muhimdir.\n"
        "• [b]Televizor[/b] ko'rish haqida umuman gapirilganda:\n"
        "  • I watch [b]television[/b] a lot. (not: the television) 📺 – Men televizor ko'p ko'raman.\n"
        "  • What's on [b]TV[/b] today? – Bugun TVda nima bor?\n"
        "• [b]Ovqatlanish vaqtlari[/b] (nonushta, tushlik, kechki ovqat) bilan:\n"
        "  • What time do you have [b]breakfast[/b]? (not: the breakfast) 🥣 – Nonushtani soat nechchida qilasiz?\n"
        "  • [b]Dinner[/b] will be served later! 🍽️ – Kechki ovqat keyinroq suziladi!\n"
        "• [b]Keyingi/o'tgan[/b] hafta/oy/yil/kun kabi vaqt iboralari bilan:\n"
        "  • I'm going away [b]next week[/b]. (not: the next week) ✈️ – Men keyingi hafta ketaman.\n"
        "  • Did you have a good time [b]last summer[/b]? 🏖️ – O'tgan yozda yaxshi dam oldingizmi?\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=dOp6p--WgS4&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=70]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
