  {
    "lesson": 58,
    "title": "Artikl 'The' Ishlatilmaydigan Holatlar (When 'The' is NOT Used)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 58[/b] darsimizda aniq artikl – [b]'the'[/b]ni qaysi holatlarda [b]ishlatmaslik[/b] kerakligini o'rganamiz. Ingliz tilida umumiy g'oyalar, sport turlari va til nomlari kabi ba'zi kontekstlarda 'the' artikli tushirib qoldiriladi. Keling, bu qoidalarni ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Umumiy G'oyalar Uchun 'The' Ishlatilmaydi (Do not use 'the' for general ideas)[/b]\n"
        "Biror narsa yoki g'oya haqida [b]umumiy[/b] gapirilganda, ya'ni aniq bir nusxasi haqida emas, [b]'the'[/b] ishlatilmaydi.\n"
        "• I like [b]coffee[/b]. ☕ – Men qahvani yaxshi ko'raman. (Har qanday qahva)\n"
        "• [b]Life[/b] is full of surprises. 🌍 – Hayot syurprizlarga to'la.\n"
        "• I hate [b]cold weather[/b]. 🥶 – Sovuq ob-havoni yomon ko'raman.\n"
        "• [b]Water[/b] is essential for survival. 💧 – Suv yashash uchun zarur.\n"
        "• Do you read [b]newspapers[/b] often? 📰 – Siz tez-tez gazetalar o'qiysizmi?\n\n"
        "✅ [b]Sport va O'yinlar (Sports and Games)[/b]\n"
        "[b]Sport turlari va o'yinlarning nomlari[/b] bilan 'the' ishlatilmaydi.\n"
        "• My favorite sport is [b]basketball[/b]. 🏀 – Mening sevimli sport turim basketbol.\n"
        "• Do you play [b]tennis[/b]? 🎾 – Siz tennis o'ynaysizmi?\n"
        "• He enjoys [b]swimming[/b] in the lake. 🏊‍♂️ – U ko'lda suzishdan zavqlanadi.\n\n"
        "✅ [b]Tillar va Fanlar (Languages and Academic Subjects)[/b]\n"
        "[b]Tillar nomlari[/b] yoki [b]o'quv fanlari[/b] bilan 'the' ishlatilmaydi.\n"
        "• Do you speak [b]English[/b]? 🗣️ – Siz inglizcha gapirasizmi?\n"
        "• [b]Mathematics[/b] is a challenging subject. ➕ – Matematika qiyin fan.\n"
        "• She is studying [b]history[/b] at university. 🏛️ – U universitetda tarixni o'rganmoqda.\n\n"
        "✅ [b]Umumlashma va Maxsus Holatlar (General vs. Specific)[/b]\n"
        "Biror narsa haqida [b]umuman[/b] gapirilganda 'the' ishlatilmaydi, ammo [b]aniq bir holatda[/b] yoki [b]ma'lum bir guruh[/b] haqida gapirilganda 'the' ishlatiladi.\n"
        "• [b]Books[/b] are important for education. 📚 (Umumiy) – Kitoblar ta'lim uchun muhim.\n"
        "  [b]The books[/b] on this shelf are mine. 📖 (Aniq) – Bu javondagi kitoblar meniki.\n\n"
        "• I don't like [b]cold weather[/b]. ❄️ (Umumiy) – Men sovuq ob-havoni yoqtirmayman.\n"
        "  [b]The weather[/b] was terrible yesterday. 🌧️ (Aniq, o'tgan kundagi ob-havo) – Kecha ob-havo juda yomon edi.\n\n"
        "• We often eat [b]fruit[/b]. 🍎🍌 (Umumiy) – Biz tez-tez meva yeymiz.\n"
        "  [b]The fruit[/b] you bought yesterday was delicious. 🍓 (Aniq, kecha sotib olingan meva) – Siz kecha sotib olgan meva juda mazali edi.\n\n"
        "• Are you interested in [b]science[/b]? 🔬 (Umumiy) – Siz fanga qiziqasizmi?\n"
        "  Are you interested in [b]the science of robotics[/b]? 🤖 (Aniq, robototexnika fani) – Siz robototexnika faniga qiziqasizmi?\n\n"
