  {
    "lesson": 59,
    "title":
        "Artikl 'The' Geografik Nomlar va Joylar Bilan (The with Names of Places)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 59[/b] darsimizda aniq artikl – [b]'the'[/b]ni geografik nomlar va joylar bilan qanday ishlatishni o'rganamiz. Bu qoidalar ba'zan chalkash bo'lishi mumkin, shuning uchun diqqat bilan o'rganing! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'The' Ishlatilmaydigan Holatlar (When 'The' is NOT Used)[/b]\n"
        "• [b]Qit'alar, alohida mamlakatlar, shtatlar, shaharlar, shaharchalar[/b] nomlari bilan odatda 'the' ishlatilmaydi.\n"
        "  • I want to visit [b]France[/b] someday. 🇫🇷 – Kun kelib Fransiyaga borishni xohlayman.\n"
        "  • [b]Tashkent[/b] is the capital of Uzbekistan. 🇺🇿 – Toshkent O'zbekiston poytaxti.\n"
        "  • She lives in [b]California[/b]. ☀️ – U Kaliforniyada yashaydi.\n\n"
        "• [b]Ko'chalar va maydonlar[/b] nomlari bilan 'the' ishlatilmaydi.\n"
        "  • My office is on [b]Main Street[/b]. 🏢 – Mening ofisim Main ko'chasida.\n"
        "  • Let's meet at [b]Central Square[/b]. 📍 – Keling, Markaziy maydonda uchrashamiz.\n\n"
        "• Ba'zi umumiy joylar (aeroportlar, stansiyalar, universitetlar, qal'alar) nomlari bilan 'the' odatda ishlatilmaydi.\n"
        "  • We arrived at [b]Heathrow Airport[/b]. ✈️ – Biz Xitrou aeroportiga yetib keldik.\n"
        "  • She studies at [b]Cambridge University[/b]. 🎓 – U Kembrij universitetida o'qiydi.\n\n"
        "✅ [b]'The' Ishlatiladigan Holatlar (When 'The' IS Used)[/b]\n"
        "• [b]'Republic', 'United States', 'Kingdom'[/b] kabi so'zlar bilan kelgan mamlakat nomlari bilan:\n"
        "  • [b]The Republic of Korea[/b] is in East Asia. 🇰🇷 – Koreya Respublikasi Sharqiy Osiyoda joylashgan.\n"
        "  • Have you ever been to [b]the United States[/b]? 🗽 – Siz AQShda bo'lganmisiz?\n"
        "• [b]Ko'plik shaklidagi mamlakat, orol yoki tog' nomlari[/b] bilan:\n"
        "  • [b]The Netherlands[/b] is known for its tulips. 🌷 – Niderlandiya lola gullari bilan mashhur.\n"
        "  • They are planning a trip to [b]the Caribbean Islands[/b]. 🏝️ – Ular Karib orollariga sayohatni rejalashtirishmoqda.\n"
        "  • [b]The Himalayas[/b] are the highest mountains in the world. ⛰️ – Himolay tog'lari dunyodagi eng baland tog'lardir.\n"
        "• [b]Dengizlar, daryolar, okeanlar va kanallar[/b] nomlari bilan:\n"
        "  • [b]The Atlantic Ocean[/b] separates Europe and America. 🌊 – Atlantika okeani Yevropa va Amerikani ajratib turadi.\n"
        "  • [b]The Nile River[/b] is the longest river in Africa. 🏞️ – Nil daryosi Afrikadagi eng uzun daryo.\n"
        "  • Ships pass through [b]the Suez Canal[/b]. 🚢 – Kemalar Suvaysh kanali orqali o'tadi.\n"
        "• Ba'zi [b]mehmonxonalar, restoranlar, kinoteatrlar, teatrlar, muzeylar, galereyalar[/b] nomlari bilan:\n"
        "  • We stayed at [b]the Grand Hotel[/b]. 🏨 – Biz Grand mehmonxonasida qoldik.\n"
        "  • Let's go to [b]the National Theatre[/b] tonight. 🎭 – Bugun kechqurun Milliy teatrga boramiz.\n\n"
        "✅ [b]'The ... of ...' Tuzilishi (The ... of ... Structure)[/b]\n"
        "Biror narsaning biror joyga tegishliligini bildiruvchi [b]'the ... of ...'[/b] tuzilishida ham 'the' ishlatiladi.\n"
        "• [b]The Bank of England[/b] is in London. 🏦 – Angliya banki Londonda joylashgan.\n"
        "• [b]The Great Wall of China[/b] is a famous landmark. 🧱 – Buyuk Xitoy devori mashhur diqqatga sazovor joy.\n\n"
        "✅ [b]Yo'nalishlar (Directions)[/b]\n"
        "Dunyo yo'nalishlarini bildiruvchi so'zlar bilan [b]'the'[/b] ishlatiladi.\n"
        "• The sun rises in [b]the east[/b] and sets in [b]the west[/b]. 🌅 – Quyosh sharqdan chiqib, g'arbga botadi.\n"
        "• My country is located in [b]the middle[/b] of Asia. 🌏 – Mening mamlakatim Osiyoning markazida joylashgan.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=S_YCCGK-Zxc&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=73]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 60,
    "title":
        "Ko'rsatish Olmoshlari: This / That / These / Those (Demonstrative Pronouns)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 60[/b] darsimizda ingliz tilidagi ko'rsatish olmoshlari – [b]'this', 'that', 'these', 'those'[/b]ni o'rganamiz. Bu so'zlar narsalarni yoki odamlarni ko'rsatish va ularning o'rnini (yaqin yoki uzoq) bildirish uchun ishlatiladi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]This / These (Yaqin Narsalar Uchun) (For Near Things)[/b]\n"
        "• [b]'This'[/b] birlikdagi, [b]'these'[/b] ko'plikdagi, [b]sizga yaqin bo'lgan[/b] narsalar yoki odamlarni ko'rsatish uchun ishlatiladi.\n"
        "  • [b]This book[/b] is very interesting. 📖 – Bu kitob juda qiziq.\n"
        "  • I like [b]these shoes[/b] a lot. 👟 – Menga bu poyabzallar juda yoqadi.\n"
        "  • [b]This is[/b] my new phone. 📱 – Bu mening yangi telefonim.\n\n"
        "✅ [b]That / Those (Uzoq Narsalar Uchun) (For Far Things)[/b]\n"
        "• [b]'That'[/b] birlikdagi, [b]'those'[/b] ko'plikdagi, [b]sizdan uzoqda bo'lgan[/b] narsalar yoki odamlarni ko'rsatish uchun ishlatiladi.\n"
        "  • Look at [b]that building[/b] over there. 🏙️ – Anavi binoga qarang.\n"
        "  • [b]Those flowers[/b] in the vase are beautiful. 🌷 – Vazadagi o'sha gullar chiroyli.\n"
        "  • Who are [b]those people[/b] standing outside? 🚶‍♂️🚶‍♀️ – Tashqarida turgan o'sha odamlar kimlar?\n\n"
        "✅ [b]Ot bilan va Otsiz Ishlatish (Using with and without Nouns)[/b]\n"
        "Bu olmoshlar [b]otlar bilan birga (sifatdek)[/b] yoki [b]otsiz (olmoshdek)[/b] ishlatilishi mumkin.\n"
        "• [b]This car[/b] is new. (ot bilan) 🚗 – Bu mashina yangi.\n"
        "• [b]This[/b] is new. (otsiz) 🆕 – Bu yangi.\n"
        "• Do you like [b]those pictures[/b]? (ot bilan) 🖼️ – O'sha rasmlarni yoqtirasizmi?\n"
        "• Which do you prefer, [b]this or that[/b]? (otsiz) 🤔 – Qaysini afzal ko'rasiz, buni yoki anavini?\n\n"
        "✅ [b]Maxsus Qo'llanish Holatlari (Special Uses)[/b]\n"
        "• [b]“That” o'tgan voqea uchun (That for something that has happened)[/b]: Avval sodir bo'lgan yoki aytilgan narsalarga ishora qilish uchun [b]'that'[/b] ishlatiladi.\n"
        "  • I'm sorry I was late. – [b]That's all right[/b]. 👍 – Kech qolganim uchun uzr. – Hechqisi yo'q.\n"
        "  • I just heard the news. [b]That's terrible[/b]! 😔 – Men hozirgina yangilikni eshitdim. Bu dahshatli!\n"
        "• [b]Telefon suhbatlarida (In telephone conversations)[/b]: O'zingizni tanishtirish uchun [b]'this'[/b], boshqa shaxsni so'rash uchun [b]'that'[/b] ishlatiladi.\n"
        "  • Hello, [b]this is[/b] Mark. 📞 – Salom, bu Mark.\n"
        "  • Is [b]that[/b] Sarah? 👧 – Bu Sara(mi)?\n"
        "• [b]Odamlarni tanishtirishda (To introduce people)[/b]: Kimnidir tanishtirish uchun [b]'this'[/b] ishlatiladi.\n"
        "  • Mum, [b]this is[/b] my friend, Alex. 👋 – Ona, bu mening do'stim, Aleks.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=UY6oRh4cC_4&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=74]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 61,
    "title":
        "Ot O'rnini Bosuvchi 'One' va 'Ones' (Substituting 'One' and 'Ones')",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 61[/b] darsimizda ingliz tilida takrorlanishdan qochish uchun ishlatiladigan [b]'one' va 'ones'[/b] so'zlarini o'rganamiz. Bu so'zlar oldinroq tilga olingan birlik yoki ko'plikdagi otlarning o'rnini bosadi(ya'ni bitta so'zning ikkinchi marta takrorlanishini oldini oladi), bu esa nutqni tabiiyroq qiladi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'One' (Birlik Otlar O'rnida) (For Singular Nouns)[/b]\n"
        "[b]'One'[/b] so'zi takrorlanayotgan [b]birlik sanaladigan ot[/b]ning o'rnini bosadi, ayniqsa undan oldin [b]'a' yoki 'an'[/b] kelsa.\n"
        "• Do you have a pen? Yes, I have [b]one[/b]. 🖊️ – Sizda ruchka bormi? Ha, menda bor(bittasi).\n"
        "• This is a nice shirt. I might buy [b]one[/b]. 👕 – Bu chiroyli ko'ylak. Ehtimol, bittasini sotib olaman.\n"
        "• Which car is yours? [b]The red one[/b]. 🚗 – Qaysi mashina sizniki? Qizil ranglisi(qizil bittasi).\n\n"
        "✅ [b]'Ones' (Ko'plik Otlar O'rnida) (For Plural Nouns)[/b]\n"
        "[b]'Ones'[/b] so'zi takrorlanayotgan [b]ko'plik sanaladigan ot[/b]ning o'rnini bosadi.\n"
        "• I need new shoes. These [b]ones[/b] are too old. 👟 – Menga yangi poyabzal kerak. Bular juda eski.\n"
        "• Do you want these cookies or those [b]ones[/b]? 🍪 – Sizga bu pechenyelar kerakmi yoki anavilari?\n"
        "• My shoes are old. I'm going to buy some new [b]ones[/b]. 🛍️ – Poyabzallarim eski. Bir nechta yangisini sotib olaman.\n\n"
        "✅ [b]'This/That one' va 'These/Those ones' (Specific Items)[/b]\n"
        "Ma'lum bir narsani ko'rsatish yoki tanlashda [b]'this one', 'that one', 'these ones', 'those ones'[/b] ishlatiladi.\n"
        "• Which cake would you like? I'll take [b]this one[/b]. 🍰 – Qaysi tortni xohlaysiz? Men buni olaman(bu bittasini).\n"
        "• Do you prefer [b]that one[/b] or [b]this one[/b]? 🤔 – Anavini afzal ko'rasizmi yoki bunimi?\n"
        "• I don't like [b]those ones[/b] with sprinkles. 🍩 – Men shakar sepilgan anavilarni yoqtirmayman.\n\n"
        "✅ [b]'The one(s)' va Sifatlar Bilan ('The one(s)' with Adjectives)[/b]\n"
        "• [b]'The one(s)'[/b] ma'lum bir, aniq, ajratilgan narsaga ishora qilish uchun ishlatiladi, ko'pincha sifat yoki ta'rif bilan birga keladi.\n"
        "  • This is the old phone, and that's [b]the new one[/b]. 📞 – Bu eski telefon, anavi esa yangisi(yangi bittasi).\n"
        "  • I don't like the red jacket, but I like [b]the black one[/b]. ⚫ – Menga qizil kurtka yoqmaydi, lekin qorasini yoqtiraman.\n"
        "  • I prefer [b]the larger ones[/b]. 📦 – Menga kattaroqlar afzal.\n"
        "  • These are good apples, but [b]the ones[/b] you bought yesterday were better. 🍏 – Bular yaxshi olmalar, lekin siz kecha sotib olganlaringiz yaxshiroq edi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=ddC4HqzPevA&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=75]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 62,
    "title": "Miqdor Olmoshi: Some va Any (Quantifiers: Some and Any)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 62[/b] darsimizda ingliz tilidagi miqdor olmoshlari – [b]'some' va 'any'[/b]ni o'rganamiz. Bu so'zlar narsalarning aniq miqdori yoki sonini aytmasdan, umuman ularning mavjudligini bildirish uchun ishlatiladi. Keling, ularning qo'llanish qoidalarini ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Some' (Darak Gaplar Uchun) (For Affirmative Sentences)[/b]\n"
        "[b]'Some'[/b] (ya'ni, 'biroz', 'ozgina', 'bir nechta', 'qanchadir') odatda [b]darak gaplarda[/b] ham sanaladigan (ko'plikda), ham sanalmaydigan otlar bilan ishlatiladi.\n"
        "• I've got [b]some money[/b] in my wallet. 💰 – Hamyonimda ozgina pulim bor.\n"
        "• She bought [b]some flowers[/b] for her mother. 💐 – U onasi uchun bir nechta gul sotib oldi.\n"
        "• There is [b]some milk[/b] in the fridge. 🥛 – Muzlatkichda ozgina sut bor.\n\n"
        "✅ [b]'Any' (Salbiy Gaplar va Ko'pincha Savollar Uchun) (For Negative Sentences and Most Questions)[/b]\n"
        "[b]'Any'[/b] (ya'ni, 'hech qanday', 'hech qancha', 'biroz'(savol gaplarda)) odatda [b]salbiy (inkor) gaplarda[/b] va [b]ko'pgina savollarda[/b] ishlatiladi.\n"
        "• I don't have [b]any questions[/b]. ❓ – Menda hech qanday savollar yo'q.\n"
        "• Is there [b]any sugar[/b] left? 🍚 – Biroz shakar qolganmi?\n"
        "• We didn't see [b]any cars[/b] on the road. 🛣️ – Yo'lda hech qanday mashinalarni ko'rmadik.\n\n"
        "✅ [b]Savollarda 'Some' Ishlatiladigan Holatlar (When 'Some' is Used in Questions)[/b]\n"
        "Ba'zi savollarda [b]'some'[/b] ishlatilishi mumkin, ayniqsa biz biror narsani [b]taklif qilganimizda[/b], [b]so'raganimizda[/b] yoki [b]ijobiy javob kutganimizda[/b].\n"
        "• Would you like [b]some tea[/b]? ☕ – Siz choy ichasizmi? (Taklif)\n"
        "• Could I have [b]some help[/b], please? 🙏 – Menga yordam bera olasizmi, iltimos? (So'rov)\n"
        "• Are you bringing [b]some friends[/b] to the party? 🎉 (Do'stlarining kelishini kutyapman) – Bazmga do'stlaringizni olib kelayapsizmi?\n\n"
        "✅ [b]Ot bilan va Otsiz 'Some/Any' (Some/Any with and without Nouns)[/b]\n"
        "[b]'Some'[/b] va [b]'any'[/b] ot bilan birga yoki ot tushirib qoldirilgan holda ham ishlatilishi mumkin, agar ot ma'lum bo'lsa.\n"
        "• I need to buy [b]some milk[/b]. Do you have [b]any[/b]? 🥛 – Menga sut sotib olishim kerak. Sizda bormi?\n"
        "• She offered me [b]some coffee[/b], but I didn't want [b]any[/b]. ☕ – U menga kofe taklif qildi, lekin men xohlamadim.\n"
        "• Are there [b]any biscuits[/b] left? Yes, there are [b]some[/b]. 🍪 – Pechenyeler qoldimi? Ha, ozgina bor.\n\n"
        "✅ [b]'Something/Somebody' va 'Anything/Anybody' (Compounds with Some/Any)[/b]\n"
        "[b]'Some'[/b] va [b]'any'[/b] so'zlari [b]'-thing', '-body', '-one', '-where'[/b] kabi qo'shimchalar bilan birikmalar hosil qiladi:\n"
        "• [b]Darak gaplarda[/b]: [b]something, somebody/someone, somewhere[/b].\n"
        "  • I saw [b]somebody[/b] at the door. 🚪 – Eshik oldida kimnidir ko'rdim.\n"
        "  • There is [b]something[/b] in my eye. 👀 – Ko'zimga nimadir tushdi.\n"
        "  • Let's go [b]somewhere[/b] warm. ☀️ – Keling, iliqroq joyga boramiz.\n"
        "• [b]Salbiy gaplarda va savollarda[/b]: [b]anything, anybody/anyone, anywhere[/b].\n"
        "  • She didn't say [b]anything[/b]. 🤫 – U hech narsa demadi.\n"
        "  • Did you see [b]anyone[/b] in the room? 🚶‍♀️ – Xonada kimnidir ko'rdingizmi?\n"
        "  • I couldn't find my keys [b]anywhere[/b]. 🔑 – Kalitlarimni hech qayerdan topa olmadim.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=RCC6J4wlw9Q&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=76]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 63,
    "title":
        "Inkor Ma'nosi: Not + Any, No va None (Negative Meaning: Not + Any, No and None)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 63[/b] darsimizda ingliz tilida inkor ma'nosini ifodalovchi [b]'not + any', 'no' va 'none'[/b] so'zlarini o'rganamiz. Bu so'zlar bir-biriga o'xshash bo'lsa-da, ularni ishlatishda ma'lum qoidalar mavjud. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Not + Any (Any bilan Inkor Gaplar) (Negative Sentences with Any)[/b]\n"
        "Biz [b]\"not\"[/b] bilan birga [b]'any'[/b] ishlatib, hech narsa yoki hech qancha yo'qligini bildiramiz.\n"
        "• They haven't got [b]any furniture[/b]. 👨‍👩‍👧‍👦 – Ularning hech qanday mebeli yo'q.\n"
        "• There isn't [b]any sugar[/b] in my coffee. ☕ – Kofemda shakar yo'q.\n"
        "• I didn't find [b]any information[/b] about it. ℹ️ – Bu haqida hech qanday ma'lumot topmadim.\n\n"
        "✅ [b]'No' (Otlar Bilan) (Using 'No' with Nouns)[/b]\n"
        "[b]'No'[/b] so'zi [b]to'g'ridan-to'g'ri ot oldidan[/b] keladi va \"hech qanday\" yoki \"nol miqdorda\" degan ma'noni beradi. U [b]'not + any'[/b] ga teng ma'noli bo'lishi mumkin, lekin grammatik tuzilishi boshqa.\n"
        "• We've got [b]no key[/b]. 💸 – Bizda kalit yo'q.\n"
        "• There are [b]no cars[/b] in the car park. 🅿️ – Avtoturargohda mashinalar yo'q.\n"
        "• She has [b]no idea[/b] what to do. 💡 – U nima qilishni bilmaydi.\n\n"
        "✅ [b]'None' (Otsiz) (Using 'None' without a Noun)[/b]\n"
        "[b]'None'[/b] olmoshi \"hech qanday (narsa/odam)\" degan ma'noni beradi va [b]otsiz[/b] ishlatiladi. Ko'pincha 'How much?' yoki 'How many?' savollariga javob sifatida keladi.\n"
        "• How much money have you got? [b]None[/b]. 💵 – Qancha pulingiz bor? Hech qancha (yo'q).\n"
        "• There were many problems, but [b]none[/b] were too serious. ⚠️ – Ko'p muammolar bor edi, lekin hech qaysisi jiddiy emasdi.\n"
        "• I asked if there were any questions, and [b]none[/b] were asked. 🤔 – Savollar bormi, deb so'radim, va hech qaysi berilmadi.\n\n"
        "✅ [b]'No-one' (Odamlar Uchun) (Using 'No-one' for People)[/b]\n"
        "[b]'No-one'[/b] (yoki [b]'nobody'[/b]) so'zi \"hech kim\" degan ma'noni beradi va faqat [b]odamlar[/b]ga nisbatan ishlatiladi. U ko'pincha 'Who?' savoliga javob sifatida keladi.\n"
        "• [b]No-one[/b] was at home when I called. 🏠 – Men qo'ng'iroq qilganimda uyda hech kim yo'q edi.\n"
        "• Who did you meet? [b]No-one[/b]. 🤷‍♂️ – Kim bilan uchrashdingiz? Hech kim bilan.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=eA1grZkCozU&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=77]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 64,
    "title":
        "Inkor Olmoshlari: Nobody / No-one / Nothing va Any-Birikmalar (Negative Pronouns: Nobody / No-one / Nothing and Any-Compounds)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 64[/b] darsimizda ingliz tilida inkor ma'nosini ifodalashda keng qo'llaniladigan [b]'not + anybody/anyone/anything'[/b] hamda [b]'nobody/no-one/nothing'[/b] olmoshlarini o'rganamiz. Bu tuzilmalar biror narsaning yoki shaxsning mutlaqo yo'qligini bildirish uchun muhimdir va ingliz tilidagi 'ikki karra inkor'ga yo'l qo'ymaslik uchun turli grammatik usullar taklif etadi. Keling, ularning qo'llanilish qoidalarini va sabablarini batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Inkor Fe'l + Any-Birikma (Negative Verb + Any-Compound)[/b]\n"
        "Biz [b]inkor fe'l[/b] (masalan, [b]isn't, don't have[/b]) bilan birga [b]'anybody' / 'anyone'[/b] (odamlar uchun) va [b]'anything'[/b] (narsalar uchun) ishlatamiz.\n"
        "• There [b]isn't anybody[/b] in the office right now. 🏢 – Hozir ofisda hech kim yo'q.\n"
        "• I [b]didn't hear anything[/b] unusual last night. 🔇 – Kecha tunda g'ayrioddiy hech narsa eshitmadim.\n"
        "• She [b]doesn't want anyone[/b] to know her address. ✉️ – U manzilini hech kim bilishini istamaydi.\n"
        "• We [b]haven't seen anything[/b] like this before. 😲 – Biz ilgari bunaqasini ko'rmaganmiz.\n"
        "• Are you sure you [b]don't need any help[/b]? 🙋‍♀️ – Hech qanday yordam kerak emasligiga ishonchingiz komilmi?\n\n"
        "✅ [b]'No'-Birikmalar (Darak Fe'l Bilan) ('No'-Compounds with Affirmative Verb)[/b]\n"
        "[b]'Nobody' / 'no-one'[/b] (odamlar uchun) va [b]'nothing'[/b] (narsalar uchun) [b]darak fe'l[/b] bilan ishlatiladi, lekin inkor ma'nosini beradi. Ular [b]inkor fe'l + any-birikmaga[/b] tengdir.\n"
        "• There's [b]nobody[/b] in the office right now. ( = There isn't anybody) 🏢 – Hozir ofisda hech kim yo'q.\n"
        "• I heard [b]nothing[/b] unusual last night. ( = I didn't hear anything) 🔇 – Kecha tunda g'ayrioddiy hech narsa eshitmadim.\n"
        "• She wants [b]no-one[/b] to know her address. ( = She doesn't want anyone) ✉️ – U manzilini hech kim bilishini istamaydi.\n"
        "• We've seen [b]nothing[/b] like this before. ( = We haven't seen anything) 😲 – Biz ilgari bunaqasini ko'rmaganmiz.\n"
        "• [b]Nobody[/b] understood the difficult lecture. 😵 – Qiyin ma'ruzani hech kim tushunmadi.\n\n"
        "✅ [b]Gap Boshida Yoki Javob Sifatida ('No'-Compounds at the beginning of a sentence or as an answer)[/b]\n"
        "[b]'Nobody', 'no-one', 'nothing'[/b] gapning [b]boshida ega sifatida[/b] yoki [b]qisqa javob[/b] sifatida ishlatilishi mumkin.\n"
        "• [b]Nothing[/b] can stop us now. 🚀 – Endi bizni hech narsa to'xtata olmaydi.\n"
        "• Who saw the accident? [b]No-one[/b]. 🚓 – Baxtsiz hodisani kim ko'rdi? Hech kim.\n"
        "• [b]Nobody[/b] answered the phone. ☎️ – Telefonga hech kim javob bermadi.\n"
        "• What did you find in the box? [b]Nothing[/b]. 📦 – Qutidan nima topdingiz? Hech narsa.\n\n"
        "✅ [b]Ikki Karra Inkor Qilish Mumkin Emas (No Double Negatives)[/b]\n"
        "Ingliz tilida odatda [b]ikki karra inkor qilish[/b] (ya'ni, inkor fe'l va 'no-' birikmasini birga ishlatish) mumkin emas. Agar [b]'nobody', 'no-one', 'nothing'[/b] ishlatsak, fe'l [b]darak shaklda[/b] bo'lishi kerak.\n"
        "• I [b]didn't tell anybody[/b] about it. (TO'G'RI) ✅\n"
        "  I [b]told nobody[/b] about it. (TO'G'RI) ✅\n    (NOT: I didn't tell nobody about it.) ❌\n"
        "• She [b]doesn't have anything[/b] to eat. (TO'G'RI) ✅\n"
        "  She [b]has nothing[/b] to eat. (TO'G'RI) ✅\n    (NOT: She doesn't have nothing to eat.) ❌\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=Jza-8IOZsM8&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=78]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 65,
    "title":
        "Murakkab Olmoshlar: Somebody, Anything, Nowhere va Boshqalar (Compound Pronouns: Somebody, Anything, Nowhere and Others)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 65[/b] darsimizda ingliz tilidagi [b]murakkab olmoshlar[/b] – [b]'-body/-one', '-thing' va '-where'[/b] qo'shimchalari bilan yasalgan so'zlarni (masalan, [b]'somebody', 'anything', 'nowhere'[/b]) o'rganamiz. Bu so'zlar noaniq odamlarga, narsalarga yoki joylarga murojaat qilish uchun ishlatiladi. Keling, ularning qo'llanilish qoidalarini batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Some-' Birikmalar (Darak Gaplar va Taklif/So'rovlar Uchun) (For Affirmative Sentences and Offers/Requests)[/b]\n"
        "Bu birikmalar odatda [b]darak gaplarda[/b] hamda [b]taklif va so'rovlarda[/b] ishlatiladi.\n"
        "• [b]Somebody[/b] left a message for you. 📞 – Kimdir sizga xabar qoldirdi.\n"
        "• I need [b]something[/b] to drink. 🥤 – Menga ichishga biror narsa kerak.\n"
        "• Let's go [b]somewhere[/b] quiet this weekend. 🏞️ – Shu dam olish kunlari biror tinch joyga boraylik.\n"
        "• Would you like [b]something[/b] to eat? 🍔 – Biror narsa yegingiz keladimi? (Taklif)\n"
        "• Can [b]someone[/b] help me with this box? 📦 – Kimdir menga bu qutini ko'tarishga yordam bera oladimi? (So'rov)\n\n"
        "✅ [b]'Any-' Birikmalar (Inkor Gaplar va Ko'p Savollar Uchun) (For Negative Sentences and Most Questions)[/b]\n"
        "Bu birikmalar odatda [b]inkor gaplarda[/b] va [b]ko'pgina savollarda[/b] ishlatiladi.\n"
        "• I [b]didn't see anybody[/b] interesting at the event. 🚶‍♀️ – Tadbirda qiziqarli hech kimni ko'rmadim.\n"
        "• Do you have [b]anything[/b] to say? 🗣️ – Ayta oladigan biror narsangiz bormi?\n"
        "• She couldn't find her keys [b]anywhere[/b]. 🔑 – U kalitlarini hech qayerdan topa olmadi.\n"
        "• Is there [b]anyone[/b] who can speak French? 🇫🇷 – Frantsuzcha gapira oladigan bormi?\n"
        "• He doesn't need [b]anything[/b] from the shop. 🛒 – Unga do'kondan hech narsa kerak emas.\n\n"
        "✅ [b]'No-' Birikmalar (Darak Fe'l Bilan) (With Affirmative Verb)[/b]\n"
        "Bu birikmalar ([b]nobody/no-one, nothing, nowhere[/b]) [b]darak fe'l[/b] bilan ishlatiladi, ammo inkor ma'nosini beradi. Ular [b]inkor fe'l + any-birikmaga[/b] teng ma'noli bo'ladi.\n"
        "• [b]Nobody[/b] arrived on time. ⏰ – Hech kim o'z vaqtida yetib kelmadi.\n"
        "• I found [b]nothing[/b] in the empty cupboard. 🍽️ (= I [b]didn't find anything[/b] in the empty cupboard.) – Bo'sh shkafda hech narsa topmadim.\n"
        "• We went [b]nowhere[/b] last holiday. 🏖️ (= We [b]didn't go anywhere[/b] last holiday.) – O'tgan bayramda hech qayerga bormadik.\n"
        "• [b]No-one[/b] understood the complex instructions. 🤯 – Murakkab ko'rsatmalarni hech kim tushunmadi.\n\n"
        "✅ [b]Sifatlar Bilan Ishlatilishi (Usage with Adjectives)[/b]\n"
        "Bu murakkab olmoshlardan keyin [b]sifat[/b] kelishi mumkin.\n"
        "• I want [b]something hot[/b] to drink. ♨️ – Issiqroq biror narsa ichishni xohlayman.\n"
        "• Did you meet [b]anyone famous[/b] at the concert? 🎤 – Konsertda biror mashhur kishini uchratdingizmi?\n"
        "• There's [b]nothing new[/b] to report. 📰 – Xabar beradigan yangi hech narsa yo'q.\n\n"
        "✅ [b]'To + Verb' Bilan Ishlatilishi (Usage with 'To + Verb')[/b]\n"
        "Bu murakkab olmoshlardan keyin [b]'to + fe'l' (infinitiv)[/b] kelishi mumkin.\n"
        "• I need [b]something to eat[/b] before I go. 🍕 – Ketishimdan oldin biror narsa yeyishim kerak.\n"
        "• He has [b]nobody to talk[/b] to. 😞 – Uning gaplashadigan hech kimi yo'q.\n"
        "• There is [b]nowhere to sit[/b] in this crowded room. 🛋️ – Bu gavjum xonada o'tirishga joy yo'q.\n\n"
