  {
    "lesson": 66,
    "title": "Miqdor Olmoshlari: Every va All (Quantifiers: Every and All)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 66[/b] darsimizda ingliz tilidagi ikkita muhim miqdor olmoshi – [b]'every' va 'all'[/b]ni o'rganamiz. Bu so'zlar odamlar, narsalar yoki joylarning butun guruhlariga murojaat qilish uchun ishlatiladi, ammo ular o'ziga xos grammatik qoidalarga ega. Keling, ularning qo'llanilishini batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Every' (Har Bir) ('Every' (Each one))[/b]\n"
        "[b]'Every'[/b] har bir individual a'zoga ishora qilib, guruhdagi har bir shaxs yoki narsani anglatadi. U doimo [b]birlikdagi ot[/b] bilan ishlatiladi va fe'l ham birlikda bo'ladi.\n"
        "• [b]Every student[/b] received a certificate. 🎓 – Har bir talaba sertifikat oldi.\n"
        "• She reads [b]every book[/b] in the library. 📚 – U kutubxonadagi har bir kitobni o'qiydi.\n"
        "• [b]Every house[/b] on the street has a garden. 🏡 – Ko'chadagi har bir uyning bog'i bor.\n"
        "• I visit my grandparents [b]every summer[/b]. ☀️ – Har yozda bobom va buvimni ziyorat qilaman.\n\n"
        "✅ [b]'All' (Hamma/Barcha) ('All' (The Whole/Entire))[/b]\n"
        "[b]'All'[/b] bir guruhning yoki miqdorning [b]butunligini[/b] ifodalaydi. U [b]ko'plikdagi otlar[/b] (yoki sanalmaydigan otlar) bilan ishlatiladi.\n"
        "• [b]All students[/b] passed the exam. 💯 – Barcha talabalar imtihondan o'tishdi.\n"
        "• [b]All the information[/b] is available online. 🌐 – Barcha ma'lumotlar onlayn mavjud.\n"
        "• [b]All my friends[/b] came to my birthday party. 🎉 – Barcha do'stlarim tug'ilgan kunimga kelishdi.\n"
        "• We drank [b]all the water[/b] in the bottle. 💧 – Shishadagi barcha suvni ichdik.\n\n"
        "✅ [b]'Every' va 'All' Taqqoslanishi (Comparing 'Every' and 'All')[/b]\n"
        "• [b]Every[/b] child needs love. (Har bir bolani alohida ta'kidlaydi) 🧒❤️\n"
        "  [b]All[/b] children need love. (Barcha bolalarni bir guruh sifatida ta'kidlaydi) 👧👦❤️\n"
        "• [b]Every car[/b] in the parking lot was new. 🚗 (Har bir mashina alohida-alohida yangi edi)\n"
        "  [b]All the cars[/b] in the parking lot were new. 🚙 (Mashinalar guruhining hammasi yangi edi)\n"
        "• She read [b]every page[/b] of the book. 📖 (Kitobning har bir sahifasini o'qidi)\n"
        "  She read [b]all the pages[/b] of the book. 📚 (Kitobning barcha sahifalarini o'qidi)\n\n"
        "✅ [b]'Every day' va 'All day' (Har Kuni va Kun Bo'yi) ('Every day' vs 'All day')[/b]\n"
        "• [b]Every day[/b] (Har kuni): Takrorlanuvchi harakat yoki odatni bildiradi (qanchalik tez-tez? degan savolga javob).\n"
        "  • I drink coffee [b]every day[/b]. ☕ – Men har kuni kofe ichaman.\n"
        "  • She goes for a walk [b]every morning[/b]. 🚶‍♀️ – U har kuni ertalab sayrga chiqadi.\n"
        "• [b]All day[/b] (Kun bo'yi): Butun kun davomida sodir bo'lgan narsani bildiradi (qancha vaqt? degan savolga javob).\n"
        "  • I worked [b]all day[/b] yesterday. 👩‍💻 – Men kecha kun bo'yi ishladim.\n"
        "  • It rained [b]all day[/b], so we stayed inside. ☔ – Kun bo'yi yomg'ir yog'di, shuning uchun uyda qoldik.\n\n"
        "✅ [b]'-body/-one', '-thing', '-where' bilan 'Every-' Birikmalar (Compound 'Every-' Pronouns)[/b]\n"
        "Bu birikmalar ham guruhdagi barcha shaxslarni, narsalarni yoki joylarni anglatadi va ulardan keyin [b]birlikdagi fe'l[/b] keladi.\n"
        "• [b]Everybody[/b] needs water to survive. 💧 – Hamma tirik qolish uchun suvga muhtoj.\n"
        "• [b]Everything[/b] is ready for the trip. 🎒 – Sayohat uchun hamma narsa tayyor.\n"
        "• I looked [b]everywhere[/b] for my glasses. 👓 – Ko'zoynagimni hamma joydan qidirdim.\n"
        "• [b]Everyone[/b] agreed with the decision. 👍 – Qarorga hamma rozi bo'ldi.\n\n"
