  },
  {
    "lesson": 67,
    "title":
        "Miqdor Olmoshlari: Most / Some va Ularning 'Of' Bilan Qo'llanilishi (Quantifiers: Most / Some and Their Usage with 'Of')",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 67[/b] darsimizda ingliz tilidagi miqdor olmoshlari – [b]'most' va 'some'[/b] (shuningdek, [b]'any', 'no', 'none'[/b]) ning qo'llanilishini, ayniqsa [b]'of'[/b] predlogi bilan bog'liq qoidalarni o'rganamiz. Bu so'zlar miqdorlarni umumiy yoki aniq guruhlarga nisbatan ifodalashda muhim ahamiyatga ega. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Most/Some/Any/No + Ot (Umumiy Ma'noda) (Most/Some/Any/No + Noun (In General Sense))[/b]\n"
        "Odamlar yoki narsalarni [b]umumiy ma'noda[/b] nazarda tutganimizda, [b]'most', 'some', 'any', 'no'[/b] so'zlarini ot oldidan [b]bevosita[/b] ishlatamiz. Bu holatda [b]'of'[/b] predlogi qo'yilmaydi.\n"
        "• [b]Most birds[/b] can fly. 🐦 – Ko'pgina qushlar ucha oladi.\n"
        "• [b]Some people[/b] prefer tea over coffee. ☕ – Ba'zi odamlar kofedan ko'ra choyni afzal ko'rishadi.\n"
        "• I don't have [b]any free time[/b] this week. ⏳ – Bu hafta bo'sh vaqtim yo'q.\n"
        "• She has [b]no fear[/b] of heights. ⛰️ – Uning balandlikdan hech qanday qo'rquvi yo'q.\n\n"
        "✅ [b]Most/Some/Any/None + Of + The/This/My/etc. (Aniq Guruhga Nisbatan) (Referring to a Specific Group)[/b]\n"
        "Agar biz odamlar yoki narsalarning [b]aniq bir guruhiga[/b] murojaat qilsak, [b]'of'[/b] predlogini ishlatishimiz kerak. 'Of' dan keyin odatda [b]'the', 'this', 'that', 'these', 'those'[/b] yoki [b]egalik olmoshlari ('my', 'your', 'his', 'her' va hokazo)[/b] keladi.\n"
        "• [b]Most of the students[/b] in this class are from Tashkent. 🎓 – Bu sinfdagi talabalarning aksariyati Toshkentdan.\n"
        "• I've read [b]some of these books[/b] before. 📚 – Bu kitoblarning ba'zilarini ilgari o'qiganman.\n"
        "• Do you know [b]any of my friends[/b]? 🤔 – Mening do'stlarimdan birortasini bilasizmi?\n"
        "• [b]None of the money[/b] was found. 💸 – Pulning hech qaysi qismi topilmadi.\n"
        "• [b]Most of my colleagues[/b] are working remotely. 🧑‍💻 – Hamkasblarimning aksariyati masofadan ishlamoqda.\n\n"
        "✅ [b]'All of the...' va 'All my...' (Faqat 'All' Bilan) ('All of the...' and 'All my...' (Only with 'All'))[/b]\n"
        "[b]'All'[/b] so'zi bilan [b]'the'[/b] yoki [b]egalik olmoshi[/b] kelganda, [b]'of'[/b] predlogi odatda ishlatilmaydi, lekin bu xato emas.\n"
        "• [b]All the guests[/b] enjoyed the party. 🎉 (ko'pincha shunday ishlatiladi, 'all of the guests' ham to'g'ri) – Barcha mehmonlar bazmdan zavqlanishdi.\n"
        "• [b]All my clothes[/b] are clean. 👕 (ko'pincha shunday ishlatiladi, 'all of my clothes' ham to'g'ri) – Barcha kiyimlarim toza.\n"
        "• She spent [b]all her life[/b] in this city. 🏙️ – U butun umrini shu shaharda o'tkazdi.\n\n"
        "✅ [b]'All/Most/Some/Any/None + of + Olmosh' (Shaxs Olmoshlari Bilan) (With Personal Pronouns)[/b]\n"
        "[b]'Of'[/b] predlogi [b]har doim[/b] shaxs olmoshlari ([b]it, them, us, you[/b]) oldidan ishlatiladi.\n"
        "• You can have [b]some of it[/b], if you want. 🍰 – Agar xohlasangiz, uning bir qismini olishingiz mumkin.\n"
        "• [b]Most of them[/b] arrived late. 🚶‍♀️🚶‍♂️ – Ularning aksariyati kechikib kelishdi.\n"
        "• Did [b]any of you[/b] finish the assignment? 📝 – Sizlardan birortangiz topshiriqni tugatdingizmi?\n"
        "• [b]None of us[/b] knew the answer. 🤷‍♀️🤷‍♂️ – Hech birimiz javobni bilmas edik.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=NAaBhYgOvzQ&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=81]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 68,
    "title":
        "Farqlar: Each va Every, Among va Between (Distinctions: Each and Every, Among and Between)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 68[/b] darsimizda ingliz tilida ko'pincha adashtiriladigan ikkita juftlik – [b]'each' va 'every'[/b] hamda [b]'among' va 'between'[/b] so'zlari o'rtasidagi farqlarni ko'rib chiqamiz. Bu so'zlarni to'g'ri qo'llay olish nutqingizni tabiiy bo'lishiga yordam beradi. Keling, ularni batafsil o'rganamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Each va Every (Each vs Every)[/b]\n"
        "Bu ikkala so'z ham 'har bir' ma'nosini bersa-da, ma'noda nozik farqlarga ega va turli vaziyatlarda qo'llaniladi:\n\n"
        "• [b]Each (Har bir/Har bittasi)[/b]\n"
        "  [b]'Each'[/b] guruhdagi individual (alohida) shaxslar yoki narsalarni nazarda tutadi, ko'pincha soni kam bo'lgan yoki aniq belgilangan guruhlar uchun ishlatiladi. Har bir a'zoning alohidaligini ta'kidlaydi.\n"
        "  • [b]Each student[/b] received a personalized feedback. 🧑‍🎓 – Har bir talaba shaxsiylashtirilgan fikr-mulohaza oldi.\n"
        "  • There are two books on the table, and [b]each[/b] has a different cover. 📚 – Stolda ikkita kitob bor, har birining muqovasi har xil.\n"
        "  • [b]Each of the children[/b] got a toy. 👧👦 – Bolalarning har biri o'yinchoq oldi.\n"
        "  • The teacher spoke to [b]each parent[/b] individually. 👨‍🏫 – O'qituvchi har bir ota-ona bilan alohida gaplashdi.\n\n"
        "• [b]Every (Har bir/Hammasi)[/b]\n"
        "  [b]'Every'[/b] guruhdagi barcha a'zolarni bir butun sifatida nazarda tutadi, ko'pincha soni ko'p yoki noaniq bo'lgan guruhlar uchun ishlatiladi. Umumiy ma'noni ifodalaydi.\n"
        "  • [b]Every seat[/b] in the cinema was taken. 🍿 – Kinoteatrda har bir o'rindiq band edi.\n"
        "  • I visit my grandmother [b]every weekend[/b]. 👵 – Men har dam olish kunlari buvimni ziyorat qilaman.\n"
        "  • [b]Every country[/b] has its own unique culture. 🌎 – Har bir mamlakatning o'ziga xos madaniyati bor.\n"
        "  • [b]Every person[/b] deserves respect. 🙏 – Har bir inson hurmatga loyiqdir.\n\n"
        "[center][b]Asosiy Farqlar (Key Differences):[/b][/center]\n"
        "  * [b]Individuallik vs Butunlik:[/b] [b]'Each'[/b] alohida-alohida a'zolarni, [b]'every'[/b] esa guruhning butunligini ta'kidlaydi.\n"
        "  * [b]'Of' Bilan Qo'llanish:[/b] [b]'Each'[/b] dan keyin [b]'of'[/b] kelishi mumkin ([b]each of the students[/b]), lekin [b]'every'[/b] dan keyin kelmaydi (NOT: [b]every of the students[/b]).\n"
        "  * [b]Fe'l:[/b] Ikkalasi ham doimo [b]birlikdagi fe'l[/b] bilan ishlatiladi.\n\n"
        "✅ [b]Among va Between (Among vs Between)[/b]\n"
        "Bu ikkala predlog ham 'orasida' ma'nosini bersa-da, ular orasida muhim farqlar bor:\n\n"
        "• [b]Between (O'rtasida)[/b]\n"
        "  [b]'Between'[/b] odatda [b]ikkita alohida narsa, odam yoki nuqta[/b] o'rtasidagi munosabatni ifodalash uchun ishlatiladi. Garchi ikkitadan ko'p narsa bo'lsa ham, agar ular aniq ajratilgan va individual ravishda ko'rib chiqilsa, [b]'between'[/b] qo'llanilishi mumkin.\n"
        "  • The shop is located [b]between[/b] the bank and the post office. 🏦✉️ – Do'kon bank va pochta bo'limi o'rtasida joylashgan.\n"
        "  • Share the cake [b]between[/b] you two. 🎂 – Tortni ikkalangiz bo'lishib oling.\n"
        "  • The negotiations [b]between[/b] the three countries were successful. 🤝 (Bu yerda uchta mamlakat aniq, alohida tomonlar sifatida ko'rib chiqiladi) – Uch mamlakat o'rtasidagi muzokaralar muvaffaqiyatli bo'ldi.\n\n"
        "• [b]Among (O'rtasida/Ichida)[/b]\n"
        "  [b]'Among'[/b] biror narsa yoki odamlar [b]kattaroq, noaniq guruh yoki massaning bir qismi[/b] ekanligini ifodalash uchun ishlatiladi. Bu yerda individual elementlar aniq ajratilmagan, balki bir butunning ichida joylashgan bo'ladi.\n"
        "  • She felt nervous [b]among[/b] strangers. 😟 – U begona odamlar orasida o'zini noqulay his qildi.\n"
        "  • The house is hidden [b]among[/b] the trees. 🌳🏡 – Uy daraxtlar orasida yashiringan.\n"
        "  • They distributed the candy [b]among[/b] the children. 🍬 – Ular konfetlarni bolalar orasida tarqatishdi.\n\n"
        "[center][b]Asosiy Farqlar (Key Differences):[/b][/center]\n"
        "  * [b]Son/Aniqlov:[/b] [b]'Between'[/b] aniq ikki narsa (yoki alohida sanaladigan bir necha narsa) uchun, [b]'among'[/b] esa uch yoki undan ortiq, aniq sanalmaydigan yoki umumiy guruh uchun.\n"
        "  * [b]Munosabat:[/b] [b]'Between'[/b] individual aloqalar yoki ajratilgan nuqtalar o'rtasidagi munosabatni, [b]'among'[/b] esa biror narsaning umumiy massaning ichida joylashishini anglatadi.\n\n"
  },
