        "Bugun biz ingliz tilidagi [b]noto‘g‘ri ko‘plik shakllari[/b]ni o‘rganamiz. Ba’zi so‘zlar oddiy [b]-s[/b] yoki [b]-es[/b] qo‘shimchasi bilan emas, balki butunlay boshqacha shaklga kiradi. Keling, ular bilan tanishamiz! 🚀\n\n"
