  {
    "lesson": 70,
    "title":
        "Tanlov va Inkor: Both, Either, Neither (Choice and Negation: Both, Either, Neither)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 70[/b] darsimizda ingliz tilida ikkita narsa yoki shaxs haqida gapirganda ishlatiladigan muhim so'zlar – [b]'both', 'either' va 'neither'[/b]ni o'rganamiz. Bu so'zlar birikish, ikkitadan birini tanlash yoki ikkalasini ham inkor etish kabi ma'nolarni ifodalaydi. Keling, ularning qoidalarini va qo'llanilishini batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Both (Ikkisi Ham) (Both (Both of Two))[/b]\n"
        "[b]'Both'[/b] 'ikkalasi' yoki 'ikkalasi ham' degan ma'noni anglatadi. U ikkita narsa yoki shaxs haqidagi [b]darak gaplarda[/b] ishlatiladi.\n"
        "• [b]Both[/b] my parents are doctors. 👨‍⚕️👩‍⚕️ – Ikkala ota-onam ham shifokor.\n"
        "• We liked [b]both[/b] the movies we watched. 🎬 – Biz ko'rgan ikkala filmni ham yoqtirdik.\n"
        "• They [b]both[/b] agreed to the proposal. 👍 – Ularning ikkalasi ham taklifga rozi bo'lishdi.\n"
        "• You can take [b]both[/b] apples if you want. 🍎🍏 – Agar xohlasangiz, ikkala olmani ham olishingiz mumkin.\n\n"
        "✅ [b]Either (Ikkisidan Biri) (Either (One of Two))[/b]\n"
        "[b]'Either'[/b] 'ikkitadan biri' degan ma'noni anglatadi. U ikkita tanlovdan birini bildiradi.\n"
        "• You can choose [b]either[/b] the red or the blue car. 🚗🔵🔴 – Qizil yoki ko'k mashinani tanlashingiz mumkin.\n"
        "• Is [b]either[/b] of your sisters at home? 🏠 – Opa-singillaringizdan birortasi uyda bormi?\n"
        "• I don't mind [b]either[/b] tea or coffee. ☕ – Menga choy ham, kofe ham farqi yo'q.\n"
        "• You can sit on [b]either[/b] side of the table. 🛋️ – Stolning istalgan tomoniga o'tirishingiz mumkin.\n\n"
        "✅ [b]Neither (Ikkisidan Hech Qaysisi) (Neither (Not One, Not the Other))[/b]\n"
        "[b]'Neither'[/b] 'ikkisi ham emas' degan ma'noni anglatadi. U inkor ma'nosiga ega bo'lsa ham, [b]darak fe'l[/b] bilan ishlatiladi. [b]'Neither'[/b] = [b]'not either'[/b] ga teng.\n"
        "• [b]Neither[/b] of the answers was correct. ❌ – Javoblarning ikkalasi ham to'g'ri emas edi.\n"
        "• I like [b]neither[/b] football nor basketball. ⚽🏀 – Men futbolni ham, basketbolni ham yoqtirmayman.\n"
        "• [b]Neither[/b] candidate seemed suitable for the job. 👔 – Ikkala nomzod ham ishga mos kelmadi.\n"
        "• She gave me [b]neither[/b] money nor advice. 💰 – U menga na pul, na maslahat berdi.\n\n"
        "✅ [b]Both/Either/Neither + Ot (With Nouns)[/b]\n"
        "• [b]Both[/b] + [b]ko'plikdagi ot[/b]: [b]Both countries[/b] (ikkala mamlakat) 🌍\n"
        "  • [b]Both teams[/b] played well. ⚽ – Ikkala jamoa ham yaxshi o'ynadi.\n"
        "• [b]Either[/b] + [b]birlikdagi ot[/b]: [b]Either way[/b] (ikkala yo'lning birortasi) 🛣️\n"
        "  • You can take [b]either bus[/b]. 🚌 – Ikkala avtobusdan birortasiga chiqishingiz mumkin.\n"
        "• [b]Neither[/b] + [b]birlikdagi ot[/b]: [b]Neither option[/b] (ikkala variantning hech biri) 🚫\n"
        "  • [b]Neither parent[/b] attended the meeting. 👨‍👩‍👧‍👦 – Ota-onalarning hech biri uchrashuvga kelmadi.\n\n"
        "✅ [b]Both/Either/Neither + Of + The/These/My/etc. (Determinerlar Bilan) (With 'Of' and Determiners)[/b]\n"
        "Agar [b]'the', 'this/that/these/those'[/b] yoki [b]egalik olmoshlari ('my', 'your', 'his', 'her' va hokazo)[/b] dan oldin kelsa, [b]'of'[/b] predlogi ishlatiladi.\n"
        "• [b]Both of my brothers[/b] live abroad. 👨‍👦‍👦 – Ikkala akam ham chet elda yashaydi.\n"
        "• I haven't read [b]either of these books[/b]. 📖 – Bu kitoblarning ikkalasidan ham birortasini o'qimadim.\n"
        "• [b]Neither of the suggestions[/b] was practical. 💡 – Takliflarning ikkalasi ham amaliy emas edi.\n\n"
        "✅ [b]Both/Either/Neither + Of + Olmosh (Shaxs Olmoshlari Bilan) (With Personal Pronouns)[/b]\n"
        "Obyekt olmoshlari ([b]us, them, you[/b]) oldidan [b]'of'[/b] predlogi [b]har doim[/b] ishlatiladi.\n"
        "• [b]Both of us[/b] are tired after the long journey. 😴 – Ikkalamiz ham uzoq safardan keyin charchaganmiz.\n"
        "• I invited them, but [b]neither of them[/b] came. ✉️ – Men ularni taklif qildim, lekin ikkalasi ham kelmadi.\n"
        "• I asked [b]both of you[/b] to complete the task. ✅ – Ikkalangizdan ham vazifani bajarishingizni so'radim.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=0uU9VH2p67Y&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=82]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 71,
    "title":
        "Miqdor Olmoshlari: A Lot / Much / Many (Quantifiers: A Lot / Much / Many)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 71[/b] darsimizda ingliz tilida miqdorlarni ifodalashda ishlatiladigan [b]'a lot (of)', 'much' va 'many'[/b] so'zlarini o'rganamiz. Bu so'zlarning asosiy farqi ularning [b]sanaladigan (countable)[/b] yoki [b]sanalmaydigan (uncountable)[/b] otlar bilan ishlatilishidadir. Keling, avval sanaladigan va sanalmaydigan otlarni eslab olsak, keyin esa ushbu miqdor olmoshlarini batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Sanaladigan (Countable) va Sanalmaydigan (Uncountable) Otlar[/b]\n"
        "• [b]Sanaladigan otlar[/b] (Countable nouns): Sanash mumkin bo'lgan narsalar (masalan: [b]books[/b] (kitoblar), [b]apples[/b] (olmalar), [b]chairs[/b] (stullar)). Ular birlik va ko'plik shakllariga ega bo'ladi.\n"
        "• [b]Sanalmaydigan otlar[/b] (Uncountable nouns): Sanab bo'lmaydigan narsalar (masalan: [b]water[/b] (suv), [b]money[/b] (pul), [b]information[/b] (ma'lumot), [b]rice[/b] (guruch)). Ular faqat birlik shaklida bo'ladi va ularni [b]a/an[/b] artikli bilan ishlatib bo'lmaydi.\n\n"
        "✅ [b]Much (Ko'p - Sanalmaydigan Otlar Uchun) (Much (A lot - For Uncountable Nouns))[/b]\n"
        "[b]'Much'[/b] so'zi faqat [b]sanalmaydigan otlar[/b] bilan [b]ko'p[/b] ma'nosida ishlatiladi. U ko'pincha [b]inkor gaplar[/b] va [b]savollarda[/b] qo'llaniladi.\n"
        "• I [b]don't have much time[/b] to prepare for the meeting. ⏳ – Yig'ilishga tayyorlanish uchun ko'p vaqtim yo'q.\n"
        "• Did you spend [b]much money[/b] on your holiday? 💸 – Dam olishingizga ko'p pul sarfladingizmi?\n"
        "• There [b]isn't much traffic[/b] on the roads today. 🚗 – Bugun yo'llarda tirbandlik uncha ko'p emas.\n"
        "• We [b]don't have much milk[/b] left in the fridge. 🥛 – Muzlatgichda uncha ko'p sut qolmagan.\n\n"
        "✅ [b]Many (Ko'p - Sanaladigan Otlar Uchun) (Many (A lot - For Countable Nouns))[/b]\n"
        "[b]'Many'[/b] so'zi faqat [b]ko'plikdagi sanaladigan otlar[/b] bilan [b]ko'p[/b] ma'nosida ishlatiladi. U ham ko'pincha [b]inkor gaplar[/b] va [b]savollarda[/b] qo'llaniladi.\n"
        "• She [b]doesn't have many friends[/b] in the new city. 👯‍♀️ – Uning yangi shaharda ko'p do'stlari yo'q.\n"
        "• Were there [b]many people[/b] at the concert? 🎤 – Konsertda ko'p odam bormidi?\n"
        "• I haven't read [b]many books[/b] this year. 📖 – Bu yil ko'p kitob o'qimadim.\n"
        "• Did you take [b]many photos[/b] during your trip? 📸 – Sayohat davomida ko'p suratga tushdingizmi?\n\n"
        "✅ [b]A Lot (of) (Ko'p - Barcha Turdagi Otlar Uchun) (A Lot (of) (A lot - For All Types of Nouns))[/b]\n"
        "[b]'A lot of'[/b] ([b]yoki 'lots of'[/b]) ikkala turdagi otlar – [b]sanaladigan ko'plik otlar[/b] va [b]sanalmaydigan otlar[/b] bilan ham ishlatilishi mumkin. U [b]barcha turdagi gaplarda[/b] (tasdiq, inkor, savol) keng qo'llaniladi va [b]'much'[/b] va [b]'many'[/b] ga nisbatan umumiyroq va norasmiyroq hisoblanadi.\n"
        "• We bought [b]a lot of food[/b] for the party. 🍕 (Sanalmaydigan) – Biz bazm uchun ko'p ovqat sotib oldik.\n"
        "• There are [b]a lot of trees[/b] in this park. 🌳 (Sanaladigan) – Bu bog'da ko'p daraxtlar bor.\n"
        "• She has [b]a lot of experience[/b] in marketing. 📈 (Sanalmaydigan) – Uning marketingda ko'p tajribasi bor.\n"
        "• I received [b]a lot of emails[/b] today. 📧 (Sanaladigan) – Bugun ko'p elektron xatlar oldim.\n"
        "• He talks [b]a lot[/b]. 🗣️ (faqat [b]'a lot'[/b] tarzida, fe'lni ta'kidlash uchun) – U ko'p gapiradi.\n"
        "• We study [b]a lot[/b] for our exams. 📖 – Biz imtihonlar uchun ko'p o'qiymiz.\n\n"
        "✅ [b]Qo'llanilish Qoidalari (Usage Rules)[/b]\n"
        "• Odatda, [b]'much' va 'many'[/b] [b]inkor gaplar[/b] va [b]savollarda[/b] ishlatiladi. [b]'A lot (of)'[/b] esa [b]tasdiq gaplarda[/b] afzal ko'riladi, lekin boshqa gap turlarida ham ishlatilishi mumkin.\n"
        "  • Do you watch [b]much TV[/b]? (TO'G'RI) ✅\n"
        "  • I don't watch [b]much TV[/b]. (TO'G'RI) ✅\n"
        "  • I watch [b]a lot of TV[/b]. (TO'G'RI) ✅ (NOT: I watch much TV. ❌)\n"
        "• [b]'Much'[/b] yoki [b]'many'[/b] sizga yoqmasa, [b]'a lot of'[/b] ni ishlatish har doim to'g'ri bo'ladi va tabiiyroq eshitiladi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
