  {
    "lesson": 72,
    "title":
        "Miqdor Olmoshlari: (A) Little va (A) Few (Quantifiers: (A) Little and (A) Few)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 72[/b] darsimizda ingliz tilida oz miqdorni ifodalash uchun ishlatiladigan [b]'(a) little' va '(a) few'[/b] so'zlarini o'rganamiz. Bu so'zlarning tanlovi otning sanaladigan yoki sanalmaydigan turiga bog'liq bo'lib, 'a' artiklining bor yoki yo'qligi esa ma'noga nozik farqlar qo'shadi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b](A) Little (Ozgina - Sanalmaydigan Otlar Uchun) ((A) Little (Small amount - For Uncountable Nouns))[/b]\n"
        "• [b]A little[/b]: 'ozgina, ammo yetarli miqdorda' degan ma'noni beradi va odatda [b]ijobiy ma'no[/b]ga ega bo'ladi. Faqat [b]sanalmaydigan otlar[/b] bilan ishlatiladi.\n"
        "  • I have [b]a little money[/b] left for coffee. ☕ – Menda kofe uchun ozgina pul qoldi (va bu yetarli).\n"
        "  • Could I have [b]a little water[/b], please? 💧 – Menga ozgina suv bera olasizmi, iltimos?\n"
        "  • She needs [b]a little help[/b] with her project. 🤝 – Uning loyihasiga ozgina yordam kerak.\n"
        "• [b]Little[/b] ( 'a'siz): 'deyarli yo'q' yoki 'juda oz' degan ma'noni beradi va odatda [b]salbiy ma'no[/b]ga ega bo'ladi. Faqat [b]sanalmaydigan otlar[/b] bilan ishlatiladi.\n"
        "  • We have [b]little time[/b] before the train leaves. ⏰ – Poezd jo'nashidan oldin vaqtimiz juda oz qoldi (deyarli yo'q).\n"
        "  • There was [b]little food[/b] in the fridge, so I went shopping. 🛒 – Muzlatgichda juda oz ovqat bor edi, shuning uchun men xaridga bordim.\n\n"
        "✅ [b](A) Few (Oz - Sanaladigan Otlar Uchun) ((A) Few (Small number - For Countable Nouns))[/b]\n"
        "• [b]A few[/b]: 'oz, ammo yetarli son' degan ma'noni beradi va odatda [b]ijobiy ma'no[/b]ga ega bo'ladi. Faqat [b]ko'plikdagi sanaladigan otlar[/b] bilan ishlatiladi.\n"
        "  • I have [b]a few friends[/b] in this city. 👯‍♀️ – Bu shaharda ozgina do'stlarim bor (va bu yaxshi).\n"
        "  • She wrote [b]a few letters[/b] to her relatives. ✉️ – U qarindoshlariga bir nechta xat yozdi.\n"
        "  • There are [b]a few chairs[/b] left if you need one. 🪑 – Agar kerak bo'lsa, bir nechta stul qoldi.\n"
        "• [b]Few[/b] ( 'a'siz): 'deyarli yo'q' yoki 'juda oz' degan ma'noni beradi va odatda [b]salbiy ma'no[/b]ga ega bo'ladi. Faqat [b]ko'plikdagi sanaladigan otlar[/b] bilan ishlatiladi.\n"
        "  • [b]Few people[/b] understood the complex lecture. 🤯 – Murakkab ma'ruzani juda oz odam tushundi (deyarli hech kim).\n"
        "  • There are [b]few opportunities[/b] for growth in this company. 📉 – Bu kompaniyada o'sish uchun imkoniyatlar juda oz.\n\n"
        "✅ [b]Ma'no Farqlari (Difference in Meaning)[/b]\n"
        "• [b]A little money[/b] (Ozgina pul, ammo bor) vs [b]Little money[/b] (Juda oz pul, deyarli yo'q). 💰\n"
        "  • I have [b]a little money[/b], so I can buy a snack. (Pulim bor, shuning uchun yegulik sotib olaman) ✅\n"
        "  • I have [b]little money[/b], so I can't afford a snack. (Pulim juda oz, shuning uchun yegulik ololmayman) ❌\n"
        "• [b]A few friends[/b] (Ozgina do'stlar, ammo bor) vs [b]Few friends[/b] (Juda oz do'stlar, deyarli yo'q). 🫂\n"
        "  • She has [b]a few friends[/b] and is quite happy. (Do'stlari oz bo'lsa ham, baxtli) 😊\n"
        "  • He has [b]few friends[/b] and often feels lonely. (Do'stlari juda oz, ko'pincha yolg'iz his qiladi) 😔\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=iFTrQy_3-O8&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=84]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 73,
    "title": "Sifatlarning Qiyosiy Darajalari (Comparative Forms)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 73[/b] darsimizda ingliz tilidagi [b]sifatlarning qiyosiy darajalari (comparative forms)[/b]ni o'rganamiz. Bu shakllar ikkita narsa yoki shaxsni solishtirish, ya'ni birining boshqasidan qandaydir jihatdan ustun yoki kamligini ifodalash uchun ishlatiladi. Keling, ularni qanday yasash va qo'llashni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Qisqa Sifatlar (-er Qo'shimchasi) (Short Adjectives (-er Suffix))[/b]\n"
        "Bir bo'g'inli sifatlarning aksariyati va '-y' bilan tugaydigan ikki bo'g'inli sifatlarga [b]'-er'[/b] qo'shimchasi qo'shiladi. Bu shakllar biror narsaning o'zgargan holatini yoki umumiy biror sifatini ifodalash uchun ishlatiladi.\n"
        "• Oxirgi harf undosh bo'lib, undan oldin unli bo'lsa, undosh harf ikki marta yoziladi: [b]hot -> hotter[/b] (issiq -> issiqroq).\n"
        "• '-y' bilan tugagan sifatlarda '-y' 'i' ga o'zgaradi: [b]easy -> easier[/b] (oson -> osonroq).\n\n"
        "  • I feel [b]better[/b] today. ☀️ – Bugun o'zimni yaxshiroq his qilyapman.\n"
        "  • The new laptop is [b]faster[/b]. 💻 – Yangi noutbuk tezroq.\n"
        "  • The coffee needs to be a bit [b]hotter[/b]. ☕ – Kofe biroz issiqroq bo'lishi kerak.\n"
        "  • It's getting [b]darker[/b] outside. 🌃 – Tashqarisi qorong'iroq bo'lmoqda.\n\n"
        "✅ [b]Uzun Sifatlar (More So'zi) (Long Adjectives (Using 'More'))[/b]\n"
        "Ikki yoki undan ortiq bo'g'inli sifatlar uchun sifatdan oldin [b]'more'[/b] so'zi ishlatiladi. Bu ham biror narsaning sifat darajasini yoki o'zgarishini ko'rsatadi.\n"
        "  • The new design is [b]more creative[/b]. 🎨 – Yangi dizayn ijodiyroq.\n"
        "  • The problem became [b]more serious[/b]. ⚠️ – Muammo jiddiyroq bo'ldi.\n"
        "  • The lecture was [b]more interesting[/b]. 📚 – Ma'ruza qiziqarliroq edi.\n"
        "  • We need to be [b]more careful[/b]. 🧐 – Biz ehtiyotkorroq bo'lishimiz kerak.\n\n"
        "✅ [b]Tartibsiz Qiyosiy Darajalar (Irregular Comparative Forms)[/b]\n"
        "Tartibsiz shaklga ega bo'lgan sifatlar ham 'than'siz ishlatilishi mumkin, ayniqsa vaziyatdan ma'no aniq bo'lsa.\n"
        "• [b]good[/b] (yaxshi) -> [b]better[/b] (yaxshiroq)\n"
        "  • Her English is getting [b]better[/b]. 🗣️ – Uning ingliz tili yaxshilanmoqda.\n"
        "• [b]bad[/b] (yomon) -> [b]worse[/b] (yomonroq)\n"
        "  • My headache got [b]worse[/b]. 🤕 – Bosh og'rig'im yomonlashdi.\n"
        "• [b]far[/b] (uzoq) -> [b]further / farther[/b] (uzoqroq)\n"
        "  • Let's walk a little [b]further[/b]. 🚶‍♀️ – Keling, biroz uzoqroq yuramiz.\n\n"
        "✅ [b]Qo'shimcha misollar[/b]\n"
        "    • I tried both shirts. This one is [b]nicer[/b]. 👕 (Avvalgi ko'ylakdan yaxshiroq ekanligi aniq) – Ikkala ko'ylakni ham kiyib ko'rdim. Bu yaxshiroq.\n"
        "    • The baby is growing [b]taller[/b] every day. 👶 – Chaqaloq har kuni bo'y cho'zmoqda.\n"
        "    • My city is becoming [b]more crowded[/b]. 🏙️ – Shahrim gavjumroq bo'lmoqda.\n"
        "    • This coffee is [b]stronger[/b]. ☕ – Bu kofe kuchliroq.\n"
        "    • We need a [b]bigger[/b] car. 🚗 – Bizga kattaroq mashina kerak.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=pcjGsmbDc3o]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 74,
    "title":
        "Qiyosiy Darajalar: 'Than' bilan Qo'llanilishi (Comparative Forms: Using 'Than')",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 74[/b] darsimizda sifatlarning qiyosiy darajalarini o'rganishda davom etamiz, ammo bu safar ularni [b]'than' predlogi[/b] bilan qanday qilib aniq solishtirish uchun ishlatishni ko'rib chiqamiz. 'Than' so'zi ikkita narsa yoki shaxsni solishtirib, ulardan birining boshqasidan qandaydir jihatdan ustun yoki kamligini ko'rsatishga yordam beradi. Keling, buni batafsil o'rganamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Than' Bilan Qisqa Sifatlar (Short Adjectives with 'Than')[/b]\n"
        "Bir bo'g'inli sifatlarga [b]'-er'[/b] qo'shimchasini qo'shib, keyin [b]'than'[/b] predlogi bilan solishtiramiz.\n"
        "  • My new apartment is [b]bigger than[/b] my old one. 🏡 – Yangi kvartiram eskisidan kattaroq.\n"
        "  • She is [b]younger than[/b] her brother. 👩‍👧‍👦 – U akasidan yoshroq.\n"
        "  • This path is [b]shorter than[/b] the main road. 🛤️ – Bu yo'l asosiy yo'ldan qisqaroq.\n"
        "  • The second option is [b]cheaper than[/b] the first. 💰 – Ikkinchi variant birinchisidan arzonroq.\n\n"
        "✅ [b]'Than' Bilan Uzun Sifatlar (Long Adjectives with 'Than')[/b]\n"
        "Ikki yoki undan ortiq bo'g'inli sifatlar uchun sifatdan oldin [b]'more'[/b] so'zini ishlatamiz, keyin [b]'than'[/b] predlogi bilan solishtiramiz.\n"
        "  • Learning English is [b]more challenging than[/b] I initially thought. 🗣️ – Ingliz tilini o'rganish dastlab o'ylaganimdan ko'ra qiyinroq.\n"
        "  • The new restaurant is [b]more popular than[/b] the old one. 🍽️ – Yangi restoran eskisidan mashhurroq.\n"
        "  • This task is [b]more important than[/b] that one. ✅ – Bu vazifa unisidan muhimroq.\n"
        "  • Their presentation was [b]more impressive than[/b] ours. 📊 – Ularning taqdimoti biznikidan ta'sirliroq edi.\n\n"
        "✅ [b]'Than' Bilan Tartibsiz Sifatlar (Irregular Adjectives with 'Than')[/b]\n"
        "Ba'zi tartibsiz sifatlar ham 'than' bilan ishlatiladi.\n"
        "• [b]good[/b] (yaxshi) -> [b]better than[/b] (yaxshiroq)\n"
        "  • My new laptop performs [b]better than[/b] my old desktop. 💻\n"
        "• [b]bad[/b] (yomon) -> [b]worse than[/b] (yomonroq)\n"
        "  • The traffic was [b]worse than[/b] I expected. 🚦\n"
        "• [b]far[/b] (uzoq) -> [b]further / farther than[/b] (uzoqroq)\n"
        "  • Their house is [b]further than[/b] ours from the city center. 🗺️\n\n"
        "✅ [b]'Than'dan Keyin Olmoshlar (Pronouns After 'Than')[/b]\n"
        "'Than'dan keyin odatda [b]obyekt olmoshlari[/b] ([b]me, him, her, us, them[/b]) ishlatiladi. Rasmiyroq holatlarda [b]subyekt olmoshi + yordamchi fe'l[/b] ([b]than I am, than she is[/b]) ishlatilishi mumkin.\n"
        "  • He runs [b]faster than me[/b]. 🏃 (yoki [b]faster than I do[/b].) – U mendan tezroq yuguradi.\n"
        "  • My brother is [b]taller than him[/b]. 🧑‍🤝‍🧑 (yoki [b]taller than he is[/b].) – Akam undan balandroq.\n"
        "  • She is [b]more confident than us[/b]. 💪 (yoki [b]more confident than we are[/b].) – U bizdan ko'ra o'ziga ishonganroq.\n\n"
        "✅ [b]Miqdorlarni Solishtirish: More/Less Than (Comparing Quantities: More/Less Than)[/b]\n"
        "[b]'More than'[/b] 'dan ko'proq', [b]'less than'[/b] esa 'dan kamroq' degan ma'nolarda sonlar yoki miqdorlarni solishtirish uchun ishlatiladi.\n"
        "  • I spent [b]more than[/b] \$50 on this book. 💸 – Bu kitobga 50 dollardan ko'proq sarfladim.\n"
        "  • The project needs [b]more than[/b] three months to complete. ⏳ – Loyihani yakunlash uchun uch oydan ko'proq vaqt kerak.\n"
        "  • There were [b]less than[/b] ten people at the meeting. 👥 – Yig'ilishda o'ntadan kam odam bor edi.\n"
        "  • The new car uses [b]less fuel than[/b] the old model. ⛽ – Yangi mashina eski modeldan kamroq yoqilg'i sarflaydi.\n"
        "  • He has [b]less experience than[/b] his colleagues. 🧑‍💻 – Uning hamkasblariga qaraganda tajribasi kamroq.\n\n"
        "✅ [b]Farq Darajasini Ko'rsatish: A Bit / Much + Comparative (Indicating Degree of Difference: A Bit / Much + Comparative)[/b]\n"
        "Solishtiruvchi sifatdan oldin [b]'a bit'[/b] (bir oz) yoki [b]'much'[/b] (ancha) so'zlarini qo'llash orqali farqning darajasini ko'rsatish mumkin.\n"
        "  • My new phone is [b]a bit bigger[/b] than my old one. 📱 – Yangi telefonim eskisidan bir oz kattaroq.\n"
        "  • The second option is [b]much cheaper[/b] than the first. 💲 – Ikkinchi variant birinchisidan ancha arzonroq.\n"
        "  • The test was [b]much more difficult[/b] than I expected. 🤯 – Test men kutganimdan ancha qiyinroq edi.\n"
        "  • She feels [b]a bit better[/b] after taking the medicine. 💊 – U dori ichganidan keyin o'zini bir oz yaxshiroq his qilyapti.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=p091YqwUMWY]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 75,
    "title": "Solishtirish: Not As ... As (Comparison: Not As ... As)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 75[/b] darsimizda ingliz tilidagi [b]'not as ... as'[/b] (kabi emas) solishtiruv konstruktsiyasini o'rganamiz. Bu tuzilma ikki narsaning bir xil xususiyatga yoki miqdorga ega emasligini, ya'ni birining boshqasidan kamroq ekanligini ifodalash uchun ishlatiladi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Not As + Sifat + As (Not As + Adjective + As)[/b]\n"
        "Bu konstruktsiya ikkita narsa yoki shaxs biror sifat bo'yicha teng emasligini ifodalash uchun ishlatiladi. Bu odatda birinchi narsa ikkinchisidan kamroq ekanligini bildiradi.\n"
        "  • My new phone is [b]not as fast as[/b] yours. 📱 – Mening yangi telefonim siznikichalik tez emas.\n"
        "  • This book is [b]not as interesting as[/b] the movie. 📖 – Bu kitob filmchalik qiziqarli emas.\n"
        "  • Their house is [b]not as big as[/b] ours. 🏠 – Ularning uyi biznikichalik katta emas.\n"
        "  • The exam was [b]not as difficult as[/b] I expected. 🤯 – Imtihon men kutganchalik qiyin emas edi.\n\n"
        "✅ [b]Not As Much As / Not As Many As (Not As Much As / Not As Many As)[/b]\n"
        "• [b]Not as much as[/b]: Sanalmaydigan otlar bilan 'unchalik ko'p emas' ma'nosida ishlatiladi.\n"
        "  • I don't have [b]as much time as[/b] you. ⏳ – Siznikichalik ko'p vaqtim yo'q.\n"
        "  • She doesn't drink [b]as much coffee as[/b] I do. ☕ – U menchalik ko'p kofe ichmaydi.\n"
        "• [b]Not as many as[/b]: Ko'plikdagi sanaladigan otlar bilan 'unchalik ko'p emas' ma'nosida ishlatiladi.\n"
        "  • There are [b]not as many students as[/b] last year. 🧑‍🎓 – O'tgan yilgichalik ko'p talaba yo'q.\n"
        "  • We didn't receive [b]as many applications as[/b] we hoped. 📧 – Biz umid qilganimizchalik ko'p arizalar ololmadik.\n\n"
        "✅ [b]'As'dan Keyin Olmoshlar (Pronouns After 'As')[/b]\n"
        "'As'dan keyin odatda [b]obyekt olmoshlari[/b] ([b]me, him, her, us, them[/b]) ishlatiladi. Rasmiyroq holatlarda [b]subyekt olmoshi + yordamchi fe'l[/b] ([b]as I am, as she is[/b]) ishlatilishi mumkin.\n"
        "  • She is [b]not as old as him[/b]. 👩‍🦳 (yoki [b]as old as he is[/b].) – U unchalik qari emas.\n"
        "  • He doesn't work [b]as hard as me[/b]. 🧑‍💻 (yoki [b]as hard as I do[/b].) – U menchalik qattiq ishlamaydi.\n"
        "  • They are [b]not as tall as us[/b]. 🧑‍🤝‍🧑 (yoki [b]as tall as we are[/b].) – Ular bizchalik baland emas.\n\n"
        "'Not as ... as' konstruktsiyasi [b]'than'[/b] bilan tuzilgan qiyosiy darajalarga muqobil sifatida ishlatilishi mumkin. Bu bir narsaning boshqasidan kamroq ekanligini ifodalashning boshqacha yo'li hisoblanadi.\n"
        "  • The small car is [b]not as powerful as[/b] the SUV. 🚗💨 – Kichik mashina SUV kabi kuchli emas. (Bu shuni anglatadiki, SUV kuchliroq.)\n"
        "  • My old computer was [b]not as reliable as[/b] my new one. 💻 – Eski kompyuterim yangisi kabi ishonchli emas edi. (Bu shuni anglatadiki, yangisi ishonchliroq.)\n\n"
        "✅ [b]The Same As ... (Bir Xil As ... (The Same As ...))[/b]\n"
        "Agar ikki narsa biror jihatdan to'liq bir xil bo'lsa, [b]'the same as'[/b] konstruktsiyasi ishlatiladi.\n"
        "  • Her new dress is [b]the same colour as[/b] mine. 👗 – Uning yangi ko'ylagi meniki bilan bir xil rangda.\n"
        "  • My birthday is [b]the same day as[/b] my friend's. 🎂 – Mening tug'ilgan kunim do'stimniki bilan bir kunda.\n"
        "  • The weather today is [b]the same as[/b] yesterday. ☁️ – Bugungi ob-havo kechagi bilan bir xil.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=aHd3KbWPzoM]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 76,
    "title":
        "Sifatlarning Orttirma Darajalari (Superlative Forms of Adjectives)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 76[/b] darsimizda ingliz tilidagi [b]sifatlarning orttirma darajalari (superlative forms)[/b]ni o'rganamiz. Bu shakllar bir narsani yoki shaxsni ma'lum bir guruhdagi barcha narsa yoki shaxslarning eng yuqorisi, eng zo'ri yoki eng yomoni ekanligini ifodalash uchun ishlatiladi (qisqasi eng deb gapirishni o'rganamiz). Keling, ularni qanday yasash va qo'llashni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Qisqa Sifatlar (The -est Qo'shimchasi) (Short Adjectives (The -est Suffix))[/b]\n"
        "Bir bo'g'inli sifatlarning aksariyati va '-y' bilan tugaydigan ikki bo'g'inli sifatlarga [b]'the -est'[/b] qo'shimchasi qo'shiladi. Imlo qoidalariga rioya qilish muhim (masalan, 'y' 'i' ga o'zgaradi, undosh harf ikki marta yoziladi):\n"
        "  • This is [b]the fastest[/b] car in the world. 🏎️ – Bu dunyodagi eng tez mashina.\n"
        "  • She is [b]the youngest[/b] person in our team. 👧 – U bizning jamoamizdagi eng yosh odam.\n"
        "  • That was [b]the coldest[/b] winter I remember. 🥶 – Bu men eslay oladigan eng sovuq qish edi.\n"
        "  • Getting a visa was [b]the easiest[/b] part of the trip. ✅ – Viza olish sayohatning eng oson qismi edi.\n\n"
        "✅ [b]Uzun Sifatlar (The Most So'zi) (Long Adjectives (Using 'The Most'))[/b]\n"
        "Ikki yoki undan ortiq bo'g'inli sifatlar (faqat '-y' bilan tugamaydiganlar) uchun sifatdan oldin [b]'the most'[/b] so'zi ishlatiladi.\n"
        "  • Everest is [b]the most famous[/b] mountain in the world. ⛰️ – Everest dunyodagi eng mashhur tog'.\n"
        "  • This is [b]the most beautiful[/b] painting in the museum. 🖼️ – Bu muzeydagi eng chiroyli rasm.\n"
        "  • He gave [b]the most interesting[/b] lecture I've ever heard. 🗣️ – U men eshitgan eng qiziqarli ma'ruzani o'qidi.\n"
        "  • Safety is [b]the most important[/b] thing. ⚠️ – Xavfsizlik eng muhim narsa.\n\n"
        "✅ [b]The Least (Eng Kam) (The Least (Least))[/b]\n"
        "[b]'The least'[/b] 'the most' (eng ko'p/eng) so'zining qarama-qarshisi bo'lib, uzun sifatlar bilan biror sifatning eng minimal darajasini ifodalash uchun ishlatiladi.\n"
        "  • This is [b]the least expensive[/b] option. 💲 – Bu eng arzon variant.\n"
        "  • It was [b]the least interesting[/b] part of the whole presentation. 😴 – Bu butun taqdimotning eng zerikarli qismi edi.\n\n"
        "✅ [b]Tartibsiz Orttirma Darajalar (Irregular Superlative Forms)[/b]\n"
        "Ba'zi umumiy sifatlar orttirma darajada tartibsiz shaklga ega bo'lib, ularni yodlash kerak.\n"
        "• [b]good[/b] (yaxshi) -> [b]the best[/b] (eng yaxshi)\n"
        "  • She is [b]the best[/b] student in the class. 🏆\n"
        "• [b]bad[/b] (yomon) -> [b]the worst[/b] (eng yomon)\n"
        "  • That was [b]the worst[/b] movie I've ever seen. 🎬\n"
        "• [b]far[/b] (uzoq) -> [b]the furthest / the farthest[/b] (eng uzoq)\n"
        "  • Pluto is [b]the furthest[/b] planet from the Sun (among the traditional ones). 🪐\n\n"
        "✅ [b]'In' va 'Of' bilan Ishlatilishi (Usage with 'In' and 'Of')[/b]\n"
        "Orttirma darajalar ko'pincha quyidagilar bilan ishlatiladi:\n"
        "• [b]'In'[/b] joylar yoki guruhlar uchun:\n"
        "  • She's [b]the tallest[/b] person [b]in[/b] our family. 👨‍👩‍👧‍👦\n"
        "  • This is [b]the highest[/b] building [b]in[/b] the city. 🏙️\n"
        "• [b]'Of'[/b] vaqt davrlari yoki umuman guruhlar uchun:\n"
        "  • Monday is [b]the busiest[/b] day [b]of[/b] the week. 📅\n"
        "  • This is [b]the most interesting[/b] topic [b]of[/b] all. ✨\n\n"
        "✅ [b]Ot bilan va Otsiz Qo'llanilishi (Usage With and Without a Noun)[/b]\n"
        "Orttirma darajalar ot bilan yoki otsiz ishlatilishi mumkin, agar ot gapning ma'nosidan aniq bo'lsa.\n"
        "• Ot bilan:\n"
        "  • Who is [b]the tallest student[/b] in your class? 🧑‍🎓 – Sinifingizdagi eng baland bo'yli talaba kim?\n"
        "  • It was [b]the most memorable trip[/b] of my life. ✈️ – Bu hayotimdagi eng esda qolarli sayohat edi.\n"
        "• Otsiz:\n"
        "  • This is [b]the best[/b]. (Ya'ni, [b]the best option / thing[/b]). 👍 – Bu eng yaxshisi.\n"
        "  • I took [b]the earliest[/b]. (Ya'ni, [b]the earliest bus / train[/b]). ⏰ – Eng ertasini oldim.\n\n"
