  {
    "lesson": 77,
    "title": "Enough (Yetarli)",
    "content":
        "👋 Salom, aziz o‘rganuvchilar!\n\nBugun biz 'enough' so‘zining ishlatilishini o‘rganamiz. Bu so‘z biror narsa yetarli yoki yetarli emasligini ifodalash uchun kerak bo‘ladi.\n\n✅ [b]Enough + noun:[/b]\n• Do we have [b]enough water[/b] for the trip? 🚰 – Sayohat uchun yetarli suv bormi?\n• I didn’t bring [b]enough money[/b] to buy the book. 📖 – Kitob olish uchun yetarli pul olmadim.\n\n✅ [b]Adjective + enough:[/b]\n• This room isn’t [b]big enough[/b] for ten people. 🏠 – Bu xona o‘nta odam uchun yetarlicha katta emas.\n• Is this coat [b]warm enough[/b] for winter? 🧥 – Bu palto qish uchun yetarlicha issiqmi?\n\n✅ [b]Enough without a noun:[/b]\n• I’ve eaten [b]enough[/b], thank you. 🍽️ – Men yetarlicha yedim, rahmat.\n• We walked [b]enough[/b] for today. 🚶 – Bugun yetarlicha yurdik.\n\n✅ [b]Enough for (someone/something):[/b]\n• There isn’t [b]enough tea[/b] for everybody. 🍵 – Hamma uchun yetarli choy yo‘q.\n• This chair isn’t [b]strong enough for him[/b]. 🪑 – Bu stul u uchun yetarlicha mustahkam emas.\n\n✅ [b]Enough to (do something):[/b]\n• I don’t have [b]enough money to buy a car[/b]. 🚗 – Men mashina olish uchun yetarli pulga ega emasman.\n• Is your phone loud [b]enough to hear outside?[/b] 📱 – Tashqarida eshitish uchun telefoning yetarlicha balandmi?\n\n[center][b]🎥 Video darslik[/b][/center]\n"
            "[link=https://www.youtube.com/watch?v=e0PSWp9uyY8&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=91]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 78,
    "title": "Too (Juda, Haddi ortiq)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 📚\n\n"
        "Bugun biz [b]too[/b] so‘zini qanday ishlatilishini o‘rganamiz. Bu so‘zning ikkita asosiy ma'nosi bor ya'ni 'juda', 'haddan tashqari' va 'ham' ma'nolari.\n\n"
        "✅ [b]too + sifat (adjective)[/b]\n"
        "Bu 'juda' degani, lekin ko‘pincha salbiy ma’noda — ya’ni keraklikdan ortiq.\n"
        "• This bag is [b]too heavy[/b]. – Bu sumka juda og‘ir.\n"
        "• It’s [b]too cold[/b] to swim. – Bu cho'milish uchun juda sovuq.\n"
        "• He is [b]too young[/b] to drive. – U mashina haydash uchun juda yosh.\n\n"
        "✅ [b]too + ravish (adverb)[/b]\n"
        "• You’re walking [b]too fast[/b]. – Sen juda tez yuryapsan.\n"
        "• She speaks [b]too quietly[/b]. – U juda sekin gapiradi.\n\n"
        "✅ [b]too much / too many[/b]\n"
        "[b]Too much[/b] – sanalmaydigan narsalar uchun.\n"
        "[b]Too many[/b] – sanaladigan narsalar uchun.\n\n"
        "• There’s [b]too much noise[/b] outside. – Tashqarida juda ko‘p shovqin.\n"
        "• You drink [b]too much tea[/b]. – Sen juda ko‘p choy ichasan.\n"
        "• There are [b]too many people[/b] in this room. – Bu xonada juda ko‘p odam bor.\n"
        "• I have [b]too many books[/b] to carry. – Menda ko‘tarish kerak bo'lgan juda ko'p kitob bor.\n\n"
        "✅ [b]too ... for (somebody)[/b]\n"
        "• This hat is [b]too small for me[/b]. – Bu shlyapa men uchun juda kichkina.\n"
        "• The soup is [b]too hot for children[/b]. – Sho‘rva bolalar uchun juda issiq.\n\n"
        "✅ [b]too ... to (do something)[/b]\n"
        "• It’s [b]too dark to read[/b]. – O‘qish uchun juda qorong‘i.\n"
        "• I’m [b]too tired to walk[/b]. – Yurish uchun juda charchadim.\n"
        "• This bag is [b]too heavy to carry[/b]. – Bu sumka ko‘tarish uchun juda og‘ir.\n\n"
        "✅ [b]too va not enough farqi[/b]\n"
        "• The dress is [b]too big[/b]. – Ko‘ylak juda katta.\n"
        "• The dress is [b]not big enough[/b]. – Ko‘ylak yetarlicha katta emas.\n"
        "• There’s [b]too much sugar[/b] in the tea. – Choyda juda ko‘p shakar bor.\n"
        "• There isn’t [b]enough sugar[/b] in the tea. – Choyda yetarlicha shakar yo‘q.\n\n"
        "✅ [b]'also' va 'too' ma’nosi[/b]\n"
        "[b]Also[/b] va [b]too[/b] ikkisi ham 'ham' degani:\n"
        "• I like football. I like basketball [b]too[/b]. – Men futbolni yaxshi ko‘raman. Basketbolni ham.\n"
        "• She is coming [b]too[/b]. – U ham keladi.\n"
        "• He is a teacher. She is a teacher [b]also[/b]. – U o‘qituvchi. U ham.\n"
        "[b]Also[/b] odatda gapning o‘rtasida yoki boshida keladi, [b]too[/b] esa odatda oxirida ishlatiladi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=Z0Zqo-LfmSg&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=92]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 79,
    "title": "Word Order 1 (Fe’l va Ob’yekt Tartibi)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 📚\n\n"
        "Bugun gap ichida so‘zlarning to‘g‘ri tartibini o‘rganamiz.\n"
        "Ayniqsa, fe’l (verb) va ob’yekt (object) qayerda kelishi kerakligini.\n\n"
        "✅ [b]Verb + Object[/b]\n"
        "Fe’l va ob’yekt birga bo‘ladi:\n"
        "• My friend found a wallet. – Do‘stim hamyon topdi.\n"
        "• We opened the window. – Biz derazani ochdik.\n"
        "• Nora drinks coffee every morning. – Nora har tong qahva ichadi.\n"
        "• I play the piano on weekends. – Men dam olish kunlari pianino chalaman.\n\n"
        "❌ Noto‘g‘ri:\n"
        "We opened quickly the window. (❌)\n"
        "✔️ To‘g‘ri:\n"
        "We quickly opened the window. (✔️)\n\n"
        "✅ [b]Joy va Vaqt Tartibi[/b]\n"
        "Odatda [b]qayerda[/b] va [b]qachon[/b] ketma-ketligi:\n"
        "• They ate lunch at school yesterday. – Ular kecha maktabda tushlik qilishdi.\n"
        "• I met my uncle at the station this morning. – Men bugun ertalab vokzalda amakimni uchratdim.\n"
        "• Tom and Alice stayed at a hotel last summer. – Tom va Alisa o‘tgan yoz mehmonxonada qolishdi.\n"
        "• We had breakfast in the garden at 8 o’clock. – Biz soat sakkizda bog‘da nonushta qildik.\n\n"
        "✅ [b]Qanday, Qachon, Qayerda Tartibi[/b]\n"
        "Gapda tartib: [b]How? → Where? → When?[/b]\n"
        "• Sarah danced beautifully at the party on Saturday. – Sara shanba kuni bazmda chiroyli raqs tushdi.\n"
        "• I finished my homework quickly at home last night. – Men kecha uyda tezda uy vazifamni tugatdim.\n"
        "• We listened carefully in class this morning. – Biz bugun ertalab darsda diqqat bilan tingladik.\n"
        "• They walked slowly along the beach yesterday. – Ular kecha plyaj bo‘ylab sekin yurishdi.\n\n"
        "✅ [b]Misollar:[/b]\n"
        "• Can you close the door, please? – Iltimos, eshikni yopib qo‘y.\n"
        "• I enjoy classical music. – Men klassik musiqani yoqtiraman.\n"
        "• They read a lot of books in summer. – Ular yozda juda ko‘p kitob o‘qishadi.\n"
        "• He bought a new car last month. – U o‘tgan oy yangi mashina sotib oldi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=hSlJmfz4hUw&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=93]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 80,
    "title": "Always / Usually / Often (Word Order 2)",
    "content": "👋 Salom, aziz o‘rganuvchilar! 📚\n\n"
        "Bugun biz [b]always, usually, often, never[/b] kabi so‘zlarning gapdagi o‘rnini o‘rganamiz.\n\n"
        "✅ [b]Fe’l oldidan kelishi:[/b]\n"
        "Bu so‘zlar odatda fe’ldan oldin yoziladi:\n"
        "• I usually drink tea in the evening. – Men odatda kechqurun choy ichaman.\n"
        "• We often visit our grandparents. – Biz tez-tez buvamiz va buvimiznikiga boramiz.\n"
        "• She rarely watches TV. – U juda kam televizor ko‘radi.\n"
        "• They never eat fast food. – Ular hech qachon fastfud yemaydi.\n\n"
        "✅ [b]To be fe’li bilan:[/b]\n"
        "[b]am/is/are/was/were[/b] fe’li bilan bu so‘zlar fe’ldan keyin yoziladi:\n"
        "• He is always happy. – U doimo baxtli.\n"
        "• We are often tired after work. – Ishdan keyin biz tez-tez charchaymiz.\n"
        "• I am never late. – Men hech qachon kechikmayman.\n"
        "• She was usually at home in the afternoon. – U odatda peshindan keyin uyda bo‘lardi.\n\n"
        "✅ [b]can/could/should/have/will va fe'l o'rtasida:[/b]\n"
        "Agar gapda ikki fe’l bo‘lsa, bu so‘zlar ularning orasida keladi:\n"
        "• I can always help you. – Men doimo senga yordam bera olaman.\n"
        "• You should never lie. – Hech qachon yolg‘on gapirma.\n"
        "• They have already left. – Ular allaqachon ketishdi.\n"
        "• She will still be at the office. – U hali ham ofisda bo‘ladi.\n\n"
        "✅ [b]Misollar:[/b]\n"
        "• My parents usually cook dinner together. – Ota-onam odatda birga kechki ovqat tayyorlashadi.\n"
        "• Do you often play chess? – Sen tez-tez shaxmat o‘ynaysanmi?\n"
        "• He just called me. – U hozirgina menga qo‘ng‘iroq qildi.\n"
        "• They both study at the same university. – Ularning ikkalasi ham bir universitetda o‘qiydi.\n"
        "• I’ve already done my homework. – Men uy vazifamni allaqachon bajardim.\n"
        "• Are you still at work? – Sen hali ham ishdamisan?\n"
        "• We seldom go out on weekdays. – Biz ish kunlari kamdan-kam tashqariga chiqamiz.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=QaNWQkzDZyo&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=94]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 81,
    "title": "Still / Yet / Already",
    "content": "👋 Salom, aziz o‘rganuvchilar! 📚\n\n"
        "Bugun biz ingliz tilidagi [b]still[/b], [b]yet[/b] va [b]already[/b] so‘zlarining qanday ishlatilishini o‘rganamiz.\n\n"
        "✅ [b]Still[/b] – bu narsaning hali davom etayotganini bildiradi:\n"
        "• I’m still at the office. – Men hali ham ofisdam.\n"
        "• Are you still watching that movie? – Sen hali ham o‘sha filmni ko‘rayapsanmi?\n"
        "• She’s still waiting for your message. – U hali ham senga xabar kutyapti.\n"
        "• My cat is still sleeping. – Mening mushugim hali ham uxlayapti.\n\n"
        "✅ [b]Yet[/b] – hozirgacha bo‘lmagan yoki hozirgacha noma’lum bo‘lgan narsani bildiradi.\n"
        "[b]Yet[/b] odatda salbiy gap va savollarda gap oxirida ishlatiladi:\n"
        "• Have you cleaned your room yet? – Xonangni tozaladingmi?\n"
        "• The guests haven’t arrived yet. – Mehmonlar hali kelishgani yo‘q.\n"
        "• Is dinner ready yet? – Kechki ovqat tayyormi?\n"
        "• I don’t know the answer yet. – Men javobni hali bilmayman.\n\n"
        "✅ [b]Already[/b] – kutilganidan oldin sodir bo‘lgan narsani bildiradi:\n"
        "• I’ve already had lunch. – Men allaqachon tushlik qildim.\n"
        "• She’s already bought a new phone. – U allaqachon yangi telefon olgan.\n"
        "• They’ve already left the building. – Ular allaqachon binodan chiqib ketishgan.\n"
        "• We’ve already seen that show. – Biz allaqachon o‘sha shouni ko‘rganmiz.\n\n"
        "✅ [b]Misollarni solishtiring:[/b]\n"
        "• He hasn’t finished his work yet. = He’s still working. – U ishini hali tugatgani yo‘q. = U hali ishlayapti.\n"
        "• I haven’t called Ali yet. = I still need to call him. – Men hali Aliga qo‘ng‘iroq qilganim yo‘q. = Men hali unga qo‘ng‘iroq qilishim kerak.\n"
        "• I’ve already packed my bag. – Men allaqachon sumkamni yig‘dim.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=7aG3-5hKaDY&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=95]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 82,
    "title": "Give / Lend / Pass / Send / Show (2 ta tuzilma)",
    "content": "👋 Assalomu alaykum! 📚\n\n"
        "Bugun biz quyidagi fe’llardan keyin gapda ikki xil tuzilmani qanday ishlatishni o‘rganamiz:\n"
        "[b]give, lend, pass, send, show, buy, get[/b]\n\n"
        "✅ [b]1. Something to somebody[/b]\n"
        "• Can you send the message to my brother? – Xabarni akamga yubora olasanmi?\n"
        "• I showed the photo to my grandmother. – Men bu suratni buvimga ko‘rsatdim.\n"
        "• Please give this pen to your teacher. – Iltimos, bu ruchkani o‘qituvchingga ber.\n"
        "• I lent my bicycle to my cousin yesterday. – Kecha velosipedimni amakivachchamga berdim.\n"
        "• Will you pass the ball to me? – Menga to‘pni uzatasanmi?\n\n"
        "✅ [b]2. Somebody something[/b]\n"
        "• Give me that pencil, please. – Menga o‘sha ruchkani ber.\n"
        "• She sent Ali a letter last week. – U o‘tgan hafta Aliga xat yubordi.\n"
        "• I lent my friend some books. – Men do‘stimga bir nechta kitob berdim.\n"
        "• Can you show me your new shoes? – Menga yangi tuflingni ko‘rsatsang bo‘ladimi?\n"
        "• I’ll get you some water. – Men senga suv olib kelaman.\n\n"
        "✅ [b]Buy/Get somebody something[/b]\n"
        "• I bought my sister a nice bag. – Men singlimga chiroyli sumka oldim.\n"
        "• Can you get me a sandwich, please? – Menga bitta sendvich olib berasanmi?\n\n"
        "✅ [b]Farqlar:[/b]\n"
        "• I gave the pen to Sara. – Men ruchkani Saraga berdim.\n"
        "• I gave Sara the pen. (but not ‘I gave to Sara the pen.’)\n"
        "• This is my notebook. Give it to me. – Bu mening daftarim, uni menga ber.\n"
        "• Give me that notebook. – Menga o‘sha daftarni ber.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=yJ4YCzrfSVE&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=96]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 83,
    "title": "Vaqt Predloglari: On, At, In (Prepositions of Time: On, At, In)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 83[/b] darsimizda ingliz tilida vaqtni ifodalashda ishlatiladigan asosiy predloglar – [b]'on', 'at', 'in'[/b] ni o'rganamiz. Bu predloglarning har biri vaqtning turli ko'rinishlari bilan ishlatiladi va ularni to'g'ri qo'llash muhim. Keling, har birini alohida ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]At (Aniqlik uchun) (At (For Specificity))[/b]\n"
        "[b]'At'[/b] predlogi aniq vaqtni, kunning aniq bir qismini yoki bayramlarni (agar 'day' so'zi ishlatilmagan bo'lsa) ifodalash uchun ishlatiladi.\n"
        "  • The meeting starts [b]at 9 AM[/b]. ⏰ – Yig'ilish soat ertalab 9 da boshlanadi.\n"
        "  • I usually go to bed [b]at midnight[/b]. 🌙 – Men odatda yarim tunda uxlayman.\n"
        "  • We'll celebrate New Year [b]at Christmas[/b]. 🎄 – Rojdestvoda Yangi yilni nishonlaymiz.\n"
        "  • The shops close [b]at 5 o'clock[/b]. 🛍️ – Do'konlar soat 5 da yopiladi.\n\n"
        "✅ [b]On (Kunlar va Sanalar uchun) (On (For Days and Dates))[/b]\n"
        "[b]'On'[/b] predlogi haftaning aniq kunlarini, aniq sanalarni va 'day' so'zi bilan kelgan bayramlarni ifodalash uchun ishlatiladi.\n"
        "  • I have an appointment [b]on Monday[/b]. 🗓️ – Dushanba kuni uchrashuvim bor.\n"
        "  • Her birthday is [b]on January 1st[/b]. 🎂 – Uning tug'ilgan kuni 1-yanvar.\n"
        "  • We're visiting them [b]on Christmas Day[/b]. 🎅 – Biz ularni Rojdestvo kunida boramiz.\n"
        "  • Let's meet [b]on Saturday evening[/b]. 🌆 – Shanba oqshom uchrashaylik.\n\n"
        "✅ [b]In (Davrlar uchun) (In (For Periods of Time))[/b]\n"
        "[b]'In'[/b] predlogi uzoqroq vaqt davrlarini – oylar, fasllar, yillar, asrlar va kunning asosiy qismlarini ifodalash uchun ishlatiladi.\n"
        "  • The flowers bloom [b]in spring[/b]. 🌸 – Gullar bahorda ochiladi.\n"
        "  • My family moved here [b]in 2010[/b]. 🏘️ – Oilam bu yerga 2010 yilda ko'chib kelgan.\n"
        "  • I like to read books [b]in the evening[/b]. 📖 – Men kechqurun kitob o'qishni yaxshi ko'raman.\n"
        "  • The industrial revolution happened [b]in the 18th century[/b]. 🏭 – Sanoat inqilobi 18-asrda sodir bo'lgan.\n\n"
        "✅ [b]Istisnolar va Umumiy Qoidalar (Exceptions and General Rules)[/b]\n"
        "• Ba'zi umumiy iboralar:\n"
        "  • [b]at night[/b] (tunda) – I often work [b]at night[/b]. 🦉 – Men ko'pincha tunda ishlayman.\n"
        "  • [b]at the weekend[/b] (hafta oxirida) – We usually relax [b]at the weekend[/b]. 🥳 – Biz odatda hafta oxirida dam olamiz.\n"
        "• Umumiy qoida shundaki, [b]'at'[/b] eng aniq vaqtlar uchun, [b]'on'[/b] kunlar va sanalar uchun, [b]'in'[/b] esa uzunroq davrlar uchun ishlatiladi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=UR-5WGOz6BQ&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=97]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 84,
    "title": "from, until, since, for bilan vaqt ifodalash",
    "content": "📖 Assalomu alaykum!\n\n"
        "Bugun vaqt davomiyligini ifodalovchi [b]from, until, since, for[/b] so‘zlarini o‘rganamiz.\n\n"
        "✅ [b]from ... to[/b] – nimadandir nimagacha:\n"
        "• We studied from 9 o’clock to 12. – Biz soat 9 dan 12 gacha o‘qidik.\n"
        "• The shops are open from Monday to Saturday. – Do‘konlar dushanbadan shanbagacha ochiq.\n\n"
        "✅ [b]until[/b] – biror vaqtgacha:\n"
        "• I’ll stay here until 6 o’clock. – Men bu yerda soat 6 gacha bo‘laman.\n"
        "• They waited until evening. – Ular kechgacha kutishdi.\n"
        "• Wait here until I return. – Men qaytgunimcha shu yerda turing.\n"
        "• You can also use [b]till[/b] (bu [i]until[/i] ning oddiy shakli):\n"
        "• She works till midnight. – U yarim tungacha ishlaydi.\n\n"
        "✅ [b]since[/b] – biror vaqt boshlanganidan hozirgacha:\n"
        "• I’ve known her since 2020. – Men uni 2020-yildan beri bilaman.\n"
        "• It has been raining since morning. – Tongdan beri yomg‘ir yog‘moqda.\n"
        "• We have lived here since last year. – Biz bu yerda o‘tgan yildan beri yashaymiz.\n\n"
        "✅ [b]for[/b] – qancha vaqt davomida:\n"
        "• They stayed for three days. – Ular uch kun qolishdi.\n"
        "• I’ve been busy for a week. – Men bir haftadan beri bandman.\n"
        "• She worked for five hours. – U besh davomida soat ishladi.\n\n"
        "✅ [b]Eslatma:[/b]\n"
        "[b]since[/b] faqat [i]present perfect[/i] (have/has + 3-forma) bilan ishlatiladi:\n"
        "• I have lived here since 2018. – Men bu yerda 2018-yildan beri yashayman.\n\n"
        "Ammo [b]for[/b] har qanday zamonda ishlatilishi mumkin:\n"
        "• He lived in London for ten years. – U Londonda o‘n yil yashagan.\n"
        "• They have worked here for a long time. – Ular bu yerda anchadan beri ishlaydi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=lwpu0ZAVQBg&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=98]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 85,
    "title": "before, after, during, while bilan vaqt ifodalash",
    "content": "📖 Assalomu alaykum!\n\n"
        "Bugun vaqtni ketma-ketlikda yoki bir vaqtda sodir bo‘lishini bildiradigan [b]before, after, during, while[/b] so‘zlarini o‘rganamiz.\n\n"
        "✅ [b]before[/b] – biror ish sodir bo‘lishidan oldin:\n"
        "• I always wash my hands before dinner. – Har doim kechki ovqatdan oldin qo‘limni yuvaman.\n"
        "• Close the window before you leave. – Ketishdan oldin derazani yoping.\n\n"
        "✅ [b]after[/b] – biror ish sodir bo‘lgandan keyin:\n"
        "• They went home after the game. – Ular o‘yindan keyin uyga ketishdi.\n"
        "• After breakfast, I read a book. – Nonushtadan keyin kitob o‘qidim.\n\n"
        "✅ [b]during[/b] – biror voqea, vaqt yoki davr paytida yoki davomida:\n"
        "• It rained during the tennis match. – Tennis o'yini paytida yomg'ir yog'di.\n"
        "• Don’t use your phone during the lesson. – Dars paytida telefon ishlatma.\n\n"
        "✅ [b]while[/b] – bir vaqtda ikkita ish sodir bo‘lishi:\n"
        "• I listened to music while doing my homework. – Uy vazifamni qilayotganimda musiqa tingladim.\n"
        "• She was sleeping while I was watching TV. – Men televizor ko‘rayotganimda u uxlayotgan edi.\n\n"
        "✅ [b]during[/b] va [b]while[/b] farqi:\n"
        "[b]during[/b] + [i]noun[/i]:\n"
        "• I slept during the film. – Film davomida uxlab qoldim.\n\n"
        "[b]while[/b] + [i]verb[/i]:\n"
        "• I slept while he was watching TV. – U televizor ko'rayotganida men uxladim.\n\n"
        "✅ [b]before[/b] va [b]after[/b] + [i]-ing[/i] shakli:\n"
        "• I had tea before going to school. – Maktabga ketishdan oldin choy ichdim.\n"
        "• After finishing the book, I went to bed. – Kitobni tugatgandan keyin uxlashga yotdim.\n\n"
        "📌 Eslatma:\n"
        "‘before to go’ yoki ‘after to do’ deyish mumkin emas!\n"
        "To‘g‘risi: ‘before going’, ‘after doing’ ya'ni before/after + fe'l + ing.\n\n"
        "During va while bir xil ma'noga ega ammo during + ot va while + fe'l."
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=DPof4n7-yjo&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=99]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 86,
    "title": "in / at / on (joylar bilan)",
    "content": "📖 Assalomu alaykum!\n\n"
        "Bugun [b]in[/b], [b]at[/b], va [b]on[/b] predloglari joylar bilan qanday ishlatilishini o‘rganamiz.\n\n"
        "✅ [b]in[/b] – ichida:\n"
        "• She is in the kitchen. – U oshxonada.\n"
        "• There’s a pen in my bag. – Sumkamda ruchka bor.\n"
        "• They live in London. – Ular Londonda yashaydi.\n"
        "• I swam in the river. – Men daryoda suzdim.\n\n"
        "✅ [b]at[/b] – aniq joyda:\n"
        "• There’s a man at the door. – Eshik oldida bir odam bor.\n"
        "• The car is waiting at the traffic lights. – Mashina svetaforda kutyapti.\n"
        "• I’m at work. – Men ishxonadaman.\n"
        "• Write your name at the top of the page. – Sahifaning tepasiga ismingni yoz.\n\n"
        "✅ [b]on[/b] – ustida / yuzasida:\n"
        "• The book is on the table. – Kitob stol ustida.\n"
        "• There’s a picture on the wall. – Devor ustida rasm bor.\n"
        "• Don’t sit on the grass. – Chim ustida o‘tirma.\n"
        "• She’s on a bicycle. – U velosipedda.\n\n"
        "✅ [b]in[/b], [b]at[/b], [b]on[/b] farqi:\n"
        "• [b]in[/b] – ichida (joy ichida): in a room, in a bag\n"
        "• [b]at[/b] – aniq joy nuqtasi: at the door, at the bus stop\n"
        "• [b]on[/b] – ustida, sirtida: on the table, on the wall\n\n"
        "📌 Eslatma:\n"
        "on a horse / on a bike / on a motorbike – otda, velosipedda, mototsiklda\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=-kRhiZzOuiA&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=100]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 87,
    "title": "in / at / on (joylar bilan 2)",
    "content": "📖 Salom do‘stlar!\n\n"
        "Bugun [b]in[/b], [b]at[/b], va [b]on[/b] predloglarini yana ko‘proq joylar bilan qanday ishlatilishini ko‘rib chiqamiz.\n\n"
        "✅ [b]in[/b] – ichida:\n"
        "• She is in bed. – U yotog‘ida.\n"
        "• My uncle is in hospital. – Amakim kasalxonada.\n"
        "• They live in a small street. – Ular kichik ko‘chada yashaydi.\n"
        "• I see birds in the sky. – Men osmonda qushlarni ko‘ryapman.\n"
        "• I read it in a book. – Men buni kitobda o‘qidim.\n"
        "• There’s a big tree in the middle of the park. – Parkning o‘rtasida katta daraxt bor.\n\n"
        "✅ [b]at[/b] – aniq joy:\n"
        "• Are you at home? – Uydamisan?\n"
        "• She is at work now. – U hozir ishda.\n"
        "• Tom is at university. – Tom universitetda.\n"
        "• I saw her at the station. – Men uni vokzalda ko‘rdim.\n"
        "• We met at a concert. – Biz kontsertda uchrashdik.\n"
        "• She was at her friend’s. – U do‘stinikida edi.\n\n"
        "✅ [b]on[/b] – ustida / sirtida:\n"
        "• The office is on the second floor. – Ofis ikkinchi qavatda.\n"
        "• There’s a stamp on the envelope. – Konvert ustida muhri bor.\n"
        "• He came on the bus. – U avtobusda keldi.\n"
        "• I met her on the way home. – Men uni uyga ketayotib uchratdim.\n\n"
        "📌 Eslatma:\n"
        "• [b]in a car[/b], lekin [b]on a bus / on a train / on a plane[/b]\n"
        "• [b]at school / at work / at university[/b]\n"
        "• [b]on the first floor / on the way[/b]\n\n"
