  {
    "lesson": 88,
    "title": "Prepositions: under, behind, opposite, up, over, through, across",
    "content": "📖 Salom do‘stlar!\n\n"
        "Bugun biz joy va harakatni bildiruvchi predloglarni o‘rganamiz:\n\n"
        "✅ [b]under[/b] – ostida:\n"
        "• The cat is under the table. – Mushuk stol ostida.\n"
        "• She is standing under a tree. – U daraxt ostida turibdi.\n\n"
        "✅ [b]behind[/b] – orqasida:\n"
        "• The car is behind the house. – Mashina uy orqasida.\n"
        "• Who is behind you? – Orqangda kim bor?\n\n"
        "✅ [b]opposite[/b] – ro‘parasida, to'g'risida:\n"
        "• The bank is opposite the park. – Bank park ro‘parasida.\n"
        "• He is sitting opposite me. – U menga ro‘parada o‘tiribdi.\n\n"
        "✅ [b]up[/b] / [b]down[/b] – yuqoriga / pastga:\n"
        "• We walked up the hill. – Biz tepalikka ko‘tarildik.\n"
        "• She fell down the stairs. – U zinadan yiqilib tushdi.\n\n"
        "✅ [b]over[/b] – ustidan:\n"
        "• The plane flew over the city. – Samolyot shahar ustidan uchib o‘tdi.\n"
        "• I jumped over the ball. – Men to'p ustidan sakradim.\n\n"
        "✅ [b]through[/b] – ichidan, orqali:\n"
        "• The dog ran through the garden. – It bog‘ ichidan yugurdi.\n"
        "• We drove through the tunnel. – Biz tunnel orqali o‘tdik.\n\n"
        "✅ [b]across[/b] – kesib:\n"
        "• We walked across the road. – Biz yo‘lni kesib o‘tdik.\n"
        "• She swam across the river. – U daryoni suzib kesib o‘tdi.\n\n"
        "✅ [b]along[/b] – bo‘ylab:\n"
        "• We walked along the beach. – Biz sohil bo‘ylab sayr qildik.\n"
        "• He drove along the street. – U ko‘cha bo‘ylab haydadi.\n\n"
        "✅ [b]past[/b] – yonidan o‘tib:\n"
        "• They walked past me. – Ular yonimdan o‘tib ketishdi.\n"
        "• Go past the shop and turn left. – Do‘kondan o‘tib, chapga buriling.\n\n"
