  {
    "lesson": 89,
    "title": "Prepositions: on, at, by, with, about",
    "content": "📖 Salom, do‘stlar!\n\n"
        "Bugun ingliz tilida tez-tez ishlatiladigan ba’zi predloglarni ko‘rib chiqamiz. Ularning har biri turli vaziyatlarda ishlatiladi. Keling, birma-bir o‘rganamiz.\n\n"
        "✅ [b]on[/b] – biror yuzada yoki aloqa vositalarida:\n"
        "• She is on holiday. – U ta’tilda.\n"
        "• I heard it on the radio. – Men buni radioda eshitdim.\n"
        "• They spoke on the phone. – Ular telefonda gaplashishdi.\n"
        "• The picture is on the wall. – Surat devorda.\n\n"
        "✅ [b]at[/b] – joy yoki aniq vaqt:\n"
        "• We arrived at the station. – Biz vokzalga yetib keldik.\n"
        "• He got married at 25. – U 25 yoshida uylangan.\n"
        "• Water freezes at zero degrees. – Suv nol darajada muzlaydi.\n\n"
        "✅ [b]with[/b] / [b]without[/b] – bilan / -siz:\n"
        "• I drink tea without sugar. – Men choyni shakarsiz ichaman.\n"
        "• Never go without your keys. – Hech qachon kalitlarsiz ketma.\n"
        "• She painted the wall with a brush. – U devorni cho‘tkasi bilan bo‘yadi.\n"
        "• A boy with a hat. – Shapkali bola.\n\n"
        "✅ [b]about[/b] – haqida:\n"
        "• We talked about the trip. – Biz sayohat haqida gaplashdik.\n"
        "• He doesn’t know much about music. – U musiqa haqida ko‘p bilmaydi.\n"
        "• Did you watch the film about space? – Kosmos haqidagi filmni ko‘rdingmi?\n\n"
        "✅ [b]by[/b] – transport, usul yoki muallif:\n"
        "• They went by car. – Ular mashinada ketishdi.\n"
        "• I prefer travelling by train. – Men poezdda sayohat qilishni afzal ko‘raman.\n"
        "• A story by an Uzbek writer. – O‘zbek yozuvchisi yozgan hikoya.\n"
        "• The letter was written by my friend. – Xat mening do'stim tomonidan yozilgan.\n\n"
