  {
    "lesson": 90,
    "title": "Common words with Prepositions",
    "content": "📖 Salom, do‘stlar!\n\n"
        "Ingliz tilida ba’zi mashhur so‘zlar bilan birga har doim ba'zi bir predloglarni(yordamchi vositalarni) ishlatamiz.\n Bu vositalar o'zbek tilida ham mavjud. Masalan -dan, bilan, -ga, uchun, bo'ylab, -ning va hokazo. Quyida tez-tez ishlatiladigan ana shunday so'zlarni ko'rib chiqamiz!\n\n"
        "✅ [b]Afraid of ...[/b]\n"
        "• Are you afraid of speaking in public? – Sen odamlar oldida gapirishdan qo‘rqasanmi?\n\n"
        "✅ [b]Angry with (kimdirga) / Angry about (narsaga)[/b]\n"
        "• She was angry with her brother. – Uni akasidan jahli chiqdi.\n"
        "• Are you angry about losing your keys? – Kalitlaringni yo‘qotganingga jahling chiqyaptimi?\n\n"
        "✅ [b]Different from ...[/b]\n"
        "• This book is different from the others. – Bu kitob boshqalardan farq qiladi.\n\n"
        "✅ [b]Fed up with ...[/b]\n"
        "• I'm fed up with waiting. – Kutishdan charchadim.\n\n"
        "✅ [b]Full of ...[/b]\n"
        "• The box was full of books. – Quti kitoblarga to‘la edi.\n\n"
        "✅ [b]Good at ... / Bad at ...[/b]\n"
        "• Are you good at drawing? – Chizishda yaxshimisan?\n"
        "• I’m bad at remembering names. – Men ismlar yodlashda yomonman.\n\n"
        "✅ [b]Interested in ...[/b]\n"
        "• She’s interested in learning languages. – U tillarni o‘rganishga qiziqadi.\n\n"
        "✅ [b]Married to ...[/b]\n"
        "• He’s married to a singer. – U qo‘shiqchi bilan turmush qurgan.\n\n"
        "✅ [b]Nice/kind of (somebody) to ...[/b]\n"
        "• It was nice of you to visit us. – Bizni ko‘rgani kelganing yaxshi bo‘ldi.\n"
        "✅ [b]Sorry about (narsa) / Sorry for (biror ish)[/b]\n"
        "• Sorry about the mess. – Tartibsizlik uchun uzr.\n"
        "• Sorry for not calling you. – Telefon qilmaganim uchun uzr.\n\n"
        "✅ [b]Preposition + -ing form[/b]\n"
        "Predlogdan (at, with, about va boshqalar) keyin fe’l kelganda -ing bilan ishlatiladi:\n"
        "• I’m not good at telling jokes. – Men hazil aytishda yaxshi emasman.\n"
        "• He left without saying a word. – U bir og‘iz gapirmay ketdi.\n"
        "• They went home after finishing dinner. – Ular ovqatni tugatgach, uyga ketishdi.\n"
        "• She’s thinking of buying a car. – U mashina sotib olishni o‘ylayapti.\n\n"
