  {
    "lesson": 91,
    "title": "Phrasal Verbs (O‘zaro birikkan fe’llar)",
    "content": "👋 Salom, aziz o‘quvchilar! 📚\n\n"
        "Bugun biz ingliz tilidagi [b]Phrasal Verbs[/b] bilan tanishamiz.\n"
        "[b]Phrasal verbs[/b] — bu ikkita yoki undan ortiq so‘zdan iborat bo‘lib, ular birga kelib yangi ma’no beradi. \n"
        "O‘zbek tilida ham shunga o‘xshash so'zlar mavjud: [i]olib kelmoq[/i], [i]tashlab ketmoq[/i], [i]qaytib kelmoq[/i].\n\n"
        "Ingliz tilida esa fe’l + predlog(in, out, up, down, back, forward va boshqalar) yoki ravish qo‘shilib [i]phrasal verb[/i] hosil qiladi:\n"
        "[b]come in[/b] (kir), [b]get up[/b] (uyg‘on), [b]go away[/b] (ket)\n\n"
        "✅ [b]Phrasal verbs kategoriyalari[/b]\n"
        "Predlog qanday ma’no berishini bilsangiz, phrasal verbni oson tushunasiz:\n\n"
        "📌 [b]IN[/b] — ichkariga:\n"
        "• [b]come in[/b] — kirish\n"
        "• [b]get in[/b] — ichkariga kirish\n\n"
        "📌 [b]OUT[/b] — tashqariga:\n"
        "• [b]come out[/b] — chiqib kelish\n"
        "• [b]go out[/b] — tashqariga chiqish\n"
        "• [b]eat out[/b] — restoranda ovqatlanish\n\n"
        "📌 [b]UP[/b] — yuqoriga yoki boshlash:\n"
        "• [b]wake up[/b] — uyg‘onish\n"
        "• [b]stand up[/b] — o‘rnidan turish\n"
        "• [b]speak up[/b] — balandroq gapirish\n"
        "• [b]get up[/b] — o‘rnidan turish\n\n"
        "📌 [b]DOWN[/b] — pastga:\n"
        "• [b]sit down[/b] — o‘tirmoq\n"
        "• [b]calm down[/b] — tinchlanish\n"
        "• [b]put down[/b] — qo‘yish\n"
        "• [b]fall down[/b] — yiqilish\n\n"
        "📌 [b]AWAY[/b] — uzoqlashish:\n"
        "• [b]run away[/b] — qochib ketish\n"
        "• [b]go away[/b] — ketib qolish\n"
        "• [b]give away[/b] — berib yuborish, hadya qilish\n\n"
        "📌 [b]BACK[/b] — orqaga qaytish:\n"
        "• [b]go back[/b] — qaytib borish\n"
        "• [b]come back[/b] — qaytib kelish\n"
        "• [b]call back[/b] — qayta qo‘ng‘iroq qilish\n\n"
        "✅ [b]Misollar:[/b]\n"
        "• [b]Come in[/b], please! 📢 — Iltimos, kiring.\n"
        "• Let’s [b]eat out[/b] tonight. 🍽️ — Kechqurun restoranda ovqatlanamiz.\n"
        "• [b]Wake up[/b]! It’s 7 o’clock. ⏰ — Tur, soat yetti bo‘ldi.\n"
        "• [b]Sit down[/b], please. 🪑 — Iltimos, o‘tiring.\n"
        "• Don’t [b]run away[/b]! 🏃‍♂️ — Qochib ketma!\n"
        "• I’ll [b]call you back[/b] later. 📞 — Keyinroq yana qo‘ng‘iroq qilaman.\n\n"
        "✅ [b]Mashq:[/b]\n"
        "Quyidagilarni tarjima qiling:\n"
        "1. Iltimos, kir.\n"
        "2. U o‘rnidan turdi.\n"
        "3. Biz kechqurun restoranga boramiz.\n"
        "4. Bola qochib ketdi.\n"
        "5. Men yana qo‘ng‘iroq qilaman.\n\n"
  },
  {
    "lesson": 92,
    "title": "Phrasal Verbs 2 (Ko‘p ishlatiladigan iboraviy fe’llar 2-qism)",
    "content": "👋 Salom, aziz o‘quvchilar! 📚\n\n"
        "Bugun biz [b]Phrasal Verbs[/b] mavzusining 2-qismi bilan tanishamiz.\n"
        "Bu iboraviy fe’llar ingliz tilida juda ko‘p ishlatiladi va har kuni kerak bo‘ladi.\n"
        "O‘zbek tilida ham shunga o‘xshagan birikmalar bor: [i]axtarib topmoq[/i], [i]yuzma-yuz kelmoq[/i], [i]yordam bermoq[/i].\n\n"
        "✅ [b]Bugungi phrasal verbs:[/b]\n"
        "Ularni ma’no va prepozitsiyalariga qarab guruhlaymiz:\n\n"
        "📌 [b]Atrofda yoki harakat yo‘nalishi:[/b]\n"
        "• [b]look around[/b] — atrofga qaramoq\n"
        "• [b]turn around[/b] — orqaga burilmoq\n"
        "• [b]fly over[/b] — ustidan uchib o‘tmoq\n"
        "• [b]climb over[/b] — ustidan chiqib o‘tmoq\n\n"
        "📌 [b]Aloqalar va munosabatlar:[/b]\n"
        "• [b]get along[/b] — yaxshi chiqishmoq\n"
        "• [b]look after[/b] — g‘amxo‘rlik qilmoq\n\n"
        "📌 [b]Bilish va topish:[/b]\n"
        "• [b]find out[/b] — bilib olmoq\n"
        "• [b]figure out[/b] — tushunib yetmoq, yechim topmoq\n"
        "• [b]come across[/b] — tasodifan uchratmoq\n\n"
        "📌 [b]Davom ettirish va to‘xtatish:[/b]\n"
        "• [b]go on[/b] — davom etmoq\n"
        "• [b]keep on[/b] — davom ettira bermoq\n"
        "• [b]hold on[/b] — kutmoq (telefonni ushlab turmoq)\n"
        "• [b]drop out[/b] — maktab, kurs yoki ishni tashlab ketmoq\n\n"
        "📌 [b]Natija va qaror:[/b]\n"
        "• [b]give up[/b] — taslim bo‘lmoq, voz kechmoq\n"
        "• [b]end up[/b] — ohirida bir holatga tushib qolmoq\n\n"
        "✅ [b]Misollar:[/b]\n"
        "• Let’s [b]look around[/b] the city. 🏙️ — Keling, shaharni aylanamiz.\n"
        "• [b]Turn around[/b]! 📣 — Orqaga qarang!\n"
        "• Birds [b]fly over[/b] the trees. 🐦 — Qushlar daraxtlar ustidan uchadi.\n"
        "• He can [b]climb over[/b] the wall. 🧗 — U devordan chiqib o‘tishi mumkin.\n"
        "• They [b]get along[/b] well. 🤝 — Ular yaxshi chiqishadi.\n"
        "• Can you [b]look after[/b] my cat? 🐱 — Mening mushugimga qarab tura olasanmi?\n"
        "• I’ll [b]find out[/b] the answer. 🔍 — Men javobini bilib olaman.\n"
        "• She [b]figured out[/b] the problem. 💡 — U muammoni tushundi.\n"
        "• I [b]came across[/b] an old friend. 👋 — Men eski do‘stimni uchratdim.\n"
        "• [b]Go on[/b]! I’m listening. 🎧 — Davom et, eshitayapman.\n"
        "• He [b]keeps on[/b] talking. 🗣️ — U gapira beradi.\n"
        "• [b]Hold on[/b] a minute, please. 📞 — Bir daqiqa kuting.\n"
        "• She [b]dropped out[/b] of college. 🎓 — U kollejni tashlab ketdi.\n"
        "• Don’t [b]give up[/b]! 💪 — Taslim bo‘lma!\n"
        "• We [b]ended up[/b] in a small café. ☕ — Oxirida kichkina kafega tushib qoldik.\n\n"
        "✅ [b]Mashq:[/b]\n"
        "Quyidagilarni tarjima qiling:\n"
        "1. U devordan chiqib o‘tdi.\n"
        "2. Men javobini topdim.\n"
        "3. Biz eski do‘stimizni uchratdik.\n"
        "4. Davom et!\n"
        "5. U ishni tashlab ketdi.\n\n"
  },
  {
    "lesson": 93,
    "title": "And, But, Or, So, Because (Bog‘lovchilar)",
    "content": "👋 Salom, aziz o‘quvchilar! 📖\n\n"
        "Bugun biz [b]and[/b], [b]but[/b], [b]or[/b], [b]so[/b], [b]because[/b] kabi so‘zlarni o‘rganamiz. Ular ikkita gapni bog‘lab, bitta uzun gap hosil qilish uchun ishlatiladi.\n\n"
        "✅ [b]And[/b] – va\n"
        "Ikkita gap yoki fikrni bog‘lash uchun ishlatiladi:\n"
        "• I have a cat [b]and[/b] a dog. 🐱🐶 – Menda mushuk va it bor.\n"
        "• Sam likes coffee [b]and[/b] tea. ☕🍵 – Sam qahva va choyni yaxshi ko‘radi.\n\n"
        "✅ [b]But[/b] – lekin\n"
        "Ikki gapni qarama-qarshi ma’noda bog‘laydi:\n"
        "• I called you [b]but[/b] you didn’t answer. 📞 – Men senga qo‘ng‘iroq qildim, lekin javob bermading.\n"
        "• This dress is nice [b]but[/b] expensive. 👗💸 – Bu ko‘ylak chiroyli, lekin qimmat.\n\n"
        "✅ [b]Or[/b] – yoki\n"
        "Tanlovni bildiradi:\n"
        "• Do you want pizza [b]or[/b] pasta? 🍕🍝 – Pitsa istaysanmi yoki makaron?\n"
        "• Is it a rabbit [b]or[/b] a cat? 🐰🐱 – Bu quyonmi yoki mushuk?\n\n"
        "✅ [b]So[/b] – shuning uchun\n"
        "Natijani bildiradi:\n"
        "• It’s raining, [b]so[/b] we stayed at home. 🌧️ – Yomg‘ir yog‘moqda, shuning uchun uyda qoldik.\n"
        "• I was hungry, [b]so[/b] I made a sandwich. 🥪 – Men och edim, shuning uchun sendvich tayyorladim.\n\n"
        "✅ [b]Because[/b] – chunki\n"
        "Sababni bildiradi:\n"
        "• I’m happy [b]because[/b] today is my birthday. 🎉 – Men xursandman, chunki bugun tug‘ilgan kunim.\n"
        "• They left early [b]because[/b] they were tired. 💤 – Ular erta ketishdi, chunki charchashgan edi.\n\n"
        "✅ [b]Mashq:[/b]\n"
        "Quyidagi gaplarni to‘g‘ri conjunction bilan to‘ldiring:\n"
        "1. She bought a cake [b]but[/b] didn’t eat it.\n"
        "2. Do you want tea [b]or[/b] coffee?\n"
        "3. I was late, [b]so[/b] my friend waited for me.\n"
        "4. I stayed at home [b]because[/b] it was cold outside.\n"
        "5. He likes fish [b]and[/b] doesn’t like meat.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=segCafsJnYk&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=110]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 94,
    "title": "Vaqt Bog'lovchisi: When (Conjunction of Time: When)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 94[/b] darsimizda ingliz tilidagi muhim vaqt bog'lovchisi – [b]'when'[/b] ni o'rganamiz. Bu so'z ikkita harakat yoki hodisani bog'lash uchun ishlatiladi, birining boshqasi bilan bir vaqtda yoki undan keyin sodir bo'lishini ko'rsatadi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]O'tgan Zamonda Ishlatilishi (Using in the Past Tense)[/b]\n"
        "[b]'When'[/b] ko'pincha o'tgan zamondagi ikkita harakatni bog'lash uchun ishlatiladi. [b]'When'[/b] bilan bog'langan harakat asosiy gapdagi harakat bilan bir vaqtda yoki undan sal oldin sodir bo'ladi.\n"
        "  • Agar [b]'when'[/b] bilan boshlangan bo'lak birinchi kelsa, undan keyin vergul qo'yiladi:\n"
        "    • [b]When I arrived[/b] at the station, the train had already left. 🚂 – Stansiyaga yetib kelganimda, poyezd allaqachon jo'nab ketgan edi.\n"
        "    • [b]When she saw[/b] the surprise, she smiled. 😄 – Sovg'ani ko'rganida, u jilmaydi.\n"
        "  • Agar [b]'when'[/b] bilan boshlangan bo'lak ikkinchi kelsa, vergul qo'yilmaydi:\n"
        "    • The lights went out [b]when I was[/b] cooking dinner. 💡 – Kechki ovqat pishirayotganimda chiroqlar o'chib qoldi.\n"
        "    • He called me [b]when I was[/b] in the shower. 📞 – Men dushda bo'lganimda u menga qo'ng'iroq qildi.\n\n"
        "✅ [b]Kelasi Ma'noda Hozirgi Zamon Bilan Ishlatilishi (Using Present Tense for Future Meaning)[/b]\n"
        "Kelajakdagi harakatlar haqida gapirganda, [b]'when'[/b] bog'lovchisidan keyin kelasi zamon emas, balki [b]hozirgi oddiy zamon (present simple)[/b] ishlatiladi. Asosiy gap esa odatda kelasi zamonda bo'ladi.\n"
        "  • [b]When I finish[/b] my work, [b]I will go[/b] for a walk. 🚶 – Ishimni tugatsam, sayrga chiqaman.\n"
        "  • [b]When you come[/b] to my house, [b]we can watch[/b] a movie. 🍿 – Uyimga kelsangiz, film tomosha qilishimiz mumkin.\n"
        "  • [b]When he arrives[/b], please tell him to wait. 👋 – U kelganida, iltimos, kutib turishini ayting.\n"
        "  • [b]When it stops[/b] raining, [b]we'll play[/b] outside. ⚽ – Yomg'ir to'xtaganida, tashqarida o'ynaymiz.\n\n"
        "✅ [b]Boshqa Vaqt Bog'lovchilari bilan Solishtirish (Comparison with Other Time Conjunctions)[/b]\n"
        "[b]'Before'[/b] (oldin), [b]'while'[/b] (paytida), [b]'after'[/b] (keyin), [b]'until'[/b] (gacha) kabi boshqa vaqt bog'lovchilari ham kelajakdagi ma'no uchun o'zlaridan keyin hozirgi oddiy zamonni ishlatadilar.\n"
        "  • I'll call you [b]before I leave[/b] for the airport. 🛫 – Aeroportga jo'nashimdan oldin sizga qo'ng'iroq qilaman.\n"
        "  • Don't open the door [b]until I tell[/b] you. 🔒 – Men aytmagunimcha eshikni ochmang.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=q9ZNXPvEeWQ&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=111]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 95,
    "title": "Agar ... Bo'lsa (First Conditional: If ... Happens)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 95[/b] darsimizda ingliz tilidagi [b]Birinchi Shart Gapi (First Conditional)[/b]ni o'rganamiz. Bu gap tuzilishi kelajakda ro'y berishi mumkin bo'lgan haqiqiy va ehtimoliy vaziyatlar hamda ularning natijalari haqida gapirish uchun ishlatiladi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Tuzilishi (Structure)[/b]\n"
        "Birinchi shart gapining asosiy tuzilishi quyidagicha:\n"
        "[b]If + hozirgi oddiy zamon (present simple), kelasi oddiy zamon (future simple: will + asosiy fe'l)[/b]\n"
        "Shuningdek, [b]'will'[/b] o'rniga [b]'can', 'may', 'might', 'should', 'must'[/b] kabi modal fe'llar ham ishlatilishi mumkin, bu natijaning ehtimolligi yoki majburiyatini ifodalaydi.\n\n"
        "✅ [b]Qo'llanilishi (Usage)[/b]\n"
        "Birinchi shart gapi kelajakdagi haqiqiy va ehtimoliy vaziyatlar va ularning oqibatlarini tasvirlash uchun qo'llaniladi. Bu, ma'lum bir shart bajarilsa, nima sodir bo'lishi mumkinligini aytadi.\n"
        "  • [b]If it rains[/b] tomorrow, [b]we will stay[/b] at home. ☔ – Agar ertaga yomg'ir yog'sa, uyda qolamiz.\n"
        "  • [b]If you study[/b] hard, [b]you will pass[/b] the exam. 📚 – Agar qattiq o'qisangiz, imtihondan o'tasiz.\n"
        "  • [b]If she calls[/b], [b]I can tell[/b] her the news. 📞 – Agar u qo'ng'iroq qilsa, unga yangilikni aytishim mumkin.\n"
        "  • [b]If I have[/b] enough money, [b]I might buy[/b] a new car. 💸 – Agar yetarli pulim bo'lsa, yangi mashina sotib olishim mumkin.\n\n"
        "✅ [b]'If' Bog'lovchisini Gap O'rtasida Ishlatish (Using 'If' in the Middle of the Sentence)[/b]\n"
        "Gap bo'laklarining o'rnini almashtirish mumkin. Agar [b]'if'[/b] gapning o'rtasida kelsa, vergul qo'yilmaydi.\n"
        "  • We will go to the park [b]if the weather is[/b] nice. 🏞️ – Ob-havo yaxshi bo'lsa parkga boramiz.\n"
        "  • You can get a discount [b]if you pay[/b] in cash. 💵 – Agar naqd to'lasangiz chegirma olishingiz mumkin.\n\n"
        "✅ [b]'Unless' Bilan Ishlatish (Using 'Unless')[/b]\n"
        "[b]'Unless'[/b] so'zi [b]'if ... not'[/b] (agar ... bo'lmasa) ma'nosini beradi. U salbiy shartni ifodalash uchun ishlatiladi.\n"
        "  • [b]Unless you hurry[/b], you will miss the train. 🚆 – Agar shoshilmasangiz, poyezdni o'tkazib yuborasiz. (Ya'ni, [b]If you don't hurry[/b]...)\n"
        "  • [b]Unless it stops[/b] raining, we can't go outside. 🌧️ – Yomg'ir to'xtamaguncha, tashqariga chiqa olmaymiz. (Ya'ni, [b]If it doesn't stop[/b]...)\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=JnIVizF3eys&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=112]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 96,
    "title":
        "Ikkinchi Shartli Gaplar: Agar ... Bo'lganda Edi (Second Conditional: If ... Happened)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 96[/b] darsimizda ingliz tilidagi [b]Ikkinchi Shartli Gaplar (Second Conditional)[/b]ni o'rganamiz. Bu gap tuzilishi hozirgi yoki kelajakdagi hayoliy, haqiqiy bo'lmagan yoki juda kam ehtimolli vaziyatlar hamda ularning hayoliy natijalari haqida gapirish uchun ishlatiladi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Tuzilishi (Structure)[/b]\n"
        "Ikkinchi shart gapining asosiy tuzilishi quyidagicha:\n"
        "[b]If + o'tgan oddiy zamon (past simple), would/could/might + asosiy fe'l (base verb)[/b]\n"
        "Bu yerda [b]o'tgan oddiy zamon[/b] o'tgan zamondagi voqealarni emas, balki hozirgi yoki kelajakdagi xayoliy vaziyatni ifodalaydi.\n\n"
        "✅ [b]Qo'llanilishi (Usage)[/b]\n"
        "Ikkinchi shart gapi hozirgi yoki kelajakdagi haqiqatga to'g'ri kelmaydigan yoki ro'y berishi juda dargumon bo'lgan vaziyatlar haqida gapirish uchun ishlatiladi. Bu asosan [i]'agar shunday bo'lganda edi, bunday bo'lar edi'[/i] ma'nosini beradi.\n"
        "  • [b]If I had[/b] a million dollars, [b]I would travel[/b] around the world. ✈️ – Agar million dollarim bo'lganda edi, dunyo bo'ylab sayohat qilardim. (Lekin hozir million dollarim yo'q.)\n"
        "  • [b]If she spoke[/b] English, [b]she would get[/b] that job. 🗣️ – Agar u ingliz tilida gapirganida edi, o'sha ishni olardi. (Lekin u ingliz tilida gapirmaydi.)\n"
        "  • [b]If we lived[/b] in a bigger city, [b]we would have[/b] more opportunities. 🏙️ – Agar kattaroq shaharda yashaganimizda edi, ko'proq imkoniyatlarga ega bo'lardik. (Lekin biz kattaroq shaharda yashamaymiz.)\n\n"
        "✅ [b]'If I were...' Ishlatilishi (Using 'If I were...')[/b]\n"
        "[b]'To be'[/b] fe'li uchun [b]'if'[/b] bo'lagida barcha shaxslar uchun ([b]I, he, she, it[/b]) [b]'were'[/b] shaklidan foydalanish odatiy holdir, ayniqsa maslahat berishda.\n"
        "  • [b]If I were[/b] you, [b]I wouldn't buy[/b] that car. 🚗 – Men sizning o'rningizda bo'lganimda, bu mashinani sotib olmasdim.\n"
        "  • [b]If she were[/b] here, [b]she would help[/b] us. 🙋‍♀️ – Agar u bu yerda bo'lganida edi, bizga yordam berardi.\n\n"
        "✅ [b]Asosiy Gapda 'Could' va 'Might' (Using 'Could' and 'Might' in the Main Clause)[/b]\n"
        "Asosiy gapda [b]'would'[/b] dan tashqari, [b]'could'[/b] (qobiliyat/imkoniyat) yoki [b]'might'[/b] (ehtimollik) ham ishlatilishi mumkin.\n"
        "  • [b]If I had[/b] more time, [b]I could learn[/b] a new skill. ⏱️ – Agar ko'proq vaqtim bo'lganda edi, yangi ko'nikma o'rganishim mumkin edi.\n"
        "  • [b]If he studied[/b] harder, [b]he might pass[/b] the exam. 🤞 – Agar u qattiqroq o'qiganida edi, imtihondan o'tishi mumkin edi.\n\n"
        "✅ [b]Birinchi va Ikkinchi Shart Gaplari O'rtasidagi Farq (Difference Between First and Second Conditionals)[/b]\n"
        "• [b]Birinchi Shart Gapi[/b] (Lesson 95): Kelajakda ro'y berishi [b]haqiqiy va ehtimoliy[/b] vaziyatlar uchun.\n"
        "  • [b]If I win[/b] the lottery, [b]I will buy[/b] a house. (Lotereyani yutish ehtimoli bor) 🏠\n"
        "• [b]Ikkinchi Shart Gapi[/b]: Hozirgi yoki kelajakdagi [b]xayoliy, kam ehtimolli yoki imkonsiz[/b] vaziyatlar uchun.\n"
        "  • [b]If I won[/b] the lottery, [b]I would buy[/b] a house. (Lotereyani yutish ehtimoli juda kam yoki bu shart xayoliy) 💭\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=dX5opXNxAvw&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=113]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 97,
    "title": "If I had had ... / If we had gone ...",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 97[/b] darsimizda ingliz tilidagi [b]Uchinchi Shartli Gaplar (Third Conditional)[/b]ni o‘rganamiz. Bu murakkabroq tuzilma bo'lib, o'tmishda sodir bo'lmagan voqealar va ularning ham amalga oshmagan ehtimoliy natijalari haqida gapirish uchun ishlatiladi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "✅ Bu darsda biz [b]If I had had / If we had gone ...[/b] kabi [i]uchinchi turdagi if[/i] jumlalarini o‘rganamiz.\n\n"
        "Bu jumlalar o‘tmishdagi amalga oshmagan vaziyatlar va ularning oqibatlarini tasvirlash uchun ishlatiladi:\n"
        "• [b]If I had had a car[/b], I would have driven to work. 🚗 — Agar mashinam bo‘lganida edi, ishga mashinada borgan bo‘lardim.\n"
        "(Lekin o‘tmishda mashinam yo‘q edi, shuning uchun piyoda bordim/transportda bordim.)\n\n"
        "📌 [b]If + past perfect[/b] → [b]would have + past participle[/b]\n"
        "• [b]If we had lived in Paris[/b], we would have spoken French every day. 🗼🇫🇷\n"
        "(Lekin biz Parijda yashamagandik, shuning uchun har kuni fransuzcha gapirmadik.)\n\n"
        "📌 [b]If[/b] jumlasi boshida yoki o‘rtasida kelishi mumkin:\n"
        "• [b]If he had known the answer[/b], he would have told us. 🤔\n"
        "• He would have told us [b]if he had known the answer[/b].\n\n"
        "✅ [b]I would have[/b] qisqartmasi: [b]I’d have[/b]\n"
        "• I’d have helped you if I had had more time. 🕒 — Agar ko‘proq vaqtim bo‘lganida edi, senga yordam bergan bo‘lardim.\n"
        "• She’d have been happy if she had lived by the sea. 🌊 — Agar u dengiz bo‘yida yashaganida edi, baxtli bo‘lgan bo‘lardi.\n\n"
        "✅ [b]Could have[/b] va [b]might have[/b] ham ishlatiladi:\n"
        "• [b]If we had had a car[/b], we [b]could have traveled[/b] more. 🚗🗺️ — Agar mashinamiz bo‘lganida edi, ko‘proq sayohat qila olgan bo‘lardik.\n"
        "• [b]If I had known her better[/b], I [b]might have asked her out[/b]. 😊 — Uni yaxshiroq bilganimda edi, uchrashuvga taklif qilgan bo‘lishim mumkin edi.\n\n"
        "✅ [b]Taqqoslang:[/b]\n"
        "• [b]If I have money[/b], I’ll buy that phone. 💰📱 (Ehtimol pulim bo‘ladi.)\n"
        "• [b]If I had money[/b], I’d buy that phone. ❌💸 (Lekin hozir pulim yo‘q.)\n"
        "• [b]If I had had money[/b], I would have bought that phone. ❌💸 (Lekin o‘tmishda pulim yo‘q edi, shuning uchun sotib ololmadim.)\n\n"
        "✅ [b]Yangi misollar:[/b]\n"
        "• [b]If he had worked less[/b], he’d have felt better. 🧘 — Agar u kamroq ishlaganida edi, o‘zini yaxshi his qilgan bo‘lardi.\n"
        "• [b]If they had known the rules[/b], they wouldn’t have made mistakes. 📘 — Agar ular qoidalarni bilganida edi, xatolar qilmagan bo‘lardi.\n"
        "• [b]If she had had a bicycle[/b], she’d have gone to school faster. 🚲 — Velosipedi bo‘lganida edi, maktabga tezroq borgan bo‘lardi.\n"
        "• [b]If I had been able to sing well[/b], I’d have joined a band. 🎤 — Yaxshi qo‘shiq ayta olganimda edi, guruhga qo‘shilgan bo‘lardim.\n\n"
        "✅ [b]Qo'shimcha misollar:[/b]\n"
        "1. [b]If I had studied harder[/b], I would have passed the exam. 📚\n"
        "2. [b]If she had arrived earlier[/b], she wouldn’t have missed the bus. 🚌\n"
        "3. We would have gone to the party [b]if we had been invited[/b]. 🎉\n"
        "4. [b]If they hadn’t lost their map[/b], they wouldn’t have got lost. 🗺️\n"
        "5. [b]If you had told me sooner[/b], I could have helped you. 🤝\n\n"
  },
  {
    "lesson": 98,
    "title": "Aniqlovchi Ergash Gaplar (Relative Clauses)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 98[/b] darsimizda ingliz tilidagi [b]Aniqlovchi Ergash Gaplar (Relative Clauses)[/b] ni o'rganamiz. Bu gaplar aniqlovchiga qo'shimcha ma'lumot beradi va ko'pincha [b]'who', 'that', 'which'[/b] kabi bog'lovchi olmoshlar orqali boshlanadi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Who (Shaxslar uchun) (Who (For People))[/b]\n"
        "[b]'Who'[/b] bog'lovchi olmoshi faqatgina [b]shaxslarga[/b] nisbatan ishlatiladi.\n"
        "  • I met a woman [b]who[/b] teaches art. 👩‍🎨 – Men san'atdan dars beradigan ayolni uchratdim.\n"
        "  • He is the person [b]who[/b] helped me yesterday. 🤝 – U kecha menga yordam bergan odam.\n"
        "  • Do you know anyone [b]who[/b] speaks Japanese? 🗣️🇯🇵 – Yapon tilida gapiradigan birorta odamni bilasizmi?\n\n"
        "✅ [b]That (Narsalar va Ba'zan Shaxslar uchun) (That (For Things and Sometimes People))[/b]\n"
        "[b]'That'[/b] bog'lovchi olmoshi [b]narsalarga[/b] nisbatan ishlatiladi. Shuningdek, u [b]shaxslarga[/b] nisbatan ham ishlatilishi mumkin, lekin [b]'who'[/b] ko'proq afzal ko'riladi.\n"
        "  • This is the book [b]that[/b] I was talking about. 📚 – Bu men gapirayotgan kitob.\n"
        "  • Where is the pen [b]that[/b] was on the table? 🖊️ – Stol ustidagi ruchka qayerda?\n"
        "  • She works for a company [b]that[/b] makes software. 💻 – U dasturiy ta'minot ishlab chiqaradigan kompaniyada ishlaydi.\n\n"
        "✅ [b]Which (Faqat Narsalar uchun) (Which (Only for Things))[/b]\n"
        "[b]'Which'[/b] bog'lovchi olmoshi [b]faqatgina narsalarga[/b] nisbatan ishlatiladi. U [b]'that'[/b] ning o'rnida ishlatilishi mumkin, lekin ayrim holatlarda ma'no farqi bo'lishi mumkin (keyingi darslarda batafsil).\n"
        "  • The car [b]which[/b] is parked outside is mine. 🚗 – Tashqarida turgan mashina meniki.\n"
        "  • I found a wallet [b]which[/b] contained a lot of money. 💰 – Ko'p puli bor hamyon topdim.\n"
        "  • He bought a new phone [b]which[/b] has a great camera. 📸 – U ajoyib kamerasi bor yangi telefon sotib oldi.\n\n"
        "✅ [b]Who va That ni Taqqoslash (Comparing Who and That)[/b]\n"
        "Shaxslarga nisbatan [b]'who'[/b] ishlatish ko'proq tabiiyroq, lekin [b]'that'[/b] ham to'g'ri hisoblanadi, ayniqsa norasmiy nutqda.\n"
        "  • He's the student [b]who[/b] won the scholarship. (yoki [b]that[/b] won) 🏅 – U stipendiyani yutgan talaba.\n"
        "  • Do you remember the woman [b]who[/b] spoke at the conference? (yoki [b]that[/b] spoke) 👩‍🏫 – Konferensiyada nutq so'zlagan ayolni eslaysizmi?\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=PUSsEM3mJ-E&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=114]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 99,
    "title": "Aniqlovchi Ergash Gaplar 2 (Relative Clauses 2)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 99[/b] darsimizda [b]Aniqlovchi Ergash Gaplar (Relative Clauses)[/b] mavzusining ikkinchi qismini o'rganamiz. Bu darsda biz nisbiy olmoshlarni qachon tushirib qoldirish mumkinligini va ularni predloglar bilan qanday ishlatishni ko'rib chiqamiz. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Who/That/Which' Qoldirilishi Mumkin Bo'lgan Holatlar (When 'Who/That/Which' Can Be Omitted)[/b]\n"
        "[b]'Who'[/b], [b]'that'[/b] yoki [b]'which'[/b] bog'lovchi olmoshlarini, agar ular nisbiy ergash gapda fe'lning [b]to'ldiruvchisi (object)[/b] bo'lib kelsa, tushirib qoldirishimiz mumkin. Ya'ni, nisbiy olmoshdan keyin fe'l emas, balki boshqa bir ot yoki olmosh (sub'ekt) kelsa.\n"
        "  • This is the man [b](who/that)[/b] [i]I met[/i] yesterday. 👨‍💼 – Bu men kecha uchratgan odam.\n"
        "  • The car [b](which/that)[/b] [i]you bought[/i] is very fast. 🏎️ – Siz sotib olgan mashina juda tez.\n"
        "  • I found the keys [b](which/that)[/b] [i]I lost[/i] last week. 🔑 – Men o'tgan hafta yo'qotgan kalitlarni topdim.\n\n"
        "✅ [b]Predloglar Bilan Ishlatilishi (Usage with Prepositions)[/b]\n"
        "Agar nisbiy ergash gapda predlog bo'lsa ([b]in, at, for, with[/b] va boshqalar), predlog odatda gapning oxirida keladi.\n"
        "  • This is the house [b]that I live in[/b]. 🏠 – Bu men yashaydigan uy.\n"
        "  • Do you know the girl [b]who he was talking to[/b]? 💬 – U gaplashayotgan qizni bilasizmi?\n"
        "  • The project [b]which they are working on[/b] is very important. 📈 – Ular ishlayotgan loyiha juda muhim.\n"
        "• Rasmiyroq nutqda predlogni [b]'which'[/b] (narsalar uchun) yoki [b]'whom'[/b] (shaxslar uchun) dan oldin qo'yish ham mumkin, lekin bu kundalik nutqda kam uchraydi:\n"
        "  • This is the house [b]in which I live[/b]. (rasmiyroq)\n\n"
        "✅ [b]'Where' Ishlatilishi (Using 'Where')[/b]\n"
        "Joylarga nisbatan gapirganda, [b]'in which'[/b] yoki [b]'at which'[/b] o'rniga ko'pincha [b]'where'[/b] ishlatiladi, chunki u qulayroq va tabiiyroq eshitiladi.\n"
        "  • This is the restaurant [b]where[/b] we had our first date. 💖 – Bu biz birinchi marta uchrashgan restoran.\n"
        "  • I visited the city [b]where[/b] my grandparents were born. 📍 – Bobo-buvilarim tug'ilgan shaharga tashrif buyurdim.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=8yN2qK3OnRo&list=PLkREkayoYCyI9KGsZ2TfeVccRv9zqP0gl&index=115]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 100,
    "title": "Hozirgi Tugallangan Davomli Zamon (Present Perfect Continuous)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 100[/b] darsimizda ingliz tilidagi [b]Hozirgi Tugallangan Davomli Zamon (Present Perfect Continuous)[/b] ni o'rganamiz. Bu zamon o'tmishda boshlangan va hozirgacha davom etayotgan yoki yaqinda tugagan, natijasi hozirda ko'rinib turgan harakatlar haqida gapirish uchun ishlatiladi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Tuzilishi (Structure)[/b]\n"
        "Hozirgi Tugallangan Davomli Zamon [b]'have/has been + fe'l-ing'[/b] shaklida yasaladi.\n"
        "• [b]I/You/We/They[/b] uchun: [b]have been + fe'l-ing[/b]\n"
        "• [b]He/She/It[/b] uchun: [b]has been + fe'l-ing[/b]\n"
        "  • I [b]have been reading[/b] a book for two hours. 📖 – Men ikki soatdan beri kitob o'qiyapman.\n"
        "  • She [b]has been working[/b] all day. 💻 – U butun kun ishlayapti.\n\n"
        "✅ [b]Qo'llanilishi (Usage)[/b]\n"
        "Bu zamon quyidagi holatlarda ishlatiladi:\n"
        "1.  O'tmishda boshlangan va [b]hozirgacha davom etayotgan[/b] harakatlar uchun.\n"
        "    • It [b]has been raining[/b] since morning. ☔ – Ertalabdan beri yomg'ir yog'yapti.\n"
        "    • They [b]have been living[/b] in this city for ten years. 🏘️ – Ular bu shaharda o'n yildan beri yashashadi.\n"
        "2.  Yaqinda tugagan, ammo [b]natijasi yoki ta'siri hozirda ko'rinib turgan[/b] harakatlar uchun.\n"
        "    • Your eyes are red. [b]Have you been crying[/b]? 😢 – Ko'zlaringiz qizargan. Yig'laganmidingiz?\n"
        "    • I'm tired because I [b]have been running[/b]. 🏃‍♀️ – Charchadim, chunki yugurgandim.\n\n"
        "✅ [b]'For' va 'Since' bilan Ishlatilishi (Usage with 'For' and 'Since')[/b]\n"
        "Hozirgi Tugallangan Davomli Zamon bilan harakatning davomiyligini ko'rsatish uchun [b]'for'[/b] va [b]'since'[/b] predloglari ishlatiladi.\n"
        "  • [b]For[/b]: vaqt oralig'ini ko'rsatadi (masalan, [b]for two hours, for a long time[/b]). ⏳\n"
        "    • He [b]has been playing[/b] guitar [b]for three hours[/b]. 🎸 – U uch soatdan beri gitara chalyapti.\n"
        "  • [b]Since[/b]: harakat boshlangan aniq vaqtni ko'rsatadi (masalan, [b]since 2020, since last Monday[/b]). 📅\n"
        "    • We [b]have been waiting[/b] [b]since 10 o'clock[/b]. ⏰ – Biz soat 10 dan beri kutyapmiz.\n\n"
        "✅ [b]Hozirgi Davomli Zamon bilan Taqqoslash (Comparison with Present Continuous)[/b]\n"
        "• [b]Hozirgi Davomli Zamon (Present Continuous)[/b] ([i]I am doing[/i]):\n"
        "  Hozir, aynan gapirayotgan paytda sodir bo'layotgan harakatlar uchun.\n"
        "  • Please don't disturb me. I [b]am working[/b]. 🤫 – Iltimos, meni bezovta qilmang. Men ishlayapman.\n"
        "• [b]Hozirgi Tugallangan Davomli Zamon (Present Perfect Continuous)[/b] ([i]I have been doing[/i]):\n"
        "  O'tmishda boshlangan va hozirgacha davom etayotgan yoki yaqinda tugagan, ammo natijasi mavjud bo'lgan harakatlar uchun.\n"
        "  • I [b]have been working[/b] hard all day, so I'm tired now. 😓 – Men butun kun qattiq ishladim, shuning uchun hozir charchadim.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=tuVjUbwrSeo]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 101,
    "title": "Tugallangan O'tgan Zamon (Past Perfect)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 101[/b] darsimizda ingliz tilidagi [b]Tugallangan O'tgan Zamon (Past Perfect)[/b] ni o'rganamiz. Bu zamon o'tmishdagi boshqa bir harakatdan oldin sodir bo'lgan harakatlarni ifodalash uchun ishlatiladi. Bu o'tmishdagi voqealar ketma-ketligini aniqlashga yordam beradi. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Tuzilishi (Structure)[/b]\n"
        "Tugallangan O'tgan Zamon [b]'had + fe'lning o'tgan zamon sifatdoshi (past participle ya'ni V3)'[/b] shaklida yasaladi.\n"
        "• [b]Barcha shaxslar[/b] uchun: [b]had + fe'lning 3-shakli[/b] (masalan, [b]gone, finished, eaten[/b]).\n"
        "  • I [b]had already finished[/b] my homework when my friend called. 📚 – Do'stim qo'ng'iroq qilganida, men uy vazifamni allaqachon tugatgan edim.\n"
        "  • She [b]had never seen[/b] such a beautiful place before that trip. 🏞️ – U o'sha sayohatdan oldin bunday go'zal joyni hech qachon ko'rmagan edi.\n\n"
        "✅ [b]Qo'llanilishi (Usage)[/b]\n"
        "Bu zamon quyidagi holatlarda ishlatiladi:\n"
        "1.  O'tmishdagi [b]boshqa bir harakatdan oldin tugallangan[/b] harakatni ifodalash uchun.\n"
        "    • When I arrived at the cinema, the film [b]had already started[/b]. 🎬 – Kinoteatrga yetib borganimda, film allaqachon boshlangan edi.\n"
        "    • They felt tired because they [b]had walked[/b] for hours. 🚶‍♀️ – Ular charchagan edi, chunki bir necha soat piyoda yurishgan edi.\n"
        "2.  O'tmishdagi biror nuqtaga qadar [b]boshlangan va davom etgan[/b] harakatlar uchun (ko'pincha [b]'for'[/b] yoki [b]'since'[/b] bilan).\n"
        "    • He [b]had been[/b] a teacher [b]for twenty years[/b] before he retired. 👨‍🏫 – Nafaqaga chiqishidan oldin u yigirma yil o'qituvchi bo'lgan edi.\n\n"
        "✅ [b]O'tgan Oddiy Zamon bilan Taqqoslash (Comparison with Past Simple)[/b]\n"
        "• [b]O'tgan Oddiy Zamon (Past Simple)[/b]:\n"
        "  O'tmishdagi voqealarni ularning [b]sodir bo'lish tartibi[/b] bo'yicha ketma-ket sanash uchun ishlatiladi. Harakatlar birin-ketin sodir bo'ladi.\n"
        "  • I [b]came[/b] home and [b]ate[/b] dinner. 🏡 – Uyga keldim va kechki ovqatni yedim.\n"
        "• [b]Tugallangan O'tgan Zamon (Past Perfect)[/b]:\n"
        "  O'tmishdagi bir harakatning [b]boshqa bir harakatdan oldinroq[/b] sodir bo'lganligini ko'rsatish uchun.\n"
        "  • I [b]ate[/b] dinner after I [b]had come[/b] home. 🍽️ – Uyga kelganimdan keyin kechki ovqatni yedim. (Uyga kelish ovqat yeyishdan oldin sodir bo'lgan).\n\n"
        "✅ [b]Hozirgi Tugallangan Zamon bilan Taqqoslash (Comparison with Present Perfect)[/b]\n"
        "• [b]Hozirgi Tugallangan Zamon (Present Perfect)[/b] ([i]have/has done[/i]):\n"
        "  O'tmishda boshlangan va [b]hozirgi paytga bog'liq[/b] bo'lgan harakatlar uchun.\n"
        "  • I [b]have lost[/b] my keys, so I can't open the door now. 🔑 – Kalitlarimni yo'qotdim, shuning uchun hozir eshikni ocha olmayman.\n"
        "• [b]Tugallangan O'tgan Zamon (Past Perfect)[/b] ([i]had done[/i]):\n"
        "  O'tmishda boshlangan va [b]o'tmishdagi boshqa bir nuqtaga bog'liq[/b] bo'lgan harakatlar uchun.\n"
        "  • I couldn't open the door because I [b]had lost[/b] my keys. 🔒 – Eshikni ocha olmadim, chunki kalitlarimni yo'qotgan edim.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=IXP2aTaC3No]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 102,
    "title": "Present tenses (I am doing / I do) for the future",
    "content": "Assalomu alaykum! 👋 Bugun biz hozirgi zamon shakllaridan kelajakdagi voqealarni ifodalash uchun qanday foydalanishni o‘rganamiz: [b]Present Continuous[/b] ([b]I am doing[/b]) va [b]Present Simple[/b] ([b]I do[/b]) zamonlari.\n\n"
        "✅ [b]Present Continuous (I am doing)[/b] — kelajakdagi rejalar va tashkillashtirilgan tadbirlar uchun\n"
        "Bu zamonni biz allaqachon qaror qilingan va tashkillashtirilgan kelajakdagi harakatlar uchun ishlatamiz. Ya’ni, siz bu ishni qilasiz.\n\n"
        "Misollar:\n"
        "• Shanba kuni kechqurun nima qilyapsiz? 🌃\n"
        "  [b]What are you doing on Saturday evening?[/b]\n\n"
        "• Biz shanba kuni kontsertga boryapmiz. 🎶\n"
        "  [b]We are going to a concert on Saturday.[/b]\n\n"
        "• Oybek ertaga ertalab yangi telefonini olib kelyapti. 📱\n"
        "  [b]Oybek is bringing his new phone tomorrow morning.[/b]\n\n"
        "• Keyingi oy mening do‘stlarim bilan uchrashyapman. 🤝\n"
        "  [b]I am meeting my friends next month.[/b]\n\n"
        "✅ [b]Present Simple (I do)[/b] — jadvallar va dasturlar uchun\n"
        "Bu zamonni biz poezdlar, avtobuslar, kinolar, darslar kabi belgilangan jadvallar va dasturlar haqida gapirganda ishlatamiz. Ular shaxsiy rejalaringizdan ko‘ra, ko‘proq qat’iy va o‘zgarmas holatlarni bildiradi.\n\n"
        "Misollar:\n"
        "• Poezd soat ertalab 9:00da jo‘naydi. 🚂\n"
        "  [b]The train leaves at 9:00 AM.[/b]\n\n"
        "• Kino soat 19:30da boshlanadi. 🎬\n"
        "  [b]The film starts at 7:30 PM.[/b]\n\n"
        "• Bizning darsimiz keyingi hafta seshanba kuni tugaydi. 🏫\n"
        "  [b]Our class finishes next Tuesday.[/b]\n\n"
        "• Yangi do‘kon dushanba kuni ochiladi. 🛍️\n"
        "  [b]The new store opens on Monday.[/b]\n\n"
        "✅ [b]Taqqoslang: Present Continuous (I am doing) va Present Simple (I do)[/b]\n\n"
        "[b]Present Continuous:[/b] Shaxsiy kelishuvlar, rejalashtirilgan tadbirlar.\n"
        "• Siz bugun kechqurun nima qilyapsiz? 🌙\n"
        "  [b]What are you doing this evening?[/b]\n\n"
        "• Men yakshanba kuni sayohatga ketyapman. 🏞️\n"
        "  [b]I am going on a trip on Sunday.[/b]\n\n"
        "[b]Present Simple:[/b] Jadvallar, dasturlar, belgilangan vaqtlar.\n"
        "• Samolyot qachon keladi? ✈️\n"
        "  [b]What time does the plane arrive?[/b]\n\n"
        "• Konsert 20:00da boshlanadi. 🎤\n"
        "  [b]The concert begins at 8:00 PM.[/b]\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=xG8-hTPvpeQ]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 103,
    "title":
        "Vaqt Bog'lovchilari (Kelajak Ma'noda): When, After, Before, As Soon As, Until/Till, While",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 103[/b] darsimizda ingliz tilida kelajakdagi voqealarni ifodalashda [b]when, after, while, before, as soon as, until[/b] va [b]till[/b] kabi bog‘lovchilardan keyin qanday zamonlarni ishlatishni o‘rganamiz. Bu bog‘lovchilar kelajak haqida gapirganda odatda [b]Present Simple[/b] yoki [b]Present Perfect[/b] bilan ishlatiladi, [b]Future Simple[/b] (will) bilan emas. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]Umumiy Qoida (General Rule)[/b]\n"
        "Kelajakdagi voqealar haqida gapirayotganda, [b]when, after, while, before, as soon as, until[/b] va [b]till[/b] kabi vaqt bog'lovchilaridan keyin [b]will[/b] ishlatilmaydi. Buning o'rniga, biz [b]Present Simple[/b] (hozirgi oddiy zamon) yoki [b]Present Perfect[/b] (hozirgi tugallangan zamon) dan foydalanamiz. Asosiy gap esa odatda [b]Future Simple[/b] (kelasi oddiy zamon) da bo'ladi.\n\n"
        "✅ [b]When (Qachonki/Paytida) (When)[/b]\n"
        "• [b]When I arrive[/b] at the airport, I will call you. ✈️ – Aeroportga yetib borganimda, sizga qo'ng'iroq qilaman.\n"
        "• We will start the meeting [b]when everyone is[/b] ready. 👥 – Hamma tayyor bo'lganida yig'ilishni boshlaymiz.\n\n"
        "✅ [b]After (Keyin) (After)[/b]\n"
        "• [b]After I finish[/b] my homework, I will go outside. 📚 – Uy vazifamni tugatganimdan keyin, tashqariga chiqaman.\n"
        "• They will eat dinner [b]after the sun sets[/b]. 🌅 – Quyosh botganidan keyin ular kechki ovqatni yeyishadi.\n\n"
        "✅ [b]While (Paytida/Davomida) (While)[/b]\n"
        "• [b]While you are waiting[/b], you can read this magazine. 📖 – Kutayotganingizda, bu jurnalni o'qishingiz mumkin.\n"
        "• I will prepare the meal [b]while he is[/b] taking a shower. 🚿 – U dush qabul qilayotganida, men ovqat tayyorlayman.\n\n"
        "✅ [b]Before (Oldin) (Before)[/b]\n"
        "• [b]Before you leave[/b], please turn off the lights. 💡 – Ketishdan oldin, iltimos, chiroqlarni o'chiring.\n"
        "• She will check her email [b]before she starts[/b] work. 📧 – U ishni boshlashdan oldin elektron pochtasini tekshiradi.\n\n"
        "✅ [b]As Soon As (Bilanoq/Hamono) (As Soon As)[/b]\n"
        "• [b]As soon as I get[/b] home, I will send you the photos. 📸 – Uyga yetib borishim bilanoq, sizga rasmlarni yuboraman.\n"
        "• They will announce the results [b]as soon as they are[/b] ready. 📢 – Natijalar tayyor bo'lishi bilanoq, ular e'lon qilishadi.\n\n"
        "✅ [b]Until / Till (Gacha) (Until / Till)[/b]\n"
        "• [b]Until[/b] va [b]till[/b] 'gacha' ma'nosini beradi. [b]Till[/b] odatda norasmiyroq hisoblanadi.\n"
        "• I will wait here [b]until you come[/b] back. 🚶‍♀️ – Siz qaytib kelguningizcha shu yerda kutaman.\n"
        "• Don't open the package [b]till I tell[/b] you. 📦 – Men aytmagunimcha paketni ochmang.\n\n"
        "✅ [b]Present Perfect bilan Qo'llanilishi (Usage with Present Perfect)[/b]\n"
        "Ba'zida bu bog'lovchilardan keyin [b]Present Perfect[/b] ishlatiladi, ayniqsa bir harakat tugaganidan keyin boshqa harakat boshlanishini ta'kidlash uchun.\n"
        "• [b]When I have finished[/b] my project, I will take a break. ✅ – Loyihamni tugatganimdan keyin, tanaffus qilaman.\n"
        "• [b]After you have eaten[/b] dinner, you can watch TV. 🍽️ – Kechki ovqatni yeb bo'lganingizdan keyin, televizor ko'rishingiz mumkin.\n    (Bu yerda 'After you eat dinner' ham to'g'ri, lekin 'have eaten' ovqatlanish jarayonining tugaganligini ko'proq ta'kidlaydi).\n\n"
        "[center][b]🎥 Eslatma[/b][/center]\n"
        "Bu vaqt bog'lovchilari bilan Present Perfect for Future kam holatlarda qo'llaniladi va uning umuman qo'llanilmasligi ham hech qanday xato emas.\n"
  },
  {
    "lesson": 104,
    "title": "'Could (do)' va 'Could have (done)'",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 104[/b] darsimizda [b]'could (do)'[/b] va [b]'could have (done)'[/b] modal fe'llarining farqlari va qo'llanilishini o'rganamiz. Bu ikkala ifoda ham imkoniyatni bildiradi, ammo turli vaqt davrlariga tegishlidir. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Could (do)' Ishlatilishi (Using 'Could (do)')[/b]\n"
        "[b]'Could (do)'[/b] hozirgi yoki kelajakdagi [b]imkoniyatni, qobiliyatni[/b] yoki [b]taklifni[/b] ifodalash uchun ishlatiladi. Bu [b]'can'[/b] ning o'tgan zamon shakli bo'lishi mumkin, lekin bu yerda imkoniyat va taklif ma'nosida keladi.\n"
        "  • We [b]could go[/b] to the cinema tonight. 🎬 – Bugun kechqurun kinoga borishimiz mumkin.\n"
        "  • I [b]could help[/b] you with your project if you need. 🤝 – Agar sizga kerak bo'lsa, loyihangizda yordam berishim mumkin.\n"
        "  • It [b]could rain[/b] later, so take an umbrella. ☔ – Keyinroq yomg'ir yog'ishi mumkin, shuning uchun soyabon oling.\n\n"
        "✅ [b]'Could have (done)' Ishlatilishi (Using 'Could have (done)')[/b]\n"
        "[b]'Could have (done)'[/b] o'tmishda [b]sodir bo'lishi mumkin bo'lgan[/b], ammo [b]ro'y bermagan[/b] harakat yoki vaziyatlar haqida gapirish uchun ishlatiladi. Bu o'tkazib yuborilgan imkoniyatni yoki o'tmishdagi ehtimollikni ifodalaydi.\n"
        "  • I [b]could have gone[/b] to the party, but I decided to stay home. 🥳 – Bazmga borsam bo'lar edi, lekin uyda qolishga qaror qildim. (Lekin bormadim).\n"
        "  • You [b]could have called[/b] me if you needed help. 📞 – Agar yordam kerak bo'lsa, menga qo'ng'iroq qilishingiz mumkin edi. (Lekin qo'ng'iroq qilmadingiz).\n"
        "  • He [b]could have won[/b] the race if he hadn't fallen. 🏃‍♂️ – Agar yiqilmaganida, u poygani yutishi mumkin edi. (Lekin yiqildi va yutmadi).\n\n"
        "✅ [b]'Could (do)' va 'Could have (done)' ni Taqqoslash (Comparing 'Could (do)' and 'Could have (done)')[/b]\n"
        "Asosiy farq vaqtda: [b]'could (do)'[/b] hozirgi yoki kelajakdagi imkoniyatni, [b]'could have (done)'[/b] esa o'tmishdagi amalga oshmagan imkoniyatni bildiradi.\n"
        "  • I [b]could go[/b] to the concert tonight. (Bugun borish imkoniyatim bor) 🎵\n"
        "  • I [b]could have gone[/b] to the concert last night, but I was busy. (Kecha borish imkoniyatim bor edi, lekin bormadim) 😔\n\n"
        "✅ [b]'Couldn't have (done)' (O'tmishda imkonsizlik) (Couldn't have (done))[/b]\n"
        "[b]'Couldn't have (done)'[/b] o'tmishda biror narsaning [b]imkonsiz[/b] bo'lganligini ifodalash uchun ishlatiladi.\n"
        "  • They [b]couldn't have known[/b] about the surprise party. It was a secret! 🤫 – Ular kutilmagan bazm haqida bilishlari mumkin emas edi. Bu sir edi!\n"
        "  • He [b]couldn't have finished[/b] all that work by himself. It's too much. 🤯 – U barcha bu ishni yolg'iz o'zi tugatgan bo'lishi mumkin emas. Bu juda ko'p.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=TojrfsZOWwc]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 105,
    "title": "Must and Can't (for certainty)",
    "content": "Assalomu alaykum! 👋 Bugun biz [b]must[/b] va [b]can't[/b] modal fe'llarining yangi ma'nolarini o‘rganamiz. Ehtimol siz [b]must[/b] ni 'majburiyat' (qilishingiz kerak) va [b]can't[/b] ni 'qila olmaslik' (qila olmaysiz) ma’nolarida o‘rgangan bo‘lishingiz mumkin. Bugun esa ularning [b]ishonch[/b] va [b]imkonsizlik[/b] ma’nolarini ko‘rib chiqamiz.\n\n"
        "✅ [b]Must[/b] — ishonch (biror narsa aniq haqiqat ekanligiga ishonch bildirish)\n"
        "Biz [b]must[/b] dan biror narsa haqiqat ekanligiga ishonch hosil qilganimizda foydalanamiz, chunki buning uchun dalillar bor:\n\n"
        "Misol vaziyat: Mening uyim avtomagistral yaqinida joylashgan. 🛣️\n"
        "Bu nima degani? Bu [b]U yer juda shovqinli bo‘lsa kerak[/b] degani.\n"
        "Ingliz tilida: [b]My house is near the motorway. It must be very noisy.[/b]\n\n"
        "• Qo‘shnilarimning chiroqlari yonib turibdi va musiqa eshitilyapti. Ular uyda bo‘lishsa kerak. 🏠\n"
        "  [b]My neighbors' lights are on and I hear music. They must be home.[/b]\n\n"
        "• U mukammal ingliz tilida gapiradi. U ingliz tilida so‘zlashuvchi mamlakatdan bo‘lsa kerak. 🇬🇧\n"
        "  [b]She speaks perfect English. She must be from an English-speaking country.[/b]\n\n"
        "• Uning ustida shifokor xalati bor. U shifokor bo‘lsa kerak. 🧑‍⚕️\n"
        "  [b]He’s wearing a doctor’s coat. He must be a doctor.[/b]\n\n"
        "✅ [b]Can't[/b] — imkonsizlik (biror narsa haqiqat bo‘lishi mumkin emasligiga ishonch bildirish)\n"
        "Biz [b]can't[/b] dan biror narsa haqiqat bo‘lishi mutlaqo imkonsiz ekanligiga ishonch hosil qilganimizda foydalanamiz:\n\n"
        "• U hozirgina katta taom yedi. U yana och bo‘lishi mumkin emas. 🍽️\n"
        "  [b]He just ate a huge meal. He can’t be hungry again.[/b]\n\n"
        "• Bu eski mashina qimmat bo‘lishi mumkin emas. U juda zanglagan. 🚗\n"
        "  [b]That old car can’t be worth much. It’s too rusty.[/b]\n\n"
        "• U hozirgina jo‘nadi. U allaqachon aeroportda bo‘lishi mumkin emas. ✈️\n"
        "  [b]She only just left. She can’t be at the airport already.[/b]\n\n"
        "✅ [b]Must have (done)[/b] — o‘tmishdagi ishonch (biror narsa o‘tmishda sodir bo‘lganiga ishonch)\n"
        "Biz [b]must have (done)[/b] dan o‘tmishda biror narsa sodir bo‘lganligiga ishonchimiz komil bo‘lganida foydalanamiz:\n\n"
        "• Yo‘l ho‘l. Kecha kechqurun yomg‘ir yog‘gan bo‘lishi kerak. 🌧️\n"
        "  [b]The road is wet. It must have rained last night.[/b]\n\n"
        "• U eng yuqori ballni oldi. U juda ko‘p o‘qigan bo‘lishi kerak. 💯\n"
        "  [b]He got the top score. He must have studied very hard.[/b]\n\n"
        "• U holdan toygan ko‘rinadi. U butun tun ishlagan bo‘lishi kerak. 😴\n"
        "  [b]She looks exhausted. She must have been working all night.[/b]\n\n"
        "✅ [b]Can't have (done)[/b] — o‘tmishdagi imkonsizlik (biror narsa o‘tmishda sodir bo‘lmaganiga ishonch)\n"
        "Biz [b]can't have (done)[/b] dan o‘tmishda biror narsa sodir bo‘lmaganligiga ishonchimiz komil bo‘lganida foydalanamiz:\n\n"
        "• Posilka bugun yetib keldi. U yo‘qolgan bo‘lishi mumkin emas. 📦\n"
        "  [b]The package arrived today. It can’t have been lost.[/b]\n\n"
        "• U uchrashuvda emas edi. U bu haqda bilgan bo‘lishi mumkin emas. 🤷‍♂️\n"
        "  [b]He wasn’t at the meeting. He can’t have known about it.[/b]\n\n"
        "• Ular bir soat oldin ketishdi. Ular hali shaharga yetib borgan bo‘lishlari mumkin emas. 🏙️\n"
        "  [b]They left an hour ago. They can’t have reached the city yet.[/b]\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=NI_wuZLkmB0]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 106,
    "title": "May / Might have done",
    "content": "Assalomu alaykum! 👋 Bugungi darsimizda biz [b]may have (done)[/b] va [b]might have (done)[/b] iboralarini o‘rganamiz. Bu tuzilmalar o‘tmishda sodir bo‘lgan voqealar haqida [b]noaniqlik[/b] yoki [b]taxmin[/b] bildirish uchun ishlatiladi.\n\n"
        "✅ [b]May have (done)[/b] va [b]Might have (done)[/b]\n"
        "Biz bu iboralarni biror narsa o‘tmishda sodir bo‘lgan bo‘lishi mumkinligini aytish uchun ishlatamiz. [b]May[/b] va [b]might[/b] bu ma’noda juda o‘xshashdir.\n\n"
        "Misol vaziyat: Men tushunmayapman, Feruza nega telefonga javob bermadi. 🤔\n"
        "Bu nima degani? Bu [b]Ehtimol u uxlayotgan bo'lgan[/b] degani.\n"
        "Ingliz tilida: [b]I wonder why Feruza didn’t answer the phone. She may have been asleep.[/b]\n\n"
        "• Men sumkamni hech qayerdan topolmayapman. 👜\n"
        "  [b]I can’t find my bag anywhere.[/b]\n"
        "  Siz uni do'konda qoldirgan bo'lishingiz mumkin. (Ehtimol do‘konda qoldirgansiz)\n"
        "  [b]You might have left it in the shop.[/b]\n\n"
        "• Nega Anvar kecha kayfiyati yomon edi, hayronman. 🙁\n"
        "  [b]I wonder why Anvar was in such a bad mood yesterday.[/b]\n"
        "  U o‘zini yaxshi his qilmagan bo‘lishi mumkin. (Ehtimol o‘zini yaxshi his qilmagan)\n"
        "  [b]He may not have been feeling well.[/b]\n\n"
        "✅ Yana bir misol:\n"
        "• Men hayronman, nima uchun Dilshod kecha uchrashuvda yo‘q edi. 🤷‍♀️\n"
        "  [b]I was surprised that Dilshod wasn't at the meeting yesterday.[/b]\n"
        "  U bu haqda bilmagan bo‘lishi mumkin. (Ehtimol bilmagan)\n"
        "  [b]She might not have known about it.[/b]\n\n"
        "✅ Qo'shimcha misollar:\n"
        "• A: Nima uchun Anna bu yerda emas? ❓\n"
        "  B: U uchrashuvni unutgan bo‘lishi mumkin. (Ehtimol unutgan)\n"
        "  [b]A: I wonder why Anna isn't here. B: She may have forgotten about the meeting.[/b]\n\n"
        "• A: Telefonim jiringlamayapti. 🔇\n"
        "  B: Siz uni jim rejimga qo‘ygan bo‘lishingiz mumkin. (Ehtimol jim rejimga qo‘ygansiz)\n"
        "  [b]A: My phone isn't ringing. B: You might have left it on silent.[/b]\n\n"
        "• Chiroqlar o‘chiq. Ular allaqachon uxlagani yotgan bo‘lishlari mumkin. 🛌\n"
        "  [b]The lights are off. They may have already gone to bed.[/b]\n\n"
        "• A: Nega u shunchalik g‘amgin ko‘rindi? 😔\n"
        "  B: U hali yaxshi xabarni eshitmagan bo‘lishi mumkin. (Ehtimol eshitmagan)\n"
        "  [b]A: Why did he look so sad? B: He might not have heard the good news yet.[/b]\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "Qo‘shimcha tushuncha uchun quyidagi videoni ko‘ring:\n"
        "1.[link=https://www.youtube.com/watch?v=q_EQ4WE3g5U]Birinchi qism[/link]\n"
        "2.[link=https://www.youtube.com/watch?v=FTz5KFJi51E]Ikkinchi qism[/link]"
  },
  {
    "lesson": 107,
    "title": "Mustn't, Needn't / Don't need to, and Needn't have done",
    "content": "Assalomu alaykum! 👋 Bugungi darsimizda biz [b]mustn't[/b], [b]needn't / don't need to[/b] va [b]needn't have done[/b] kabi modal fe'llarni o‘rganamiz. Bu fe'llar majburiyat yo‘qligi, taqiqlar yoki o‘tmishdagi keraksiz harakatlar haqida gapirish uchun ishlatiladi.\n\n"
        "✅ [b]Must not yoki qisqartirilgani mustn't[/b] — taqiq (Buni qilmang!)\n"
        "Bu biror narsa qilish mutlaqo taqiqlanganligini yoki zarur emasligini bildiradi. Siz buni qilmasligingiz kerak:\n\n"
        "• Siz o‘sha tugmachaga tegmasligingiz kerak. Bu xavfli. ⚠️\n"
        "  [b]You mustn’t touch that button. It’s dangerous.[/b]\n\n"
        "• Tashrif buyuruvchilar hayvonot bog‘idagi hayvonlarni ovqatlantirmasliklari kerak. 🦒\n"
        "  [b]Visitors must not feed the animals in the zoo.[/b]\n\n"
        "• Ketishdan oldin eshiklarni qulflashni unutmasligimiz kerak. 🔒\n"
        "  [b]We mustn’t forget to lock the doors before leaving.[/b]\n\n"
        "✅ [b]Needn't[/b] yoki [b]Don't need to[/b] — majburiyat yo‘qligi (Siz buni qilishingiz shart emas)\n"
        "Bu biror narsa qilish zarur emasligini bildiradi, ammo agar xohlasangiz qilishingiz mumkin:\n\n"
        "• Siz ovqat olib kelishingiz shart emas; bizda yetarlicha bor. 🍎\n"
        "  [b]You needn’t bring food; we have plenty.[/b]\n\n"
        "• Men ertaga ishlashim shart emas, chunki bayram. 🎉\n"
        "  [b]I don’t need to work tomorrow, it’s a holiday.[/b]\n\n"
        "• U imtihon haqida tashvishlanishi shart emas; u yaxshi tayyorlangan. 🧠\n"
        "  [b]She needn’t worry about the exam; she’s well-prepared.[/b]\n\n"
        "✅ [b]Needn't have (done)[/b] — o‘tmishdagi keraksiz harakat (Qildingiz, lekin keragi yo‘q edi)\n"
        "Bu o‘tmishda biror ish qilinganini, ammo keyinchalik bu keraksiz bo‘lib chiqqanini bildiradi. Harakat bajarilgan, lekin uning keragi yo‘q edi:\n\n"
        "Misol vaziyat: Men yomg'ir yog'adi deb o'yladim. Men soyabonni oldim. Lekin yomg'ir yog'madi, shuning uchun soyabonga ehtiyoj qolmadi. ☔\n"
        "Ingliz tilida: [b]I needn’t have brought the umbrella.[/b]\n\n"
        "• Men bunchalik ko‘p ovqat pishirishim shart emas edi; yarmi qolib ketdi. 🍲\n"
        "  [b]I needn’t have cooked so much food; half of it is left over.[/b]\n\n"
        "• Menga sovg‘a sotib olishingiz shart emas edi, lekin rahmat! 🎁\n"
        "  [b]You needn’t have bought me a present, but thank you![/b]\n\n"
        "• U shoshilishi shart emas edi; uchrashuv kechiktirildi. ⏱️\n"
        "  [b]He needn’t have hurried; the meeting was delayed.[/b]\n\n"
        "✅ [b]Didn't need to[/b] va [b]Needn't have done[/b] farqi:\n\n"
        "[b]Didn't need to:[/b] Bu biror ishni qilishga ehtiyoj bo'lmaganligi sababli, uni qilmaganligingizni bildiradi. (Kerak emasligini bilganingiz uchun qilmadingiz)\n"
        "• Menga sut sotib olishim shart emas edi, chunki bizda allaqachon bor edi. 🥛\n"
        "  [b]I didn’t need to buy milk, because we already had some.[/b] (Men sutsiz qaytib keldim)\n\n"
        "[b]Needn't have done:[/b] Bu biror ishni qildingiz, lekin keyinchalik uning keragi yo'qligini tushundingiz. (Qildingiz, ammo keraksiz bo'lib chiqdi)\n"
        "• Men sut sotib oldim, lekin uni sotib olishim shart emas edi, chunki bizda allaqachon bor ekan. 🛒\n"
        "  [b]I bought milk, but I needn’t have bought it because we already had some.[/b] (Men sut bilan qaytib keldim)\n\n"
  },
  {
    "lesson": 108,
    "title": "Should / Shouldn't (do) and Should / Shouldn't have (done)",
    "content": "Assalomu alaykum! 👋 Bugungi darsimizda biz [b]should[/b] va [b]shouldn't[/b] modal fe'llarini hamda ularning o‘tmish shakllari [b]should have done[/b] va [b]shouldn't have done[/b] iboralarini o‘rganamiz. Bu fe'llar maslahat berish, tavsiyalar bildirish va o‘tmishdagi afsuslanishlarni ifodalash uchun ishlatiladi.\n\n"
        "✅ [b]Should (do)[/b] — maslahat yoki tavsiya\n"
        "Biz [b]should[/b] dan biror narsa qilish yaxshi yoki to‘g‘ri ekanligini aytish uchun foydalanamiz. Bu odatda hozirgi yoki kelajakdagi harakatlarga tegishli:\n\n"
        "• Siz sog‘lig‘ingiz uchun ko‘proq sabzavot iste'mol qilishingiz kerak. 🥕\n"
        "  [b]You should eat more vegetables for your health.[/b]\n\n"
        "• Men bugun kechqurun ota-onamga qo‘ng‘iroq qilishim kerak. 📞\n"
        "  [b]I should call my parents tonight.[/b]\n\n"
        "• Ular soat 20:00 gacha yetib kelishlari kerak. ⏰\n"
        "  [b]They should arrive by 8 PM.[/b]\n\n"
        "✅ [b]Shouldn't (do)[/b] — qilmaslikning maslahat yoki tavsiyasi\n"
        "Bu biror narsa qilish yaxshi yoki to‘g‘ri emasligini bildiradi:\n\n"
        "• Siz juda ko‘p televizor ko‘rmasligingiz kerak. 📺\n"
        "  [b]You shouldn’t watch too much TV.[/b]\n\n"
        "• U sumkasini qarovsiz qoldirmasligi kerak. 🎒\n"
        "  [b]He shouldn’t leave his bag unattended.[/b]\n\n"
        "✅ [b]Should have (done)[/b] — o‘tmishdagi afsuslanish (qilinishi kerak edi, ammo qilinmadi)\n"
        "Bu o‘tmishda biror narsa qilinishi kerak bo‘lganini, ammo haqiqatda qilinmaganligini anglatadi. Ko‘pincha afsuslanishni bildiradi:\n\n"
        "• Men imtihonga qattiqroq o‘qishim kerak edi. (Ammo o‘qimadim va hozir afsusdaman) 😩\n"
        "  [b]I should have studied harder for the exam.[/b]\n\n"
        "• Ular o‘zgarish haqida bizga avvalroq aytishlari kerak edi. (Ammo aytishmadi) 📢\n"
        "  [b]They should have told us about the change earlier.[/b]\n\n"
        "• Siz palto kiyishingiz kerak edi; tashqarida sovuq. (Ammo kiymadingiz va hozir sovuq qotyapsiz) 🧥\n"
        "  [b]You should have worn a coat; it’s cold outside.[/b]\n\n"
        "✅ [b]Shouldn't have (done)[/b] — o‘tmishdagi afsuslanish (qilinmasligi kerak edi, ammo qilindi)\n"
        "Bu o‘tmishda biror narsa qilinmasligi kerak bo‘lganini, ammo haqiqatda qilinganligini anglatadi. Bu harakatning noto‘g‘ri yoki xato bo‘lganligini bildiradi:\n\n"
        "• Siz unga baqirmasligingiz kerak edi. (Baqirdingiz, bu xato edi) 😠\n"
        "  [b]You shouldn't have shouted at him.[/b]\n\n"
        "• Men bunchalik ko‘p kiyim sotib olmasligim kerak edi. (Sotib oldim, hozir afsusdaman) 👗\n"
        "  [b]I shouldn't have bought so many clothes.[/b]\n\n"
        "• Ular eshikni qulflamasdan qoldirmasliklari kerak edi. (Qoldirishdi, endi muammo bor) 🔑\n"
        "  [b]They shouldn't have left the door unlocked.[/b]\n\n"
  },
  {
    "lesson": 109,
    "title": "'Had better' va 'It's time ...'",
    "content": "Assalomu alaykum! 👋 [b]Lesson 110[/b] uchun qo'shimcha misollar va batafsilroq tushuntirish bilan yangilangan darslikni taqdim etaman. Sizga manzur bo'lishiga umid qilaman. 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Had better' Ishlatilishi (Using 'Had better')[/b]\n"
        "[b]'Had better'[/b] iborasi muayyan vaziyatda qilinishi kerak bo'lgan ish haqida [b]kuchli maslahat[/b] yoki [b]ogohlantirish[/b] berish uchun ishlatiladi. Agar bu ish qilinmasa, salbiy oqibatlar bo'lishi mumkinligini anglatadi.\n"
        "• Tuzilishi: [b]had better + fe'lning asosiy shakli[/b].\n"
        "• Inkor shakli: [b]had better not[/b].\n"
        "  • The car's tank is almost empty. We [b]had better stop[/b] for petrol soon. ⛽ – Mashina baki deyarli bo'sh. Yaqin orada benzin quyish uchun to'xtaganimiz ma'qul.\n"
        "  • You have a meeting in ten minutes. You [b]had better go[/b] now or you'll be late. ⏰ – O'n daqiqadan keyin yig'ilishingiz bor. Hozir ketganingiz ma'qul, aks holda kechikib qolasiz.\n"
        "  • I [b]had better study[/b] for the exam tomorrow. It's a difficult subject. 🧠 – Ertangi imtihon uchun o'qiganim ma'qul. Bu qiyin fan.\n"
        "  • We [b]had better not[/b] eat all the cake before the guests arrive. 🍰 – Mehmonlar kelishidan oldin tortning hammasini yeb qo'ymaganimiz ma'qul.\n\n"
        "✅ [b]'Had better' vs 'Should' (Taqqoslash) (Comparison)[/b]\n"
        "[b]'Had better'[/b] faqat [b]o'ziga xos, hozirgi vaziyat[/b] uchun ogohlantiruvchi ma'noda ishlatiladi. [b]'Should'[/b] esa [b]umumiy maslahat[/b] berish uchun ishlatiladi va unchalik kuchli emas.\n"
        "  • It's late. You [b]had better go[/b] now. (Aynan shu vaziyatga tegishli kuchli maslahat.) 🚪\n"
        "  • You [b]should go[/b] to bed earlier. (Bu umumiy maslahat.) 😴\n"
        "  • Your skin is getting red. You [b]had better put[/b] on some sunscreen. ☀️ – Teringiz qizarib ketyapti. Quyoshdan himoyalovchi krem surtganingiz ma'qul.\n"
        "  • You [b]should use[/b] sunscreen every day. (Bu umumiy sog'liq maslahati.)\n\n"
        "✅ [b]'It's time...' Ishlatilishi (Using 'It's time...')[/b]\n"
        "[b]It's time to go home[/b] kabi iboralar biror harakatni amalga oshirish vaqti kelganini bildiradi.\n"
        "  • [b]It's time to start[/b] the project. 🚀 – Loyihani boshlash vaqti keldi.\n"
        "  • [b]It's time for[/b] us [b]to make[/b] a decision. ⚖️ – Biz qaror qabul qilishimiz vaqti keldi.\n\n"
        "✅ [b]'It's time you did...' Ishlatilishi (Using 'It's time you did...')[/b]\n"
        "Bu ibora kimdir biror ishni [b]allaqachon qilgan bo'lishi kerak[/b]ligini tanqid yoki shikoyat ohangida aytish uchun ishlatiladi. Bu yerda [b]o'tgan zamon fe'li[/b] ishlatilsa-da, ma'no [b]hozirgi[/b] yoki [b]kelajakdagi[/b] harakatga tegishli.\n"
        "  • [b]It's time you found[/b] a job. 💼 – Aniq ish topish vaqti keldi. (Hozirgacha ish topmaganingizdan norozilik).\n"
        "  • [b]It's time they tidied[/b] their room. 🧹 – Ular xonalarini yig'ishtiradigan vaqt keldi. (Xonasi tartibsizligi haqida shikoyat).\n"
        "  • You've been trying to learn a language for years. [b]It's time you started[/b] taking it seriously. 🗣️ – Bir necha yildan beri til o'rganishga harakat qilyapsiz. Bunga jiddiy yondashish vaqti keldi.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=BdMZOoGRzxU]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 110,
    "title": "Would (do) and Would have (done)",
    "content": "Assalomu alaykum! 👋 Bugungi darsimizda biz [b]would[/b] modal fe'lini yana bir bor ko‘rib chiqamiz. Biz [b]would[/b] ning [b]if[/b] (agar) bilan birga kelgan shart gaplarida qanday ishlatilishini avvalroq o‘rgangan edik. Bugun esa [b]would[/b] ni [b]if[/b] so‘zisiz ishlatilganda ham uning shartli ma’nosi qanday saqlanib qolishini bilib olamiz.\n\n"
        "✅ [b]Would (do)[/b] — hayoliy vaziyatlar (odatda [b]if[/b] ma'nosi anglashiladi)\n"
        "Biz [b]would[/b] dan haqiqat bo‘lmagan yoki sodir bo‘lishi dargumon bo‘lgan vaziyatlar yoki harakatlarni tasavvur qilganimizda foydalanamiz. Garchi [b]if[/b] so‘zi ishlatilmasa ham, ko‘pincha uning ma'nosi saqlanib qoladi:\n\n"
        "• [b]I would love a cup of coffee right now.[/b] ☕\n"
        "  Men hozir bir chashka qahva ichishni juda xohlardim. (Agar imkoniyat bo‘lganida/taklif qilinganida)\n\n"
        "• [b]He wouldn't accept such a low offer.[/b] 💰\n"
        "  U bunday past taklifni qabul qilmasdi. (Agar unga berilganida)\n\n"
        "• [b]It would be nice to relax by the sea.[/b] 🌊\n"
        "  Dengiz bo‘yida dam olish yoqimli bo‘lardi. (Agar imkoniyatim bo‘lganida)\n\n"
        "✅ [b]Would have (done)[/b] — o‘tmishdagi hayoliy vaziyatlar (odatda [b]if[/b] ma'nosi anglashiladi)\n"
        "Bu iboradan o‘tmishda sodir bo‘lishi mumkin bo‘lgan, ammo haqiqatda sodir bo‘lmagan narsalarni tasavvur qilganimizda foydalanamiz. Bu yerda ham [b]if[/b] ning ma'nosi ko‘pincha yashirin bo‘ladi:\n\n"
        "• [b]I would have helped you, but I didn’t know you needed it.[/b] 🆘\n"
        "  Men sizga yordam bergan bo‘lardim, lekin sizga kerakligini bilmasdim. (Agar bilganimda edi)\n\n"
        "• [b]She would have passed the test, but she was sick on that day.[/b] 🤒\n"
        "  U imtihondan o‘tgan bo‘lardi, lekin o‘sha kuni kasal bo‘lib qoldi. (Agar kasal bo‘lmaganida edi)\n\n"
        "• [b]They wouldn’t have believed me.[/b] 🤷‍♂️\n"
        "  Ular menga ishonmagan bo‘lardilar. (Hatto aytganimda ham)\n\n"
        "✅ [b]Would[/b] — o‘tmishdagi odatlar yoki takrorlanadigan harakatlar\n"
        "Bu [b]used to[/b] ga o‘xshash tarzda, o‘tmishda muntazam sodir bo‘lgan harakatlarni tasvirlash uchun ishlatiladi:\n\n"
        "• [b]Every summer, we would go to the beach.[/b] 🏖️\n"
        "  Har yozda biz plyajga borardik.\n\n"
        "• [b]My grandmother would always bake cookies on Sundays.[/b] 🍪\n"
        "  Buvim yakshanba kunlari har doim pechenye pishirardi.\n\n"
        "• [b]When I was a child, I would read for hours before bed.[/b] 📖\n"
        "  Men bolaligimda uxlashdan oldin soatlab kitob o‘qirdim.\n\n"
        "✅ [b]Wouldn't[/b] — o‘tmishdagi rad etish\n"
        "Biz [b]wouldn't[/b] dan o‘tmishda kimdir biror narsani qilishdan bosh tortganini aytish uchun foydalanamiz:\n\n"
        "• [b]He wouldn’t listen to my advice.[/b] 🗣️\n"
        "  U mening maslahatimga quloq solmadi.\n\n"
        "• [b]The car wouldn’t start this morning.[/b] 🚗\n"
        "  Mashina bugun ertalab yurishni xohlamadi.\n\n"
