  },
  {
    "lesson": 111,
    "title": "'Don't have to' / 'Didn't have to'",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 111[/b] darsimizda [b]'have to'[/b] fe'lining inkor shakli bo'lgan [b]'don't have to'[/b] ni o'rganamiz. [b]30-dars[/b]da biz biror ishni qilish zarurligini ifodalash uchun [b]'have to'[/b] iborasini o'rgangan edik. Bugun esa uning teskarisi – biror ishni qilishning [b]zarurati yo'qligini[/b] qanday aytishni o'rganamiz. Shuni eslatib o'tish joizki, bu [b]'don't need to'[/b] iborasi bilan bir xil ma'noni anglatadi, uni oldingi darslarimizda o‘rgangan edik.\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Don't have to' Ishlatilishi (Using 'Don't have to')[/b]\n"
        "Bu ibora hozirgi yoki kelajakda biror ishni qilishning [b]zarurati yo'qligini[/b] bildiradi. U majburiyatni emas, balki ixtiyoriylikni ifodalaydi. Ya'ni, agar xohlasangiz qilasiz, xohlamasangiz yo'q.\n"
        "• Tuzilishi: [b]Subject + don't / doesn't + have to + fe'lning asosiy shakli[/b].\n"
        "  • I [b]don't have to go[/b] to work tomorrow. It's a holiday. 🎉 – Ertaga ishga borishim shart emas. Bayrami.\n"
        "  • She [b]doesn't have to cook[/b] dinner tonight. We're eating out. 🍝 – U bugun kechqurun ovqat pishirishi shart emas. Biz restoranda ovqatlanamiz.\n"
        "  • You [b]don't have to finish[/b] the project by Friday. The deadline is next week. 📆 – Loyihani juma kunigacha tugatishingiz shart emas. Muddat keyingi hafta.\n\n"
        "✅ [b]'Didn't have to' Ishlatilishi (Using 'Didn't have to')[/b]\n"
        "Bu ibora o'tmishda biror ishni qilishning [b]zarurati yo'qligini[/b] anglatadi. Bu ish qilinmagan bo'lishi yoki qilingan bo'lishi ham mumkin.\n"
        "• Tuzilishi: [b]Subject + didn't + have to + fe'lning asosiy shakli[/b].\n"
        "  • We [b]didn't have to buy[/b] any tickets, because the concert was free. 🎟️ – Hech qanday chipta sotib olishimiz shart emas edi, chunki konsert bepul edi.\n"
        "  • He [b]didn't have to wait[/b] for a long time. The bus came quickly. 🚌 – Uzoq kutishi shart emas edi. Avtobus tezda keldi.\n\n"
        "✅ [b]'Don't have to' va 'Mustn't' Taqqoslanishi (Comparison with 'Mustn't')[/b]\n"
        "Bu ikki ibora mutlaqo boshqa ma'nolarni anglatadi:\n"
        "  • [b]Don't have to[/b]: biror ishni qilish [b]shart emas[/b] ([i]it is not necessary[/i]). ✅\n"
        "  • [b]Mustn't[/b]: biror ishni qilish [b]taqiqlangan[/b] ([i]it is forbidden[/i]). ❌\n"
        "  • You [b]don't have to tell[/b] anyone my secret. (Aytishingiz shart emas, lekin aytsangiz ham muammo bo'lmasligi mumkin).\n"
        "  • You [b]mustn't tell[/b] anyone my secret. (Aytishingiz qat'iyan man etiladi. Aytsangiz, yomon oqibatlar bo'ladi).\n\n"
        "✅ [b]'Don't have to' va 'Don't need to' (Sinonimlar) (Synonyms)[/b]\n"
        "[b]'Don't have to'[/b] va [b]'don't need to'[/b] iboralari bir xil ma'noni beradi va ko'pincha bir-birining o'rnida ishlatiladi.\n"
        "  • You [b]don't have to hurry[/b]. We have plenty of time. ⏳\n"
        "  • You [b]don't need to hurry[/b]. We have plenty of time.\n\n"
  },
  {
    "lesson": 112,
    "title": "'Wish' fe'li: Qaniydi",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 112[/b] darsimizda ingliz tilidagi muhim fe'llardan biri bo'lgan [b]'wish'[/b] fe'lini o'rganamiz. Bu fe'l yordamida biz o'tmish, hozirgi yoki kelajakdagi vaziyatlardan afsuslanish, norozilik bildirish yoki istaklarni ifodalashimiz mumkin. Keling, buni batafsil ko'rib chiqamiz! 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'Wish' + Ot (Kimdirga Nimanidir Tilash)[/b]\n"
        "[b]'Wish'[/b] fe'li ko'pincha kimdirga biror yaxshi narsani tilash uchun ishlatiladi.\n"
        "  • I [b]wish you[/b] every success in the future. 🏆 – Sizga kelajakda har qanday muvaffaqiyatni tilayman.\n"
        "  • We [b]wish you[/b] a happy birthday! 🎂 – Tug'ilgan kuningiz muborak bo'lsin!\n"
        "  • I [b]wish you[/b] a pleasant stay. 🏨 – Sizga yoqimli qolishni tilayman.\n\n"
        "✅ [b]'Wish' + o'tgan zamon (Past Simple) (Hozirgi Vaziyatdan Afsuslanish)[/b]\n"
        "Hozirgi vaziyat boshqacha bo'lganida desak, [b]'wish'[/b] dan keyin [b]o'tgan oddiy zamon[/b] (Past Simple) ishlatamiz. Bu yerda fe'l o'tgan zamonda bo'lsa-da, ma'no [b]hozirgi paytga[/b] tegishli bo'ladi.\n"
        "  • I [b]wish I had[/b] more free time. 🕰️ – Qaniydi bo'sh vaqtim ko'proq bo'lganida. (Hozir bo'sh vaqtim kamligidan afsuslanish).\n"
        "  • I [b]wish he was[/b] taller. 🦒 – Qaniydi u uzunroq bo'lganida. (Hozir past bo'lganidan afsuslanish).\n"
        "  • I [b]wish they didn't have[/b] to work today. 😔 – Qaniydi ular bugun ishlashi kerak bo'lmaganida. (Hozir ishlashlari shartligidan afsuslanish).\n\n"
        "✅ [b]'Wish' + 'could' (Qobiliyatdan Afsuslanish)[/b]\n"
        "Agar hozirda biror ishni qilishga [b]qodir emasligimizdan[/b] afsuslansak, [b]'wish'[/b] dan keyin [b]'could'[/b] dan foydalanamiz.\n"
        "  • I [b]wish I could fly[/b]. 🦅 – Qaniydi ucha olganimda. (Hozir ucha olmasligimdan afsuslanish).\n"
        "  • I [b]wish she could speak[/b] more languages. 🗣️ – Qaniydi u ko'proq tillarda gapira olganida. (Hozir qodir emasligidan afsuslanish).\n\n"
        "✅ [b]'Wish' + o'tgan tugallangan zamon (Past Perfect) (O'tmishdagi Vaziyatdan Afsuslanish)[/b]\n"
        "O'tmishda sodir bo'lgan yoki sodir bo'lmagan biror ishdan [b]afsuslanganda[/b], [b]'wish'[/b] dan keyin [b]o'tgan tugallangan zamon[/b] (Past Perfect) ishlatiladi.\n"
        "  • I [b]wish I hadn't eaten[/b] so much cake. 🎂 – Qaniydi buncha ko'p tort yemagan bo'lganimda. (Yegan ishimdan afsuslanish).\n"
        "  • I [b]wish he had studied[/b] harder for the test. 📖 – Qaniydi u testga qattiqroq o'qiganida. (O'qimaganidan afsuslanish).\n"
        "  • I [b]wish we had gone[/b] to the party. It sounded fun. 🎉 – Qaniydi bazmga borganimizda. Qiziqarli bo'lgan ko'rinadi.\n\n"
        "✅ [b]'Wish' + 'would' (Shikoyatlar va Talablar) (Complaints/Desires)[/b]\n"
        "Kimningdir xatti-harakatidan yoki biror vaziyatdan [b]norozilik[/b] bildirganimizda, [b]'wish'[/b] dan keyin [b]'would'[/b] fe'lidan foydalanamiz. Bu odatda biroz g'ashlikni ifodalaydi.\n"
        "  • I [b]wish it would stop[/b] raining. 🌧️ – Qaniydi yomg'ir tinib qolsa. (Yomg'irdan norozilik).\n"
        "  • I [b]wish you wouldn't interrupt[/b] me all the time. 🗣️ – Qaniydi doim gapimni bo'lavermasang. (Boshqa odamdan norozilik).\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=4NFu5zznbss]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 113,
    "title": "Passive Voice 3: Majhul Nisbat 3",
    "content": "Assalomu alaykum! 👋 Bugungi darsimizda biz [b]Passive Voice[/b] ya'ni majhul nisbat mavzusining uchinchi qismini o‘rganamiz. Bu darsda passiv shaklning yanada murakkabroq qo‘llanilishini va ba’zi bir umumiy iboralarni ko‘rib chiqamiz.\n\n"
        "✅ [b]Ikki to'ldiruvchili fe'llarda passiv shakl (Passive with two objects)[/b]\n"
        "Ba'zi fe'llar, masalan, [b]give (bermoq), offer (taklif qilmoq), pay (to‘lamoq), send (yubormoq), show (ko‘rsatmoq), tell (aytmoq)[/b], ikkita to'ldiruvchiga ega bo‘lishi mumkin (masalan, kimga va nimani berish). Bunday fe'llarni passivga o‘zgartirganda, ikkala to'ldiruvchi ham gapning egasi bo‘lishi mumkin:\n\n"
        "• [b]Active:[/b] Someone gave the students a new project.\n"
        "  Kimdir talabalarga yangi loyiha berdi.\n"
        "  [b]Passive 1:[/b] The students were given a new project. 🧑‍🎓\n"
        "  Talabalarga yangi loyiha berildi. (Talabalar to'ldiruvchisi egaga aylandi)\n\n"
        "• [b]Passive 2:[/b] A new project was given to the students. 📝\n"
        "  Talabalarga yangi loyiha berildi. (Loyiha to'ldiruvchisi ega aylandi)\n\n"
        "• [b]Active:[/b] The company offered him a promotion.\n"
        "  Kompaniya unga lavozim taklif qildi.\n"
        "  [b]Passive 1:[/b] He was offered a promotion by the company. 💼\n"
        "  Unga kompaniya tomonidan lavozim taklif qilindi.\n\n"
        "• [b]Passive 2:[/b] A promotion was offered to him by the company. ✨\n"
        "  Unga kompaniya tomonidan lavozim taklif qilindi.\n\n"
        "✅ [b]“I don't like being done/seen/etc.” (Menga qilinishi/ko‘rinishi yoqmaydi)\n[/b]"
        "Biz [b]like, hate, remember[/b] kabi fe'llardan keyin biror narsaning bizga qilinishi yoki biz bilan sodir bo‘lishi haqida o‘z fikrimizni bildirish uchun [b]being + past participle[/b] (fe'lning 3-shakli) tuzilishidan foydalanamiz:\n\n"
        "• [b]She hates being told what to do.[/b] 🙅‍♀️\n"
        "  U nima qilish kerakligini aytishlarini yomon ko‘radi.\n\n"
        "• [b]I don't like being interrupted when I'm speaking.[/b] 🤫\n"
        "  Gapirayotganimda meni to‘xtatishlarini yoqtirmayman.\n\n"
        "• [b]He remembered being praised for his work.[/b] 👏\n"
        "  U o‘z ishi uchun maqtashganlarini esladi.\n\n"
        "✅ [b]“I was born...” (Men tug‘ilganman...)\n[/b]"
        "[b]Born[/b] fe'li har doim passiv shaklda ishlatiladi. Faqat shu fe'lning passiv shakli “tug‘ilmoq” ma'nosini beradi:\n\n"
        "• [b]I was born in Samarkand in 1995.[/b] 👶\n"
        "  Men 1995-yilda Samarqandda tug‘ilganman.\n\n"
        "• [b]Where were you born?[/b] 🗺️\n"
        "  Siz qayerda tug‘ilgansiz?\n\n"
        "• [b]How many babies are born each day in this city?[/b] 📊\n"
        "  Bu shaharda har kuni nechta chaqaloq tug‘iladi?\n\n"
        "✅ [b]“Get” fe'lining passivda ishlatilishi\n[/b]"
        "Norasmiy nutqda ba'zida [b]be[/b] fe'li o‘rniga [b]get[/b] fe'lidan passiv shaklda foydalanish mumkin, ayniqsa sub'ekt bilan biror narsa sodir bo‘lganda:\n\n"
        "• [b]My car got stolen last night.[/b] 🚔\n"
        "  Mening mashinam kecha kechqurun o‘g‘irlandi.\n\n"
        "• [b]He gets paid every Friday.[/b] 💸\n"
        "  Unga har juma kuni maosh to‘lanadi.\n\n"
        "• [b]She got lost in the big city.[/b] 🏙️\n"
        "  U katta shaharda adashib qoldi.\n\n"
        "✅ [b]“Get” bilan ishlatiladigan umumiy norasmiy iboralar:\n[/b]"
        "• [b]get married[/b] (turmushga chiqmoq/uylanmoq)\n"
        "• [b]get divorced[/b] (ajrashmoq)\n"
        "• [b]get dressed[/b] (kiyinmoq)\n"
        "• [b]get lost[/b] (adashmoq)\n"
        "• [b]get tired[/b] (charchamoq)\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=2c9OA1OP3Eg]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
