  {
    "lesson": 114,
    "title":
        "'It is said that...', 'He is said to...' va 'He is supposed to...'",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 114[/b] darsimizda ingliz tilida biror ma'lumotni kimdandir eshitganimizda yoki umumiy fikrni aytishda ishlatiladigan [b]'It is said that...'[/b], [b]'He is said to...'[/b] va [b]'He is supposed to...'[/b] iboralarini o'rganamiz. Bu iboralar biror yangilikni yoki taxminni boshqalarga yetkazish uchun qulay usul hisoblanadi. 😊\n\n"
        "[center][b]Grammatik tushuntirish[/b][/center]\n"
        "✅ [b]'It is said that...' va 'He is said to...' (Xabarlarni Yetkazish)[/b]\n"
        "Bu ikkala tuzilish ham odamlar biror narsa haqida nima deyishini yoki ishonishini ifodalash uchun ishlatiladi. Ular bir xil ma'noni anglatadi.\n"
        "• Tuzilishi 1: [b]It is + fe'lning o'tgan zamon sifatdoshi + that + jumla[/b].\n"
        "• Tuzilishi 2: [b]Ega + is/are/was/were + fe'lning o'tgan zamon sifatdoshi + to + fe'l[/b].\n"
        "Ushbu tuzilishda ko'pincha quyidagi fe'llar ishlatiladi: [b]said, alleged, believed, considered, expected, reported, thought, understood[/b].\n\n"
        "  • [b]Said[/b] (aytmoq)\n"
        "    • [b]It is said that[/b] the new park will open next month. 🏞️ – Yangi park kelasi oyda ochilar emish.\n"
        "    • The new park [b]is said to be[/b] a great addition to the city. – Yangi park shaharga katta hissa qo'shar emish.\n"
        "  • [b]Alleged[/b] (da'vo qilinmoqda, ayblanmoqda)\n"
        "    • [b]It is alleged that[/b] the CEO stole money from the company. 🕵️‍♂️ – Bosh direktor kompaniyadan pul o'g'irlaganligi da'vo qilinmoqda.\n"
        "    • The CEO [b]is alleged to have stolen[/b] money from the company.\n"
        "  • [b]Believed[/b] (ishonilmoqda)\n"
        "    • [b]It is believed that[/b] a new treatment for the disease has been found. 🔬 – Kasallikni davolash uchun yangi usul topilganiga ishonilmoqda.\n"
        "    • A new treatment [b]is believed to have been found[/b].\n"
        "  • [b]Considered[/b] (hisoblanmoqda)\n"
        "    • [b]It is considered that[/b] he is the best player in the team. ⚽ – U jamoada eng yaxshi o'yinchi deb hisoblanadi.\n"
        "    • He [b]is considered to be[/b] the best player in the team.\n"
        "  • [b]Expected[/b] (kutilmoqda)\n"
        "    • [b]It is expected that[/b] inflation will rise next year. 📈 – Kelgusi yilda inflyatsiya ko'tarilishi kutilmoqda.\n"
        "    • Inflation [b]is expected to rise[/b] next year.\n"
        "  • [b]Known[/b] (ma'lumki, bilamizki)\n"
        "    • [b]It is known that[/b] the company is facing financial problems. 💼 – Kompaniyaning moliyaviy muammolarga duch kelayotgani ma'lum.\n"
        "    • The company [b]is known to be[/b] facing financial problems.\n"
        "  • [b]Reported[/b] (xabar berilmoqda)\n"
        "    • [b]It is reported that[/b] the president will visit our city. 🏙️ – Prezident shahrimizga tashrif buyurishi haqida xabar berilmoqda.\n"
        "    • The president [b]is reported to be visiting[/b] our city.\n"
        "  • [b]Thought[/b] (o'ylashicha)\n"
        "    • [b]It is thought that[/b] the witness is lying. 🤥 – Guvoh yolg'on gapiryapti deb o'ylashyapti.\n"
        "    • The witness [b]is thought to be[/b] lying.\n"
        "  • [b]Understood[/b] (tushunishimizcha)\n"
        "    • [b]It is understood that[/b] the new law will be enforced soon. ⚖️ – Yangi qonun tez orada kuchga kirishi tushunilmoqda bu xabardan.\n"
        "    • The new law [b]is understood to be[/b] enforced soon.\n\n"
        "✅ [b]'Be supposed to' Ishlatilishi (Using 'Be supposed to')[/b]\n"
        "Bu iboraning bir necha ma'nosi bor.\n"
        "  1. [b]Rejalashtirilgan / Kutilgan[/b]\n"
        "    • You [b]are supposed to be[/b] here at 9 a.m. 🕗 – Siz bu yerda ertalab soat 9 da bo'lishingiz kerak.\n"
        "    • The train [b]is supposed to arrive[/b] in ten minutes. 🚂 – Poezd o'n daqiqada yetib kelishi kerak.\n\n"
        "  2. [b]Taqiqlangan / Ruxsat etilmagan[/b] (inkor shakli)\n"
        "    • You [b]are not supposed to take[/b] photos inside the museum. 📸 – Muzey ichida suratga olishga ruxsat etilmaydi.\n"
        "    • We [b]are not supposed to talk[/b] during the exam. 🤫 – Imtihon paytida gaplashishimizga ruxsat yo'q.\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=k2HxWaZ-qsw]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 115,
    "title": "Have something done (Causative Form)",
    "content": "Assalomu alaykum! 👋  Bugungi [b]Lesson 115[/b] darsimizda [b]\"Have something done\"[/b] tuzilmasini o‘rganamiz. Bu ibora siz biror ishni o‘zingiz qilmasdan, boshqa kishiga (odatda xizmat uchun) qildirganingizda ishlatiladi.\n\n"
        "✅ [b]Have something done[/b] — Birovga biror ishni qildirish (xizmat)\n"
        "Bu tuzilmadan biz biror ishni o‘zimiz qilmasdan, boshqa biror shaxsga (mutaxassisga yoki xizmat ko‘rsatuvchiga) qildirishni tashkil qilganimizda foydalanamiz. Bu siz xizmat uchun pul to‘lashingizni yoki uni tashkil qilganingizni bildiradi.\n\n"
        "[b]Shakli:[/b] [b]Subject + have + object + past participle (fe'lning 3-shakli)[/b]\n\n"
        "• [b]I had my hair cut yesterday.[/b]\n"
        "  Men kecha sochlarimni kestirdim. (Sochlarimni o‘zim kesmadim, sartaroshga kestirdim) 💇‍♀️\n\n"
        "• [b]She's going to have her car repaired next week.[/b]\n"
        "  U kelasi hafta mashinasini tuzattirmoqchi. (Mashinasini o‘zi tuzatmaydi, mexanikka tuzattiradi) 🚗\n\n"
        "• [b]We had our house painted last summer.[/b]\n"
        "  Biz o‘tgan yozda uyimizni bo‘yattirdik. (Uyni o‘zimiz bo‘yamadik, bo‘yoqchiga bo‘yattirdik) 🏠\n\n"
        "✅ [b]Get something done[/b] — Norasmiy variant\n"
        "[b]Get something done[/b] iborasi [b]have something done[/b] bilan bir xil ma’noni beradi, ammo u norasmiy nutqda ko‘proq ishlatiladi:\n\n"
        "• [b]I need to get my teeth checked.[/b]\n"
        "  Men tishlarimni tekshirtirishim kerak. 🦷\n\n"
        "• [b]Can you get the documents translated?[/b]\n"
        "  Hujjatlarni tarjima qildira olasizmi? 📝\n\n"
        "✅ [b]Have something done[/b] — Biror yomon narsaning sizga sodir bo‘lishi\n"
        "Bu iboraning boshqa bir ma’nosi ham bor. Bu, biror yomon narsa sizga sodir bo‘lganini, va uni boshqa kishi qilganini (ko‘pincha sizning xohishingizsiz) bildirish uchun ishlatiladi:\n\n"
        "• [b]He had his wallet stolen while on vacation.[/b]\n"
        "  U ta’tilda hamyonini o‘g‘irlatib yubordi. 👛\n\n"
        "• [b]She had her phone snatched from her hand.[/b]\n"
        "  Uning qo‘lidan telefonini tortib olishdi. 📱\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=UD2Sef7lpaQ]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 116,
    "title": "Reported Speech 1 (He said that...)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 116[/b] darsimizda biz [b]\"Reported Speech 1\"[/b] mavzusini, ya'ni [b]boshqa birovning gapini o‘z so‘zlarimiz bilan qanday yetkazishni[/b] o‘rganamiz. Bu ingliz tilida juda muhim ko‘nikmalardan biridir.\n\n"
        "✅ [b]Reported Speech (Ko‘chirma gap) nima?[/b]\n"
        "Reported speech (yoki Indirect speech – o'zlashtirma gap) – bu kimningdir aytgan gapini uning aynan so‘zlaridan foydalanmasdan, o‘z so‘zlarimiz bilan boshqa birovga yetkazishdir. Bu Direct speech (ko‘chirma gap – birovning aynan so‘zlarini tirnoq ichida berish) ga qarama-qarshidir.\n\n"
        "Misol:\n"
        "• [b]Direct Speech:[/b] “Men charchadim,” dedi u. 😴\n"
        "  [b]She said, “I am tired.”[/b]\n\n"
        "• [b]Reported Speech:[/b] U charchaganini aytdi. 🗣️\n"
        "  [b]She said (that) she was tired.[/b]\n\n"
        "✅ [b]Zamon o‘zgarishlari (Backshift)[/b]\n"
        "Reported speech ga o‘tkazilganda, odatda fe'l zamonlari bir bosqich orqaga siljiydi (agar asosiy gap o‘tgan zamonda bo‘lsa):\n\n"
        "• [b]Present Simple[/b] (hozirgi oddiy) → [b]Past Simple[/b] (o‘tgan oddiy)\n"
        "  [b]Direct:[/b] “Men bankda ishlayman.”\n"
        "  [b]Reported:[/b] U bankda ishlashini aytdi. 🏦\n"
        "  [b]He said (that) he worked in a bank.[/b]\n\n"
        "• [b]Present Continuous[/b] (hozirgi davomli) → [b]Past Continuous[/b] (o‘tgan davomli)\n"
        "  [b]Direct:[/b] “Biz kechki ovqat qilyapmiz.”\n"
        "  [b]Reported:[/b] Ular kechki ovqat qilayotganliklarini aytishdi. 🍲\n"
        "  [b]They said (that) they were having dinner.[/b]\n\n"
        "• [b]Present Perfect[/b] (hozirgi tugallangan) → [b]Past Perfect[/b] (o‘tgan tugallangan)\n"
        "  [b]Direct:[/b] “Men uy vazifamni tugatdim.”\n"
        "  [b]Reported:[/b] U uy vazifasini tugatganini aytdi. ✅\n"
        "  [b]He told me (that) he had finished his homework.[/b]\n\n"
        "• [b]Will[/b] → [b]Would[/b]\n"
        "  [b]Direct:[/b] “Men ertaga sizga qo‘ng‘iroq qilaman.”\n"
        "  [b]Reported:[/b] U ertasi kuni qo‘ng‘iroq qilishini aytdi. 📞\n"
        "  [b]She said (that) she would call me the next day.[/b]\n\n"
        "• [b]Can[/b] → [b]Could[/b]\n"
        "  [b]Direct:[/b] “Men suzishni bilaman.”\n"
        "  [b]Reported:[/b] U suza olishini aytdi. 🏊\n"
        "  [b]He said (that) he could swim.[/b]\n\n"
        "• [b]Am/is/are going to[/b] → [b]Was/were going to[/b]\n"
        "  [b]Direct:[/b] “Biz konsertga bormoqchimiz.”\n"
        "  [b]Reported:[/b] Ular konsertga bormoqchi ekanliklarini aytishdi. 🎶\n"
        "  [b]They said (that) they were going to go to the concert.[/b]\n\n"
        "• [b]Past Simple[/b] (o‘tgan oddiy) → [b]Past Perfect[/b] (o‘tgan tugallangan) yoki [b]Past Simple[/b] o‘zgarmasligi ham mumkin.\n"
        "  [b]Direct:[/b] “Men do‘konga bordim.”\n"
        "  [b]Reported:[/b] U do‘konga borganini aytdi. 🛒\n"
        "  [b]She said (that) she had gone to the store.[/b] (yoki [b]she went to the store[/b])\n\n"
        "✅ [b]Olmoshlar va joy/vaqt ifodalari o‘zgarishi[/b]\n"
        "Ko‘chirma gapda olmoshlar (I → he/she, we → they), shuningdek, vaqt va joy ifodalari ham o‘zgarishi mumkin:\n"
        "• [b]now[/b] (hozir) → [b]then[/b] (o‘shanda)\n"
        "• [b]here[/b] (bu yerda) → [b]there[/b] (o‘sha yerda)\n"
        "• [b]today[/b] (bugun) → [b]that day[/b] (o‘sha kuni)\n"
        "• [b]tomorrow[/b] (ertaga) → [b]the next day / the following day[/b] (ertasi kuni)\n    • [b]yesterday[/b] (kecha) → [b]the day before / the previous day[/b] (oldingi kuni)\n\n"
        "✅ [b]Tuzilma: Subject + reporting verb + (that) + reported clause[/b]\n"
        "• [b]Say[/b] (aytdi) fe'lidan keyin to‘g‘ridan-to‘g‘ri [b]that[/b] bilan gap keladi. [b]That[/b] ixtiyoriy.\n"
        "  [b]He said (that) he was busy.[/b] (U band ekanligini aytdi.)\n\n"
        "• [b]Tell[/b] (aytmoq) fe'lidan keyin har doim kimga aytilgani ([b]to'ldiruvchi[/b]) keladi, keyin [b]that[/b] bilan gap keladi.\n"
        "  [b]She told me (that) she was leaving.[/b] (U menga ketayotganini aytdi.)\n\n"
        "[center][b]🎥 Video darslik[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=YN-vKQYgmIk]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 117,
    "title": "Questions 2: Indirect Questions and Reported Questions",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 117[/b] darsimizda biz [b]\"Questions 2\"[/b] mavzusini, ya’ni [b]bilvosita savollar (Indirect Questions)[/b] va [b]ko‘chirma savollar (Reported Questions)[/b]ni o‘rganamiz. Bu gap tuzilmalari ingliz tilida muloyim tarzda savol berish yoki boshqa biror kishining savolini yetkazish uchun ishlatiladi.\n\n"
        "✅ [b]Bilvosita savollar (Indirect Questions)[/b]\n"
        "Bu savollar odatda [b]\"Do you know...?\"[/b], [b]\"Could you tell me...?\"[/b], [b]\"I wonder...?\"[/b] kabi iboralar bilan boshlanadi va ulardan keyin gapdagi to‘g‘ri so‘z tartibi ([b]Subject + Verb[/b] – ega + kesim) qo‘llaniladi. To‘g‘ridan-to‘g‘ri savollardagi [b]do/does/did[/b] yordamchi fe'llari ishlatilmaydi.\n\n"
        "• [b]To‘g‘ridan-to‘g‘ri:[/b] Soat nechchi?\n"
        "  [b]What time is it?[/b]\n"
        "  [b]Bilvosita:[/b] Soat nechchi ekanligini ayta olasizmi? ⏰\n"
        "  [b]Could you tell me what time it is?[/b]\n\n"
        "• [b]To‘g‘ridan-to‘g‘ri:[/b] U qayerda yashaydi?\n"
        "  [b]Where does he live?[/b]\n"
        "  [b]Bilvosita:[/b] U qayerda yashashini bilasizmi? 🏡\n"
        "  [b]Do you know where he lives?[/b]\n\n"
        "• [b]Ha/yo‘q savollar uchun:[/b] [b]if[/b] yoki [b]whether[/b] ishlatiladi.\n"
        "  [b]To‘g‘ridan-to‘g‘ri:[/b] Muzey ochiqmi?\n"
        "  [b]Is the museum open?[/b]\n"
        "  [b]Bilvosita:[/b] Muzey ochiqmi-yo‘qmi, ayta olasizmi? 🏛️\n"
        "  [b]Can you tell me if the museum is open?[/b]\n\n"
        "  [b]To‘g‘ridan-to‘g‘ri:[/b] Ular o‘yinni yutishdimi?\n"
        "  [b]Did they win the game?[/b]\n"
        "  [b]Bilvosita:[/b] Ular o‘yinni yutishganmi-yo‘qmi, hayronman. 🎮\n"
        "  [b]I wonder whether they won the game.[/b]\n\n"
        "✅ [b]Ko‘chirma savollar (Reported Questions)[/b]\n"
        "Ko‘chirma savollar ham bilvosita savollar kabi so‘z tartibiga amal qiladi (ya’ni, fe'l ega oldiga o‘tmaydi, [b]do/does/did[/b] ishlatilmaydi). Savol berish fe'li odatda [b]asked[/b] (so‘radi), [b]wanted to know[/b] (bilishni xohladi) yoki [b]wondered[/b] (hayron bo‘ldi) bo‘ladi. Zamon o‘zgarishlari (backshift) ham qo‘llaniladi, xuddi ko‘chirma gaplardagidek.\n\n"
        "• [b]To‘g‘ridan-to‘g‘ri:[/b] “Eng yaqin pochta bo‘limi qayerda?”\n"
        "  [b]“Where is the nearest post office?”[/b]\n"
        "  [b]Ko‘chirma:[/b] U mendan eng yaqin pochta bo‘limi qayerda ekanligini so‘radi. 📮\n"
        "  [b]He asked me where the nearest post office was.[/b]\n\n"
        "• [b]To‘g‘ridan-to‘g‘ri:[/b] “Ertaga bandmisiz?”\n"
        "  [b]“Are you busy tomorrow?”[/b]\n"
        "  [b]Ko‘chirma:[/b] U mendan ertasi kuni band ekanligimni so‘radi. 🗓️\n"
        "  [b]She asked me if I was busy the next day.[/b]\n\n"
        "• [b]To‘g‘ridan-to‘g‘ri:[/b] “Buning uchun qancha to‘ladingiz?”\n"
        "  [b]“How much did you pay for it?”[/b]\n"
        "  [b]Ko‘chirma:[/b] U menga buning uchun qancha to‘laganimni bilishni xohladi. 💰\n"
        "  [b]He wanted to know how much I had paid for it.[/b]\n\n"
        "• [b]To‘g‘ridan-to‘g‘ri:[/b] “Menga yordam bera olasizmi?”\n"
        "  [b]“Can you help me?”[/b]\n"
        "  [b]Ko‘chirma:[/b] U mendan unga yordam bera olishimni so‘radi. 🙏\n"
        "  [b]She asked me if I could help her.[/b]\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=6KljqC9707I]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 118,
    "title": "Auxiliary Verbs and 'I think so / I hope so' structures",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 118[/b] darsimizda biz [b]yordamchi fe'llarni (auxiliary verbs)[/b] va ularning [b]\"I think so / I hope so\"[/b] kabi tuzilmalarda qanday ishlatilishini o‘rganamiz. Yordamchi fe'llar ingliz tilida juda muhim rol o‘ynaydi, ular nafaqat zamonlarni hosil qilishda, balki qisqa javoblarda, savollarda va fikrlarni ifodalashda ham yordam beradi.\n\n"
        "✅ [b]Yordamchi fe'llar (Auxiliary verbs) nima?[/b]\n"
        "Yordamchi fe'llar (masalan, [b]be, have, do, can, will[/b] va boshqalar) asosiy fe'l bilan birga kelib, turli zamonlar, mayllar yoki nisbatlarni hosil qilishga yordam beradi. Ular gapdagi takrorlanishni oldini olishda ham juda qulaydir.\n\n"
        "• [b]“Have you finished your work?” “Yes, I have.”[/b]  – Siz ishni tugatdingizmi? Ha, tugatdim. ✅\n\n"
        "• [b]“Does she speak French?” “No, she doesn’t.”[/b] – U fransuzcha gapiradimi? Yo‘q, gapirmaydi. 🇫🇷\n\n"
        "• [b]“Can you swim?” “Yes, I can.”[/b] – Siz suza olasizmi? Ha, ola olaman. 🏊\n\n"
        "✅ [b]“So am I / Neither do I” — Rozilik va rozi emaslikni bildirish:[/b]\n"
        "• [b]So + yordamchi fe'l + ega[/b] — ijobiy gapga rozi bo‘lish uchun:\n"
        "  [b]“I’m feeling hungry.” “So am I.”[/b] – Men ochman. Men ham. 😋\n\n"
        "• [b]Neither + yordamchi fe'l + ega[/b] yoki [b]Nor + yordamchi fe'l + ega[/b] — inkor gapga rozi bo‘lish uchun:\n"
        "  [b]“I don't like horror movies.” “Neither do I.”[/b] – Men dahshatli filmlarni yoqtirmayman. Men ham. 👻\n\n"
        "• [b]“He works hard.” “So does she.”[/b] – U qattiq ishlaydi. U ham. 💪\n\n"
        "• [b]“They didn't come to the party.” “Neither did we.”[/b] – Ular ziyofatga kelishmadi. Biz ham. 👯‍♀️\n\n"
        "✅ [b]“I think so / I hope so / I guess so” va boshqalar:[/b]\n"
        "Bu iboralar uzun [b]that clause[/b] ni takrorlamasdan, qisqa javob berishda ishlatiladi.\n\n"
        "• [b]“Will it rain tomorrow?” “I hope so.”[/b] – Ertaga yomg‘ir yog‘adimi? Umid qilamanki. ☔\n\n"
        "• [b]“Is he coming to the meeting?” “I think so.”[/b] – U yig‘ilishga keladimi? Menimcha. 🤝\n\n"
        "• [b]“Did you enjoy the concert?” “I suppose so.”[/b] – Konsert sizga yoqdimi? Menimcha. 🎶\n\n"
        "• [b]“Is the new movie good?” “I don’t think so.”[/b] – Yangi film yaxshimi? Menimcha emas. 👎\n\n"
        "• [b]“Will she pass the exam?” “I hope not.”[/b] – U imtihondan o‘tadimi? Umid qilmayman. 📚\n\n"
        "✅ [b]Question Tags (do you? isn't it? etc.)[/b]\n"
        "Question tags gap oxiriga qo'shiladigan qisqa so'roqlar bo'lib, ular ma'lumotni tasdiqlash uchun ishlatiladi.\n\n"
        "• Ijobiy gapdan so'ng inkor question tag keladi:\n"
        "  [b]“It's a beautiful day, isn't it?”[/b] – Bugun chiroyli kun, shunday emasmi? ☀️\n"
        "  [b]“They have arrived, haven't they?”[/b] – Ular yetib kelishdi, shunday emasmi? 👋\n\n"
        "• Inkor gapdan so'ng ijobiy question tag keladi:\n"
        "  [b]“You don't like coffee, do you?”[/b] – Siz qahvani yoqtirmaysiz, shundaymi? ☕\n"
        "  [b]“He can't swim, can he?”[/b] – U suza olmaydi, shundaymi? 🏊\n\n"
        "• [b]'Yes' va 'No' ma'nolari[/b]: Inkor gapga javob berayotganda [b]yes[/b] va [b]no[/b] so'zlari o'zbekchadagi kabi emas, teskari ma'noda ishlatiladi.\n"
        "  [b]“You're not going out, are you?”[/b] – Siz tashqariga chiqmayapsiz, shundaymi? 🚪\n"
        "   • [b]Yes[/b]. ([i]Ha, chiqyapman[/i].)\n"
        "   • [b]No[/b]. ([i]Yo'q, chiqmayapman[/i].)\n\n"
  },
  {
    "lesson": 119,
    "title": "Verb + -ing or To + infinitive (Gerunds and Infinitives)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 119[/b] darsimizda biz ingliz tilidagi muhim grammatik mavzu – [b]fe'llardan keyin qachon -ing shakli (gerund) va qachon to + infinitive (fe'lning bosh shakli) ishlatilishini[/b] bir takrorlab va bilmaganlarimizni to'ldirib olamiz. Ingliz tilida ba'zi fe'llardan keyin har doim -ing shakli, ba'zilaridan keyin esa har doim to + infinitive keladi. Tanlov oldingi fe'lga yoki iboraga bog‘liq bo‘ladi.\n\n"
        "✅ [b]-ing shakli (Gerund) keladigan fe'llar:[/b]\n"
        "Quyidagi ba'zi fe'llardan keyin har doim fe'lning [b]-ing[/b] shakli ([b]gerund[/b]) keladi:\n"
        "[b]enjoy, mind, finish, suggest, avoid, risk, deny, imagine, consider[/b] va boshqalar.\n\n"
        "• I enjoy reading novels. 📚 – Men roman o‘qishni yoqtiraman.\n"
        "• Would you mind opening the window? 🚪 – Eshikni ochib yubora olmaysizmi?\n"
        "• She finished writing her essay. ✍️ – U inshosini yozib tugatdi.\n"
        "• He suggested going to the cinema. 🎬 – U kinoga borishni taklif qildi.\n\n"
        "✅ [b]To + infinitive keladigan fe'llar:[/b]\n"
        "Quyidagi ba'zi fe'llardan keyin esa [b]to + infinitive[/b] (fe'lning bosh shakli) keladi:\n"
        "[b]agree, decide, plan, hope, promise, refuse, manage, learn, pretend, seem[/b] va boshqalar.\n\n"
        "• They decided to buy a new car. 🚗 – Ular yangi mashina sotib olishga qaror qilishdi.\n"
        "• I plan to visit my grandparents next month. 👵👴 – Men kelasi oy buvim va bobomnikiga borishni rejalashtiraman.\n"
        "• He promised to help me with my project. ✅ – U loyihamda yordam berishga va'da berdi.\n"
        "• She seemed to be happy. 😊 – U baxtli ko‘rinardi.\n\n"
        "✅ [b]-ing shakli keladigan iboralar va predloglar:[/b]\n"
        "Ba'zi iboralar va barcha predloglardan keyin keladigan fe'llar har doim [b]-ing[/b] shaklida bo‘ladi:\n\n"
        "• [b]It's no use/no good:[/b] (Foydasi yo‘q, befoyda)\n"
        "  It’s no use crying over spilled milk. 🥛 – To‘kilgan sutga yig‘lashdan foyda yo‘q.\n\n"
        "• [b]look forward to:[/b] (Intizorlik bilan kutmoq)\n"
        "  I look forward to meeting you. 👋 – Siz bilan uchrashishni intizorlik bilan kutyapman.\n\n"
        "• [b]Predloglardan keyin:[/b] ([b]of, in, for, about, instead of, before, after[/b] va boshqalar)\n"
        "  I'm interested in learning new languages. 🗣️ – Men yangi tillarni o‘rganishga qiziqaman.\n\n"
        "  Before leaving, check all the doors. 🚪 – Chiqishdan oldin barcha eshiklarni tekshiring.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=JxYq0JpDk4c&t=4s]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 120,
    "title":
        "Verbs of Preference: Would like/love/hate/prefer (+to) and Would mind (+-ing)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 120[/b] darsimizda biz [b]\"would like / love / hate / prefer\"[/b] va [b]\"would mind\"[/b] kabi fe'llar bilan to'g'ri fe'l shakllarini ishlatishni o'rganamiz. Bu fe'llar odatda sizning xohish-istaklaringiz, afzalliklaringiz yoki yoqtirmasliklaringizni muloyim tarzda ifodalash uchun ishlatiladi.\n\n"
        "✅ [b]Would like / Would love / Would prefer / Would hate + To + infinitive[/b]\n"
        "Agar siz biror narsani qilishni xohlashingizni, nimani afzal ko‘rishingizni yoki nimadan nafratlanishingizni muloyim tarzda ifodalamoqchi bo‘lsangiz qo'llashingiz mumkin. Bu fe'llardan keyin [b]to + infinitive[/b] (fe'lning bosh shakli) keladi.\n\n"
        "• I would like to drink some tea. – Men biroz choy ichishni xohlardim. ☕\n"
        "• Would you like to join us for dinner? – Kechki ovqatga bizga qo‘shilishni xohlaysizmi? 🍽️\n\n"
        "• I would love to travel the world. – Men butun dunyo bo‘ylab sayohat qilishni juda xohlardim. ✈️\n"
        "• We would love to see your new house. – Biz sizning yangi uyingizni ko‘rishni juda xohlardik. 🏡\n\n"
        "• I would prefer to stay at home tonight. – Men bugun kechqurun uyda qolishni afzal ko‘rardim. 🏠\n"
        "• She would prefer to study alone. – U yolg‘iz o‘qishni afzal ko‘radi. 📖\n\n"
        "• I would hate to miss the concert. – Men konsertni o‘tkazib yuborishni yomon ko‘rardim. 🎶\n"
        "• He would hate to disappoint his parents. – U ota-onasini xafa qilishni yomon ko‘radi. 😔\n\n"
        "✅ [b]Would mind + -ing (Gerund)[/b]\n"
        "[b]Would mind[/b] iborasi (ko‘pincha savollarda muloyim tarzda biror kishidan biror ishni bajarishni so‘rash yoki unga e’tirozi bormi-yo‘qligini bilish uchun ishlatiladi) har doim [b]fe'lning -ing shakli[/b] bilan birga keladi.\n\n"
        "• Would you mind closing the door? – Eshikni yopib yubora olmaysizmi? 🚪\n"
        "• I wouldn’t mind helping you with that. – Bu borada sizga yordam berishga qarshi emasman. ✅\n"
        "• Do you mind me asking a personal question? – Shaxsiy savol berishimga qarshimisiz? 🤔\n\n"
  },
  {
    "lesson": 121,
    "title": "Prefer and Would Rather",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 121[/b] darsimizda biz [b]\"Prefer\" (afzal ko'rmoq)[/b] va [b]\"Would rather\" (afzal ko'rmoq, yaxshiroq bo'lardi)[/b] iboralarini ishlatishni o'rganamiz. Bu ikkala ibora ham tanlovlar yoki afzalliklarni ifodalash uchun ishlatiladi, ammo ularning tuzilishi va qo‘llanilishida farqlar mavjud.\n\n"
        "✅ [b]Prefer (Umumiy afzalliklar)[/b]\n"
        "[b]Prefer[/b] odatda umumiy afzalliklarni ifodalash uchun ishlatiladi. Undan keyin [b]-ing[/b] shakli yoki [b]to + infinitive[/b] kelishi mumkin.\n\n"
        "• [b]Prefer + -ing (something to something else):[/b]\n"
        "  I prefer [b]playing[/b] with children. 🚶‍♀️ - Men bolalar bilan o'ynashni afzal ko'raman."
        "  I prefer [b]reading[/b] to [b]watching[/b] TV. 📖 – Men televizor ko‘rishdan ko‘ra kitob o‘qishni afzal ko‘raman.\n"
        "  I prefer [b]walking[/b] to [b]driving[/b]. 🚶‍♀️ – Men mashina haydashdan ko‘ra yurishni afzal ko‘raman.\n"
        "  They prefer [b]eating[/b] at home to [b]going[/b] to a restaurant. 🏠 – Ular restoranga borishdan ko'ra uyda ovqatlanishni afzal ko'rishadi.\n\n"
        "• [b]Prefer + to + infinitive (something to something else):[/b]\n"
        "  She prefers [b]to[/b] study in the library. 📚 – U kutubxonada o‘qishni afzal ko‘radi.\n"
        "  He prefers [b]to[/b] work alone. 🧑‍💻 – U yolg'iz ishlashni afzal ko'radi.\n"
        "  We prefer [b]to[/b] go to the cinema. 🎬 – Biz kinoga borishni afzal ko'ramiz.\n\n"
        "• [b]Prefer + noun + to + noun:[/b]\n"
        "  I prefer hot chocolate [b]to[/b] coffee. ☕ – Men kofega [b]nisbatan[/b] issiq shokoladni afzal ko‘raman.\n"
        "  They prefer summer [b]to[/b] winter. 🌞 – Ular qishga [b]nisbatan[/b] yozni afzal ko'rishadi.\n"
        "  He prefers rock music [b]to[/b] pop music. 🎸 – U pop musiqaga [b]nisbatan[/b] rok musiqasini afzal ko'radi.\n\n"
        "• [b]Agar Prefer dan keyin to + Verb ishlatsangiz Prefer + to do something + rather than (do) something else:[/b]\n"
        "  He [b]prefers to[/b] walk [b]rather than[/b] drive. 🚶‍♂️ – U mashina haydashdan [b]ko‘ra[/b] yurishni afzal ko‘radi.\n"
        "  I [b]prefer to[/b] stay home [b]rather than[/b] go out. 🏡 – Men tashqariga chiqishdan [b]ko'ra[/b] uyda qolishni afzal ko'raman.\n"
        "  She [b]prefers to[/b] read [b]rather than[/b] watch TV. 📺 – U televizor ko'rishdan [b]ko'ra[/b] kitob o'qishni afzal ko'radi.\n\n"
        "✅ [b]Would prefer (Aniq vaziyatdagi afzalliklar)[/b]\n"
        "[b]Would prefer[/b] ma'lum bir vaziyatdagi aniq afzalliklarni ifodalash uchun ishlatiladi va undan keyin [b]to + infinitive[/b] keladi.\n\n"
        "• I’d prefer [b]to[/b] eat out tonight. 🍽️ – Men bugun kechqurun tashqarida ovqatlanishni afzal ko‘rardim.\n"
        "• Would you prefer [b]to[/b] sit here or by the window? 🪑 – Bu yerda o‘tirishni yoki deraza yonida o‘tirishni afzal ko‘rasizmi?\n"
        "• She’d prefer [b]to[/b] call them rather than send an email. 📧 – U elektron pochta yuborishdan ko‘ra ularga qo‘ng‘iroq qilishni afzal ko‘radi.\n\n"
        "✅ [b]Would rather (Aniq vaziyatdagi afzalliklar)[/b]\n"
        "[b]Would rather[/b] ham ma'lum bir vaziyatdagi aniq afzalliklarni ifodalash uchun ishlatiladi. Undan keyin [b]to[/b]siz fe'lning bosh shakli ([b]infinitive without to[/b]) keladi.\n\n"
        "• I’d [b]rather go[/b] to the beach tomorrow. 🏖️ – Men ertaga plyajga borganim ma'qul.\n"
        "• Would you [b]rather have[/b] pizza or pasta? 🍕🍝 – Siz pitsani afzal ko‘rasizmi yoki pastani?\n"
        "• I’d [b]rather stay[/b] home than go to the party. 🏡 – Men ziyofatga borishdan ko‘ra uyda qolganim ma'qul.\n\n"
        "✅ [b]Would rather + subject + past simple (Boshqalarning harakatlari haqida xohishlar)[/b]\n"
        "Agar siz boshqa biror kishining biror ishni bajarishini afzal ko‘rsangiz, [b]would rather[/b] dan keyin [b]ega[/b] va [b]o‘tgan oddiy zamon (past simple)[/b] ishlatiladi. Bu o‘tgan zamon hozirgi yoki kelasi zamonni anglatadi.\n\n"
        "• [b]I’d rather[/b] you [b]didn’t tell[/b] him about this. 🤫 – Menga desa unga bu haqda aytmasangiz yaxshi bo‘lardi.\n"
        "• [b]She’d rather[/b] he [b]cooked[/b] dinner tonight. 🍳 – U bugun kechqurun u ovqat pishirsa yaxshi bo‘lardi.\n"
        "• [b]We’d rather[/b] they [b]arrived[/b] a bit later. ⏰ – Biz ularning biroz kechroq kelishlarini afzal ko‘rardik.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=8ULeBXTkw3I]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 122,
    "title": "'Be/get used to something' (Biror narsaga ko'nikish)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 122[/b] darsimizda [b]'be/get used to something'[/b] (biror narsaga ko'nikish) iborasini o'rganamiz. Bu iboralar odatda o'zingiz uchun yangi yoki g'alati bo'lgan narsaga vaqt o'tishi bilan ko'nikib ketganingizni ifodalash uchun ishlatiladi. Keling, bu farqlarni ko'rib chiqamiz! 😊\n\n"
        "✅ [b]I'm used to something/doing something (Holat)[/b]\n"
        "Bu tuzilish biror narsa siz uchun g'alati yoki yangi emasligini, odatiy holga aylanganini bildiradi. Undan keyin [b]ot[/b] yoki [b]gerund[/b] ([i]fe'l+ing[/i]) keladi.\n\n"
        "• I'm used to waking up early. ⏰ – Men erta turishga ko'nikkanman.\n"
        "• She's used to the cold weather now. ❄️ – U hozir sovuq havoga ko'nikkan.\n"
        "• They are used to living in a big city. 🏙️ – Ular katta shaharda yashashga ko'nikkanlar.\n\n"
        "✅ [b]Get used to doing something (Jarayon)[/b]\n"
        "[b]Get used to[/b] esa ko'nikish jarayonini, ya'ni biror narsaga ko'nikishni boshlaganingizni anglatadi.\n\n"
        "• It was strange at first, but I'm getting used to it. 😅 – Avvaliga g'alati edi, lekin men unga ko'nikib boryapman.\n"
        "• You'll get used to driving on the left. 🚗 – Siz chap tomonda haydashga ko'nikib ketasiz.\n"
        "• My new boss is strict, but I'll get used to her. 👩‍💼 – Yangi boshlig'im qattiqqo'l, lekin men unga ko'nikib ketaman.\n\n"
        "✅ [b]'Used to do' bilan solishtirish[/b]\n"
        "Bu ikkala ibora ma'no jihatidan butunlay boshqa narsani anglatadi. [b]Used to do[/b] o'tmishda muntazam qilingan, hozir esa qilinmaydigan ishni bildiradi. [b]Be used to doing[/b] esa hozir odatiy holga aylanganini bildiradi.\n\n"
        "• I used to live in a small town. 🏡 – Men ilgari kichik shaharchada yashardim. ([i]Hozir yashamayman[/i]).\n"
        "• I'm used to living in a big city. 🌃 – Men katta shaharda yashashga ko'nikkanman. ([i]Hozir g'alati emas[/i]).\n"
        "• We used to have long hair. 💇‍♀️ – Bizning ilgari sochlarimiz uzun bo'lardi. ([i]Hozir qisqa[/i]).\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=MEhu76S0EbA]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 123,
    "title": "Verb + Preposition + -ing (Fe'l + predlog + -ing)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 123[/b] darsimizda biz ingliz tilida [b]fe'l, predlog va -ing shakli[/b] ([b]Verb + Preposition + -ing[/b]) birgalikda ishlatilishini o‘rganamiz. Ingliz tilida ba'zi fe'llardan keyin ma'lum bir predlog keladi va agar bu predlogdan keyin yana bir fe'l kelishi kerak bo‘lsa, u doimo [b]-ing[/b] shaklida ([b]gerund[/b]) bo‘lishi shart.\n\n"
        "✅ [b]Fe'l + predlog + -ing (ob'ekt)[/b]\n"
        "Bu tuzilmada fe'ldan keyin ma'lum bir predlog keladi, so'ngra fe'lning [b]-ing[/b] shakli (yoki ot/olmosh) keladi. Bu holatda [b]-ing[/b] shakli predlogning ob'ekti vazifasini bajaradi.\n\n"
        "• [b]succeed in (muvaffaqiyatga erishmoq):[/b]\n"
        "  He succeeded in finding a new job. 💼 – U yangi ish topishda muvaffaqiyatga erishdi.\n"
        "  We succeeded in solving the problem. 💡 – Biz muammoni hal qilishda muvaffaqiyatga erishdik.\n\n"
        "• [b]insist on (turib olmoq):[/b]\n"
        "  She insisted on paying for the meal. 💸 – U ovqat uchun pul to‘layman deb turib oldi.\n"
        "  He insisted on going out despite the rain. ☔ – U yomg'irga qaramay, tashqariga chiqaman deb turib oldi.\n\n"
        "• [b]think of/about (o‘ylamoq):[/b]\n"
        "  I’m thinking of buying a house. 🏡 – Men uy sotib olish haqida o‘ylayapman.\n"
        "  Have you thought about changing your career? 👩‍⚕️ – Siz kasbingizni o'zgartirish haqida o'ylab ko'rdingizmi?\n\n"
        "• [b]decide against (qarshi qaror qilmoq):[/b]\n"
        "  They decided against going out tonight. 🌃 – Ular bugun kechqurun tashqariga chiqmaslikka qaror qilishdi.\n"
        "  We decided against painting the room yellow. 🎨 – Biz xonani sariq rangga bo'yashga qarshi qaror qildik.\n\n"
        "• [b]feel like (xohlash):[/b]\n"
        "  I feel like having some ice cream. 🍦 – Men biroz muzqaymoq yeyishni xohlayapman.\n"
        "  Do you feel like going for a walk? 🚶‍♂️ – Sayrga borishni xohlaysizmi?\n\n"
        "• [b]look forward to (intizorlik bilan kutmoq):[/b]\n"
        "  I’m looking forward to meeting you. 👋 – Men siz bilan uchrashishni intizorlik bilan kutyapman.\n"
        "  She looks forward to starting her new job. 🥳 – U yangi ishini boshlashni intizorlik bilan kutyapti.\n\n"
        "✅ [b]Fe'l + ob'ekt + predlog + -ing (ob'ekt)[/b]\n"
        "Ba'zi fe'llar esa predlogdan oldin to'g'ridan-to'g'ri ob'ektni talab qiladi, keyin esa predlog va fe'lning [b]-ing[/b] shakli keladi.\n\n"
        "• [b]congratulate (somebody) on (tabriklamoq):[/b]\n"
        "  We congratulated her on getting a promotion. 🎉 – Biz uni lavozimga ko‘tarilgani bilan tabrikladik.\n"
        "  I congratulated him on passing his exams. 🎓 – Men uni imtihonlaridan o'tganligi bilan tabrikladim.\n\n"
        "• [b]accuse (somebody) of (ayblamoq):[/b]\n"
        "  They accused him of stealing the money. 💰 – Ular uni pul o‘g‘irlashda ayblashdi.\n"
        "  He was accused of lying to the police. 🚨 – U politsiyaga yolg'on gapirishda ayblandi.\n\n"
        "• [b]suspect (somebody) of (shubhalanmoq):[/b]\n"
        "  The police suspected her of being a spy. 🕵️‍♀️ – Politsiya uni josuslikda gumon qildi.\n"
        "  I suspect him of taking my keys. 🔑 – Men uni kalitlarimni olganlikda gumon qilaman.\n\n"
        "• [b]prevent (somebody) from (to‘smoq):[/b]\n"
        "  His injury prevented him from playing in the match. 🤕 – Uning jarohati uni o‘yinda qatnashishiga to‘sqinlik qildi.\n"
        "  The bad weather prevented us from going on a picnic. 🧺 – Yomon ob-havo bizni sayrga chiqishimizga to'sqinlik qildi.\n\n"
        "• [b]stop (somebody) from (to‘xtatmoq):[/b]\n"
        "  Nothing could stop her from leaving. 🏃‍♀️ – Uni ketishdan hech narsa to‘xtata olmadi.\n"
        "  They stopped me from getting on the bus. 🚌 – Ular meni avtobusga chiqishdan to'xtatishdi.\n\n"
        "• [b]thank (somebody) for (minnatdorchilik bildirmoq):[/b]\n"
        "  Thank you for helping me. 🙏 – Yordamingiz uchun rahmat.\n"
        "  I want to thank you for inviting me to your party. 🎉 – Meni bazmingizga taklif qilganingiz uchun sizga minnatdorchilik bildirmoqchiman.\n\n"
        "• [b]excuse (somebody) for (kechirim so‘ramoq):[/b]\n"
        "  Excuse me for being late. 🙇‍♂️ – Kech qolganim uchun meni kechirasiz.\n"
        "  Please excuse him for not answering your call. 📞 – Iltimos, u qo'ng'irog'ingizga javob bermagani uchun uni kechiring.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=t-_LQjSiuRU]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 124,
    "title": "Expressions + -ing (Gerund)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 124[/b] darsimizda biz ingliz tilida ba'zi [b]iboralar va fe'lning -ing shakli[/b] ([b]Expressions + -ing[/b]) birgalikda ishlatilishini o‘rganamiz. Ingliz tilida ma'lum bir iboralar (expressions) doimo fe'lning [b]-ing[/b] shakli ([b]gerund[/b]) bilan birga keladi. Bular gapni yanada tabiiy va to‘g‘ri qilishga yordam beradi.\n\n"
        "✅ [b]It’s no use / It’s no good + -ing (Foydasi yo‘q, befoyda)[/b]\n"
        "Bu iboralar biror ishni qilishning ma'nosi yo‘qligini yoki undan hech qanday natija chiqmasligini bildiradi.\n\n"
        "• It’s no use complaining about the weather. ☁️ – Ob-havodan shikoyat qilishdan foyda yo‘q.\n"
        "• It’s no good arguing with him. 🗣️ – U bilan bahslashishdan foyda yo‘q.\n\n"
        "✅ [b]There’s no point in + -ing (Ma'nosi yo‘q)[/b]\n"
        "Bu ibora biror ishni bajarishga hech qanday sabab yoki foyda yo‘qligini anglatadi.\n\n"
        "• There’s no point in waiting for her, she won’t come. ⏳ – Uni kutishdan ma'no yo‘q, u kelmaydi.\n"
        "• What’s the point of buying a new phone if you don’t use its features? 📱 – Agar yangi telefonning funksiyalaridan foydalanmasangiz, uni sotib olishdan nima ma'no?\n\n"
        "✅ [b]It’s (not) worth + -ing (Arziydi / arzimaydi)[/b]\n"
        "Bu ibora biror narsaning qiymatini yoki biror harakatga sarflangan kuchga arziydimi-yo‘qligini bildiradi.\n\n"
        "• This book is worth reading. 📚 – Bu kitob o‘qishga arziydi.\n"
        "• It’s not worth arguing over such a small thing. 🤏 – Bunday kichik narsa tortishishga arzimaydi.\n\n"
        "✅ [b]Have difficulty / trouble + -ing (Qiyinchilik/muammo bo‘lmoq)[/b]\n"
        "Bu iboralar biror ishni bajarishda qiyinchiliklarga yoki muammolarga duch kelishni ifodalaydi.\n\n"
        "• I had difficulty understanding his accent. 🗣️ – Men uning talaffuzini tushunishda qiyinchilikka uchradim.\n"
        "• She has trouble remembering names. 🧠 – U ismlarni eslab qolishda qiynaladi.\n\n"
        "✅ [b]Waste of money / a waste of time + -ing (Pulni/vaqtni isrof qilish)[/b]\n"
        "Bu iboralar pul yoki vaqtni biror narsaga samarasiz sarflashni bildiradi.\n\n"
        "• It was a waste of time trying to fix the old computer. 💻 – Eski kompyuterni tuzatishga urinish vaqtni isrof qilish edi.\n"
        "• Buying that expensive jacket was a waste of money. 💰 – Bu qimmat ko‘ylagni sotib olish pulni isrof qilish edi.\n\n"
        "✅ [b]Spend / waste (time) + -ing (Vaqt sarflash / isrof qilish)[/b]\n"
        "[b]Spend[/b] va [b]waste[/b] fe'llari vaqtni qanday sarflanganini yoki isrof qilinganini ko‘rsatish uchun [b]-ing[/b] shakli bilan ishlatiladi.\n\n"
        "• I spent hours preparing for the presentation. ⏳ – Men taqdimotga tayyorgarlik ko‘rish uchun soatlab vaqt sarfladim.\n"
        "• He wastes a lot of time scrolling through social media. 📱 – U ijtimoiy tarmoqlarni varaqlash bilan ko‘p vaqtini isrof qiladi.\n\n"
        "✅ [b]Be busy + -ing (Band bo‘lmoq)[/b]\n"
        "Bu ibora biror faoliyat bilan band bo‘lishni anglatadi.\n\n"
        "• I’m busy cleaning the house. 🧹 – Men uyni tozalash bilan bandman.\n"
        "• They were busy discussing the new project. 🗣️ – Ular yangi loyihani muhokama qilish bilan band edilar.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=sq7g-KR28Yg]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 125,
    "title": "Maqsadni ifodalash: To ..., For ..., va So that ...",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 125[/b] darsimizda biz ingliz tilida maqsadni ifodalashning turli usullarini, xususan, [b]\"to...\"[/b], [b]\"for...\"[/b] va [b]\"so that...\"[/b] iboralari orqali qanday amalga oshirilishini o‘rganamiz. O'zbek tiliga ular '[b]uchun[/b]', '[b]...ga[/b]' deb tarjima qilinadi.\n\n"
        "✅ [b]To + infinitive (Harakatning maqsadini ifodalash uchun)[/b]\n"
        "Bu eng keng tarqalgan usul bo'lib, biror harakatning nima maqsadda bajarilganini bildiradi.\n\n"
        "• He went to the shop to buy some milk. 🥛 – U bir oz sut sotib olish uchun do‘konga bordi.\n"
        "• She studies hard to pass her exams. 📚 – U imtihonlarini topshirish uchun qattiq o‘qiydi.\n"
        "• We called him to invite him to the party. 📞 – Biz uni ziyofatga taklif qilish uchun qo‘ng‘iroq qildik.\n\n"
        "✅ [b]To + verb (Biror narsaning maqsadini ifodalash uchun)[/b]\n"
        "Bu tuzilma biror buyum yoki narsaning nima maqsadda mavjudligini bildiradi.\n\n"
        "• This button is to start the engine. ⚙️ – Bu tugma dvigatelni ishga tushirish uchun.\n"
        "• A knife is used to cut things. 🔪 – Pichoq narsalarni kesish uchun ishlatiladi.\n\n"
        "✅ [b]For + noun (Predmet yoki hodisa maqsadi uchun)[/b]\n"
        "Bu ibora maqsad ot bilan ifodalanganda ishlatiladi.\n\n"
        "• I went to Spain for a holiday. ✈️ – Men ta'tilga Ispaniyaga bordim.\n"
        "• We met for a discussion. 🗣️ – Biz muhokama uchun uchrashdik.\n\n"
        "✅ [b]For + -ing (Biror narsaning umumiy maqsadi uchun)[/b]\n"
        "Bu ibora biror buyumning umumiy funksiyasini yoki nima uchun ishlatilishini tavsiflash uchun ishlatiladi.\n\n"
        "• This brush is for cleaning shoes. 👟 – Bu cho‘tka poyabzallarni tozalash uchun.\n"
        "• What is this tool for? It’s for opening cans. 🥫 – Bu asbob nima uchun? Konservalarni ochish uchun.\n\n"
        "✅ [b]So that (Maqsadni ergash gap orqali ifodalash)[/b]\n"
        "[b]So that[/b] ko‘pincha ergash gap va modal fe'l ([b]can/could/will/would[/b]) bilan birga ishlatiladi.\n\n"
        "• I closed the window so that the noise wouldn’t come in. 🤫 – Shovqin kirmasligi uchun derazani yopdim.\n"
        "• She saved money so that she could buy a new laptop. 💻 – U yangi noutbuk sotib olishi uchun pul yig‘di.\n"
        "• He hurried so that he wouldn’t miss the bus. 🏃 – U avtobusdan qolib ketmasligi uchun shoshildi.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=vp48M6h0g9s]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 126,
    "title":
        "Fe'l va Sifatlar bilan 'to' yoki 'of/-ing' (Afraid, Interested, Sorry)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 126[/b] darsimizda biz ba'zi fe'llar va sifatlar bilan keladigan [b]\"to + infinitive\"[/b] yoki [b]\"predlog + -ing\"[/b] shakllarini o'rganamiz. Bu iboralar ingliz tilida his-tuyg'ularni, qiziqishlarni yoki afsuslanishni ifodalashda muhim ahamiyatga ega.\n\n"
        "✅ [b]Afraid to do vs. Afraid of -ing[/b]\n"
        "Bu ikkala ibora ham qo‘rquvni ifodalaydi, ammo ular orasida ma'no farqi bor:\n\n"
        "• [b]Afraid to do:[/b] Biror narsani qilishdan o‘zingizni tiyish, chunki bu xavfli bo‘lishi yoki yomon natija berishi mumkinligidan qo‘rqasiz. Bu ko‘proq [b]qasddan qilingan harakat[/b] bilan bog‘liq.\n"
        "  She’s afraid to walk home alone at night. 🚶‍♀️ – U kechasi uyga yolg‘iz borishdan qo‘rqadi.\n"
        "  He’s afraid to tell his parents about his bad grades. 🗣️ – U yomon baholari haqida ota-onasiga aytishdan qo‘rqadi.\n\n"
        "• [b]Afraid of -ing:[/b] Biror narsaning sodir bo‘lishidan yoki biror narsadan umumiy tarzda qo‘rqish. Bu ko‘proq [b]potensial natija[/b] yoki [b]umumiy qo‘rquv[/b] bilan bog‘liq.\n"
        "  I’m afraid of flying. ✈️ – Men uchishdan qo‘rqaman.\n"
        "  They are afraid of getting lost in the forest. 🌲 – Ular o‘rmonda adashib qolishdan qo‘rqishadi.\n\n"
        "✅ [b]Interested in -ing vs. Interested to do[/b]\n"
        "Bu ikkala ibora ham qiziqishni ifodalaydi:\n\n"
        "• [b]Interested in -ing:[/b] Biror narsani qilishga qiziqish, uni ko‘rib chiqish yoki rejalashtirish.\n"
        "  I’m interested in joining the new club. 🧩 – Men yangi klubga a'zo bo‘lishga qiziqaman.\n"
        "  Are you interested in learning a new language? 🗣️ – Yangi til o‘rganishga qiziqasizmi?\n\n"
        "• [b]Interested to do:[/b] Biror narsani bilishga yoki o‘rganishga qiziqish, qiziquvchanlik.\n"
        "  I was interested to hear about your travel plans. 🗺️ – Men sizning sayohat rejalaringizni eshitishga qiziqdim.\n"
        "  We are interested to know what his next step will be. 🤔 – Biz uning keyingi qadami nima bo‘lishini bilishga qiziqamiz.\n\n"
        "✅ [b]Sorry to do vs. Sorry for -ing[/b]\n"
        "Bu iboralar uzr so‘rash yoki afsuslanishni ifodalaydi:\n\n"
        "• [b]Sorry to do:[/b] Biror narsani hozirda qila turib (yoki hozirgina qilib bo‘lib) uzr so‘rash, odatda noqulaylik yoki yomon xabar yetkazishda ishlatiladi.\n"
        "  I’m sorry to disturb you, but I have a question. 🤷‍♀️ – Uzr, sizni bezovta qilganim uchun, lekin savolim bor edi.\n"
        "  I’m sorry to hear that you lost your job. 😔 – Ishingizni yo‘qotganingizni eshitganimdan afsusdaman.\n\n"
        "• [b]Sorry for -ing:[/b] Oldin qilingan harakat uchun uzr so‘rash.\n"
        "  I’m sorry for being late. ⏳ – Kech qolganim uchun uzr so‘rayman.\n"
        "  I am sorry for interrupting the meeting. 🗣️ – Yig‘ilishni bo‘lganim uchun uzr.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=cSDfcvkmZ9k]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 127,
    "title":
        "Sezgi fe'llari: See/Hear/Notice somebody do va See/Hear/Notice somebody doing",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 127[/b] darsimizda biz ingliz tilidagi sezgi fe'llari ([b]verbs of perception[/b]) — [b]\"see\" (ko‘rmoq), \"hear\" (eshitmoq), \"notice\" (payqamoq)[/b] kabilardan keyin keladigan fe'l shakllari ([b]infinitive without to[/b] yoki [b]-ing[/b] shakli) orasidagi farqni o‘rganamiz. Bu farq siz harakatni to‘liq kuzatdingizmi yoki uning bir qismini ko‘rdingizmi, shuni bildiradi.\n\n"
        "✅ [b]See / Hear / Notice + ob'ekt + fe'lning bosh shakli (to'siz infinitive)[/b]\n"
        "Bu tuzilma biror harakat yoki voqeaning [b]boshidan oxirigacha to‘liq sodir bo‘lganini[/b] ko‘rganingizni, eshitganingizni yoki payqaganingizni bildiradi. Ya'ni, siz butun jarayonni kuzatgansiz.\n\n"
        "• I saw her close the door. 🚪 – Men uning eshikni yopganini ko‘rdim. (Eshikni yopish jarayonini boshidan oxirigacha ko‘rdim.)\n"
        "• Did you see him drop his keys? 🔑 – Siz uning kalitlarini tushirib yuborganini ko‘rdingizmi?\n"
        "• I heard the children sing a whole song. 🎶 – Men bolalar butun bir qo‘shiqni aytganini eshitdim.\n\n"
        "✅ [b]See / Hear / Notice + ob'ekt + -ing (gerund)[/b]\n"
        "Bu tuzilma biror harakatning [b]jarayonida sodir bo‘layotganini[/b] yoki uning bir qismini ko‘rganingizni, eshitganingizni yoki payqaganingizni bildiradi. Ya'ni, siz harakatning biror vaqtini kuzatgansiz.\n\n"
        "• I saw her closing the door as I walked by. 🚪 – Men o‘tayotganimda uning eshikni yopayotganini ko‘rdim. (U eshikni yopish jarayonida edi.)\n"
        "• I saw him sitting on the bench, reading a book. 📖 – Men uni skameykada o‘tirganini va kitob o‘qiyotganini ko‘rdim.\n"
        "• I heard the children singing in the garden. 🎵 – Men bolalar bog‘da qo‘shiq aytayotganini eshitdim.\n\n"
        "✅ [b]Farqni qisqacha xulosa:[/b]\n"
        "• [b]Infinitive (to'siz):[/b] Harakatning [b]boshidan oxirigacha[/b] kuzatilgani.\n"
        "• [b]-ing shakli:[/b] Harakatning [b]jarayonida[/b] kuzatilgani, ya'ni bir qismi ko‘rilgan.\n\n"
        "✅ [b]Boshqa sezgi fe'llari:[/b]\n"
        "[b]Feel (sezmoq), watch (tomosha qilmoq), listen to (tinglamoq), smell (hidlamoq)[/b] kabi fe'llar ham xuddi shunday tuzilmalar bilan ishlatiladi:\n\n"
        "• I felt the ground shake. 🌍 – Men yer silkinishini his qildim. (Butun silkinishni his qildi)\n"
        "• I felt my heart beating fast. ❤️ – Men yuragim tez urayotganini his qildim. (Urayotgan jarayonni his qildi)\n"
        "• I noticed him leave the building. 🚶‍♂️ – Men uni binodan chiqib ketayotganini payqadim. (Chiqib ketish jarayonini to‘liq payqadi)\n"
        "• I noticed her talking on the phone. 📞 – Men uni telefonda gaplashayotganini payqadim. (Gaplashayotgan jarayonni payqadi)\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=WolB2i_mR8k]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 128,
    "title":
        "-ing Clauses (Fe'lning -ing shakli bilan boshlanuvchi gap bo‘laklari)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 128[/b] darsimizda biz ingliz tilida [b]-ing clauselarni (fe'lning -ing shakli bilan boshlanuvchi gap bo‘laklari)[/b] ishlatishni o‘rganamiz. Bu tuzilmalar ikki jumlani birlashtirish yoki harakatlar o‘rtasidagi bog‘liqlikni ifodalashning samarali usuli bo‘lib, ko‘pincha yozma nutqda aniqlik va qisqalikni ta'minlaydi.\n\n"
        "✅ [b]Sabab/Natijani ifodalash (because ma'nosida)[/b]\n"
        "Gapning boshida kelgan [b]-ing clause[/b] asosiy gapdagi harakatning sababini yoki natijasini ko‘rsatishi mumkin. Odatda undan keyin vergul qo‘yiladi.\n\n"
        "• Feeling unwell, she decided to stay home. 🤒 – O‘zini yomon his qilgani uchun u uyda qolishga qaror qildi.\n"
        "• Not knowing the answer, he remained silent. 🤫 – Javobni bilmagani uchun u jim qoldi.\n\n"
        "✅ [b]Ikkita harakatning bir vaqtda sodir bo‘lishi[/b]\n"
        "[b]-ing clause[/b] asosiy fe'l bilan bir vaqtda sodir bo‘ladigan harakatni tasvirlashi mumkin.\n\n"
        "• The dog ran around the garden, barking loudly. 🐶 – It baland ovozda hurib, bog‘da yugurdi.\n"
        "• She cooked dinner, listening to music. 🎧 – U musiqa tinglab, kechki ovqatni pishirdi.\n\n"
        "✅ [b]Bir harakat boshqa (uzoqroq) harakat davomida sodir bo‘lsa[/b]\n"
        "[b]-ing clause[/b] boshqa, ko‘pincha asosiy harakat davomida yuz beradigan jarayonni tasvirlaydi.\n\n"
        "• He broke his arm skiing down the mountain. ⛷️ – U tog‘dan chang‘i uchayotganda qo‘lini sindirdi.\n"
        "• She lost her wallet walking in the park. 🚶‍♀️ – U parkda yurayotganda hamyonini yo‘qotdi.\n\n"
        "✅ [b]Qisqa harakat boshqa harakatdan oldin (simple -ing form)[/b]\n"
        "Ba'zan, bir qisqa harakat boshqa harakatdan darhol oldin sodir bo‘lsa, oddiy [b]-ing[/b] shakli ishlatilishi mumkin.\n\n"
        "• Turning the corner, he saw the accident. 🚦 – Burchakka burilib, u avtohalokatni ko‘rdi.\n"
        "• Smiling, she accepted the gift. 😊 – Jilmayib, u sovg‘ani qabul qildi.\n\n"
        "✅ [b]Bir harakat boshqa harakatdan oldin sodir bo‘lsa boshqa struktura(Having + past participle)[/b]\n"
        "Agar bir harakat asosiy harakatdan oldin tugagan bo‘lsa, [b]Having + past participle[/b] (Perfect -ing clause) ishlatiladi.\n\n"
        "• Having prepared all the ingredients, she started baking the cake. 🎂 – Barcha masalliqlar tayyor bo‘lgach, u tort pishirishni boshladi.\n"
        "• Having seen that movie before, I decided to watch something else. 🎬 – O‘sha filmni avval ko‘rganligim sababli, men boshqa narsani tomosha qilishga qaror qildim.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=t9rQpZnarXQ]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 129,
    "title": "Noun + Noun (Ot + Ot birikmalari)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 129[/b] darsimizda biz ingliz tilidagi [b]Ot + Ot birikmalari (Noun + Noun)[/b] haqida gaplashamiz. Ingliz tilida ikkita otni yonma-yon qo‘yish orqali bitta g‘oya yoki narsani ifodalash juda keng tarqalgan. Bunda birinchi ot ikkinchi otni tavsiflovchi sifat vazifasini bajaradi.\n\n"
        "✅ [b]Umumiy qoida: Birinchi ot ikkinchisini tavsiflaydi[/b]\n"
        "Birinchi ot ikkinchi otning qanday turda ekanligini yoki nima uchun ishlatilishini bildiradi. U 'qanday?' yoki 'nima uchun?' degan savollarga javob beradi.\n\n"
        "• [b]tennis ball[/b] (tennis to‘pi) — tennis o‘ynash uchun to‘p\n"
        "• [b]coffee cup[/b] (kofe stakani) — kofe uchun mo‘ljallangan stakan\n"
        "• [b]school bag[/b] (maktab sumkasi) — maktab uchun sumka\n"
        "• [b]bus stop[/b] (avtobus bekati) — avtobus to‘xtaydigan bekat\n"
        "• [b]computer keyboard[/b] (kompyuter klaviaturasi) — kompyuterning klaviaturasi\n\n"
        "✅ [b]Maqsad/faoliyat uchun -ing bilan tugagan ot[/b]\n"
        "Ba'zida birinchi ot [b]-ing[/b] bilan tugaydi. Bu odatda ikkinchi otning nima uchun ishlatilishini yoki u bilan bog‘liq faoliyatni tasvirlaydi.\n\n"
        "• [b]reading light[/b] (o‘qish chirog‘i) — o‘qish uchun chiroq\n"
        "• [b]sleeping bag[/b] (uyqu xaltasi) — uxlash uchun mo‘ljallangan xalta\n"
        "• [b]walking shoes[/b] (yurish poyabzallari) — yurish uchun poyabzallar\n\n"
        "✅ [b]Bir so‘zmi yoki ikki so‘zmi?[/b]\n"
        "Ba'zi ot + ot birikmalari bir so‘z qilib yoziladi ([b]headache[/b], [b]sunflower[/b]), ba'zilari esa ikkita alohida so‘z qilib yoziladi ([b]car park[/b], [b]tea towel[/b]). Agar ishonchingiz komil bo‘lmasa, odatda ikki so‘z qilib yozish xato bo‘lmaydi.\n\n"
        "• [b]headache[/b] (bosh og‘rig‘i)\n"
        "• [b]sunflower[/b] (kungaboqar)\n"
        "• [b]tea towel[/b] (choy sochiq)\n\n"
        "✅ [b]Ma'nodagi farq (masalan, sugar bowl va bowl of sugar)[/b]\n"
        "Birikmalarning tuzilishi ma'noga ta'sir qilishi mumkin:\n\n"
        "• [b]Noun + Noun[/b] (birinchi ot ikkinchi otning [b]turi[/b] yoki [b]maqsadi[/b]ni bildiradi):\n"
        "  [b]glass door[/b] (shisha eshik) — shishadan yasalgan eshik turi\n"
        "  [b]fruit bowl[/b] (meva idishi) — meva solish uchun idish\n\n"
        "• [b]Noun + of + Noun[/b] (ikkinchi ot birinchi otning [b]mazmuni[/b] yoki [b]materialini[/b] bildiradi):\n"
        "  [b]a bowl of sugar[/b] (shakar idishi) — bir kosa shakar\n"
        "  [b]a bowl of fruit[/b] (meva solingan idish) — ichida meva bor idish\n\n"
        "✅ [b]Birinchi ot doim birlik shaklda bo‘ladi, hatto ko‘plik ma'nosini anglatsa ham[/b]\n"
        "Ikki ot birga ishlatilganda, birinchi ot deyarli har doim birlik shaklda bo‘ladi, hatto u ko‘plik ma'nosini anglatsa ham.\n\n"
        "• [b]a three-hour journey[/b] (uch soatlik sayohat) — Safar uch soat davom etdi.\n"
        "• [b]a ten-pound note[/b] (o‘n funtlik banknot) — Uning qiymati o‘n funt.\n"
        "• [b]a four-week course[/b] (to‘rt haftalik kurs) — Kurs to‘rt hafta davom etdi.\n"
        "• [b]a five-day trip[/b] (besh kunlik sayohat) — Sayohat besh kun davom etdi.\n"
        "• [b]a two-bedroom apartment[/b] (ikki yotoq xonali kvartira) — Kvartirada ikkita yotoq xonasi bor.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=TfuA9GKp4Pw]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 130,
    "title":
        "Possessives: 'of mine', 'own', va 'by myself' (Mening do'stim / o'z uyim / yolg'iz o'zim)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 130[/b] darsimizda biz ingliz tilida egalik va shaxsiy mulkni ifodalashning bir nechta usullarini, xususan, [b]\"a friend of mine\"[/b], [b]\"my own house\"[/b] va [b]\"by myself\"[/b] kabi iboralar yordamida o‘rganamiz. Bu tuzilmalar narsalarning kimga tegishli ekanligini yoki biror ishning mustaqil bajarilishini ta'kidlash uchun ishlatiladi.\n\n"
        "✅ [b]A friend of mine / A friend of Tom’s (Mening do'stim / Tomning do'sti)[/b]\n"
        "Bu tuzilma [b]“a friend of + egalik olmoshi / ot + 's”[/b] ([b]mine, yours, his, hers, ours, theirs[/b] yoki [b]Tom’s, Mary’s[/b] kabi) ko'rinishida bo'lib, biror narsaning [b]ko'plab narsalar orasidan bittasi[/b] ekanligini bildiradi. Bu ba'zan otni takrorlashdan qochish uchun ham ishlatiladi.\n\n"
        "• I met an old student of yours today. 🧑‍🎓 – Men bugun sizning eski talabangizni uchratdim.\n"
        "• That’s a clever idea of his. 💡 – Bu uning zukko g‘oyasi.\n"
        "• Do you know a cousin of theirs? 🏘️ – Siz ularning amakivachchasini bilasizmi?\n"
        "• That’s a new book of John’s. 📚 – Bu Johnning yangi kitobi.\n"
        "• This is a picture of mine. 🖼️ – Bu mening rasmlarimdan biri.\n\n"
        "✅ [b]My own ... / Your own ... etc. (O'zimning... / Sizning o'zingizning...)[/b]\n"
        "[b]Own[/b] so‘zi egalik sifatlari ([b]my, your, his, her, its, our, their[/b]) dan keyin kelib, biror narsaning faqat o‘sha shaxsga tegishli ekanligini yoki umumiy emasligini [b]ta'kidlash[/b] uchun ishlatiladi.\n\n"
        "• I want to have my own business. 💼 – Men o‘z biznesimga ega bo‘lishni xohlayman.\n"
        "• He likes to cook his own meals. 🍳 – U o‘z ovqatlarini pishirishni yaxshi ko‘radi.\n"
        "• We designed our own house. 🏠 – Biz o‘z uyimizni loyihalashtirdik.\n"
        "• It’s my own fault I forgot the keys. 🤦‍♀️ – Kalitlarni unutganim o‘z aybim.\n"
        "• The children have their own rooms. 🛏️ – Bolalarning o'z xonalari bor.\n\n"
        "✅ [b]On my own / By myself (Yolg'iz o'zim / Mustaqil)[/b]\n"
        "Bu iboralar [b]“yolg‘iz”[/b] yoki [b]“yordamsiz / mustaqil”[/b] ma'nosini bildiradi. Ular bir-birini almashtira oladi.\n\n"
        "• She prefers to study on her own. 🧑‍💻 – U yolg‘iz o‘qishni afzal ko‘radi.\n"
        "• He fixed the broken chair by himself. 🪑 – U singan stulni o‘zi ta'mirladi.\n"
        "• Are you travelling by yourself? ✈️ – Siz yolg‘iz sayohat qilyapsizmi?\n"
        "• I moved all the furniture by myself. 🛋️ – Men barcha mebellarni yolg'iz o'zim ko'chirdim.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=B_mSOI9VdIM]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 131,
    "title": "Both / both of, Neither / neither of, Either / either of",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 131[/b] darsimizda biz ingliz tilida ikkita narsa yoki shaxs haqida gapirganda ishlatiladigan [b]\"both\"[/b], [b]\"neither\"[/b] va [b]\"either\"[/b] so'zlarini, shuningdek, ularning [b]\"of\"[/b] bilan birikmalarini o'rganamiz. Bu so'zlar har ikkalasi, hech biri yoki ikkalasidan bittasi kabi ma'nolarni ifodalashga yordam beradi.\n\n"
        "✅ [b]Both (Ikkalasi ham, har ikkalasi)[/b]\n"
        "[b]Both[/b] ikkita narsa yoki shaxsning hammasini nazarda tutadi.\n\n"
        "• [b]Both + ko‘plikdagi ot:[/b]\n"
        "  Both children are studying. 📚 – Ikkala bola ham o‘qimoqda.\n"
        "• [b]Both of + the/these/my/us/them (va boshqalar):[/b]\n"
        "  Both of my parents work from home. 👨‍👩‍👧‍👦 – Mening ota-onamning ikkalasi ham uydan ishlaydi.\n"
        "  We can take both of these routes. 🗺️ – Biz bu ikki marshrutning ikkalasini ham tanlashimiz mumkin.\n"
        "  Both of us were tired. 😴 – Biz ikkalamiz ham charchagan edik.\n\n"
        "✅ [b]Neither (Hech biri, na u, na bu)[/b]\n"
        "[b]Neither[/b] ikkita narsa yoki shaxsdan hech birini nazarda tutmaslikni bildiradi. U bilan fe'l odatda [b]birlik[/b] shaklda bo'ladi, ayniqsa rasmiy uslubda.\n\n"
        "• [b]Neither + birlikdagi ot:[/b]\n"
        "  Neither answer is correct. ❌ – Hech qaysi javob to‘g‘ri emas.\n\n"
        "• [b]Neither of + the/these/my/us/them (va boshqalar):[/b]\n"
        "  Neither of the books was interesting. 📖 – Kitoblarning hech biri qiziqarli emas edi.\n"
        "  Neither of us wanted to go. 🚶‍♀️ – Biz ikkalamiz ham borishni xohlamadik.\n\n"
        "✅ [b]Either (Ikkalasidan bittasi, qaysi biri bo‘lsa ham)[/b]\n"
        "[b]Either[/b] ikkita narsa yoki shaxsdan bittasini tanlash mumkinligini yoki farqi yo‘qligini bildiradi.\n\n"
        "• [b]Either + birlikdagi ot:[/b]\n"
        "  You can choose either option. ✅ – Siz ikkala variantdan birini tanlashingiz mumkin.\n\n"
        "• [b]Either of + the/these/my/us/them (va boshqalar):[/b]\n"
        "  Either of these shirts would look good on you. 👕 – Bu ikkita ko'ylakning bittasi sizga yaxshi yarashadi.\n"
        "  Would you like tea or coffee? Either is fine. ☕ – Choy yoki kofe xohlaysizmi? Qaysi biri bo‘lsa ham farqi yo‘q.\n\n"
        "✅ [b]Both ... and ... / Neither ... nor ... / Either ... or ...[/b]\n"
        "Bu iboralar bir vaqtning o‘zida ikkita narsani bog‘lash uchun ishlatiladi:\n\n"
        "• [b]Both ... and ... (Ham ... ham ...):[/b]\n"
        "  Both John and Mary are coming. 👥 – Jon ham, Meri ham kelyapti.\n"
        "  She both sings and plays the guitar. 🎸 – U ham kuylaydi, ham gitara chaladi.\n\n"
        "• [b]Neither ... nor ... (Na u, na bu):[/b]\n"
        "  Neither rain nor snow stopped the delivery. 🌧️🌨️ – Na yomg‘ir, na qor yetkazib berishni to‘xtata olmadi.\n"
        "  He neither smokes nor drinks. 🚭 – U na chekadi, na ichadi.\n\n"
        "• [b]Either ... or ... (Yo u, yo bu):[/b]\n"
        "  You can either call me or send a message. 📞📧 – Siz yo menga qo‘ng‘iroq qilishingiz yoki xabar yuborishingiz mumkin.\n"
        "  I think the keys are either in my bag or on the table. 🔑 – Menimcha, kalitlar yo sumkamda, yo stol ustida.\n\n"
        "✅ [b]Ikkitadan ortiq narsalar bilan taqqoslash (Any/None/All)[/b]\n"
        "Unutmangki, [b]both, neither[/b] va [b]either[/b] faqat [b]ikki narsa[/b] haqida gapirganda ishlatiladi. Ikkitadan ortiq narsalar uchun [b]any, none, all[/b] kabi so‘zlar ishlatiladi:\n\n"
        "• Ikki variant uchun: Neither car is expensive. (Ikkala mashinaning hech biri qimmat emas.) 🚗🚗\n"
        "• Uch yoki undan ortiq variant uchun: None of the cars are expensive. (Mashinalarning hech biri qimmat emas.) 🚗🚗🚗\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=Os7rK9tHt80]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 132,
    "title":
        "All, Every, Whole, and Each (Barchasi, Har biri, Butun, va Har bir alohida)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 132[/b] darsimizda biz ingliz tilida miqdor va to'liqlikni ifodalashda ishlatiladigan [b]\"all\"[/b], [b]\"every\"[/b], [b]\"whole\"[/b] va [b]\"each\"[/b] so'zlarini o'rganamiz. Garchi ular o'xshash ma'nolarni bersa-da, ularning qo'llanilishida aniq farqlar mavjud.\n\n"
        "✅ [b]All (Barchasi, Umumiy miqdor)[/b]\n"
        "[b]All[/b] so‘zi narsa yoki odamlarning umumiy soni, to‘plami haqida gapirganda ishlatiladi. U ko‘plikdagi sanaladigan otlar va sanalmaydigan otlar bilan ishlatilishi mumkin.\n\n"
        "• We all enjoyed the party. 🎉 – Biz hammamiz ziyofatdan zavqlandik.\n"
        "• [b]All of + the/these/my/us/them (va boshqalar):[/b]\n"
        "  All of my friends came to the wedding. 👫 – Mening barcha do‘stlarim to‘yga keldilar.\n"
        "• All the things were sold there. 🛍️ – U yerda barcha narsalar sotilgan.\n"
        "• I read all the information. 📑 – Men barcha ma'lumotlarni o'qidim.\n\n"
        "✅ [b]Every / Everybody / Everyone / Everything (Har bir alohida, Ajratib ko‘rsatish)[/b]\n"
        "[b]Every[/b] so‘zi guruhdagi har bir alohida narsa yoki shaxsni nazarda tutadi. U har doim birlikdagi sanaladigan ot bilan ishlatiladi va fe'l ham birlik shaklida bo‘ladi. [b]Every[/b] odatda uch yoki undan ortiq narsalar haqida gapirganda ishlatiladi va [b]umumiylikni[/b] bildiradi.\n\n"
        "• Everybody has arrived. ✅ – Hamma yetib keldi.\n"
        "• Every student has their own book. 📚 – Har bir talabaning o‘z kitobi bor.\n"
        "• Every problem is important. 💡 – Har bir masala muhim.\n"
        "• I had everything. 🎁 – Mening hamma narsam bor edi.\n\n"
        "✅ [b]Each (Har bir alohida, Yakka tartibda)[/b]\n"
        "[b]Each[/b] so‘zi ham guruhdagi har bir alohida narsa yoki shaxsni nazarda tutadi, lekin u ko‘proq [b]individual, yakka tartibdagi[/b] narsalarga e'tibor qaratadi. U odatda kichikroq va aniqroq guruhlar uchun ishlatiladi va [b]ikki narsa[/b] haqida gapirganda ham qo‘llanishi mumkin.\n\n"
        "• Each student received a certificate. 🎓 – Har bir talaba sertifikat oldi. (Sertifikat har bir talabaga alohida berilganiga urg‘u.)\n"
        "• Each of the two brothers has a different personality. 🧑‍🤝‍🧑 – Ikkala aka-ukaning har birida har xil fe'l-atvor bor.\n"
        "• He gave each of us a piece of cake. 🎂 – U har birimizga bir bo‘lak tort berdi.\n\n"
        "✅ [b]Whole (Butun, To‘liq, Ajralmagan)[/b]\n"
        "[b]Whole[/b] so‘zi biror narsaning yoki butun bir davrning to‘liqligini, ajratilmaganligini bildiradi. U birlikdagi sanaladigan otlar bilan ishlatiladi va odatda [b]the/my/her[/b] kabi aniqlovchi so‘zlar bilan keladi.\n\n"
        "• Did you read the whole book? 📖 – U butun kitobni o‘qib chiqdimi?\n"
        "• I worked the whole day from home. 🏡 – Men butun kun davomida uydan ishladim.\n"
        "• We ate the whole cake. 🍰 – Biz butun bir tortni yedik.\n"
        "• The whole world knows him. 🧑‍🤝‍🧑 – Butun dunyo uni taniydi.\n"
        "• Biz [b]whole[/b] so‘zini sanalmaydigan otlar bilan ishlatmaymiz. Masalan, [b]all my money[/b] deymiz, [b]whole my money[/b] emas.\n\n"
        "✅ [b]Each va Every farqi:[/b]\n"
        "[b]Each[/b] va [b]Every[/b] ikkalasi ham guruhdagi alohida a'zolarga ishora qilsa-da, ular orasida muhim farqlar bor:\n\n"
        "• [b]Every:[/b] Katta guruhlarga nisbatan qo‘llaniladi va [b]guruhning har bir a'zosi[/b]ni umumiy ma'noda ta'kidlaydi. Ko‘pincha [b]muntazamlik[/b] yoki [b]tez-tez takrorlanadigan harakatlar[/b]ni ifodalaydi.\n"
        "  Every chair in the hall was occupied. 🪑🪑🪑 – Zaldagi har bir stul band edi. (Barcha stullar guruhiga urg‘u.)\n"
        "  Every year, we go on holiday. 🗓️ – Har yili biz ta'tilga boramiz. (Harakatning muntazam takrorlanishiga urg‘u.)\n\n"
        "• [b]Each:[/b] Kichikroq va aniqroq guruhlarga nisbatan ishlatiladi. [b]Har bir a'zoning individualligi[/b] yoki ularga alohida e'tibor berishni ta'kidlaydi. Ikki narsa haqida gapirganda ham ishlatiladi.\n"
        "  Each chair had a small tag on it. 🏷️ – Har bir stulda kichik yorliq bor edi. (Har bir alohida stulga urg‘u.)\n"
        "  Each year of university was challenging. 🎓 – Universitetning har bir yili qiyin edi. (O‘qishning har bir yiliga alohida urg‘u.)\n"
        "  There are four books. Each book is about a different topic. 📖📖📖📖 – To'rtta kitob bor. Har bir kitob har xil mavzu haqida.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=oKKVlDK1X_k]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 133,
    "title":
        "Adjectives ending in -ing and -ed (Sifatlarning -ing va -ed bilan tugashi)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 133[/b] darsimizda biz ingliz tilida ko'p uchraydigan sifatlar — [b]-ing[/b] va [b]-ed[/b] bilan tugaydigan sifatlar orasidagi farqni o'rganamiz. Bu sifatlar ko'pincha fe'llardan yasaladi va ularni to'g'ri ishlatish, siz biror narsa his-tuyg'uni [b]chaqirayotganini[/b] yoki o'sha his-tuyg'uni [b]his qilayotganini[/b] ifodalamoqchimisiz, shunga bog'liq.\n\n"
        "✅ [b]-ing bilan tugaydigan sifatlar (-ing adjectives)[/b]\n"
        "Bu sifatlar biror shaxs yoki narsaning [b]sifatini[/b], ya'ni uning boshqalarda qanday his-tuyg'uni yoki reaksiyani [b]chaqirishini[/b] tasvirlaydi. Ular his-tuyg'uning [b]manbasini[/b] ko'rsatadi.\n\n"
        "• The movie was boring. 😴 – Film zerikarli edi. (Film zerikishni keltirib chiqardi.)\n"
        "• He is an interesting speaker. 🗣️ – U qiziqarli ma'ruzachi. (U qiziqish uyg'otadi.)\n"
        "• This is exciting news! ✨ – Bu hayajonli yangilik! (Yangilik hayajonni keltirib chiqaradi.)\n"
        "• The situation was confusing. 🤯 – Vaziyat chalkash edi. (Vaziyat chalkashlikni keltirib chiqardi.)\n\n"
        "✅ [b]-ed bilan tugaydigan sifatlar (-ed adjectives)[/b]\n"
        "Bu sifatlar biror shaxsning [b]his-tuyg'usini[/b] yoki emotsiyasini tasvirlaydi. Ular biror narsaning natijasida kimdir qanday [b]his qilayotganini[/b] bildiradi.\n\n"
        "• I was bored with the movie. 🥱 – Men filmdan zerikdim. (Men zerikish hissini boshdan kechirdim.)\n"
        "• She is interested in politics. 🗳️ – U siyosatga qiziqadi. (Unda qiziqish hissi bor.)\n"
        "• I was excited by the result. 🤩 – Men natijadan hayajonlandim. (Men hayajon hissini his qildim.)\n"
        "• I was very tired after the task. 😩 – Men topshiriqdan keyin juda charchagan edim.\n\n"
        "✅ [b]Asosiy farqning xulosasi:[/b]\n"
        "• [b]-ing[/b] bilan tugaydigan sifatlar his-tuyg'uni [b]chaqiruvchi sababni[/b] yoki narsaning [b]sifatini[/b] ifodalaydi.\n"
        "• [b]-ed[/b] bilan tugaydigan sifatlar esa his-tuyg'uni [b]his qiluvchi shaxsning holatini[/b] yoki uning kechinmasini bildiradi.\n\n"
        "✅ [b]Qo‘shimcha misollar:[/b]\n\n"
        "• [b]tiring[/b] (charchatuvchi) – [b]tired[/b] (charchagan)\n"
        "  This work is [b]tiring[/b]. – Bu ish charchatuvchi.\n"
        "  I am [b]tired[/b]. – Men charchaganman.\n\n"
        "• [b]exciting[/b] (hayajonli) – [b]excited[/b] (hayajonlangan)\n"
        "  The match was [b]exciting[/b]. – O'yin hayajonli edi.\n"
        "  We were [b]excited[/b] about the trip. – Biz sayohatdan hayajonlangan edik.\n\n"
        "• [b]confusing[/b] (chalkashtiruvchi) – [b]confused[/b] (chalkashgan)\n"
        "  The instructions were [b]confusing[/b]. – Ko‘rsatmalar chalkashtiruvchi edi.\n"
        "  I was [b]confused[/b] by the instructions. – Men ko‘rsatmalardan chalkashdim.\n\n"
        "• [b]annoying[/b] (bezovta qiluvchi) – [b]annoyed[/b] (bezovtalangan)\n"
        "  His habit is [b]annoying[/b]. – Uning odati bezovta qiluvchi.\n"
        "  Julia was [b]annoyed[/b] by his loud music. – Julia uning baland musiqasidan bezovtalangan edi.\n\n"
        "• [b]frightening[/b] (qo‘rqinchli) – [b]frightened[/b] (qo‘rqqan)\n"
        "  The storm was [b]frightening[/b]. – Bo‘ron qo‘rqinchli edi.\n"
        "  We were [b]frightened[/b] by the thunder. – Biz momaqaldiroqdan qo‘rqqan edik.\n\n"
        "• [b]astonishing[/b] (hayratlanarli) – [b]astonished[/b] (hayratlangan)\n"
        "  Her progress was [b]astonishing[/b]. – Uning yutuqlari hayratlanarli edi.\n"
        "  They were [b]astonished[/b] at the news. – Ular yangilikdan hayratlangan edilar.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=xsglifwt4KI]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 134,
    "title": "Adjectives and Adverbs 1 (Sifatlar va ravishlar 1)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 134[/b] darsimizda biz ingliz tilida sifatlar (adjectives) va ravishlar (adverbs) mavzusining birinchi qismini o'rganamiz. Bu ikki so'z turkumi gapda turli vazifalarni bajaradi va ularni to'g'ri ishlatish ingliz tilida aniq va tushunarli ifodalash uchun juda muhimdir.\n\n"
        "✅ [b]Sifatlar va Ravishlarning asosiy farqi:[/b]\n"
        "• [b]Sifatlar (Adjectives)[/b] otlarni (nounds) yoki olmoshlarni (pronouns) tavsiflaydi. Ular narsalar yoki odamlarning xususiyatlari va holatlarini ifodalaydi. ([b]quick, careful, serious[/b])\n"
        "  He drives a quick car. 🚗 – U [b]tezkor[/b] mashinani haydaydi. (Mashina – ot).\n\n"
        "• [b]Ravishlar (Adverbs)[/b] fe'llarni (verbs), sifatlarni (adjectives) yoki boshqa ravishlarni (adverbs) tavsiflaydi. Ular harakatning qanday, qachon, qayerda yoki qanchalik sodir bo‘lganini bildiradi. ([b]quickly, carefully, seriously[/b])\n"
        "  He drives quickly. 💨 – U mashinani [b]tez[/b] haydaydi. (Haydaydi – fe'l).\n\n"
        "✅ [b]Ravishlarning -ly qo‘shimchasi bilan yasalishi:[/b]\n"
        "Ko‘pgina ravishlar sifatlarga [b]“-ly”[/b] qo‘shimchasini qo‘shish orqali yasaladi. Ba'zan imloda o‘zgarishlar bo‘lishi mumkin.\n\n"
        "• [b]slow[/b] (sekin - sifat) → [b]slowly[/b] (sekin - ravish)\n"
        "  She walks slowly. 🚶‍♀️ – U [b]sekin[/b] yuradi.\n\n"
        "• [b]careful[/b] (ehtiyotkor - sifat) → [b]carefully[/b] (ehtiyotkorlik bilan - ravish)\n"
        "  He completed the task carefully. ✍️ – U vazifani [b]ehtiyotkorlik bilan[/b] bajardi.\n\n"
        "• [b]easy[/b] (oson - sifat) → [b]easily[/b] (osonlik bilan - ravish) (y o‘rniga i keladi)\n"
        "  She solved the problem easily. ✅ – U muammoni [b]osonlik bilan[/b] hal qildi.\n\n"
        "• [b]terrible[/b] (dahshatli - sifat) → [b]terribly[/b] (dahshatli darajada - ravish)\n"
        "  The food was terribly good. 😋 – Ovqat [b]dahshatli darajada[/b] yaxshi edi.\n\n"
        "✅ [b]Maxsus holatlar (Noto‘g‘ri shakllar):[/b]\n"
        "Ba'zi so‘zlar ham sifat, ham ravish bo‘lishi mumkin, shaklini o‘zgartirmaydi, yoki butunlay boshqacha ravish shakliga ega bo‘ladi.\n\n"
        "• [b]fast[/b] (tez)\n"
        "  He is a fast runner. 🏃‍♂️ – U [b]tezkor[/b] yuguruvchi. (sifat)\n"
        "  He runs fast. 💨 – U [b]tez[/b] yuguradi. (ravish)\n\n"
        "• [b]hard[/b] (qiyin / qattiq)\n"
        "  It's a hard job. – Bu [b]qiyin[/b] ish. (sifat)\n"
        "  He works hard. – U [b]qattiq[/b] ishlaydi. (ravish)\n\n"
        "• [b]good[/b] (yaxshi - sifat) vs. [b]well[/b] (yaxshi - ravish)\n"
        "  He is a good person. – U [b]yaxshi[/b] odam. (sifat)\n"
        "  She speaks English well. 🗣️ – U ingliz tilida [b]yaxshi[/b] gapiradi. (ravish)\n\n"
        "✅ [b]Sifatlar bilan keladigan fe'llar:[/b]\n"
        "Holat yoki sezgi fe'llari ([b]look, feel, sound, smell, taste, be, become, seem[/b]) odatda ravish bilan emas, balki [b]sifat[/b] bilan birga keladi. Chunki ular harakatni emas, ko'proq holatni tasvirlaydi.\n\n"
        "• She looks tired. 😴 – U charchagan ko‘rinadi. (U qanday ko‘rinadi? – charchagan.)\n"
        "• The flower smells good. 🌸 – Gulning hidi yaxshi. (Gul qanday hidlanadi? – yaxshi.)\n"
        "• That idea sounds clever. 🧠 – Bu g‘oya aqlli eshitiladi. (G‘oya qanday eshitiladi? – aqlli.)\n\n"
        "✅ [b]Ravishlarning joylashuvi:[/b]\n"
        "Ravishlar fe'llarni tavsiflaganda odatda fe'ldan keyin keladi. Agar gapda to‘ldiruvchi bo‘lsa, to‘ldiruvchidan keyin keladi. Ular shuningdek sifatlarni yoki boshqa ravishlarni kuchaytirish yoki aniqlash uchun ulardan oldin keladi.\n\n"
        "• He replied quickly. ⚡ – U [b]tez[/b] javob berdi.\n"
        "• She speaks very well. 🗣️ – U juda [b]yaxshi[/b] gapiradi. (ravish + ravish)\n"
        "• It's an incredibly fast car. 🏎️ – Bu [b]g‘oyatda[/b] tez mashina. (ravish + sifat)\n"
        "• Two people were seriously injured in the accident. 🤕 – Baxtsiz hodisada ikki kishi [b]jiddiy jarohat[/b] oldi.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=KQddYvgJ88M]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 135,
    "title": "So and Such (Shunchalik va Shunday)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 135[/b] darsimizda biz ingliz tilida his-tuyg'ularni kuchaytirish, darajani ifodalash va ta'kidlash uchun ishlatiladigan [b]\"so\"[/b] va [b]\"such\"[/b] so'zlarini o'rganamiz. Bu so'zlar odatda bir-biriga o'xshash ma'nolarni bersa-da, ular gapda turli grammatik tuzilmalar bilan ishlatiladi.\n\n"
        "✅ [b]So (Shunchalik, juda)[/b]\n"
        "[b]So[/b] so'zi [b]sifatlar (adjectives)[/b] yoki [b]ravishlar (adverbs)[/b] dan oldin kelib, ularning ma'nosini kuchaytiradi. U ot bilan birga ishlatilmaydi, faqat sifat yoki ravishni tavsiflaydi.\n\n"
        "• The weather was so beautiful. ☀️ – Ob-havo [b]shunchalik[/b] go'zal edi.\n"
        "• He spoke so quickly that I didn't understand him. 🗣️ – U [b]shunchalik[/b] tez gapirdiki, men uni tushunmadim.\n"
        "• They were so kind. 🥰 – Ular [b]juda[/b] mehribon edilar.\n\n"
        "✅ [b]Such (Shunday, aynan shunday, juda)[/b]\n"
        "[b]Such[/b] so'zi odatda [b]otlar (nouns)[/b] bilan birga keladi. Agar ot sanaladigan va birlikda bo'lsa, [b]a/an[/b] artikli bilan ishlatiladi. Agar ot ko'plikda yoki sanalmaydigan bo'lsa, artikl ishlatilmaydi.\n\n"
        "• It was such a cold day! ❄️ – Bu [b]shunday[/b] sovuq kun edi!\n"
        "• They are such nice people. 🧑‍🤝‍🧑 – Ular [b]shunday[/b] yaxshi odamlar.\n"
        "• We had such good weather. ⛱️ – Bizda [b]shunday[/b] ajoyib ob-havo bo'ldi.\n"
        "• It was such a big problem. 😥 – Bu [b]shunday[/b] katta muammo edi.\n\n"
        "✅ [b]So ... that va Such ... that (Natijani ifodalash)[/b]\n"
        "[b]So[/b] yoki [b]such[/b] so'zlaridan keyin [b]that[/b] qo'shimchasi bilan bog'langan natija gapini keltirish mumkin.\n\n"
        "• She was so tired that she fell asleep. 😴 – U [b]shunchalik[/b] charchagan ediki, uxlab qoldi.\n"
        "• It was such a good book that I finished it in one day. 📖 – Bu [b]shunday[/b] yaxshi kitob ediki, men uni bir kunda o'qib tugatdim.\n\n"
        "✅ [b]So va Such so'zlarining \"bunchalik\" ma'nosida ishlatilishi:[/b]\n"
        "Ba'zan [b]so[/b] va [b]such[/b] biror narsaning [b]qandayligini[/b] yoki [b]qanchalik katta/kichikligini[/b] ifodalash uchun ishlatiladi.\n\n"
        "• Why are you so serious? 🤔 – Nega bunchalik jiddiy turibsiz?\n"
        "• I've never seen such a mess. 🗑️ – Men hech qachon [b]bunday[/b] tartibsizlikni ko'rmaganman.\n\n"
        "✅ [b]Qat'iy iboralar va tarqatilgan jumlalar:[/b]\n"
        "• [b]so long[/b] (juda uzoq vaqt) / [b]such a long time[/b] (shuncha uzoq vaqt)\n"
        "  I haven't seen her for so long. 🕰️ – Men uni [b]juda uzoq vaqtdan beri[/b] ko'rmadim.\n"
        "  I haven't seen her for such a long time. – Men uni [b]juda uzoq vaqtdan beri[/b] ko'rmadim.\n\n"
        "• [b]so far[/b] (shunchalik uzoq) / [b]such a long way[/b] (shunchalik uzoq yo'l)\n"
        "  I didn't know it was so far. 🛣️ – Men buni [b]shunchalik uzoq[/b] ekanligini bilmasdim.\n"
        "  I didn't know it was such a long way. – Men buni [b]shunchalik uzoq[/b] ekanligini bilmasdim.\n\n"
        "• [b]so many/much[/b] (shuncha ko‘p) / [b]such a lot (of)[/b] (juda ko‘p)\n"
        "  I’m sorry I’m late – there was so much traffic. 🚦 – Men [b]juda ko‘p[/b] tirbandlik borligi uchun kech qoldim, uzr.\n"
        "  I’m sorry I’m late – there was such a lot of traffic. – Men [b]juda ko‘p[/b] tirbandlik borligi uchun kech qoldim, uzr.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=bwzm1XiNIr0]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 136,
    "title":
        "Quite, Pretty, Rather, and Fairly (Ancha, Juda, Biroz, va Yetarli)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 136[/b] darsimizda biz ingliz tilida darajani yoki intensivlikni ifodalashda ishlatiladigan [b]\"quite\"[/b], [b]\"pretty\"[/b], [b]\"rather\"[/b] va [b]\"fairly\"[/b] ravishlarini o'rganamiz. Bu so'zlar sifatlar va ravishlarning ma'nosini kuchaytiradi yoki yumshatadi, lekin ularning har birining o'ziga xos qo'llanishi va ma'no nozikliklari bor.\n\n"
        "✅ [b]Quite (Ancha, Juda, To‘liq)[/b]\n"
        "[b]Quite[/b] so'zining ikki asosiy ma'nosi bor:\n\n"
        "1.  [b]“Ancha” yoki “juda” (lekin “juda” darajasida emas):[/b] Bu ma'noda u sifatlar va ravishlar bilan kelib, holatni, sifati o'rtachadan yuqori ekanligini, ammo ekstremal darajada emasligini bildiradi.\n"
        "    • It’s quite hot outside. 🥶 – Tashqarida [b]ancha[/b] issiq.\n"
        "    • She did the work quite quickly. 🚀 – U ishni [b]ancha[/b] tez bajardi.\n"
        "    • It's quite a big house. 🏠 – Bu [b]ancha[/b] katta uy.\n\n"
        "2.  [b]“To‘liq” yoki “butunlay” (certain adjectives bilan):[/b] Ba'zi sifatlar bilan kelganda ([b]sure, right, true, different, impossible[/b] kabi) [b]quite[/b] “to‘liq” yoki “mutlaqo” degan ma'noni beradi.\n"
        "    • I quite agree with you. ✅ – Men sizning fikringizga [b]to‘liq[/b] qo'shilaman.\n"
        "    • It’s quite a different situation. 🔄 – Bu [b]mutlaqo[/b] boshqacha vaziyat.\n"
        "    • It's quite an impossible task. 🤯 – Bu [b]butunlay[/b] imkonsiz vazifa.\n\n"
        "✅ [b]Pretty (Ancha, Juda - norasmiy)[/b]\n"
        "[b]Pretty[/b] so‘zi [b]“quite”[/b] yoki [b]“fairly”[/b] ga o‘xshash ma'noga ega, lekin [b]norasmiy nutqda[/b] ko'proq ishlatiladi.\n\n"
        "• She’s a pretty famous singer. 🎤 – U [b]ancha[/b] mashhur qo'shiqchi.\n"
        "• It was pretty hot. 🥵 – Havo [b]juda[/b] issiq edi.\n\n"
        "✅ [b]Rather (Biroz)[/b]\n"
        "[b]Rather[/b] ham [b]“quite”[/b] va [b]“pretty”[/b] ga o‘xshash, lekin ko‘pincha [b]salbiy fikrlar[/b] bilan ishlatiladi. U “kutilganidan ko‘ra ko‘proq” yoki “biroz” ma'nosini berishi mumkin.\n\n"
        "• The weather is rather cloudy. ☁️ – Ob-havo [b]biroz[/b] bulutli.\n"
        "• He is rather shy. 😳 – U [b]ancha[/b] uyatchan.\n"
        "• It was rather cold outside. 💡 – Havo [b]biroz[/b] sovuq edi tashqarida. (Ijobiy ma'noda, kutilmaganda yaxshi.)\n\n"
        "✅ [b]Fairly (Yetarli, Ancha)[/b]\n"
        "[b]Fairly[/b] so‘zi [b]“quite”[/b], [b]“pretty”[/b] yoki [b]“rather”[/b] dan [b]zaifroq[/b] ma'no beradi. U “yetarli darajada” yoki “maqbul” degan ma'noni anglatadi, ko‘pincha kutilganidek yoki qoniqarli darajada ekanligini bildiradi.\n\n"
        "• My room is fairly big, but I'd prefer a bigger one. 📏 – Mening xonam [b]ancha[/b] katta, lekin men yanada kattarog'ini xohlayman.\n"
        "• He did fairly well on the exam. ✅ – U imtihondan [b]yaxshi[/b] o‘tdi.\n"
        "• The film was fairly interesting. 🍿 – Film [b]yetarlicha[/b] qiziqarli edi. (Juda emas, lekin yaxshi.)\n\n"
        "✅ [b]Farqlarning qisqacha xulosasi:[/b]\n"
        "• [b]Quite:[/b] Odatda “ancha” ma'nosida, ba'zi sifatlar bilan esa “butunlay” ma'nosida.\n"
        "• [b]Pretty:[/b] “Ancha” yoki “juda” ma'nosida, lekin norasmiy.\n"
        "• [b]Rather:[/b] Ko‘pincha “bir oz ko‘proq” yoki “kutilmaganda” ma'nosida, ayniqsa salbiy sifatlar bilan.\n"
        "• [b]Fairly:[/b] “Yetarli darajada” yoki “o‘rtacha” ma'nosida, eng kuchsiz darajani ifodalaydi.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=D_g14ltcraw]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 137,
    "title":
        "Comparison 2: kuchaytiruvchilar va maxsus konstruktsiyalar (much better / any better / better and better / the sooner the better)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 137[/b] darsimizda biz ingliz tilida taqqoslashning murakkabroq shakllarini o'rganamiz. Avvalgi darslarda sifat va ravishlarning oddiy taqqoslash darajalarini ko'rib chiqqan edik. Endi esa, ularni kuchaytirish, doimiy o'zgarishlarni ifodalash va maxsus konstruktsiyalardan foydalanishni bilib olamiz.\n\n"
        "✅ [b]Taqqoslash darajalarini kuchaytiruvchi so‘zlar (Modifiers with Comparatives)[/b]\n"
        "Taqqoslash sifatlari yoki ravishlaridan oldin [b]much[/b], [b]a lot[/b], [b]far[/b] (ancha ko‘p), [b]a little[/b], [b]slightly[/b] (biroz) kabi so‘zlarni ishlatib, farqning qanchalik katta yoki kichikligini ko'rsatishimiz mumkin.\n\n"
        "• This car is [b]much[/b] faster. 🏎️ – Bu mashina [b]ancha tezroq[/b].\n"
        "• He feels [b]a lot[/b] better. 😊 – U o‘zini [b]ancha yaxshiroq[/b] his qilyapti.\n"
        "• It's [b]a little[/b] cheaper option. 💰 – Bu biroz [b]arzonroq[/b] variant.\n"
        "• It got [b]slightly[/b] colder outside. 🌬️ – Tashqarida [b]sezilarli darajada sovuqroq[/b] bo‘ldi.\n\n"
        "✅ [b]Any va No bilan taqqoslash (Any and No with Comparatives)[/b]\n"
        "[b]Any[/b] so‘zi savollarda yoki inkor gaplarda “biron bir farq bormi?” degan ma'noda ishlatiladi. [b]No[/b] esa “hech qanday farq yo‘q” degan ma'noni bildiradi.\n\n"
        "• Is it [b]any easier[/b] now? 🤔 – Hozir [b]biroz osonroqmi?[/b]\n"
        "• It's [b]no cheaper[/b] to go by bus. 🚌 – Avtobusda borish [b]hech qanday arzonroq emas[/b].\n"
        "• Did he say [b]anything more interesting[/b]? – U [b]biron bir qiziqroq[/b] narsani aytdimi?\n\n"
        "✅ [b]Better and better / More and more (Doimiy o‘zgarish)[/b]\n"
        "Taqqoslash sifatini yoki ravishini takrorlash biror narsaning [b]doimiy ravishda o‘zgarib borayotganini[/b] ko‘rsatadi.\n\n"
        "• The weather is getting warmer and warmer. ☀️ – Ob-havo [b]tobora issiqroq[/b] bo‘lmoqda.\n"
        "• English is becoming more and more popular. 🌍 – Ingliz tili [b]tobora mashhurroq[/b] bo‘lib bormoqda.\n"
        "• Her health is getting better and better. 💪 – Uning sog'lig'i [b]kundan-kunga yaxshilanmoqda[/b].\n\n"
        "✅ [b]The ... the ... (Qanchalik ... shunchalik ...)[/b]\n"
        "Bu konstruktsiya bir harakatning natijasi yoki darajasi boshqa harakatga bog'liqligini bildiradi.\n\n"
        "• [b]The more[/b] you study, [b]the better[/b] you understand. 📚 – [b]Qanchalik ko‘p[/b] o‘qisangiz, [b]shunchalik yaxshi[/b] tushunasiz.\n"
        "• [b]The earlier[/b] you leave, [b]the sooner[/b] you arrive. ⏰ – [b]Qanchalik erta[/b] jo‘nasangiz, [b]shunchalik tez[/b] yetib kelasiz.\n"
        "• [b]The higher[/b] you climb, [b]the cooler[/b] it gets. ⛰️ – [b]Qanchalik yuqori[/b] ko‘tarilsangiz, [b]shunchalik salqin[/b] bo‘ladi.\n\n"
        "✅ [b]Older va Elder (Katta)[/b]\n"
        "Ikkala so‘z ham “yoshi kattaroq” degan ma'noni beradi, ammo ularning ishlatilishida farq bor.\n\n"
        "• [b]Older:[/b] Ham odamlar, ham narsalar uchun ishlatiladi. Bu eng keng tarqalgan shakl.\n"
        "  My brother is older than me. 🧑‍ – Mening ukam mendan [b]kattaroq[/b].\n"
        "  This building is the oldest in the city. 🏛️ – Bu bino shahardagi eng [b]eskisi[/b].\n\n"
        "• [b]Elder:[/b] Faqat odamlar uchun, asosan [b]oilaviy munosabatlar[/b]da (aka, opa, o‘g‘il, qiz) ishlatiladi. Bu biroz rasmiyroq eshitiladi va odatda [b]“than”[/b] bilan ishlatilmaydi.\n"
        "  My elder sister is a doctor. 👩‍⚕️ – Mening [b]katta opam[/b] shifokor.\n"
        "  Her elder son studies at university. 👨‍🎓 – Uning [b]katta o‘g‘li[/b] universitetda o‘qiydi.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=dRwIZsMmchM]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 138,
    "title":
        "Any longer / any more / no longer / no more and Even (Endi ... emas / Hech ham ... emas va Hatto)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 138[/b] darsimizda biz ingliz tilida vaqtinchalik holatning tugashini, miqdordagi o'zgarishlarni va shuningdek, kutilmagan holatlarni ta'kidlash uchun ishlatiladigan [b]\"any longer / any more\"[/b], [b]\"no longer / no more\"[/b] va [b]\"even\"[/b] so'zlarini o'rganamiz.\n\n"
        "✅ [b]Any longer / Any more (Endi ... emas / Endi ortiqcha ... emas)[/b]\n"
        "Bu iboralar [b]inkor gaplarda[/b] ([b]not[/b] bilan) biror holatning davom etmasligini, tugashini bildirish uchun ishlatiladi. Ular ko'pincha bir-birini o'rnini bosa oladi.\n\n"
        "• She doesn't live here any longer. 🏠 – U endi bu yerda yashamaydi.\n"
        "• I can't wait any more. ⏳ – Men endi boshqa kutolmayman.\n"
        "• They aren't friends any more. 💔 – Ular endi do'st emaslar.\n\n"
        "✅ [b]No longer / No more (Endi ... emas / Hech ham ... emas)[/b]\n"
        "[b]No longer[/b] va [b]no more[/b] so'zlari [b]ijobiy fe'l[/b] bilan ishlatiladi va [b]not ... any longer/more[/b] bilan bir xil ma'noni beradi.\n"
        "• [b]No longer[/b] asosan [b]vaqtga[/b] ishora qiladi va ko'pincha fe'ldan oldin keladi.\n"
        "• [b]No more[/b] esa ham [b]vaqtga[/b], ham [b]miqdorga[/b] ishora qilishi mumkin.\n\n"
        "• He no longer works here. 🚫 – U endi bu yerda ishlamaydi. (Ya'ni, avval ishlagan, hozir ishlamaydi.)\n"
        "• There is no more bread left. 🍞 – Non boshqa qolmadi. (Miqdorga ishora.)\n"
        "• We no longer meet them. 👋 – Biz endi(boshqa) ular bilan uchrashmaymiz.\n\n"
        "✅ [b]Even (Hatto, hatto shunday ham)[/b]\n"
        "[b]Even[/b] so'zi [b]ta'kidlash[/b] uchun ishlatiladi va kutilganidan ko'proq yoki hayratlanarli darajada ekanligini bildiradi. U odatda ta'kidlanayotgan so'zdan oldin keladi, yoki asosiy fe'ldan oldin.\n\n"
        "• He can even speak Chinese. 🗣️🇨🇳 – U hatto xitoy tilida ham gaplasha oladi.\n"
        "• It's cold, even in summer. ❄️☀️ – Hatto yozda ham sovuq.\n"
        "• I don't even know him. 🤷‍♀️ – Men hatto uni bilmayman ham.\n\n"
        "✅ [b]Not even (Hatto ... ham emas)[/b]\n"
        "[b]Not even[/b] kuchli inkor ma'nosini berish uchun ishlatiladi.\n\n"
        "• She didn't even call me. 📞 – U menga hatto qo'ng'iroq ham qilmadi.\n"
        "• We don't even have chocolate. 🍫 – Bizda hatto shokolad ham yo'q.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=rU66BHGsOVE]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 139,
    "title":
        "Although / Though / Even though / In spite of / Despite (Garchi / Shunga qaramay)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 139[/b] darsimizda biz ingliz tilida qarama-qarshi fikrlarni yoki tasodifiy holatlarni ifodalash uchun ishlatiladigan bog'lovchilar va predloglarni o'rganamiz: [b]\"although\"[/b], [b]\"though\"[/b], [b]\"even though\"[/b], [b]\"in spite of\"[/b] va [b]\"despite\"[/b]. Bu so'zlar bir-biriga o'xshash ma'nolarni bersa-da, ularning grammatik ishlatilishida farqlar bor.\n\n"
        "✅ [b]Although / Though / Even though (Garchi, ga qaramay)[/b]\n"
        "Bu so'zlar [b]bog'lovchilar[/b] bo'lib, ulardan keyin har doim [b]to'liq gap[/b] (ya'ni, [b]ega + kesim[/b] bo'lgan gap bo'lagi) keladi. Ular biror faktga qaramay, kutilmagan natija sodir bo'lganini bildiradi.\n\n"
        "• [b]Although[/b]: Eng keng tarqalgan va neytral.\n"
        "  Although it rained, we went for a walk. ☔️➡️🚶‍♂️ – Garchi yomg'ir yog'gan bo'lsa ham, biz sayohatga bordik.\n\n"
        "• [b]Though[/b]: [b]Although[/b] bilan bir xil ma'noda, lekin biroz [b]norasmiyroq[/b] va ba'zan gapning oxirida ham kelishi mumkin.\n"
        "  He passed the exam, though he hadn't studied much. 📚 – U imtihondan o'tdi, garchi u ko'p o'qimagan bo'lsa ham.\n"
        "  It was a bit difficult, but I did it, though. 💪 – Bu biroz qiyin bo'ldi, ammo baribir qildim, [b]shunday bo'lsada[/b].\n\n"
        "• [b]Even though[/b]: [b]Although[/b] ga qaraganda [b]kuchliroq ta'kid[/b] beradi, ya'ni “hatto shunday bo'lsa ham” degan ma'noni beradi.\n"
        "  Even though he was very tired, he couldn't sleep. 😴 – Hatto u juda charchagan bo'lsa ham, u uxlolmadi.\n\n"
        "✅ [b]In spite of / Despite (Ga qaramay)[/b]\n"
        "Bu iboralar [b]predloglar[/b] bo'lib, ulardan keyin [b]ot (noun)[/b], [b]olmosh (pronoun)[/b] yoki [b]fe'lning -ing shakli (gerund)[/b] keladi. Ma'nosi [b]although[/b] bilan bir xil, lekin grammatik tuzilishi farq qiladi.\n\n"
        "• In spite of the bad weather, they enjoyed their holiday. 🏞️ – Yomon ob-havoga qaramay, ular dam olishdi.\n"
        "• Despite feeling tired, he continued to work. 💼 – Charchaganligiga qaramay, u ishlashda davom etdi.\n"
        "• Despite all the difficulties, she succeeded. 🏆 – Barcha qiyinchiliklarga qaramay, u muvaffaqiyatga erishdi.\n\n"
        "• Agar [b]in spite of[/b] yoki [b]despite[/b] dan keyin to'liq gap(ega kesimli) ishlatmoqchi bo'lsangiz, [b]“the fact that”[/b] iborasini qo'shishingiz mumkin.\n"
        "  In spite of the fact that it rained, they went for a walk. ☔️➡️🚶‍♂️ – Yomg'ir yog'ganiga qaramay, ular sayrga chiqdilar.\n"
        "  Despite the fact that it rained, they went for a walk. – Yomg'ir yog'ganiga qaramay, ular sayrga chiqdilar.\n\n"
        "✅ [b]Qisqacha taqqoslash va foydalanish bo'yicha eslatmalar:[/b]\n"
        "• [b]Although / Though / Even though[/b] + [b]sub'ekt + fe'l[/b] (gap)\n"
        "• [b]In spite of / Despite[/b] + [b]ot / olmosh / -ing shakli[/b]\n\n"
        "• [b]Although[/b] va [b]because[/b] ni farqlash muhim: [b]although[/b] qarama-qarshilikni, [b]because[/b] esa sababni bildiradi.\n"
        "  Although he was sick, he went to work. 🤒➡️🏢 – Garchi kasal bo'lsa ham, u ishga bordi. (Qarama-qarshilik)\n"
        "  Because he was sick, he didn't go to work. 🤒🚫🏢 – U kasal bo'lgani uchun ishga bormadi. (Sabab)\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=6Q8WZuTgSNs]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 140,
    "title": "In case (Ehtimolga qarshi / Agar shunday bo'lsa)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 140[/b] darsimizda biz ingliz tilida ehtimoliy vaziyatlarga nisbatan ehtiyot choralarini ko'rishni ifodalovchi [b]\"in case\"[/b] iborasini tabiiy misollar bilan o'rganamiz. Bu ibora biror narsa sodir bo'lishi mumkinligi sababli, biror harakatni amalga oshirishni anglatadi.\n\n"
        "✅ [b]In case ning asosiy ma'nosi:[/b]\n"
        "[b]In case[/b] iborasi “biror narsa yuz berishi mumkinligi sababli” yoki “shunchaki, har ehtimolga qarshi” degan ma'noni anglatadi. Bu kelajakda yuz berishi mumkin bo'lgan vaziyatga oldindan tayyorgarlik ko'rishni bildiradi.\n\n"
        "• I'll double-check my keys before I leave, in case I forget them. 🔑 – Men tashqariga chiqishdan oldin kalitlarimni ikki marta tekshiraman, ularni unutib qoldirgan bo'lishim mumkin deya.\n"
        "  (Kalitlarimni unutishim mumkin, shuning uchun oldindan ehtiyot chorasini ko'ryapman.)\n"
        "• Wear an extra layer in case it gets chilly later. 🧥 – Har ehtimolga qarshi issiqroq kiyim kiying, sovuqroq bo'lib qolishi mumkin.\n"
        "  (Havo sovib qolishi mumkin, shuning uchun hozirdan qalinroq kiyim kiyish tavsiya etiladi.)\n\n"
        "• E'tibor bering, [b]in case[/b] dan keyin kelajakni nazarda tutganimizda ham [b]hozirgi oddiy zamon (present simple)[/b] ishlatiladi, kelajak zamon (future simple) emas. Ya'ni 'will' ishlatilmaydi. \n\n"
        "✅ [b]In case va If o‘rtasidagi farq:[/b]\n"
        "Bu ikkala ibora ham shartni bildirishi mumkin bo'lsa-da, ularning qo'llanilishida muhim farq bor:\n"
        "• [b]If[/b] ([b]agar[/b]): Bu shunchaki shartni bildiradi – agar biror narsa sodir bo'lsa, shunda boshqa harakat qilinadi. Harakat shart bajarilgandan keyin sodir bo'ladi.\n"
        "  If you can't help now, please help later. 🤷‍♂️ – Agar hozir yordam bera olmasangiz, keyinroq yordam bering.\n"
        "  (Yordam bera olishingizga bog'liq.)\n\n"
        "• [b]In case[/b] ([b]ehtimolga qarshi[/b]): Bu ehtiyot chorasini bildiradi – biror narsa sodir bo'lishi ehtimoli borligi uchun [b]oldindan[/b] harakat qilish.\n"
        "  I bought a spare battery in case I need it. 🔋 – Ehtimol menga kerak bo'lib qolsa deb, zaxira akkumulyator oldim.\n"
        "  (U kerak bo'lmasligi ham mumkin, lekin ehtiyot shart olib qo'yganman.)\n\n"
        "✅ [b]In case + o'tgan zamon (Past):[/b]\n"
        "[b]In case[/b] + [b]o'tgan zamon[/b] ([b]past simple[/b]) biror kishi o'tmishda nima uchun biror harakatni amalga oshirganini, ya'ni qanday ehtiyot chorasini ko'rganini tushuntirish uchun ishlatiladi.\n\n"
        "• I explained everything twice in case he didn't understand. 🗣️ – Men u tushunmay qolsa deb, hamma narsani ikki marta tushuntirib berdim.\n"
        "• She saved some food in case anyone got hungry later. 🍽️ – U ovqatni saqladi, ehtimol keyinroq kimdir och qolsa deb.\n\n"
        "✅ [b]In case of (Ehtimol ... yuz berganda / Holatida):[/b]\n"
        "[b]In case of[/b] iborasi ko'pincha rasmiy ko'rsatmalarda, ogohlantirishlarda yoki favqulodda vaziyatlar uchun yo'riqnomalarda ishlatiladi. U “agar ... bo'lsa” yoki “... holatida” degan ma'noni beradi va undan keyin [b]ot (noun)[/b] keladi.\n\n"
        "• In case of a power outage, start the generator. 🔌➡️💡 – Elektr uzilishi yuz berganda, generatorni yoqing.\n"
        "• In case of system error, contact the IT department for assistance. 💻 – Tizim xatosi yuz berganda, yordam uchun texnik bo'limga murojaat qiling.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=_oCkyt9daoc]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 141,
    "title": "Unless and As Long As (Agar ... bo'lmasa / Agar ... ekan)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 141[/b] darsimizda biz ingliz tilida shartli gaplarni ifodalash uchun ishlatiladigan [b]\"unless\"[/b] va [b]\"as long as\"[/b] bog'lovchilarini o'rganamiz. Bu so'zlar biror harakatning yoki holatning boshqa bir shartga bog'liqligini ko'rsatishga yordam beradi.\n\n"
        "✅ [b]Unless (Agar ... bo'lmasa / ...dan tashqari)[/b]\n"
        "[b]Unless[/b] bog'lovchisi [b]\"if ... not\"[/b] (agar ... emas) degan ma'noni beradi. Uning yordamida biror shart bajarilmasa, ma'lum bir natija yuz berishini ifodalaymiz. Oson eslab qolish uchun siz uni '...guncha' deb tarjima qilishingiz mumkin. \n\n"
        "• We'll miss the train unless we hurry. ⏰ – Agar shoshilmasak, poyezdga kech qolamiz.\n"
        "  (Ya'ni, [b]If we don't hurry, we'll miss the train.[/b])\n\n"
        "• I won't speak to him unless he apologizes. 🤫 – U mendan kechirim so'ramaguncha, men u bilan gaplashmayman.\n"
        "  (Ya'ni, [b]If he doesn't apologize, I won't speak to him.[/b])\n\n"
        "• I won't make a decision unless I fully understand the situation. 💭 – Vaziyatni to'liq tushunmagunimcha, qaror qabul qilmayman.\n\n"
        "✅ [b]As long as (Modomiki / Sharti bilan / Ekan)[/b]\n"
        "[b]As long as[/b] bog'lovchisi [b]\"provided that\"[/b] (sharti bilan) yoki [b]\"on condition that\"[/b] (bu shart bilan) degan ma'nolarni beradi. U biror narsaning yuz berishi yoki to'g'ri bo'lishi uchun zarur bo'lgan kuchli shartni ifodalaydi.\n\n"
        "• You can stay as long as you don't mind sleeping on the couch. 🏠 – Siz xohlagancha qolavering, faqat divanda yotishga qarshi bo'lmasangiz bas.\n"
        "• You can take a break as long as you finish your work on time. ✅ – Ishni vaqtida tugatsangiz, xohlaganingizcha dam olishingiz mumkin.\n"
        "• I'll help you as long as you help me too. 🤝 – Men sizga yordam beraman, modomiki siz ham menga yordam bersangiz.\n\n"
        "✅ [b]Farqlar va Nuanslar:[/b]\n"
        "• [b]Unless[/b] [b]salbiy shartni[/b] ko'rsatadi: \"Agar bu narsa sodir bo'lmasa...\" yoki \"... bo'lmasa\".\n"
        "• [b]As long as[/b] esa [b]ijobiy shartni[/b] ko'rsatadi: \"Agar bu narsa sodir bo'lsa...\" yoki \"... sharti bilan\", ya'ni biror narsaning amalga oshishi uchun zarur bo'lgan asosiy shartni ta'kidlaydi.\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=lo09DtvKb1M]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 142,
    "title": "As and Since(As I walked... / As I was hungry...)",
    "content": "✅ Bu darsda biz [b]as[/b] va [b]since[/b] so‘zlarining ma’nolarini ko‘rib chiqamiz:\n\n"
        "1️⃣ [b]As[/b] = bir paytda / bir vaqtda\n"
        "Ikkita ish bir vaqtda bo‘lganda ishlatiladi:\n"
        "• As I was walking to school, I saw a cat. 🐈 — Maktabga ketayotganimda mushukni ko‘rdim.\n"
        "• As we were having dinner, it started raining. 🍽️🌧️ — Ovqatlanayotganimizda yomg‘ir yog'ishni boshladi.\n\n"
        "📌 [b]As + past continuous[/b] yoki oddiy [b]past simple[/b] bilan ishlatiladi.\n"
        "• As she opened the window, the phone rang. 📞 — U derazani ochganida, telefon jiringladi.\n\n"
        "• As I was driving home, I saw a beautiful rainbow. 🚗🌈 — Uyga ketayotganimda, chiroyli kamalakni ko‘rdim.\n"
        "• As they were leaving the building, they heard a loud noise. 🚶‍♀️🚪📢 — Ular binodan chiqib ketayotganlarida, qattiq shovqin eshitishdi."
        "✅ [b]As[/b] ni vaqt o‘tishi jarayonida ham ishlatish mumkin:\n"
        "• As the evening went on, it got colder. 🌙❄️ — Kech kirgan sari havo soviy boshladi.\n\n"
        "2️⃣ [b]As[/b] = chunki (sababi)\n"
        "Sabab bildirganda ham ishlatiladi:\n"
        "• As I was tired, I went to bed early. 😴 — Charchaganim uchun erta uxladim.\n"
        "• As it was raining, we stayed at home. 🌧️🏠 — Yomg‘ir yog‘ayotganligi sababli uyda qoldik.\n\n"
        "3️⃣ [b]Since[/b] = chunki\n"
        "[b]Since[/b] ham sabab bildiradi va [b]because[/b] kabi ishlatiladi:\n"
        "• Since we have time, let's watch a movie. 🎥 — Vaqtimiz bo‘lgani uchun film ko‘raylik.\n"
        "• Since it was late, I took a taxi. 🚖 — Kech bo‘lgani uchun taksi chaqirdim.\n\n"
        "✅ [b]As[/b], [b]since[/b] va [b]because[/b] farqi:\n"
        "• [b]As[/b] va [b]since[/b] odatda gap boshida keladi.\n"
        "• [b]Because[/b] esa har ikkala joyda ham ishlaydi.\n\n"
        "✅ [b]As[/b] va [b]when[/b] farqi:\n"
        "[b]As[/b] — ikki ish bir vaqtda bo‘lganda\n"
        "[b]When[/b] — biri tugab, keyin boshqasi bo‘lsa\n"
        "• As we walked home, we talked. 🚶‍♂️💬 (Yurib ketayotib suhbatlashdik.)\n"
        "• When we got home, we had tea. 🏠☕ (Uyga yetib borgach, choy ichdik.)\n\n"
        "✅ [b]Yangi misollar:[/b]\n"
        "• As he was reading a book, his friend called. 📖📱 — U kitob o‘qiyotganda do‘sti qo‘ng‘iroq qildi.\n"
        "• As the movie started, it began to rain. 🎥🌧️ — Film boshlanishi bilan yomg‘ir yog‘di.\n"
        "• As I had nothing to do, I cleaned my room. 🧹 — Ishim bo‘lmagani uchun xonani tozaladim.\n"
        "• Since we finished early, we went for a walk. 🏞️ — Erta tugatganimiz uchun sayrga chiqdik.\n"
        "• Since he was ill, he stayed at home. 🤒🏠 — Kasal bo‘lgani uchun uyda qoldi.\n\n"
  },
  {
    "lesson": 143,
    "title": "Like and As (Kabi / Sifatida)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 143[/b] darsimizda biz ingliz tilida ko'p chalkashtiriladigan, ammo muhim bog'lovchi va predlog bo'lgan [b]\"like\"[/b] va [b]\"as\"[/b] so'zlarini o'rganamiz. Bu so'zlar ikkita narsani taqqoslash, vazifalarni belgilash yoki sabablarni ifodalashda ishlatiladi.\n\n"
        "✅ [b]Like (Kabi, singari, o'xshash)[/b]\n"
        "[b]Like[/b] so'zi asosan [b]predlog[/b] sifatida ishlatiladi va “biror narsaga o'xshash” yoki “bir xil” degan ma'noni beradi. Undan keyin odatda [b]ot (noun)[/b], [b]olmosh (pronoun)[/b] yoki [b]-ing shaklidagi fe'l (gerund)[/b] keladi.\n\n"
        "• He runs fast like his brother. 🏃‍♂️ – U akasi kabi tez yuguradi.\n"
        "• This project feels like a huge task. 📝 – Bu loyiha katta vazifadek tuyuldi.\n"
        "• She laughed like children. 😂 – U bolalardek kulardi.\n"
        "• Don't act like him. 🤨 – O'sha odam kabi harakat qilmang.\n\n"
        "✅ [b]As (Sifatida, kabi, chunki, shunday qilib)[/b]\n"
        "[b]As[/b] so'zi kengroq ma'nolarga ega va ham [b]bog'lovchi[/b], ham [b]predlog[/b] sifatida ishlatiladi:\n\n"
        "1.  [b]Bog'lovchi sifatida ('... kabi', 'xuddi ...dek'):[/b] Biror narsaning [b]qandaydir tarzda[/b] yoki [b]qandaydir shartda[/b] sodir bo'lishini bildiradi. Undan keyin [b]to'liq gap[/b] ([b]ega + kesim[/b]) keladi.\n"
        "    • Do it exactly as I showed you. 💡 – Men sizga ko'rsatganimdek qiling.\n"
        "    • As I expected, he was late. ⏳ – Xuddi men kutganimdek, u kech qoldi.\n\n"
        "2.  [b]Sababni bildirish uchun ('chunki', 'tufayli'):[/b] Oldingi darsda ham ko'rganimizdek, [b]because[/b] (chunki) ma'nosini beradi.\n"
        "    • As the weather was bad, we canceled our trip. 🌧️ – Havo yomon bo'lgani uchun, sayohatimizni bekor qildik.\n\n"
        "3.  [b]Vaqtni bildirish uchun oldingi darsda aytilganidek('paytida', 'bir vaqtda'):[/b] [b]While[/b] (davomida) kabi, bir vaqtda sodir bo'lgan harakatlar uchun.\n"
        "    • As I opened the door, the bird flew away. 🚪🐦 – Men eshikni ochganimda, qush uchib ketdi.\n\n"
        "4.  [b]Predlog sifatida ('sifatida', 'vazifasida'):[/b] Biror kishining [b]roli[/b], [b]vazifasi[/b] yoki [b]maqomini[/b] bildiradi.\n"
        "    • She works as a manager at this company. 🏢 – U shu kompaniyada menejer sifatida ishlaydi.\n"
        "    • This tool can be used as a simple hammer. 🔨 – Ushbu qurol oddiy bolg'acha sifatida ishlatilishi mumkin.\n\n"
        "✅ [b]Asosiy farqlar va eslatmalar:[/b]\n"
        "• Eng muhim farq shundaki: [b]Like[/b] odatda [b]ot[/b], [b]olmosh[/b] yoki [b]-ing fe'l[/b] bilan ishlatiladi ([b]predlog[/b]). [b]As[/b] esa ko'pincha [b]gap[/b] (ega + kesim) bilan ishlatiladi ([b]bog'lovchi[/b]), yoki biror [b]rol/vazifani[/b] bildiruvchi predlog sifatida keladi.\n"
        "• Rasmiy kontekstda [b]like[/b] dan keyin gap ishlatishdan qochish tavsiya etiladi (masalan, [b]Like I said[/b] o'rniga [b]As I said[/b] deyish afzalroq).\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=NVvadY8eE_E]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 144,
    "title": "As if / As though / Like (Xuddi / Go'yo)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 144[/b] darsimizda biz ingliz tilida biror narsa qanday ko'ringani, eshitilgani yoki his qilinganini ifodalash uchun ishlatiladigan [b]\"as if\"[/b], [b]\"as though\"[/b] va [b]\"like\"[/b] iboralarini o'rganamiz. Bu iboralar ko'pincha taqqoslash yoki faraziy vaziyatlarni tasvirlashda qo'llaniladi.\n\n"
        "✅ [b]As if / As though (Go'yo)[/b]\n"
        "Bu iboralar biror narsaning [b]qanday ko'rinishini[/b], [b]qanday eshitilishini[/b] yoki [b]qanday his qilinishini[/b] tavsiflash uchun ishlatiladi. Ulardan keyin odatda [b]ega + kesim[/b] (to'liq gap) keladi. Ular vaziyatning haqiqatga yaqinligini yoki shunchaki bir tasavvur ekanligini bildirish mumkin.\n\n"
        "• His facial expression was as if he knew everything. 🤔 – Uning yuz ifodasi go'yoki hamma narsani biladigandek edi.\n"
        "• It felt as though someone was walking in the dark. 👣 – Go'yo qorong'ida kimdir qadam bosayotgandek tuyuldi.\n\n"
        "• [b]Noreal (mavjud bo'lmagan) vaziyatlar uchun o'tgan zamon:[/b]\n"
        "Hozirgi yoki kelajakdagi vaziyat haqida gapirayotganda, agar u noreal yoki ehtimoldan yiroq bo'lsa, [b]as if / as though[/b] dan keyin [b]o'tgan zamon fe'li[/b] ishlatiladi. Bu shartli gaplardagi foydalanishga o'xshashdir.\n\n"
        "• He talks as if he were a prince. 👑 – U xuddi shahzoda bo'lgandek gapiradi. (Lekin u shahzoda emas)\n"
        "• She acts as though she knew everything. 🤔 – U go'yo hamma narsani biladigandek harakat qiladi. (Uning hozirgi xatti-harakati haqida, lekin u hamma narsani bilmaydi)\n"
        "• They talk to me as though I were a child. 👶 – Ular men bilan go'yo yosh boladek gaplashishadi. (Hozirgi gaplashish usuli haqida, lekin men bola emasman)"
        "✅ [b]Like o'tgan darsda o'tganimiz(norasmiy holatda)[/b]\n"
        "Norasmiy so'zlashuv tilida, [b]like[/b] so'zi ham [b]as if[/b] yoki [b]as though[/b] ma'nosida, to'liq gapdan oldin ishlatilishi mumkin.\n\n"
        "• His car sounds like it's going to fly away. 🚗💨 – Uning mashinasi xuddi uchib ketadigandek ovoz chiqaradi.\n"
        "• I feel like I've already cooked dinner. 🍽️ – Men xuddi allaqachon kechki ovqat qilgandek his qilyapman.\n\n"
        "✅ [b]O'tgan zamon bilan Inkor ma'no uchun (as if / as though + had + V3)[/b]\n"
        "Qachonki biz kimdir biror narsani qilmagan bo'lsa-da, xuddi shunday qilgandek harakat qilganini yoki ko'ringanini aytmoqchi bo'lsak, [b]as if / as though[/b] dan keyin [b]past perfect[/b] (had + V3) ishlatamiz. Bu ham haqiqatga mos kelmaydigan vaziyatni ta'kidlaydi.\n\n"
        "• He laughed as if nothing had happened. 😊 – U xuddi hech narsa bo'lmagandek kulardi. (Aslida bir narsa bo'lgan)\n"
        "• She acted as though she had never seen it before. 🙈 – U xuddi avval buni ko'rmagandek harakat qildi. (Aslida ko'rgan)\n\n"
        "[center][b]🎥 Video darslik:[/b][/center]\n"
        "[link=https://www.youtube.com/watch?v=2yYzyJbazpA]Mavzuni yanada yaxshiroq o'rganish uchun bu yerni bosing va video darslikni tomosha qiling![/link]"
  },
  {
    "lesson": 145,
    "title": "By (Orqali / Bo'yicha / Yonida)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 145[/b] darsimizda biz ingliz tilida juda ko'p ma'nolarga ega bo'lgan va turli vaziyatlarda ishlatiladigan [b]\"by\"[/b] predlogini o'rganamiz. U harakat usulini, transport vositalarini, passiv gaplardagi ijrochilikni va joylashuvni bildirishga yordam beradi.\n\n"
        "✅ [b]Harakat usulini bildirish uchun (Qanday qilib? Orqali)[/b]\n"
        "[b]By[/b] so'zi biror narsani qanday amalga oshirganimizni ko'rsatish uchun ishlatiladi.\n\n"
        "• I sent all the documents [b]by email[/b]. 📧 – Men barcha hujjatlarni [b]elektron pochta orqali[/b] yubordim.\n"
        "• He usually pays [b]by bank transfer[/b]. 💰 – U odatda [b]bank o'tkazmasi orqali[/b] to'laydi.\n"
        "• You can gain much knowledge [b]by this book[/b]. 🚶‍♀️ – [b]Bu kitob orqali[/b] ko'p bilimga erishish mumkin.\n"
        "✅ [b]Transport vositalari bilan (Qanday transportda?)[/b]\n"
        "[b]By[/b] so'zi transport vositalarida sayohat qilish usulini bildirish uchun ishlatiladi.\n\n"
        "• We're traveling [b]by train[/b] on Saturday. 🚂 – Biz shanba kuni [b]poyezdda[/b] boramiz.\n"
        "• She goes to work [b]by bus[/b] every day. 🚌 – U har kuni ishga [b]avtobusda[/b] boradi.\n"
        "• E'tibor bering: [b]Alohida transport vositasi[/b] haqida gapirganda [b]in[/b] yoki [b]on[/b] ishlatiladi, [b]by[/b] emas ([b]the/my car, a taxi, the train[/b] kabi). Piyoda yurishni aytishda esa [b]on foot[/b] deymiz.\n"
        "  • He came in his car. 🚗 – U o'z mashinasida keldi.\n"
        "  • We didn't fly; we went on foot. ✈️🚶‍♀️ – Biz samolyotda uchmadik, biz piyoda bordik.\n\n"
        "✅ [b]Passiv gaplarda ijrochini bildirish uchun (Kim tomonidan?)[/b]\n"
        "Passiv gaplarda harakatni kim (yoki nima) amalga oshirganini ko'rsatish uchun [b]by[/b] dan foydalanamiz.\n\n"
        "• The book was written [b]by a famous author[/b]. ✍️ – Kitob mashhur [b]yozuvchi tomonidan[/b] yozilgan.\n"
        "• The decision was made [b]by the board of directors[/b]. 🤝 – Qaror [b]direktorlar kengashi tomonidan[/b] qabul qilindi.\n\n"
        "✅ [b]Joylashuvni bildirish uchun (Yonida, yaqinida)[/b]\n"
        "[b]By[/b] so'zi [b]beside[/b] (yonida) ma'nosida ham ishlatilishi mumkin.\n\n"
        "• His phone is [b]by the bed[/b]. 📱🛏️ – Uning telefoni [b]to'shak yonida[/b] turibdi.\n"
        "• Please sit [b]by the window[/b]. 🪟 – Iltimos, [b]deraza yoniga[/b] o'tiring.\n\n"
        "✅ [b]Qaysidir muddatgacha (Qachongacha?)[/b]\n"
        "[b]By[/b] so'zi ma'lum vaqtgacha nimadir bajarilishi kerakligini anglatadi va bu bilan 'until' ga o'xshaydi.\n\n"
        "• You should come [b]by 5:00[/b] o'clock. 📈 – [b]5:00 gacha[/b] kelishing kerak.\n"
        "• I must finish homework [b]by Sunday[/b]. 🏁 – Men [b]yakshanbagacha[/b] uy vazifasini tugatishim kerak.\n\n"
