  {
    "lesson": 146,
    "title": "Noun + Preposition (Ot + Predlog)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 146[/b] darsimizda biz ingliz tilida juda muhim bo'lgan \"Ot + Predlog\" birikmalarini o'rganamiz. Ko'pgina otlar o'zidan keyin ma'lum bir predlogni talab qiladi va bu birikmalar biror narsaning sababi, usuli, joylashuvi yoki bog'liqligini aniq ifodalashga yordam beradi.\n\n"
        "✅ [b]Noun + for (Uchun / Sababli)[/b]\n"
        "Bu birikma biror narsaning sababini, maqsadini yoki biror miqdorni bildirish uchun ishlatiladi.\n\n"
        "• He couldn't find a [b]reason for[/b] such behavior. 🤨 – U bunday xatti-harakatga hech qanday sabab topa olmadi.\n"
        "• We have a [b]demand for[/b] extra resources for the project. 🛠️ – Bizga loyiha uchun qo'shimcha resurslar kerak.\n"
        "• She sent a [b]cheque for[/b] 200 dollars for the new desk. 💸 – U yangi stol uchun 200 dollarlik chek jo'natdi.\n"
        "• There's no need [b]for haste[/b] regarding this question. 🐢 – Bu savolga shoshilishning hojati yo'q.\n\n"
        "✅ [b]Noun + of (ning / ning sababi)[/b]\n"
        "Bu birikma afzallik/kamchilik, sabab yoki biror narsaning qismini bildirish uchun qo'llaniladi.\n\n"
        "• The [b]advantage of[/b] being part of a team is that you can always find help. 🤝 – Jamoadan bir qismi bo'lishning afzalligi shundaki, siz har doim yordam topishingiz mumkin.\n"
        "• The [b]cause of[/b] the accident is still unclear. 💥 – Bu avariyaga nima sabab bo'lgani aniq emas.\n"
        "• She showed me several old [b]photographs of[/b] the city. 🖼️ – Menga shaharning bir nechta eski rasmlarini ko'rsatdi.\n\n"
        "✅ [b]Noun + in (dagi / da)[/b]\n"
        "Bu birikma ko'pincha o'zgarishlarni (o'sish/kamayish) yoki biror sohada mavjudlikni bildiradi.\n\n"
        "• There has been a significant [b]increase in[/b] the number of internet users recently. 📈 – So'nggi paytlarda internet foydalanuvchilar sonida sezilarli o'sish kuzatildi.\n"
        "• We observed a sharp [b]decrease in[/b] food prices. 📉 – Oziq-ovqat narxlarida keskin pasayish kuzatildi.\n\n"
        "✅ [b]Noun + to (ga / ga nisbatan)[/b]\n"
        "Bu birikma zarar, taklif, yechim, javob yoki munosabatni bildirish uchun ishlatiladi.\n\n"
        "• I found a quick [b]solution to[/b] the problem. 💡 – Bu muammoga tezda yechim topa oldim.\n"
        "• His [b]attitude to[/b] his job is extremely negative. 😠 – Uning ishiga nisbatan munosabati juda salbiy.\n"
        "• She sent me an [b]invitation to[/b] the party. 🎉 – U menga ziyofatga taklifnoma yubordi.\n"
        "• My [b]answer to[/b] your question is obvious. 🏚️ – Savolingizga javobim aniq.\n\n"
        "✅ [b]Noun + with / between (Bilan / O'rtasida)[/b]\n"
        "Bu birikma aloqa, munosabat yoki farqni bildirish uchun ishlatiladi.\n\n"
        "• Her [b]relationship with[/b] clients is excellent. 📞 – Uning mijozlar bilan munosabati juda yaxshi.\n"
        "• There are clear [b]differences between[/b] the two groups. ↔️ – Ikki guruh o'rtasida aniq tafovutlar mavjud.\n\n"
