  {
    "lesson": 147,
    "title": "Adjective + Preposition (Sifat + Predlog)",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 147[/b] darsimizda biz ingliz tilida juda ko'p uchraydigan \"Sifat + Predlog\" birikmalarini o'rganamiz. Ingliz tilida ko'plab sifatlar o'zidan keyin ma'lum bir predlogni talab qiladi va bu birikmalarni bilish sizning nutqingizni yanada tabiiy va to'g'ri qiladi.\n\n"
        "✅ [b]Sifat + of (Biror narsadan/kimdandir)[/b]\n"
        "Bu birikmalar ko'pincha hissiyotlar, xabardorlik, xususiyatlar yoki yetishmovchilikni bildirish uchun ishlatiladi.\n\n"
        "• She is [b]afraid of[/b] heights. ⛰️ – U balandliklardan qo'rqadi.\n"
        "• I am [b]proud of[/b] my achievements. 🌟 – Men o'zimning erishgan yutuqlarimdan faxrlanaman.\n"
        "• He is [b]envious of[/b] other people's success. 😒 – U boshqalarning muvaffaqiyatiga hasad qiladi.\n"
        "• I am fully [b]aware of[/b] the situation. 💡 – Men vaziyatdan to'liq xabardorman.\n"
        "• The pot is [b]full of[/b] water. 💧 – Idish suvga to'la.\n"
        "• I'm [b]tired of[/b] all these silly excuses. 😴 – Men barcha bema'ni bahonalardan charchadim.\n\n"
        "✅ [b]Sifat + at (Biror narsada qobiliyat)[/b]\n"
        "Bu birikma biror ko'nikma yoki ishdagi mahoratni bildirish uchun qo'llaniladi.\n\n"
        "• She is [b]good at[/b] mathematics. ➕ – U matematikadan juda yaxshi.\n"
        "• He is not very [b]bad at[/b] drawing. 🎨 – U rasm chizishda unchalik yomon emas.\n\n"
        "✅ [b]Sifat + to (Biror kishiga/narsaga nisbatan)[/b]\n"
        "Bu birikma munosabatlar, o'xshashlik yoki farqni ko'rsatadi.\n\n"
        "• His sister is[b] married to[/b] a doctor. 👰‍♀️ – Uning singlisi doktorga turmushga chiqqan.\n"
        "• My ideas are [b]similar to[/b] yours. 🧠 – Mening fikrlarim siznikiga o'xshash.\n"
        "• This is quite [b]different to[/b] the previous version. 🔄 – Bu avvalgi versiyadan ancha farq qiladi. (different bilan ko'pincha from ishlatiladi)\n\n"
        "✅ [b]Sifat + on (Biror narsaga qiziqish / Bog'liqlik)[/b]\n"
        "Bu birikma qiziqish, ishtiyoq yoki bog'liqlikni bildiradi.\n\n"
        "• She is[b] keen on[/b] sports. ⚽ – U sportga juda qiziqadi.\n"
        "• Many people are [b]dependent on[/b] the economic situation. 🌍 – Ko'plab odamlar iqtisodiy vaziyatga bog'liq.\n\n"
        "✅ [b]Sifat + for (Biror narsa uchun javobgar / Afsusda)[/b]\n"
        "Bu birikma javobgarlikni yoki biror narsa uchun kechirim so'rashni ifodalaydi.\n\n"
        "• Who is [b]responsible for[/b] this project? 👨‍💼 – Bu loyiha uchun kim mas'ul?\n"
        "• I am very [b]sorry for[/b] doing that. 😔 – Men buni qilganim uchun juda afsusdaman.\n\n"
        "✅ [b]Sifat + in (Biror narsaga qiziqish / Muvaffaqiyat)[/b]\n"
        "Bu birikma qiziqishni yoki biror sohadagi muvaffaqiyatni bildiradi.\n\n"
        "• I am very [b]interested in[/b] history. 🏛️ – Men tarixga juda qiziqaman.\n"
        "• She [b]succeeded in[/b] her chosen field. 🏆 – U o'z sohasida muvaffaqiyatga erishdi.\n\n"
        "✅ [b]Sifat + about (Hissiyotlar va fikrlar)[/b]\n"
        "Bu birikma ko'pincha biror narsa haqidagi hissiyotlar yoki fikrlarni bildiradi.\n\n"
        "• I'm a bit [b]worried about[/b] the final outcome. 😟 – Men yakuniy natijadan biroz xavotirdaman.\n"
        "• They are [b]excited about[/b] the upcoming holiday. 🥳 – Ular kelayotgan bayramdan hayajonda.\n\n"
