    "lesson": 148,
    "title": "Verb + Preposition 1 (Fe'l + Predlog 1): To va At",
    "content": "Assalomu alaykum! 👋 Bugungi [b]Lesson 148[/b] darsimizda biz ingliz tilida fe'llar bilan ishlatiladigan predloglarning muhim bir qismini, xususan [b]\"to\"[/b] va [b]\"at\"[/b] predloglarining qo'llanilishini o'rganamiz. Bu predloglar fe'lning ma'nosini o'zgartirishi yoki harakatning yo'nalishini aniqlashi mumkin.\n\n"
        "✅ [b]Fe'l + to (Biror kishiga/narsaga nisbatan)[/b]\n"
        "[b]To[/b] predlogi harakatning yoki muloqotning biror shaxsga yoki yo'nalishga qaratilganini bildirish uchun ishlatiladi.\n\n"
        "• I talked to him about the situation. 🗣️ – Men u bilan vaziyat haqida gaplashdim.\n"
        "• Listen carefully to what the teacher says. 👂 – O'qituvchining aytganlariga diqqat bilan quloq soling.\n"
        "• I apologized to her for being late. 😔 – Men undan kechikkanim uchun uzr so'radim.\n"
        "• Please explain the problem to me. 📖 – Iltimos, bu masalani menga tushuntirib bering.\n\n"
        "• [b]To[/b] predlogi ishlatilmaydigan fe'llar:\n"
        "Ba'zi fe'llar to'g'ridan-to'g'ri to'ldiruvchi oladi va [b]to[/b] predlogi bilan ishlatilmaydi. Bu xato qilish oson bo'lgan joylardan biri.\n"
        "  • Ask me a question. (NOT [b]ask to me[/b]) ❓ – Menga savol bering.\n"
        "  • Did you phone him yesterday? (NOT [b]phone to him[/b]) 📞 – Kecha unga qo'ng'iroq qildingizmi?\n"
        "  • She didn't answer my question. (NOT [b]answer to my question[/b]) ✅ – U mening savolimga javob bermadi.\n\n"
        "✅ [b]Fe'l + at (Biror narsaga/kimdirga qaratish/nazar solish)[/b]\n"
        "[b]At[/b] predlogi harakatning aniq bir nishonga qaratilganini, kimdirga qarashni yoki nimagadir kulishni bildiradi.\n\n"
        "• Don't look at me strangely. 🤨 – Menga g'alati qaramang.\n"
        "• Don't laugh at his joke. 🤣 – Uning haziliga kulma.\n"
        "• He aimed at the ball, but he couldn't hit it. 🎯 – U to'pga mo'ljal oldi, lekin uni ura olmadi.\n\n"
        "✅ [b]Fe'llarning ma'nosi predlogga qarab o'zgarishi[/b]\n"
        "Ba'zi fe'llar [b]to[/b] yoki [b]at[/b] predloglari bilan ishlatilganda, ma'nosi butunlay o'zgarishi mumkin.\n\n"
        "• [b]Shout at (Jahl bilan baqirmoq)[/b] vs. [b]Shout to (Eshitilishi uchun baqirmoq)[/b]\n"
        "  • He shouted at the children. 😡 – U bolalarga jahl bilan baqirdi.\n"
        "  • He shouted to me from a distance so I could hear him. 🗣️ – U menga uzoqdan baqirdi, shunda men uni eshitdim.\n\n"
        "• [b]Throw at (Urish niyatida otmoq)[/b] vs. [b]Throw to (Tutib olishi uchun otmoq)[/b]\n"
        "  • Somebody threw an egg at the minister. 🥚 – Kimdir vazirga tuxum otdi.\n"
        "  • Lisa threw the keys to me from the window. 🔑 – Lisa menga kalitlarni derazadan otdi.\n\n"
